INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-001', 'aws-dva', 'Uma função AWS Lambda processa mensagens de uma fila Amazon SQS via event source mapping. Algumas mensagens falham consistentemente por erro no downstream. A equipe precisa isolar essas mensagens problemáticas para análise sem bloquear o restante do batch. Qual configuração resolve?',
  '[{"id":"A","text":"Configurar uma Dead-Letter Queue na fila SQS source com maxReceiveCount=3"},{"id":"B","text":"Aumentar a reservedConcurrency da função Lambda"},{"id":"C","text":"Definir DestinationConfig.OnFailure no Lambda apontando para uma fila SNS"},{"id":"D","text":"Habilitar provisioned concurrency para reduzir cold starts"}]'::jsonb, 'A',
  '"(a) Para event source mapping SQS→Lambda, a DLQ deve ser configurada na própria fila SQS — após N falhas (maxReceiveCount), a mensagem é movida para a DLQ automaticamente. (b) reservedConcurrency limita paralelismo, não isola falhas. DestinationConfig.OnFailure só funciona para invocações assíncronas (não event source mapping síncrono do SQS). Provisioned concurrency reduz cold start, não isola erro. (c) Conceito: DLQ no SQS é o mecanismo de isolamento; DestinationConfig é caminho diferente para invokes assíncronos. (d) Ver docs Lambda com SQS."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","sqs","dlq","event-source-mapping"]'::jsonb, 'ai-draft', 'active', now(), now()
)
