INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-002', 'aws-dva', 'Um desenvolvedor cria uma tabela Amazon DynamoDB com partition key ''userId'' e precisa consultar frequentemente itens por ''email'' (atributo não-chave). A consulta deve ser eficiente sem usar Scan. Qual abordagem atende?',
  '[{"id":"A","text":"Criar um Local Secondary Index (LSI) com ''email'' como sort key"},{"id":"B","text":"Criar um Global Secondary Index (GSI) com ''email'' como partition key"},{"id":"C","text":"Usar DynamoDB Streams para indexar manualmente"},{"id":"D","text":"Habilitar DAX e fazer Scan; o cache resolve"}]'::jsonb, 'B',
  '"(a) GSI permite partition key diferente da base table (aqui ''email''), suportando Query eficiente sem Scan. (b) LSI compartilha a partition key da base table e só permite outra sort key — não resolve consulta por ''email'' diretamente. Streams é CDC para downstream, não índice de leitura. DAX é cache em memória para Query/GetItem, não acelera Scan no nível de I/O lógico (Scan continua lendo a tabela toda). (c) Regra: precisa Query por chave diferente da partition key da base → GSI. (d) Ver docs DynamoDB."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["dynamodb","gsi","lsi","query"]'::jsonb, 'ai-draft', 'active', now(), now()
)
