INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-003', 'aws-dva', 'Uma aplicação em Amazon EC2 (conta A) precisa fazer GetObject em um bucket S3 da conta B. A bucket policy autoriza a role da conta A. Mesmo assim, chamadas retornam AccessDenied. CloudTrail confirma que a chamada usa a role correta. Qual é a causa mais provável?',
  '[{"id":"A","text":"A bucket policy precisa conceder também s3:ListBucket"},{"id":"B","text":"O bucket tem Block Public Access habilitado"},{"id":"C","text":"A IAM policy da role na conta A não concede s3:GetObject no ARN do bucket/object"},{"id":"D","text":"A role precisa de sts:AssumeRole para a conta B"}]'::jsonb, 'C',
  '"(a) Cross-account S3 exige permissão nos dois lados — bucket policy (já OK) E IAM policy da role chamadora. Se a IAM policy não cita s3:GetObject no resource correto, AccessDenied mesmo com bucket policy permissiva. (b) ListBucket é outra ação (lista chaves). BPA não bloqueia acesso autenticado cross-account explicitamente permitido. AssumeRole não é necessário aqui — a EC2 já usa instance profile na conta A. (c) Regra: cross-account = permissão dos dois lados (identity-based + resource-based). (d) Ver docs S3 + IAM."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["s3","iam","cross-account","access-denied"]'::jsonb, 'ai-draft', 'active', now(), now()
)
