INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-004', 'aws-dva', 'Um desenvolvedor precisa permitir que um cliente web público faça upload direto de arquivos grandes (até 5 GB) para o S3, sem que o servidor backend manipule o objeto, e com expiração de 15 minutos na permissão de upload. Qual abordagem atende?',
  '[{"id":"A","text":"Adicionar permissão PutObject anônima na bucket policy"},{"id":"B","text":"Compartilhar as access keys de um IAM user com permissão de upload"},{"id":"C","text":"Usar S3 Transfer Acceleration sem autenticação"},{"id":"D","text":"Gerar uma presigned URL para PutObject com expiração de 900 segundos"}]'::jsonb, 'D',
  '"(a) Presigned URLs são assinadas com credenciais do backend e carregam expiração — o cliente sobe direto pro S3 sem ver credencial e sem backend bytestream; suporta multipart para objetos grandes. (b) Bucket pública anônima é vazamento de segurança grave. Compartilhar access keys quebra least privilege. Transfer Acceleration acelera upload mas exige credenciais — não substitui a presigned URL. (c) Regra: upload temporário autorizado por terceiro = presigned URL. (d) Ver docs S3 presigned URLs."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["s3","presigned-url","upload"]'::jsonb, 'ai-draft', 'active', now(), now()
)
