INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-005', 'aws-dva', 'Uma aplicação web usa Amazon Cognito User Pools para autenticação. Após login bem-sucedido, o frontend recebe um ID Token, Access Token e Refresh Token. Para chamar uma API protegida por API Gateway com autorizador Cognito, qual token o cliente deve enviar no header Authorization?',
  '[{"id":"A","text":"Access Token, que carrega scopes e identidade"},{"id":"B","text":"Refresh Token"},{"id":"C","text":"ID Token, contendo as claims do usuário"},{"id":"D","text":"Qualquer um dos três é aceito"}]'::jsonb, 'A',
  '"(a) Access Token (OAuth 2.0) é o token destinado a autorizar chamadas a APIs — carrega scopes; é o que API Gateway com Cognito Authorizer valida por padrão para autorização baseada em scope. ID Token (OIDC) é destinado ao client da app para identificar o usuário, não para autorizar APIs. Refresh Token é só para obter novos access/id tokens. (b) Embora ID Token funcione em alguns setups COGNITO_USER_POOLS authorizer, o token correto e padronizado para autorização de API é o Access Token. (c) Regra: ID = identidade no client; Access = autorização em API. (d) Ver docs Cognito + API Gateway."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito","api-gateway","jwt","oauth2"]'::jsonb, 'ai-draft', 'active', now(), now()
)
