INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-006', 'aws-dva', 'Um pipeline AWS CodePipeline tem três stages: Source (CodeCommit), Build (CodeBuild) e Deploy (CodeDeploy para EC2). O time precisa que o Build rode em paralelo dois jobs (testes unitários e linter) antes do Deploy. Qual recurso permite essa paralelização dentro do mesmo stage?',
  '[{"id":"A","text":"Criar dois stages separados, um para cada job"},{"id":"B","text":"Adicionar duas actions em paralelo dentro do stage Build, ambas com runOrder=1"},{"id":"C","text":"Usar uma única action de CodeBuild com dois buildspecs"},{"id":"D","text":"Habilitar manual approval entre as actions"}]'::jsonb, 'B',
  '"(a) Actions com o mesmo runOrder dentro do mesmo stage executam em paralelo; runOrder diferente força sequencial. (b) Dois stages separados também rodariam sequencial. Buildspec único bloqueia paralelização nativa (rodaria sequencial no mesmo container). Manual approval é gate humano, não paralelização. (c) Regra: paralelismo em CodePipeline = mesmo stage + mesmo runOrder. (d) Ver docs CodePipeline."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codepipeline","codebuild","parallel"]'::jsonb, 'ai-draft', 'active', now(), now()
)
