INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-007', 'aws-dva', 'Um deploy AWS CodeDeploy em instâncias EC2 está usando a estratégia in-place. O time quer reduzir o risco de uma versão ruim afetar 100% das instâncias simultaneamente e voltar atrás rapidamente em caso de falha. Qual deployment configuration atende melhor?',
  '[{"id":"A","text":"CodeDeployDefault.AllAtOnce"},{"id":"B","text":"CodeDeployDefault.OneAtATime"},{"id":"C","text":"CodeDeployDefault.HalfAtATime com automatic rollback habilitado"},{"id":"D","text":"Manual deploy com SSH em cada instância"}]'::jsonb, 'C',
  '"(a) HalfAtATime distribui em duas ondas — se a primeira falhar e rollback automático estiver ligado, só metade foi afetada e a versão anterior é redeployada. (b) AllAtOnce é o mais arriscado (100% simultâneo). OneAtATime é mais seguro mas extremamente lento em frota grande. SSH manual quebra automação e auditoria. (c) Tradeoff: granularidade de rollout vs tempo total. HalfAtATime equilibra. Para risco mínimo, blue/green é ainda melhor (mas exige refactoring de infra). (d) Ver docs CodeDeploy."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["codedeploy","deployment-config","rollback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
