INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-008', 'aws-dva', 'Um template AWS SAM define uma função Lambda e quer disponibilizar duas versões de produção: 90% do tráfego na versão estável e 10% na nova (canary). Qual recurso do SAM/Lambda implementa isso de forma declarativa?',
  '[{"id":"A","text":"Criar dois aliases distintos apontando para a mesma versão"},{"id":"B","text":"Configurar route53 weighted routing apontando para duas funções"},{"id":"C","text":"Duplicar a função com nomes diferentes"},{"id":"D","text":"Usar AutoPublishAlias + DeploymentPreference do tipo Canary10Percent10Minutes em SAM"}]'::jsonb, 'D',
  '"(a) AWS::Serverless::Function suporta AutoPublishAlias (publica nova Version a cada deploy) + DeploymentPreference (Canary10Percent10Minutes, Linear10PercentEvery1Minute, AllAtOnce) — CodeDeploy faz o traffic shifting entre Versions via Alias. (b) Dois aliases para mesma version não dividem tráfego. Route53 weighted é DNS, não API call routing direto de Lambda. Duplicar função quebra observabilidade e idempotência. (c) Regra: canary de Lambda = Alias com routing config + CodeDeploy. (d) Ver docs SAM Safe Deployments."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'best-practice', '["sam","lambda","canary","alias","codedeploy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
