INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-009', 'aws-dva', 'Uma aplicação chama 4 microsserviços em sequência via HTTP. O time quer ver, em uma única visualização, o tempo gasto em cada hop e identificar qual é o gargalo, incluindo chamadas a DynamoDB e SQS feitas dentro dos serviços. Qual configuração entrega isso?',
  '[{"id":"A","text":"Habilitar AWS X-Ray e instrumentar cada serviço com o SDK; ativar Active Tracing em Lambda/API Gateway"},{"id":"B","text":"Configurar Amazon CloudWatch Logs com Log Insights queries entre os serviços"},{"id":"C","text":"Usar AWS CloudTrail para correlacionar chamadas API"},{"id":"D","text":"Habilitar VPC Flow Logs em todas as subnets"}]'::jsonb, 'A',
  '"(a) X-Ray gera service map e traces com segments por hop, incluindo subsegments para chamadas a SDK (DynamoDB, SQS, S3) — única view distribuída. (b) Logs Insights consulta logs mas não monta service map nem mede latência por subsegment automaticamente. CloudTrail é auditoria de chamadas de management plane, não tracing de aplicação. Flow Logs é tráfego L3/L4, sem semântica de aplicação. (c) Regra: tracing distribuído de aplicação = X-Ray. (d) Ver docs X-Ray."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["x-ray","distributed-tracing","observability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
