INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-010', 'aws-dva', 'Uma função Lambda em produção tem p99 de latência variando muito por causa de cold starts. A função é crítica e recebe ~500 req/min com picos previsíveis às 9h. Qual configuração reduz cold starts no horário de pico sem pagar por capacidade ociosa fora dele?',
  '[{"id":"A","text":"Habilitar Reserved Concurrency em 100"},{"id":"B","text":"Habilitar Provisioned Concurrency com Application Auto Scaling agendado para 8h45-10h"},{"id":"C","text":"Migrar a função para uma EC2 t3.medium em Auto Scaling"},{"id":"D","text":"Aumentar o memorySize da função para 10240 MB"}]'::jsonb, 'B',
  '"(a) Provisioned Concurrency mantém um pool de execution environments pré-inicializados (sem cold start). Application Auto Scaling com schedule permite ligar PC só na janela de pico — custo controlado. (b) Reserved Concurrency limita paralelismo, não previne cold starts. Migrar para EC2 perde benefícios serverless. Aumentar memória reduz duração mas não elimina cold start (e cobra mais sempre). (c) Regra: cold start crítico em janela previsível = PC agendada. (d) Ver docs Lambda."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'scenario', '["lambda","provisioned-concurrency","cold-start","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
