INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-011', 'aws-dva', 'Um desenvolvedor precisa armazenar uma senha de banco de dados que deve ser rotacionada automaticamente a cada 30 dias e acessada pela aplicação em runtime. Qual serviço AWS atende esse requisito de forma nativa?',
  '[{"id":"A","text":"AWS Systems Manager Parameter Store standard tier"},{"id":"B","text":"Variável de ambiente da função Lambda"},{"id":"C","text":"AWS Secrets Manager com rotation Lambda integrada"},{"id":"D","text":"Tag de instância EC2 com a senha"}]'::jsonb, 'C',
  '"(a) Secrets Manager tem rotation built-in com Lambdas pré-prontas para RDS/DocumentDB/Redshift e suporta rotation custom. (b) Parameter Store standard não tem rotation nativo (advanced tier ainda exige automação manual). Variáveis de ambiente em Lambda são plaintext e estáticas (e visíveis no console). Tag em EC2 é texto livre, sem criptografia ou rotation. (c) Regra: rotação automática de credencial = Secrets Manager. Parameter Store é melhor para config simples não-sensível. (d) Ver docs Secrets Manager."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["secrets-manager","rotation","credentials"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
