INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-012', 'aws-dva', 'Uma função Lambda dentro de uma VPC privada precisa acessar uma API externa na internet, mas timeout consistente ocorre. A função está em subnet privada sem rota para 0.0.0.0/0. Qual ajuste resolve mantendo a função na VPC?',
  '[{"id":"A","text":"Adicionar IAM permission lambda:InvokeFunction"},{"id":"B","text":"Colocar a função em subnet pública para ter IP público"},{"id":"C","text":"Aumentar memória da função para 1024 MB"},{"id":"D","text":"Roteamento da subnet privada via NAT Gateway em subnet pública"}]'::jsonb, 'D',
  '"(a) Funções Lambda em VPC privada não recebem IP público mesmo em subnet pública — precisam de NAT Gateway (em subnet pública com IGW) para egress à internet, e route table da subnet privada deve apontar 0.0.0.0/0 → NAT Gateway. (b) IAM permission não resolve rede. Mover para subnet pública não dá conectividade pra Lambda (limitação documentada). Memória não é problema de rede. (c) Regra: Lambda em VPC + internet = NAT Gateway. Para Lambda fora de VPC, internet é default. (d) Ver docs Lambda VPC."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","vpc","nat-gateway","networking"]'::jsonb, 'ai-draft', 'active', now(), now()
)
