INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-013', 'aws-dva', 'Uma API REST construída em API Gateway tem endpoints que retornam dados que mudam raramente (uma vez por hora). O time quer reduzir latência e custo de chamadas backend. Qual feature do API Gateway atende?',
  '[{"id":"A","text":"Habilitar caching de stage com TTL=3600s"},{"id":"B","text":"Aumentar throttle limit de requests por segundo"},{"id":"C","text":"Trocar de REST API para HTTP API"},{"id":"D","text":"Configurar usage plan com API key"}]'::jsonb, 'A',
  '"(a) Caching de stage no API Gateway armazena respostas no edge do API e responde sem chamar o backend até o TTL expirar — reduz latência e custo de invocação Lambda/EC2 atrás. (b) Throttle limita rate, não reduz custo de chamadas válidas. HTTP API é mais barato mas sem cache nativo. Usage plan é monetização/quota, não cache. (c) Regra: dado pouco volátil + API REST = stage caching. (d) Ver docs API Gateway."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["api-gateway","cache","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
