INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-014', 'aws-dva', 'Uma aplicação publica eventos para múltiplos consumidores (3 microsserviços) e quer fanout assíncrono confiável, onde cada consumidor processa no seu próprio ritmo e pode reprocessar falhas. Qual padrão AWS implementa isso?',
  '[{"id":"A","text":"API Gateway com 3 integrations diretas"},{"id":"B","text":"Publicar em um tópico Amazon SNS com 3 filas Amazon SQS subscritas (fanout SNS→SQS)"},{"id":"C","text":"Publicar em um stream Amazon Kinesis e os 3 serviços consomem com mesmo shard iterator"},{"id":"D","text":"AWS Step Functions com 3 branches paralelos"}]'::jsonb, 'B',
  '"(a) SNS faz fanout pub/sub; cada SQS subscrita recebe cópia da mensagem e cada consumidor processa de forma independente, com retry + DLQ por fila. (b) API Gateway com integrations diretas é síncrono. Kinesis funciona mas exige consumer apps com checkpointing por shard — overkill para fanout simples. Step Functions é orquestração de workflow, não fanout sustentado de eventos. (c) Regra: fanout assíncrono desacoplado por consumidor = SNS→SQS. EventBridge também serve quando há regras/filtros. (d) Ver docs SNS + SQS."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["sns","sqs","fanout","pub-sub"]'::jsonb, 'ai-draft', 'active', now(), now()
)
