INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-015', 'aws-dva', 'Um desenvolvedor escreve em DynamoDB e ocasionalmente recebe ProvisionedThroughputExceededException em horário de pico. A tabela está em modo Provisioned com WCU/RCU fixos. O time quer absorver picos imprevisíveis sem rebaixar performance. Qual mudança resolve?',
  '[{"id":"A","text":"Reduzir o WCU para forçar consumo distribuído"},{"id":"B","text":"Desabilitar streams para reduzir overhead"},{"id":"C","text":"Migrar a tabela para modo On-Demand capacity"},{"id":"D","text":"Trocar partition key por uma string fixa para concentrar a partição"}]'::jsonb, 'C',
  '"(a) On-Demand escala automaticamente o throughput de leitura/escrita sem capacity planning — ideal para picos imprevisíveis. Alternativa: manter Provisioned + Auto Scaling agressivo, mas On-Demand é o ajuste mais direto para o problema descrito. (b) Reduzir WCU agrava o throttling. Streams não afeta throughput de leitura/escrita base. Partition key fixa cria hot partition e piora throttling. (c) Regra: tráfego imprevisível e bursty = On-Demand; tráfego estável e previsível = Provisioned. (d) Ver docs DynamoDB Capacity Modes."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["dynamodb","capacity-mode","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
