INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-001', 'aws-dva', 'Uma equipe quer que cada commit na branch main do CodeCommit dispare automaticamente um pipeline que executa build no CodeBuild e deploy no CodeDeploy. Qual é a forma recomendada de detectar o commit e iniciar o pipeline com a menor latência?',
  '[{"id":"A","text":"Configurar uma source action no CodePipeline com detecção via Amazon EventBridge"},{"id":"B","text":"Configurar polling periódico do CodeCommit no source action do pipeline"},{"id":"C","text":"Criar uma Lambda agendada a cada 5 minutos que lista commits e dispara start-pipeline-execution"},{"id":"D","text":"Usar um webhook customizado no servidor CodeCommit chamando a API do CodePipeline"}]'::jsonb, 'A',
  '"(a) O CodePipeline integra com EventBridge para detectar commits no CodeCommit quase em tempo real — é o método default e recomendado pela AWS. (b) Polling foi o método antigo, tem latência de até um minuto e é desencorajado. Lambda agendada introduz complexidade desnecessária e atraso. CodeCommit não suporta webhooks customizados como GitHub. (c) Regra: source CodeCommit → escolher CloudWatch Events/EventBridge no pipeline. (d) Ver CodePipeline User Guide — Source actions."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["codepipeline","codecommit","eventbridge"]'::jsonb, 'ai-draft', 'active', now(), now()
)
