INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-002', 'aws-dva', 'Um buildspec.yml do CodeBuild precisa instalar dependências, rodar testes unitários e empacotar artefatos. Em quais phases esses passos devem ficar respectivamente?',
  '[{"id":"A","text":"pre_build, build, post_build"},{"id":"B","text":"install, build, post_build"},{"id":"C","text":"install, pre_build, build"},{"id":"D","text":"build, test, deploy"}]'::jsonb, 'B',
  '"(a) O buildspec define phases: install (instalar runtimes/deps), pre_build (login em registry, etc.), build (compilar/testar), post_build (empacotar, notificar). Convenção comum: deps em install, testes em build, empacotamento em post_build. (b) pre_build é para login em ECR e similares — não para instalar dependências. test/deploy não são phases válidas no buildspec. (c) Regra: install/pre_build/build/post_build são as 4 phases canônicas. (d) Ver CodeBuild User Guide — Build spec reference."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["codebuild","buildspec"]'::jsonb, 'ai-draft', 'active', now(), now()
)
