INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-003', 'aws-dva', 'Um CodeDeploy deployment para uma frota EC2 está falhando no hook BeforeInstall com timeout. O developer verifica que o script em appspec.yml chama um wget de 500 MB de um repositório externo. Qual ajuste resolve sem mudar a arquitetura?',
  '[{"id":"A","text":"Mover o download para o hook AfterInstall"},{"id":"B","text":"Trocar o deployment group de in-place para blue/green"},{"id":"C","text":"Aumentar o timeout do hook em appspec.yml na linha ''timeout: \u003csegundos\u003e''"},{"id":"D","text":"Remover o hook BeforeInstall do appspec.yml"}]'::jsonb, 'C',
  '"(a) Cada hook em appspec.yml aceita campo timeout em segundos (padrão 3600s). Se o download legítimo excede o tempo do step, aumentar o timeout é o ajuste correto. (b) AfterInstall tem mesmo problema; blue/green não muda comportamento do hook; remover quebra a etapa necessária. (c) Regra: appspec hooks têm timeout configurável por hook, e BeforeInstall é o lugar canônico para baixar artefatos antes do app ser copiado. (d) Ver CodeDeploy User Guide — AppSpec hooks."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'troubleshoot', '["codedeploy","appspec","hooks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
