INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-004', 'aws-dva', 'Uma equipe configura CodePipeline com source CodeCommit, build CodeBuild e deploy CloudFormation. O build falha com ''AccessDenied: not authorized to perform s3:PutObject''. Onde está o problema?',
  '[{"id":"A","text":"Role do CodePipeline não tem permissão para ler do CodeCommit"},{"id":"B","text":"Bucket policy do S3 está bloqueando uploads de qualquer principal"},{"id":"C","text":"A trust policy do CodeBuild não inclui o principal codepipeline.amazonaws.com"},{"id":"D","text":"Service role do CodeBuild não tem permissão para escrever no artifact bucket do pipeline"}]'::jsonb, 'D',
  '"(a) CodeBuild precisa escrever artefatos no bucket do pipeline (codepipeline-region-xxx). Sua service role precisa de s3:PutObject/GetObject nesse bucket. (b) Permissão do CodeCommit é do pipeline, não do build, e o erro é em s3. Bucket policy bloqueando geral causaria erro em qualquer ação. Trust policy do CodeBuild deve listar codebuild.amazonaws.com, não codepipeline. (c) Regra: cada stage usa sua própria service role; falha de PutObject no build = role do CodeBuild. (d) Ver CodeBuild User Guide — Identity and access management."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'troubleshoot', '["codebuild","iam","service-role"]'::jsonb, 'ai-draft', 'active', now(), now()
)
