INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-005', 'aws-dva', 'Um developer quer rodar testes de integração em paralelo com testes de unidade no CodeBuild para reduzir o tempo total. Qual recurso é mais apropriado?',
  '[{"id":"A","text":"CodeBuild batch builds com build-graph"},{"id":"B","text":"Executar dois pipelines diferentes em paralelo"},{"id":"C","text":"Usar --parallel no comando npm test"},{"id":"D","text":"Criar uma Lambda que invoca dois builds simultaneamente"}]'::jsonb, 'A',
  '"(a) Batch builds permitem definir um grafo de jobs paralelos/dependentes em uma única build configuration, com cada job rodando em containers separados — ideal para paralelizar test suites. (b) Dois pipelines duplica overhead e dificulta correlação. --parallel só ajuda dentro de um único container. Lambda funciona mas não é a abstração nativa. (c) Regra: CodeBuild batch (build-list, build-graph, build-matrix) é o mecanismo oficial para builds paralelos. (d) Ver CodeBuild User Guide — Batch builds."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codebuild","batch-builds","parallel"]'::jsonb, 'ai-draft', 'active', now(), now()
)
