INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-006', 'aws-dva', 'Uma aplicação Java é compilada no CodeBuild. O build é lento porque baixa todas as dependências do Maven em todo run. Qual configuração reduz o tempo de build de forma persistente?',
  '[{"id":"A","text":"Aumentar o compute type para BUILD_GENERAL1_LARGE"},{"id":"B","text":"Configurar cache do tipo S3 ou LOCAL_CUSTOM_CACHE apontando para ~/.m2/repository no buildspec"},{"id":"C","text":"Mudar a imagem para aws/codebuild/amazonlinux2-x86_64-standard:5.0"},{"id":"D","text":"Adicionar mvn dependency:go-offline no install phase sem cache"}]'::jsonb, 'B',
  '"(a) CodeBuild suporta cache S3 (persistente entre builds) e cache local (Docker layer, source, custom paths). Cachear ~/.m2/repository evita re-download de jars Maven. (b) Compute maior acelera CPU mas continua baixando deps. Trocar imagem não cacheia. go-offline sem cache só pré-baixa no mesmo run, sem persistir. (c) Regra: cache.type=S3 + paths em buildspec é o padrão para deps de pacote (npm, pip, maven). (d) Ver CodeBuild User Guide — Build caching."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codebuild","cache","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
