INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-007', 'aws-dva', 'Em um deploy CodeDeploy in-place para EC2 com Auto Scaling Group, instâncias novas que escalam durante o deploy não recebem a versão correta. Qual configuração corrige isso?',
  '[{"id":"A","text":"Aumentar o cooldown do ASG para 30 minutos"},{"id":"B","text":"Desligar o scale-out durante o deploy"},{"id":"C","text":"Associar o Auto Scaling Group ao CodeDeploy deployment group; o agent aplica a última revisão"},{"id":"D","text":"Trocar AMI para amazon-linux-2023 com agent pré-instalado"}]'::jsonb, 'C',
  '"(a) Quando se associa o ASG ao deployment group, o CodeDeploy auto-aplica a última revisão bem-sucedida em qualquer instância nova lançada — resolve o gap entre deploy e scale-out. (b) Cooldown não previne instâncias novas; desligar scale-out fere availability; AMI com agent ajuda mas não conecta ASG ao deployment group. (c) Regra: deployment group pode ter EC2 tags + Auto Scaling groups como targets, e ASG é a forma de cobrir scaling events. (d) Ver CodeDeploy User Guide — Integrating CodeDeploy with Auto Scaling."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codedeploy","asg","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()
)
