INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-008', 'aws-dva', 'Um pipeline tem stages Source → Build → Deploy-Staging → Deploy-Prod. A equipe quer revisão humana antes do Deploy-Prod. Qual action é a correta?',
  '[{"id":"A","text":"Configurar uma Lambda invoke action que abre um ticket Jira e espera resposta"},{"id":"B","text":"Dividir em dois pipelines e iniciar o segundo manualmente"},{"id":"C","text":"Adicionar uma Test action com critério obrigatório de aprovação"},{"id":"D","text":"Adicionar uma manual approval action entre Deploy-Staging e Deploy-Prod"}]'::jsonb, 'D',
  '"(a) CodePipeline tem action type Approval (manual) nativa que pausa o pipeline e envia notificação SNS opcional até alguém clicar Approve/Reject. (b) Lambda invoke action pode polar status mas Approval action é nativa e mais simples. Dois pipelines aumenta complexidade. Test action é para testes automatizados, não revisão humana. (c) Regra: para gates humanos, sempre usar Approval action. (d) Ver CodePipeline User Guide — Manage approval actions."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["codepipeline","approval","manual-gate"]'::jsonb, 'ai-draft', 'active', now(), now()
)
