INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-009', 'aws-dva', 'Um buildspec.yml precisa expor uma variável OUTPUT_BUCKET para a stage seguinte do CodePipeline. Como o developer transmite essa variável corretamente?',
  '[{"id":"A","text":"Declarar ''exported-variables'' no buildspec e referenciar #{BuildVariables.OUTPUT_BUCKET} na próxima stage"},{"id":"B","text":"Salvar em /tmp/output_bucket e ler na próxima stage"},{"id":"C","text":"Usar AWS Systems Manager Parameter Store sem mais nada"},{"id":"D","text":"Echo da variável; o pipeline captura automaticamente"}]'::jsonb, 'A',
  '"(a) CodeBuild exporta variáveis declaradas em env.exported-variables; o CodePipeline disponibiliza essas variáveis a stages seguintes via namespace e sintaxe #{namespace.var}. (b) Filesystem do build não persiste entre stages. Parameter Store funciona mas exige escrita explícita e leitura — não é o mecanismo nativo. Echo não captura nada. (c) Regra: exported-variables + variable namespace do action é a forma oficial de passar valores entre stages. (d) Ver CodePipeline User Guide — Variables."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["codepipeline","codebuild","variables"]'::jsonb, 'ai-draft', 'active', now(), now()
)
