INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-010', 'aws-dva', 'Um repositório CodeCommit precisa ser acessado por developers usando IAM credentials via HTTPS. Qual é a forma recomendada de autenticar git push/pull?',
  '[{"id":"A","text":"Gerar long-lived access keys para cada developer e usar em git config"},{"id":"B","text":"Configurar git-remote-codecommit ou git credential helper aws codecommit credential-helper"},{"id":"C","text":"Usar HTTPS git credentials (username/password) gerados no IAM console"},{"id":"D","text":"Compartilhar a SSH key da service role do pipeline"}]'::jsonb, 'B',
  '"(a) git-remote-codecommit (GRC) ou o credential helper da AWS CLI usam credenciais IAM/STS temporárias automaticamente — é o método mais seguro recomendado. (b) Access keys long-lived em git config são antipadrão; HTTPS git credentials existem mas são chave estática por usuário e menos seguras que GRC; compartilhar SSH key viola least privilege. (c) Regra: para devs locais, usar GRC; para CI, IAM role. (d) Ver CodeCommit User Guide — Setup for HTTPS users using GRC."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["codecommit","iam","git"]'::jsonb, 'ai-draft', 'active', now(), now()
)
