INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-011', 'aws-dva', 'Um pipeline precisa fazer deploy de uma stack CloudFormation com parâmetros calculados pelo build. Qual configuração na action CloudFormation Deploy permite isso?',
  '[{"id":"A","text":"Passar os parâmetros como variáveis de ambiente do CodeBuild"},{"id":"B","text":"Hardcode os parâmetros no template YAML antes do deploy"},{"id":"C","text":"Configurar TemplateConfiguration apontando para um JSON gerado no build com Parameters e StackPolicy"},{"id":"D","text":"Usar SSM Parameter Store dynamic references no template diretamente"}]'::jsonb, 'C',
  '"(a) A action CloudFormation no CodePipeline aceita um arquivo TemplateConfiguration (JSON) com chaves Parameters, Tags e StackPolicy — produzido pelo build e referenciado como input artifact. (b) Env vars do build não chegam à action CloudFormation diretamente. Hardcode quebra o objetivo de parametrizar. SSM dynamic references funcionam para resolver no deploy mas não cobrem valores calculados no build. (c) Regra: TemplateConfiguration JSON é o canal oficial para parâmetros dinâmicos. (d) Ver CodePipeline User Guide — AWS CloudFormation deploy action."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["codepipeline","cloudformation","parameters"]'::jsonb, 'ai-draft', 'active', now(), now()
)
