INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-012', 'aws-dva', 'Um deploy CodeDeploy blue/green em uma frota EC2 detecta falha no hook ValidateService. Qual é o comportamento default da configuração ''Rollback on alarm'' e do ''Original instances termination wait time''?',
  '[{"id":"A","text":"A frota blue é terminada imediatamente; a green continua recebendo traffic"},{"id":"B","text":"O deploy fica pausado indefinidamente até intervenção manual"},{"id":"C","text":"O CodeDeploy faz force replace da AMI e reinicia o deploy"},{"id":"D","text":"O traffic volta para a frota blue (original) e a green é mantida temporariamente para investigação"}]'::jsonb, 'D',
  '"(a) Falha em hook após shift de traffic dispara rollback: traffic retorna para o blue (instances originais) e o green (replacement) fica aguardando termination wait time para troubleshooting. (b) Inverte o comportamento — green com falha não recebe traffic. Pausa indefinida não é o padrão; replace de AMI não é função do CodeDeploy. (c) Regra: blue/green com hook fail = rollback automático, instâncias antigas reativadas. (d) Ver CodeDeploy User Guide — Blue/green deployments."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["codedeploy","blue-green","rollback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
