INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-013', 'aws-dva', 'Em CodeDeploy para Lambda, qual hook permite executar testes pós-traffic-shift antes que a deployment seja marcada como bem-sucedida?',
  '[{"id":"A","text":"AfterAllowTraffic"},{"id":"B","text":"BeforeAllowTraffic"},{"id":"C","text":"ValidateService"},{"id":"D","text":"AllowTraffic"}]'::jsonb, 'A',
  '"(a) Hooks Lambda do CodeDeploy: BeforeAllowTraffic (antes do shift), AfterAllowTraffic (depois do shift). Testes que precisam da versão recebendo tráfego ficam em AfterAllowTraffic. (b) BeforeAllowTraffic roda antes — testes lá não exercem o tráfego shifted. ValidateService é hook de EC2/On-Prem, não de Lambda. AllowTraffic é a ação, não um hook customizável. (c) Regra: Lambda tem apenas dois hooks (Before/After AllowTraffic). (d) Ver CodeDeploy User Guide — AppSpec for Lambda."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["codedeploy","lambda","hooks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
