INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-014', 'aws-dva', 'Uma deployment configuration CodeDeployDefault.LambdaCanary10Percent5Minutes faz o quê?',
  '[{"id":"A","text":"10% por minuto durante 5 minutos, linear"},{"id":"B","text":"10% do tráfego vai para a nova versão; após 5 minutos, 100% é shifted"},{"id":"C","text":"10% do tráfego permanece na nova versão por 5 minutos, sem completar shift"},{"id":"D","text":"5% nos primeiros 10 minutos e depois 100%"}]'::jsonb, 'B',
  '"(a) Canary <X>Percent<Y>Minutes: shift inicial de X% por Y minutos (bake time), depois shift dos 100% restantes. Canary10Percent5Minutes = 10% por 5 min, depois 100%. (b) Esse padrão é Linear (LinearXPercentEveryYMinutes). 10% que nunca completa não é canary. Os números invertidos não correspondem ao nome. (c) Regra: Canary = duas etapas (X% → 100%); Linear = incrementos repetidos até 100%. (d) Ver CodeDeploy User Guide — Deployment configurations."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["codedeploy","lambda","canary"]'::jsonb, 'ai-draft', 'active', now(), now()
)
