INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-015', 'aws-dva', 'Um deploy Lambda usa CodeDeploy com canary. Durante o bake time, um CloudWatch alarm relacionado a erros 5xx dispara. Qual é o comportamento esperado se o deployment group está configurado com auto-rollback on alarm?',
  '[{"id":"A","text":"O deploy continua mas envia notificação SNS de alerta"},{"id":"B","text":"O traffic pausa em 50% até o alarm se resolver"},{"id":"C","text":"O alias é revertido para a versão anterior automaticamente"},{"id":"D","text":"Lambda escala automaticamente para absorver os erros"}]'::jsonb, 'C',
  '"(a) Auto-rollback on alarm desfaz o shift movendo o alias 100% para a versão anterior assim que qualquer alarm associado entra em ALARM. (b) Notificar sem rollback ignora o objetivo da configuração. Pausa em 50% não é comportamento do CodeDeploy Lambda. Escalar não resolve erro de código. (c) Regra: alarms + auto-rollback = mecanismo principal de safe deployment em Lambda. (d) Ver CodeDeploy User Guide — Monitoring deployments with CloudWatch alarms."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codedeploy","lambda","rollback","cloudwatch"]'::jsonb, 'ai-draft', 'active', now(), now()
)
