INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-016', 'aws-dva', 'Em uma stack CloudFormation, qual intrinsic function retorna a região AWS atual em runtime?',
  '[{"id":"A","text":"!GetAtt Stack.Region"},{"id":"B","text":"!Sub ${aws:region}"},{"id":"C","text":"!FindInMap [Regions, Default, Name]"},{"id":"D","text":"!Ref AWS::Region"}]'::jsonb, 'D',
  '"(a) AWS::Region é um pseudo parameter; !Ref AWS::Region retorna a região onde a stack está sendo criada. (b) GetAtt não opera sobre pseudo parameters. !Sub usa ${AWS::Region} (não aws:region em minúsculas). FindInMap exige Mappings explícitos e não cobre a região dinâmica. (c) Regra: pseudo parameters AWS::Region/AccountId/StackName/Partition são acessados via !Ref. (d) Ver CloudFormation User Guide — Pseudo parameters reference."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["cloudformation","intrinsic-functions","pseudo-parameters"]'::jsonb, 'ai-draft', 'active', now(), now()
)
