INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-017', 'aws-dva', 'Um template CloudFormation precisa montar o ARN de um bucket S3 a partir do nome lógico do recurso. Qual snippet está correto?',
  '[{"id":"A","text":"!Sub arn:${AWS::Partition}:s3:::${MyBucket}"},{"id":"B","text":"!Join ['''', [''arn:aws:s3:::'', !GetAtt MyBucket.Name]]"},{"id":"C","text":"!Ref MyBucket.Arn"},{"id":"D","text":"!ImportValue MyBucketArn"}]'::jsonb, 'A',
  '"(a) !Sub com pseudo parameter AWS::Partition (para suportar aws/aws-cn/aws-us-gov) e !Ref implícito ao nome do bucket é o padrão recomendado e portátil. (b) GetAtt MyBucket.Name não existe (o atributo é Arn ou DomainName, e o Ref já retorna o nome). !Ref retorna o nome, não Arn. ImportValue só serve para cross-stack quando o ARN foi exportado. (c) Regra: para ARNs de recursos, usar !GetAtt Resource.Arn quando suportado, ou !Sub para construir manualmente. (d) Ver CloudFormation User Guide — Fn::Sub."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cloudformation","intrinsic-functions","sub"]'::jsonb, 'ai-draft', 'active', now(), now()
)
