INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-018', 'aws-dva', 'Antes de aplicar mudanças em uma stack CloudFormation de produção, o developer quer revisar o impacto exato (resources que serão Modified/Replaced/Deleted). Qual mecanismo deve usar?',
  '[{"id":"A","text":"Rodar aws cloudformation validate-template"},{"id":"B","text":"Criar um Change Set e revisar a lista de resource changes antes de Execute"},{"id":"C","text":"Comparar manualmente o template antigo e o novo com diff"},{"id":"D","text":"Executar update-stack com --dry-run"}]'::jsonb, 'B',
  '"(a) Change Sets mostram exatamente quais resources serão Add/Modify/Remove e o tipo de update (No interruption, Some interruption, Replacement) — review controlado antes do execute. (b) validate-template só checa sintaxe YAML/JSON. Diff manual não infere se mudança causa replacement. update-stack não tem --dry-run. (c) Regra: para production updates, criar Change Set e Execute, nunca update-stack direto sem review. (d) Ver CloudFormation User Guide — Updating stacks using change sets."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["cloudformation","change-sets"]'::jsonb, 'ai-draft', 'active', now(), now()
)
