INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-019', 'aws-dva', 'Uma stack CloudFormation falha durante CREATE_IN_PROGRESS por um erro em um recurso. Qual é o comportamento default de OnFailure?',
  '[{"id":"A","text":"DO_NOTHING — mantém os recursos parciais para investigação"},{"id":"B","text":"DELETE — apaga a stack inteira imediatamente sem rollback intermediário"},{"id":"C","text":"ROLLBACK — deleta os recursos parcialmente criados e marca a stack como ROLLBACK_COMPLETE"},{"id":"D","text":"RETRY — tenta recriar três vezes antes de falhar"}]'::jsonb, 'C',
  '"(a) Default OnFailure de create-stack é ROLLBACK: CloudFormation reverte criando ROLLBACK_IN_PROGRESS e depois ROLLBACK_COMPLETE. (b) DO_NOTHING é opção válida mas não é default. DELETE existe mas remove direto sem etapa intermediária — também não é o default. RETRY automático não existe no CloudFormation. (c) Regra: aprenda DO_NOTHING vs ROLLBACK vs DELETE; default é ROLLBACK. (d) Ver CloudFormation User Guide — Stack failure options."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cloudformation","rollback","failure-handling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
