INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-020', 'aws-dva', 'Em uma stack CloudFormation, alguém modificou um Security Group manualmente no console. Como o developer detecta essa mudança via CloudFormation?',
  '[{"id":"A","text":"Rodar describe-stack-events e procurar UPDATE_FAILED"},{"id":"B","text":"Comparar o template original com a saída de get-template"},{"id":"C","text":"Aguardar a próxima update-stack falhar para detectar diferenças"},{"id":"D","text":"Executar drift detection na stack e revisar resources com status MODIFIED"}]'::jsonb, 'D',
  '"(a) Drift detection compara o estado real dos recursos com o template e expõe propriedades MODIFIED/DELETED — é o mecanismo oficial para detectar mudanças out-of-band. (b) stack-events lista history das ações do próprio CloudFormation, não mudanças manuais. get-template retorna o template salvo, não o estado real. Aguardar falha é reativo e arriscado. (c) Regra: para detectar configuration drift, sempre usar Drift Detection. (d) Ver CloudFormation User Guide — Detecting unmanaged configuration changes."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["cloudformation","drift-detection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
