INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-021', 'aws-dva', 'Em CloudFormation, uma stack precisa esperar que uma EC2 finalize uma instalação custom (cloud-init script) antes que outras resources sejam criadas. Qual recurso garante isso?',
  '[{"id":"A","text":"CreationPolicy com WaitCondition recebendo signal via cfn-signal"},{"id":"B","text":"DependsOn em todos os recursos posteriores"},{"id":"C","text":"UpdatePolicy com PauseTime: PT10M"},{"id":"D","text":"Metadata::AWS::CloudFormation::Init com fn::wait"}]'::jsonb, 'A',
  '"(a) CreationPolicy + cfn-signal permite que a EC2 sinalize sucesso/falha ao CloudFormation; a stack só prossegue após o signal ou timeout. (b) DependsOn ordena criação mas não espera scripts. UpdatePolicy é para ASG update; PauseTime não é absoluto. cfn-init não tem fn::wait. (c) Regra: para waitar instalação custom, usar CreationPolicy + cfn-signal (helper script do AWS CLI). (d) Ver CloudFormation User Guide — CreationPolicy attribute."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["cloudformation","creation-policy","cfn-signal"]'::jsonb, 'ai-draft', 'active', now(), now()
)
