INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-022', 'aws-dva', 'Um developer quer compartilhar o ARN de uma DynamoDB table criada em StackA com StackB na mesma região e conta. Qual mecanismo é o mais simples?',
  '[{"id":"A","text":"Salvar o ARN em SSM Parameter Store e ler com dynamic reference"},{"id":"B","text":"Outputs com Export em StackA e Fn::ImportValue em StackB"},{"id":"C","text":"Hardcode o ARN em StackB após criar StackA"},{"id":"D","text":"Usar Nested Stacks com TemplateURL apontando para StackA"}]'::jsonb, 'B',
  '"(a) Outputs.Export/ImportValue é o mecanismo nativo de cross-stack references em CloudFormation. (b) SSM funciona mas adiciona dependência externa. Hardcode acopla e quebra reusabilidade. Nested Stacks são para composição parent/child, não para compartilhar resources entre stacks independentes. (c) Regra: cross-stack = Export/Import; aninhamento parent-child = Nested Stacks. (d) Ver CloudFormation User Guide — Outputs and Fn::ImportValue."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["cloudformation","outputs","cross-stack"]'::jsonb, 'ai-draft', 'active', now(), now()
)
