INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-023', 'aws-dva', 'Em CloudFormation, qual condition function é usada para condicionalmente criar resources baseado em parâmetro ''EnvType''?',
  '[{"id":"A","text":"Usar Fn::If diretamente em Type do recurso"},{"id":"B","text":"Usar Metadata.Skip = true se EnvType != prod"},{"id":"C","text":"Definir Conditions com Fn::Equals e usar Condition: \u003cName\u003e no resource"},{"id":"D","text":"Definir múltiplos templates e selecionar via CLI flag"}]'::jsonb, 'C',
  '"(a) Bloco Conditions define expressões booleanas com Fn::Equals/And/Or/Not; resources/outputs ganham atributo Condition: <Name> que controla se serão criados. (b) Fn::If retorna valor condicional dentro de uma property, não habilita/desabilita o resource. Metadata.Skip não existe. Múltiplos templates aumenta divergência. (c) Regra: Conditions + Condition attribute = forma canônica. (d) Ver CloudFormation User Guide — Conditions."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cloudformation","conditions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
