INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-024', 'aws-dva', 'Uma stack contém um RDS DB instance e o developer rodou um update que mudou DBInstanceClass. CloudFormation iniciou Replacement e o snapshot final não foi criado. Como prevenir perda de dados em mudanças similares?',
  '[{"id":"A","text":"Trocar para UpdatePolicy: RollingUpdate"},{"id":"B","text":"Bloquear updates via Stack Policy"},{"id":"C","text":"Habilitar termination protection na stack"},{"id":"D","text":"Adicionar DeletionPolicy: Snapshot e UpdateReplacePolicy: Snapshot ao recurso"}]'::jsonb, 'D',
  '"(a) DeletionPolicy controla o que acontece quando o resource é deletado; UpdateReplacePolicy controla o que acontece quando update força replacement. Ambos com valor Snapshot preservam o dado em RDS/EBS/Redshift. (b) UpdatePolicy é para ASG/Lambda, não RDS. Stack Policy bloqueia mas não protege em delete autorizado. Termination protection protege a stack mas não recursos individuais em replacement. (c) Regra: para resources com dados, sempre definir DeletionPolicy E UpdateReplacePolicy. (d) Ver CloudFormation User Guide — UpdateReplacePolicy attribute."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'best-practice', '["cloudformation","deletion-policy","update-replace-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
