INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-025', 'aws-dva', 'Em CloudFormation, qual é a forma recomendada de referenciar uma senha de banco de dados que está armazenada em AWS Secrets Manager?',
  '[{"id":"A","text":"Dynamic reference ''{{resolve:secretsmanager:MySecret:SecretString:password}}'' no parâmetro"},{"id":"B","text":"Hardcode o valor em Parameters com NoEcho: true"},{"id":"C","text":"Adicionar uma Lambda-backed custom resource para buscar via SDK"},{"id":"D","text":"Usar Fn::GetSecret no template"}]'::jsonb, 'A',
  '"(a) Dynamic references resolvem secrets/SSM em tempo de deploy sem expor o valor no template. Suporta secretsmanager, ssm e ssm-secure. (b) NoEcho mascara em console mas o valor passa pelo template. Custom resource funciona mas é overkill. Fn::GetSecret não existe. (c) Regra: ''{{resolve:...}}'' é a sintaxe oficial e segura. (d) Ver CloudFormation User Guide — Using dynamic references."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["cloudformation","secrets-manager","dynamic-references"]'::jsonb, 'ai-draft', 'active', now(), now()
)
