INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-026', 'aws-dva', 'Uma stack CloudFormation está em UPDATE_ROLLBACK_FAILED após erro em rollback. Quais opções o developer tem para recuperar a stack sem deletá-la?',
  '[{"id":"A","text":"Rodar update-stack com o template original"},{"id":"B","text":"Executar continue-update-rollback indicando ResourcesToSkip dos recursos problemáticos"},{"id":"C","text":"Criar um drift report e aplicar manualmente"},{"id":"D","text":"Aguardar 24 horas; a stack auto-recupera"}]'::jsonb, 'B',
  '"(a) continue-update-rollback retoma o rollback; ResourcesToSkip permite pular resources que não conseguem voltar (deve-se reconciliá-los manualmente). É o único caminho oficial nesse estado. (b) Update-stack é bloqueado em UPDATE_ROLLBACK_FAILED. Drift apenas reporta. Stack não auto-recupera. (c) Regra: conhecer continue-update-rollback é alta prioridade no exame. (d) Ver CloudFormation User Guide — Continue rolling back an update."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'troubleshoot', '["cloudformation","rollback","recovery"]'::jsonb, 'ai-draft', 'active', now(), now()
)
