INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-027', 'aws-dva', 'Em SAM, um developer quer fazer deploy gradual de uma função Lambda usando 10% por minuto até 100%. Qual DeploymentPreference Type deve definir?',
  '[{"id":"A","text":"Canary10Percent1Minute"},{"id":"B","text":"AllAtOnce"},{"id":"C","text":"Linear10PercentEvery1Minute"},{"id":"D","text":"Gradual10PercentPerMinute"}]'::jsonb, 'C',
  '"(a) SAM expõe types pré-definidos: Linear<X>PercentEvery<Y>Minutes faz incrementos de X% a cada Y minutos. Linear10PercentEvery1Minute = 10 incrementos de 10% em 10 min. (b) Canary é shift X% inicial + 100% após bake time, não incremental. AllAtOnce é 100% imediato. Gradual10PercentPerMinute não existe. (c) Regra: Linear ≠ Canary; saber traduzir nome ↔ comportamento. (d) Ver SAM Developer Guide — DeploymentPreference."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["sam","deployment-preference","linear"]'::jsonb, 'ai-draft', 'active', now(), now()
)
