INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-028', 'aws-dva', 'Em SAM, AutoPublishAlias: live tem qual efeito ao fazer sam deploy?',
  '[{"id":"A","text":"SAM cria automaticamente um stage ''live'' no API Gateway"},{"id":"B","text":"SAM habilita provisioned concurrency no alias ''live''"},{"id":"C","text":"SAM mantém todas as versões anteriores ativas em paralelo"},{"id":"D","text":"SAM publica uma nova versão da Lambda a cada deploy e atualiza o alias ''live'' para apontar para ela"}]'::jsonb, 'D',
  '"(a) AutoPublishAlias instrui o SAM a criar uma nova versão imutável da função em cada deploy e movimentar o alias indicado para essa versão. Combinado com DeploymentPreference, o shift do alias usa CodeDeploy. (b) Stage do API Gateway é controlado por outras props. Provisioned concurrency é configurado em ProvisionedConcurrencyConfig. Versões anteriores ficam disponíveis mas não recebem tráfego. (c) Regra: AutoPublishAlias é pré-requisito para usar DeploymentPreference. (d) Ver SAM Developer Guide — AWS::Serverless::Function."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["sam","auto-publish-alias","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
