INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-029', 'aws-dva', 'Em SAM, qual hook do DeploymentPreference o developer usa para rodar testes pré-shift que devem aprovar antes de iniciar o canary?',
  '[{"id":"A","text":"Hooks.PreTraffic apontando para uma Lambda de validação"},{"id":"B","text":"Hooks.PostTraffic com função de smoke test"},{"id":"C","text":"Alarms apontando para CloudWatch alarms"},{"id":"D","text":"Triggers.BeforeInstall apontando para SNS topic"}]'::jsonb, 'A',
  '"(a) DeploymentPreference.Hooks tem PreTraffic (executa antes do shift) e PostTraffic (após). Lambda de validação retorna sucesso para liberar o shift. (b) PostTraffic roda depois — não bloqueia o início do shift. Alarms causam rollback se dispararem, mas não são pre-flight tests. Triggers.BeforeInstall é nomenclatura do CodeDeploy EC2, não SAM. (c) Regra: PreTraffic = gate antes; PostTraffic = validação depois. (d) Ver SAM Developer Guide — DeploymentPreference Hooks."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["sam","deployment-preference","hooks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
