INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-030', 'aws-dva', 'Em um sam template.yaml, o developer define Globals.Function.Runtime: nodejs20.x. Qual é o efeito?',
  '[{"id":"A","text":"Apenas a primeira função do template usa esse runtime"},{"id":"B","text":"Todas as AWS::Serverless::Function herdam Runtime: nodejs20.x salvo override individual"},{"id":"C","text":"Função obrigatoriamente fixa em nodejs20.x sem permitir override"},{"id":"D","text":"SAM rejeita o template; Globals não suporta Runtime"}]'::jsonb, 'B',
  '"(a) Globals define defaults aplicados a todos os resources do tipo correspondente; cada função pode sobrescrever propriedades individualmente. (b) Globals afeta todas, não a primeira. Override é permitido. Runtime é uma das props aceitas em Globals.Function. (c) Regra: Globals.Function reduz repetição em templates com muitas Lambdas. (d) Ver SAM Developer Guide — Globals section."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["sam","globals","template"]'::jsonb, 'ai-draft', 'active', now(), now()
)
