INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-031', 'aws-dva', 'O comando sam build vs sam package diferem em quê?',
  '[{"id":"A","text":"sam build deploya na nuvem; sam package só valida sintaxe"},{"id":"B","text":"Os dois fazem a mesma coisa e estão deprecated em favor de sam deploy"},{"id":"C","text":"sam build compila/empacota o código localmente; sam package faz upload de artefatos para S3 e gera template transformado"},{"id":"D","text":"sam build cria stack; sam package faz rollback"}]'::jsonb, 'C',
  '"(a) sam build prepara dependências e zipa código em .aws-sam/build/. sam package (equivalente ao cloudformation package) faz upload desses artefatos para S3 e produz um template com URIs S3 prontas para deploy. (b) sam build não deploya nada; sam package faz mais que validar. Ambos seguem ativos. sam package não faz rollback. (c) Regra: pipeline típico é build → package → deploy; sam deploy --guided faz package+deploy automaticamente. (d) Ver SAM Developer Guide — sam build / sam package."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["sam","cli"]'::jsonb, 'ai-draft', 'active', now(), now()
)
