INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-032', 'aws-dva', 'Um template SAM com transform AWS::Serverless-2016-10-31 produz erros em sam validate. Qual é a causa mais provável?',
  '[{"id":"A","text":"A região não suporta SAM"},{"id":"B","text":"AWS CLI está abaixo da versão 1.0"},{"id":"C","text":"SAM exige template em JSON, não YAML"},{"id":"D","text":"O template usa recursos AWS::Serverless::* sem a linha Transform: AWS::Serverless-2016-10-31 declarada"}]'::jsonb, 'D',
  '"(a) Sem a diretiva Transform: AWS::Serverless-2016-10-31, o CloudFormation não converte os tipos AWS::Serverless::* em recursos primitivos e o template falha. (b) SAM funciona em todas as regiões com CloudFormation. CLI tem versões muito mais recentes. SAM aceita YAML e JSON. (c) Regra: a primeira linha relevante de qualquer template SAM é o Transform. (d) Ver SAM Developer Guide — Anatomy of a SAM template."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'troubleshoot', '["sam","transform","template"]'::jsonb, 'ai-draft', 'active', now(), now()
)
