INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-033', 'aws-dva', 'Em SAM, uma função Lambda com Events.HttpApi: precisa rotear GET /users. Qual sintaxe é correta?',
  '[{"id":"A","text":"Events: { GetUsers: { Type: HttpApi, Properties: { Path: /users, Method: GET } } }"},{"id":"B","text":"Events: { Api: { Path: /users, Verb: GET } }"},{"id":"C","text":"Routes: [ ''/users:GET'' ]"},{"id":"D","text":"ApiGateway: { Endpoints: { ''/users'': ''GET'' } }"}]'::jsonb, 'A',
  '"(a) Cada event em SAM tem um Logical Id, um Type (HttpApi, Api, S3, SNS, etc.) e Properties com Path/Method. HttpApi cria um API Gateway HTTP API (v2). (b) Sintaxe inventada (Verb não existe). Routes/ApiGateway não são chaves SAM. (c) Regra: Events.<Name>.Type + Properties é o esquema universal. (d) Ver SAM Developer Guide — Function Events."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["sam","events","api-gateway"]'::jsonb, 'ai-draft', 'active', now(), now()
)
