INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-034', 'aws-dva', 'Após sam deploy, um developer quer testar a função Lambda localmente com o mesmo template. Qual comando inicia um endpoint HTTP local que simula API Gateway?',
  '[{"id":"A","text":"sam invoke local --endpoint http://localhost"},{"id":"B","text":"sam local start-api"},{"id":"C","text":"sam deploy --local"},{"id":"D","text":"lambda-local --template template.yaml"}]'::jsonb, 'B',
  '"(a) sam local start-api levanta um endpoint local em http://localhost:3000 que invoca containers Docker das funções definidas nos Events.Api. Também existe sam local start-lambda e sam local invoke. (b) Sintaxe inventada. sam deploy não tem --local. lambda-local não é o tooling oficial AWS. (c) Regra: sam local start-api (API), sam local start-lambda (Lambda invoke endpoint), sam local invoke (single invocation). (d) Ver SAM Developer Guide — Testing applications locally."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["sam","local-testing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
