INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-035', 'aws-dva', 'Um SAM template define uma função Lambda com Policies: [ AWSLambdaBasicExecutionRole, { S3ReadPolicy: { BucketName: !Ref MyBucket } } ]. O que SAM faz com S3ReadPolicy?',
  '[{"id":"A","text":"Rejeita o template porque policy templates não existem em SAM"},{"id":"B","text":"Cria um IAM user com leitura no bucket"},{"id":"C","text":"Aplica um SAM policy template pré-definido que concede s3:GetObject no bucket informado"},{"id":"D","text":"Aplica AdministratorAccess como fallback"}]'::jsonb, 'C',
  '"(a) SAM oferece policy templates (S3ReadPolicy, DynamoDBCrudPolicy, etc.) que se expandem em policies IAM mínimas com os recursos parametrizados. (b) Policy templates existem e são amplamente recomendados. SAM não cria IAM users. Não há fallback para AdministratorAccess. (c) Regra: usar policy templates é a forma idiomática de aplicar least privilege em SAM. (d) Ver SAM Developer Guide — Policy templates."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["sam","policy-templates","iam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
