INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-036', 'aws-dva', 'Em SAM, AutoPublishCodeSha256 é útil para qual cenário?',
  '[{"id":"A","text":"Desabilitar AutoPublishAlias"},{"id":"B","text":"Habilitar versioning no bucket S3 do código"},{"id":"C","text":"Validar o hash do código antes do deploy"},{"id":"D","text":"Forçar nova versão Lambda quando apenas variáveis de ambiente mudam (sem mudança no código)"}]'::jsonb, 'D',
  '"(a) Por padrão, Lambda detecta mudança no zip via CodeSha256; se apenas env vars mudam, nenhuma nova versão é criada e o alias permanece. AutoPublishCodeSha256 aceita um valor arbitrário que força nova versão mesmo sem mudança no código. (b) Não desabilita AutoPublishAlias. S3 versioning é independente. Hash validation é automático no Lambda. (c) Regra: usar AutoPublishCodeSha256 quando precisa republicar versão por outras razões. (d) Ver SAM Developer Guide — AutoPublishCodeSha256."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["sam","auto-publish","lambda-versions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
