INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-037', 'aws-dva', 'Um Elastic Beanstalk environment Web Server precisa de deploy com zero downtime e tolerância a falhas, sem dobrar custos. Qual deployment policy escolher?',
  '[{"id":"A","text":"Rolling with additional batch"},{"id":"B","text":"All at once"},{"id":"C","text":"Immutable"},{"id":"D","text":"Blue/Green via swap CNAME"}]'::jsonb, 'A',
  '"(a) Rolling with additional batch lança um batch extra antes de derrubar o primeiro, mantendo capacidade total durante o deploy — sem dobrar custos como Immutable/Blue-Green. (b) All-at-once causa downtime. Immutable é mais seguro mas duplica frota temporariamente (custos altos). Blue/Green via swap exige dois envs. (c) Regra: Rolling with additional batch = trade-off entre custo e safety. (d) Ver Elastic Beanstalk Developer Guide — Deployment policies."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["beanstalk","deployment-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
