INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-038', 'aws-dva', 'Em Elastic Beanstalk, onde o developer coloca arquivos .config para customizar instâncias (instalar packages, criar files, rodar commands)?',
  '[{"id":"A","text":"Em /etc/eb-config/ na instância EC2"},{"id":"B","text":"Na pasta .ebextensions/ na raiz do source bundle"},{"id":"C","text":"Em uma S3 bucket policy do ambiente"},{"id":"D","text":"No menu Configuration \u003e Software do console"}]'::jsonb, 'B',
  '"(a) Arquivos YAML em .ebextensions/ (ex: 01-packages.config) são processados pelo agent em cada instância e podem definir packages, files, commands, container_commands, option_settings e resources CloudFormation extras. (b) /etc/eb-config não é um caminho oficial. Bucket policy não customiza instância. Console mostra opções limitadas; .ebextensions cobre o caso geral. (c) Regra: .ebextensions é o mecanismo principal de customização declarativa. (d) Ver Elastic Beanstalk Developer Guide — Advanced environment customization."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["beanstalk","ebextensions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
