INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-039', 'aws-dva', 'Um app Beanstalk precisa rodar uma migration de banco APÓS o deploy do código mas ANTES do app iniciar. Qual mecanismo é mais apropriado?',
  '[{"id":"A","text":"commands em .ebextensions (rodam antes de extrair o app)"},{"id":"B","text":"Um cron job em /etc/cron.d/ adicionado via files"},{"id":"C","text":"container_commands em .ebextensions, que rodam após app deploy e antes do start"},{"id":"D","text":"Custom AMI com o comando hardcoded"}]'::jsonb, 'C',
  '"(a) container_commands rodam após o source bundle ser extraído mas antes do app server subir — ideal para migrations DB. Suportam leader_only: true para evitar duplicate execution. (b) commands rodam antes da extração do bundle, sem acesso ao código. Cron rodaria periodicamente, não no deploy. Custom AMI seria reconstruída a cada mudança. (c) Regra: commands (pré-app) vs container_commands (pós-deploy, pré-start). (d) Ver Elastic Beanstalk Developer Guide — Customizing software on Linux servers."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["beanstalk","ebextensions","container_commands"]'::jsonb, 'ai-draft', 'active', now(), now()
)
