INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-040', 'aws-dva', 'Um Beanstalk environment Worker Tier precisa processar mensagens de uma fila SQS. Como o developer configura a aplicação para receber as mensagens?',
  '[{"id":"A","text":"O developer escreve um consumer SQS no app que faz polling manual"},{"id":"B","text":"Beanstalk Worker tier não suporta SQS"},{"id":"C","text":"Configurar uma Lambda separada que invoca o app via API Gateway"},{"id":"D","text":"Beanstalk fornece o sqsd que faz long-poll da fila e faz POST do payload em http://localhost/ no app"}]'::jsonb, 'D',
  '"(a) Em Worker tier, o daemon sqsd lê mensagens da fila configurada e as entrega via HTTP POST a um endpoint local (default /); o app só precisa expor o endpoint. (b) Polling manual reinventa o que o sqsd já faz. Worker tier é justamente para SQS. Lambda + API Gateway é overcomplication. (c) Regra: Worker tier = sqsd → app via HTTP, sem código SDK no app. (d) Ver Elastic Beanstalk Developer Guide — Worker environments."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["beanstalk","worker-tier","sqs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
