INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-041', 'aws-dva', 'Uma equipe usa CodePipeline com cross-account deploy: build na conta A, deploy de stack CloudFormation na conta B. O pipeline falha na deploy action com AccessDenied no AssumeRole. Qual configuração resolve a integração entre contas?',
  '[{"id":"A","text":"Criar uma role na conta B que confia na conta A; configurar a action CloudFormation com RoleArn dessa role e ajustar a service role do pipeline com sts:AssumeRole para ela"},{"id":"B","text":"Compartilhar o bucket de artefatos da conta A via ACL aberta para Everyone"},{"id":"C","text":"Criar IAM user na conta B e armazenar access keys em env vars do CodeBuild"},{"id":"D","text":"Usar AWS Organizations SCPs para permitir o deploy"}]'::jsonb, 'A',
  '"(a) O padrão recomendado é uma role na conta target (B) com trust policy aceitando a conta de pipeline (A); a action CloudFormation recebe RoleArn dessa role, e a service role do pipeline precisa de sts:AssumeRole para ela. KMS key do bucket de artefatos também deve permitir a conta B. (b) ACL aberta viola segurança e não resolve o assume role. IAM user com long-lived keys é antipadrão. SCPs limitam, não concedem acesso. (c) Regra: cross-account em CodePipeline usa AssumeRole + KMS CMK compartilhada. (d) Ver CodePipeline User Guide — Cross-account actions."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["codepipeline","cross-account","iam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
