INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-042', 'aws-dva', 'Em CodeBuild, um build precisa acessar um RDS privado em VPC. Como o developer habilita conectividade?',
  '[{"id":"A","text":"Adicionar o IP público do CodeBuild na security group do RDS"},{"id":"B","text":"Configurar VPC config no projeto CodeBuild com subnets privadas, security groups e a VPC do RDS"},{"id":"C","text":"Expor o RDS via Internet Gateway temporariamente durante o build"},{"id":"D","text":"Usar AWS Direct Connect"}]'::jsonb, 'B',
  '"(a) CodeBuild aceita configuração de VPC (vpcId, subnets, securityGroupIds) para que os containers sejam lançados dentro da VPC e tenham acesso a recursos privados como RDS, ElastiCache e EC2. (b) CodeBuild não tem IP público fixo; permitir tudo viola segurança. Expor o RDS publicamente é antipadrão. Direct Connect é para conectividade on-prem. (c) Regra: para acessar resources privados, sempre VPC config no projeto. (d) Ver CodeBuild User Guide — VPC support."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codebuild","vpc","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
