INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-043', 'aws-dva', 'Um buildspec.yml expõe uma senha sensível via environment.variables em plain text. Qual ajuste é a melhor prática para passar secrets ao build?',
  '[{"id":"A","text":"Manter em variables mas usar NoEcho: true"},{"id":"B","text":"Salvar o segredo em um arquivo .env commitado privado"},{"id":"C","text":"Usar env.parameter-store ou env.secrets-manager no buildspec para resolver runtime sem expor o valor"},{"id":"D","text":"Usar git-crypt para criptografar e descriptografar no install phase"}]'::jsonb, 'C',
  '"(a) buildspec aceita env.parameter-store (SSM) e env.secrets-manager (Secrets Manager); CodeBuild resolve os valores em runtime sem aparecerem em logs nem no template. A service role precisa de permissão GetParameter/GetSecretValue. (b) NoEcho é atributo do CloudFormation, não buildspec. Arquivo commitado expõe o segredo no histórico do repo. git-crypt funciona mas é solução externa. (c) Regra: env.parameter-store/secrets-manager é nativo, com mascaramento automático em logs. (d) Ver CodeBuild User Guide — Build spec env."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["codebuild","secrets","buildspec"]'::jsonb, 'ai-draft', 'active', now(), now()
)
