INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-044', 'aws-dva', 'Em CodeDeploy ECS blue/green, o deployment cria um novo task set (replacement) e desloca traffic via listener do ALB. Como o developer força um deploy a abortar se a latência p95 ultrapassar 500ms durante o bake?',
  '[{"id":"A","text":"Configurar um EventBridge rule que mata o task set se p95 subir"},{"id":"B","text":"Aumentar o termination wait time para 60 minutos"},{"id":"C","text":"Usar canary linear em vez de blue/green"},{"id":"D","text":"Associar CloudWatch alarms baseados em latência ao deployment group com auto-rollback on alarm habilitado"}]'::jsonb, 'D',
  '"(a) Deployment groups em ECS aceitam alarms de CloudWatch; se qualquer alarm associado entrar em ALARM, o auto-rollback move traffic de volta para o task set original e termina o replacement. (b) EventBridge custom seria solução manual; alarms + rollback é nativo. Aumentar termination wait não previne problema, só atrasa. Canary linear sozinho não monitora latência. (c) Regra: alarms + auto-rollback é o padrão de safety em qualquer deployment CodeDeploy. (d) Ver CodeDeploy User Guide — Monitor and auto-rollback."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'scenario', '["codedeploy","ecs","blue-green","alarms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
