INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-045', 'aws-dva', 'Em CodePipeline, um developer quer guardar diferentes versões de pipelines em IaC e revertê-las facilmente. Qual abordagem é a recomendada?',
  '[{"id":"A","text":"Definir o pipeline em CloudFormation/CDK e versionar o template no Git"},{"id":"B","text":"Exportar JSON do console e salvar em S3 a cada mudança"},{"id":"C","text":"Usar tags de versionamento no pipeline existente"},{"id":"D","text":"Replicar manualmente o pipeline em outra região como backup"}]'::jsonb, 'A',
  '"(a) Definir pipeline com AWS::CodePipeline::Pipeline em CloudFormation/CDK permite tratá-lo como código, com PR review, rollback Git e drift detection — pipeline self-mutating é prática comum. (b) JSON em S3 não tem peer review nem rollback. Tags não armazenam definição. Replicar manualmente cria divergência. (c) Regra: pipeline-as-code é padrão de IaC em CodePipeline; CDK Pipelines tem helpers self-mutating. (d) Ver CodePipeline User Guide — Reference an existing pipeline as code."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["codepipeline","iac","versioning"]'::jsonb, 'ai-draft', 'active', now(), now()
)
