INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-046', 'aws-dva', 'Um CloudFormation template precisa selecionar uma AMI ID diferente conforme a região onde a stack é criada (us-east-1, sa-east-1, eu-west-1). Qual estrutura é apropriada?',
  '[{"id":"A","text":"Múltiplos parameters com default por região"},{"id":"B","text":"Mappings com chave por região e Fn::FindInMap para resolver"},{"id":"C","text":"Hardcode da AMI mais comum, ignorando a região"},{"id":"D","text":"Usar Fn::ImportValue de outra stack global"}]'::jsonb, 'B',
  '"(a) Mappings + Fn::FindInMap[MapName, AWS::Region, AMI] é o padrão histórico para AMI lookup por região. Alternativa moderna: SSM parameter dynamic reference {{resolve:ssm:/aws/service/ami-amazon-linux-latest/...}}. (b) Múltiplos parameters não selecionam dinamicamente. Hardcode quebra portabilidade. ImportValue exige stack global que produza esse valor — overkill. (c) Regra: Mappings ou SSM param são as soluções idiomáticas. (d) Ver CloudFormation User Guide — Mappings."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cloudformation","mappings","find-in-map"]'::jsonb, 'ai-draft', 'active', now(), now()
)
