INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-047', 'aws-dva', 'Em CloudFormation, um StackSet deve criar a mesma stack em 5 contas e 3 regiões. Qual mecanismo o developer usa para o deploy paralelo seguro?',
  '[{"id":"A","text":"Criar um Step Function que invoca create-stack em loop"},{"id":"B","text":"Usar nested stacks com Parameters por conta"},{"id":"C","text":"Configurar a StackSet operation com MaxConcurrentCount e FailureToleranceCount no StackInstances deployment"},{"id":"D","text":"Disparar 15 update-stack manualmente no console"}]'::jsonb, 'C',
  '"(a) StackSets aceita parâmetros operacionais MaxConcurrentCount/Percentage e FailureToleranceCount/Percentage que controlam paralelismo e tolerância a falhas durante deploy. (b) Step Functions duplicaria o que StackSets já faz. Nested stacks são para composição dentro de uma stack, não multi-account. Manual quebra IaC. (c) Regra: StackSets é o serviço oficial para multi-account/multi-region. (d) Ver CloudFormation User Guide — StackSet operation options."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'best-practice', '["cloudformation","stacksets","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
