INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-048', 'aws-dva', 'Um template CloudFormation grande está difícil de manter. O developer quer dividir em componentes reutilizáveis. Qual mecanismo é apropriado quando os sub-templates são parte integral do parent?',
  '[{"id":"A","text":"Cross-stack via Outputs/ImportValue"},{"id":"B","text":"Criar StackSets independentes"},{"id":"C","text":"Copiar trechos via include de YAML anchors"},{"id":"D","text":"Nested stacks via AWS::CloudFormation::Stack com TemplateURL"}]'::jsonb, 'D',
  '"(a) Nested stacks expõem o sub-template como recurso AWS::CloudFormation::Stack do parent — deploy atômico, lifecycle compartilhado, ideal para componentes reusáveis que não devem existir isoladamente. (b) Cross-stack é para stacks independentes que se comunicam. StackSets cobre multi-account/region, não componentização. YAML anchors funcionam só dentro do mesmo arquivo. (c) Regra: nested = composição parent/child; cross-stack = stacks independentes. (d) Ver CloudFormation User Guide — Working with nested stacks."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["cloudformation","nested-stacks","modularization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
