INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-049', 'aws-dva', 'Em CloudFormation, qual intrinsic function é apropriada para condicionalmente atribuir um valor de property baseado em uma condition (ex: instance class diferente em prod vs dev)?',
  '[{"id":"A","text":"Fn::If [ConditionName, ValueIfTrue, ValueIfFalse]"},{"id":"B","text":"Fn::Equals com property override"},{"id":"C","text":"Fn::Switch [ConditionName, Cases...]"},{"id":"D","text":"Condition: \u003cName\u003e direto na property"}]'::jsonb, 'A',
  '"(a) Fn::If retorna um de dois valores dependendo da Condition, podendo ser usado em qualquer property. Para suprimir uma property, use AWS::NoValue como valor false. (b) Fn::Equals define a condition mas não escolhe valor inline. Fn::Switch não existe. Condition: <Name> habilita/desabilita o resource inteiro, não property. (c) Regra: Fn::If + AWS::NoValue cobre 90% dos casos condicionais de property. (d) Ver CloudFormation User Guide — Fn::If."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cloudformation","intrinsic-functions","fn-if"]'::jsonb, 'ai-draft', 'active', now(), now()
)
