INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-050', 'aws-dva', 'Um Beanstalk environment Immutable deployment está em progresso e falha porque uma instância nova não passa healthcheck do ELB. Qual é o comportamento esperado?',
  '[{"id":"A","text":"O traffic é parcialmente shifted e fica em estado degradado"},{"id":"B","text":"Beanstalk termina o novo ASG temporário; o ambiente permanece na versão anterior, sem impacto"},{"id":"C","text":"O environment é deletado e recriado do zero"},{"id":"D","text":"Beanstalk faz force-replace com health relaxado"}]'::jsonb, 'B',
  '"(a) Immutable lança um ASG paralelo temporário; se health falha, esse ASG é terminado e o ambiente original (que nunca foi tocado) continua servindo — zero impacto. (b) Não há shift parcial em Immutable; só promove se todas as instâncias novas passam health. Environment não é deletado. Force-replace não é comportamento default. (c) Regra: Immutable = maior safety, custo dobrado durante deploy, rollback automático sem impacto. (d) Ver Elastic Beanstalk Developer Guide — Immutable deployments."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["beanstalk","immutable","rollback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
