INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-051', 'aws-dva', 'Em Elastic Beanstalk, o developer quer fazer cutover instantâneo entre versões com rollback rápido em caso de problema. Qual técnica é a mais apropriada e qual o custo?',
  '[{"id":"A","text":"Rolling deployment com pequeno batch — sem custo extra, rollback instantâneo"},{"id":"B","text":"All at once — cutover mais rápido sem custo adicional"},{"id":"C","text":"Blue/Green via swap CNAME — criar segundo environment, validar, swap; custo de dois ambientes durante validação"},{"id":"D","text":"Trocar a AMI no console — instantâneo e sem custo"}]'::jsonb, 'C',
  '"(a) Beanstalk suporta Swap Environment URLs entre dois envs (blue e green); o cutover é via DNS (CNAME swap), com rollback igualmente rápido. Custo é manter dois envs simultâneos durante a validação. (b) Rolling não é cutover instantâneo nem rollback instantâneo. All at once tem downtime. Trocar AMI no console quebra IaC e não é instantâneo. (c) Regra: Beanstalk Blue/Green = swap CNAME entre envs; CodeDeploy Blue/Green = task set + listener. (d) Ver Elastic Beanstalk Developer Guide — Blue/green deployments."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["beanstalk","blue-green","cname-swap"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
