INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-052', 'aws-dva', 'Em Elastic Beanstalk, o developer precisa rodar comandos privilegiados em todas as instâncias antes de cada deploy mas APENAS em uma delas (líder). Qual configuração no .ebextensions garante isso?',
  '[{"id":"A","text":"files: { ''/etc/leader-flag'': { content: ''true'' } }"},{"id":"B","text":"option_settings: { aws:elasticbeanstalk:application:leader: ''true'' }"},{"id":"C","text":"packages: { yum: { leader: ''*'' } }"},{"id":"D","text":"container_commands: { migrate: { command: ''...'', leader_only: true } }"}]'::jsonb, 'D',
  '"(a) leader_only: true em container_commands faz com que apenas uma instância (a líder eleita pelo Beanstalk) execute o comando — útil para migrations, schema updates, idempotência. (b) Flag em filesystem não muda comportamento de execução. option_settings não tem campo leader. packages.leader não existe. (c) Regra: leader_only é específico de container_commands. (d) Ver Elastic Beanstalk Developer Guide — container_commands."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["beanstalk","leader-only","ebextensions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
