INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-053', 'aws-dva', 'Em Elastic Beanstalk, o developer customizou o ambiente via .ebextensions mas precisa de configurações mais avançadas que persistem em rebuilds. Qual evolução o Beanstalk oferece?',
  '[{"id":"A","text":"Platform hooks em .platform/hooks/ (prebuild, predeploy, postdeploy)"},{"id":"B","text":"Migrar para CodeDeploy diretamente"},{"id":"C","text":"Criar uma custom AMI manualmente a cada deploy"},{"id":"D","text":"Editar arquivos diretamente em /var/app/current/ via SSH"}]'::jsonb, 'A',
  '"(a) Em plataformas Amazon Linux 2/2023, Beanstalk introduziu Platform Hooks: scripts shell em .platform/hooks/prebuild|predeploy|postdeploy e .platform/confighooks/ — executados pelo agent e mais flexíveis que container_commands. (b) Migrar é mudança de stack, não evolução. Custom AMI funciona mas não persiste com IaC. SSH manual quebra IaC. (c) Regra: .platform/hooks/ é a evolução recomendada para AL2/AL2023. (d) Ver Elastic Beanstalk Developer Guide — Platform hooks."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["beanstalk","platform-hooks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
