INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-054', 'aws-dva', 'Uma função Lambda em produção tem alias ''prod'' apontando para Version 42. O developer quer testar a Version 43 com 5% do tráfego usando o próprio Lambda (sem CodeDeploy). Como configurar?',
  '[{"id":"A","text":"Criar um segundo alias ''prod-canary'' apontando para 43 e usar Route 53 weighted routing"},{"id":"B","text":"Atualizar o alias ''prod'' adicionando RoutingConfig.AdditionalVersionWeights com { ''43'': 0.05 }"},{"id":"C","text":"Trocar o alias para 43 e voltar manualmente após validar"},{"id":"D","text":"Lambda não suporta routing por weight nativamente"}]'::jsonb, 'B',
  '"(a) Lambda aliases suportam RoutingConfig com AdditionalVersionWeights — peso fracionado entre a versão principal e versões adicionais. update-alias com routing-config inicia o canary nativo sem CodeDeploy. (b) Route 53 weighted serve para HTTP; invocações internas (SDK/triggers) ignorariam. Cutover total perde a granularidade. Lambda suporta sim. (c) Regra: alias.RoutingConfig é o canary nativo do Lambda; CodeDeploy é camada de orquestração por cima. (d) Ver Lambda Developer Guide — Alias routing configuration."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["lambda","alias","traffic-shifting"]'::jsonb, 'ai-draft', 'active', now(), now()
)
