INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-055', 'aws-dva', 'Em CodeDeploy Lambda, qual é a diferença prática entre LambdaAllAtOnce, LambdaLinear10PercentEvery1Minute e LambdaCanary10Percent5Minutes em termos de duração total e perfil de risco?',
  '[{"id":"A","text":"Os três têm mesma duração, diferindo apenas em nome"},{"id":"B","text":"Linear é mais rápido que AllAtOnce porque paraleliza versões"},{"id":"C","text":"AllAtOnce: instantâneo, alto risco; Linear10%Every1Min: ~10 min, risco distribuído; Canary10%5Min: ~5 min, risco em duas etapas com bake"},{"id":"D","text":"Canary nunca completa 100%, mantém versão antiga em paralelo"}]'::jsonb, 'C',
  '"(a) AllAtOnce: 100% imediato, sem bake — falha rápida e total. Linear10%Every1Min: 10 incrementos de 10% espaçados em 1 min cada (~10 min total). Canary10%5Min: 10% por 5 min de bake, depois 100% — só duas mudanças com janela de observação. (b) Cada config tem duração e perfil distintos. AllAtOnce é o mais rápido. Canary completa 100% após bake. (c) Regra: AllAtOnce (risco alto) vs Linear (gradual) vs Canary (duas etapas). (d) Ver CodeDeploy User Guide — Predefined deployment configurations."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["codedeploy","lambda","deployment-configs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
