INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-056', 'aws-dva', 'Uma Lambda usa provisioned concurrency em alias ''live''. Após um deploy com canary 10%-5min, o developer observa erros de cold start em 10% das invocações. Por quê?',
  '[{"id":"A","text":"Canary deployments desabilitam PC automaticamente"},{"id":"B","text":"CodeDeploy não suporta Lambda com PC"},{"id":"C","text":"Os erros são apenas cosméticos no CloudWatch"},{"id":"D","text":"Provisioned concurrency é por versão; a versão nova ainda não tem PC aplicada durante o canary"}]'::jsonb, 'D',
  '"(a) Provisioned Concurrency é atribuída a uma versão específica ou ao alias inteiro. Quando o canary cria nova versão sem PC pré-aquecida, 10% dos requests caem em init frio. Solução: aplicar PC à versão nova antes do shift via deployment hooks ou Application Auto Scaling. (b) Canary não desabilita PC. CodeDeploy suporta Lambda com PC. Erros de cold start são reais (latência elevada). (c) Regra: ao canary com PC, pre-warm a nova versão. (d) Ver Lambda Developer Guide — Provisioned concurrency."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'troubleshoot', '["lambda","provisioned-concurrency","canary"]'::jsonb, 'ai-draft', 'active', now(), now()
)
