INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-057', 'aws-dva', 'Lambda Layers são úteis em qual cenário de deployment?',
  '[{"id":"A","text":"Compartilhar dependências comuns (ex: numpy, AWS SDK custom) entre múltiplas funções, reduzindo o zip de cada uma"},{"id":"B","text":"Substituir o container runtime do Lambda"},{"id":"C","text":"Habilitar provisioned concurrency cross-account"},{"id":"D","text":"Versionar o código fonte do app principal"}]'::jsonb, 'A',
  '"(a) Layers permitem empacotar libraries/binaries em um zip separado, compartilhado por até 5 funções por execução. Reduz duplicação, acelera build/upload e centraliza atualização de deps comuns. (b) Layers não trocam runtime, apenas adicionam arquivos a /opt. PC é por versão da função, não cross-account via layer. Versionamento do código fica no zip da função. (c) Regra: layers = dependências comuns; código da função fica no main package. (d) Ver Lambda Developer Guide — Lambda layers."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["lambda","layers","dependencies"]'::jsonb, 'ai-draft', 'active', now(), now()
)
