INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-058', 'aws-dva', 'Em Lambda, $LATEST aponta para qual versão e qual o risco de invocar $LATEST diretamente em produção?',
  '[{"id":"A","text":"$LATEST é uma versão imutável aleatória, sem risco"},{"id":"B","text":"$LATEST é a versão mutável atual; invocá-la em prod expõe consumidores a mudanças não testadas sem rollback fácil"},{"id":"C","text":"$LATEST não pode ser invocada externamente"},{"id":"D","text":"$LATEST roda em região separada, isolando produção"}]'::jsonb, 'B',
  '"(a) $LATEST é o ponteiro para a versão mutável de desenvolvimento — todo update no código altera $LATEST sem criar versão imutável. Invocar $LATEST em prod = expor usuários a cada push, sem rollback granular. Prática correta: publicar versão (PublishVersion) e usar alias. (b) $LATEST é mutável por definição. Pode ser invocada externamente. Não há isolamento regional especial. (c) Regra: prod sempre via alias apontando para versão publicada. (d) Ver Lambda Developer Guide — Lambda function versions."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["lambda","versions","alias"]'::jsonb, 'ai-draft', 'active', now(), now()
)
