INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-059', 'aws-dva', 'Um pipeline faz deploy de uma imagem Docker para ECR. Como o developer marca a imagem com a tag git SHA E também ''latest'' simultaneamente no buildspec?',
  '[{"id":"A","text":"ECR aplica ''latest'' automaticamente em qualquer push"},{"id":"B","text":"Configurar lifecycle policy que cria tag ''latest'' após push"},{"id":"C","text":"docker tag app:$SHA $ECR/app:$SHA \u0026\u0026 docker tag app:$SHA $ECR/app:latest \u0026\u0026 docker push $ECR/app --all-tags"},{"id":"D","text":"Tags imutáveis no ECR previnem ''latest''"}]'::jsonb, 'C',
  '"(a) Docker tags são labels locais; aplicar duas tags ao mesmo digest (SHA local) e fazer push --all-tags envia ambas. ECR aceita múltiplas tags por digest. (b) ECR não cria tags automaticamente. Lifecycle policy só expira/deleta imagens, não cria tags. Tag immutability bloqueia overwrite de tag existente; não impede push inicial de ''latest''. (c) Regra: docker tag x N + docker push --all-tags ou push individual de cada tag. (d) Ver Amazon ECR User Guide — Pushing an image."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["ecr","docker","tags"]'::jsonb, 'ai-draft', 'active', now(), now()
)
