INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-060', 'aws-dva', 'Um developer quer escanear automaticamente vulnerabilidades em todas as imagens pushadas para um repositório ECR. Qual configuração habilita isso?',
  '[{"id":"A","text":"Adicionar uma Lambda trigger em ObjectCreated do bucket"},{"id":"B","text":"Configurar AWS GuardDuty no repositório"},{"id":"C","text":"Subir as imagens manualmente e rodar trivy local"},{"id":"D","text":"Habilitar scan-on-push no repositório (basic scanning) ou usar Amazon Inspector para enhanced scanning"}]'::jsonb, 'D',
  '"(a) ECR oferece basic scanning (Clair, on-push opcional) e enhanced scanning via Amazon Inspector (cobertura contínua, OS + linguagem). Habilitar no repositório triggera scan em cada push. (b) ECR não usa eventos S3. GuardDuty foca em ameaças de runtime, não em scan de imagens em registry. Trivy local não é o caminho gerenciado. (c) Regra: scan-on-push (basic) ou Inspector (enhanced) são as opções nativas. (d) Ver Amazon ECR User Guide — Image scanning."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["ecr","image-scanning","inspector"]'::jsonb, 'ai-draft', 'active', now(), now()
)
