INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-061', 'aws-dva', 'Um ECS service rodando em Fargate precisa receber atualização de imagem zero-downtime quando uma nova tag é pushada. Qual é a forma idiomática de orquestrar isso sem CodeDeploy?',
  '[{"id":"A","text":"Registrar uma nova task definition revision com a imagem nova e fazer update-service apontando para essa revision; ECS faz rolling update respeitando minimumHealthyPercent"},{"id":"B","text":"Parar todas as tasks e iniciar novas manualmente"},{"id":"C","text":"Editar a task definition existente in-place"},{"id":"D","text":"Restart do cluster Fargate via CLI"}]'::jsonb, 'A',
  '"(a) Task definitions são imutáveis; cada mudança cria uma nova revision. update-service --task-definition <revision> dispara rolling update controlado por deploymentConfiguration (min/maxHealthyPercent). (b) Stop manual causa downtime. Task definition não pode ser editada in-place — sempre cria nova revision. Cluster restart não existe como conceito. (c) Regra: task definition revision + update-service = rolling update nativo ECS. (d) Ver Amazon ECS Developer Guide — Service deployment types."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["ecs","fargate","rolling-update"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
