INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-062', 'aws-dva', 'Um deployment ECS blue/green via CodeDeploy precisa de quais resources extras comparado a um rolling update simples?',
  '[{"id":"A","text":"Dois ECS clusters separados, um para blue e outro para green"},{"id":"B","text":"Dois target groups (blue e green) atrás do mesmo listener ALB, e um deployment group CodeDeploy associado ao service"},{"id":"C","text":"Uma instância EC2 dedicada para o CodeDeploy agent (mesmo em Fargate)"},{"id":"D","text":"Um S3 bucket para os artefatos do task definition"}]'::jsonb, 'B',
  '"(a) ECS blue/green requer dois target groups (blue/green) compartilhando o listener; o CodeDeploy cria um task set replacement, registra no target group green, valida e desloca o traffic via listener rules. (b) Mesmo cluster, dois task sets. CodeDeploy agent não é necessário em Fargate (controle via API). S3 bucket não é requisito; artefatos vêm do source. (c) Regra: ECS B/G = dois TGs + ALB listener + deployment group; clusters separados não. (d) Ver CodeDeploy User Guide — ECS deployments."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'best-practice', '["ecs","blue-green","alb","codedeploy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
