INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-063', 'aws-dva', 'Um pull de imagem do ECR para um pod EKS falha com ''no basic auth credentials''. Qual configuração corrige a autenticação?',
  '[{"id":"A","text":"Configurar docker login manualmente em cada node"},{"id":"B","text":"Tornar o repositório ECR público temporariamente"},{"id":"C","text":"Anexar uma IAM role com permissão ecr:GetAuthorizationToken/BatchGet... ao node group (ou usar IRSA na service account)"},{"id":"D","text":"Criar um IAM user e armazenar credentials em ConfigMap"}]'::jsonb, 'C',
  '"(a) Em EKS, o kubelet do node usa as credenciais do instance profile do EC2 (ou IRSA da service account em modo pod) para chamar ecr:GetAuthorizationToken e ecr:BatchGetImage. Sem a policy, pull falha. (b) docker login manual não persiste após reboot. Repositório público é antipadrão. ConfigMap com credentials é antipadrão (use Secret e prefira IAM). (c) Regra: ECR + EKS = IAM role no node (ou IRSA) com policy AmazonEC2ContainerRegistryReadOnly. (d) Ver Amazon EKS User Guide — Amazon ECR."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'troubleshoot', '["eks","ecr","iam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
