INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-064', 'aws-dva', 'Em ECR, qual mecanismo evita acúmulo descontrolado de imagens antigas em repositórios de longa vida?',
  '[{"id":"A","text":"Bucket lifecycle policy do S3 underlying"},{"id":"B","text":"Cron Lambda que deleta imagens com mais de 30 dias"},{"id":"C","text":"Configurar TTL na imagem no momento do push"},{"id":"D","text":"Lifecycle policy expirando imagens por tag pattern, idade ou contagem máxima"}]'::jsonb, 'D',
  '"(a) ECR Lifecycle Policy aceita regras baseadas em tagStatus (tagged/untagged), countType (sinceImagePushed / imageCountMoreThan) e tagPrefixList. Avalia diariamente e expira automaticamente. (b) ECR não expõe S3 underlying. Lambda custom funciona mas reinventa o nativo. Imagens não têm TTL no push. (c) Regra: lifecycle policy é a forma oficial de gerenciar retenção em ECR. (d) Ver Amazon ECR User Guide — Lifecycle policies."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["ecr","lifecycle-policy","retention"]'::jsonb, 'ai-draft', 'active', now(), now()
)
