INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-065', 'aws-dva', 'Em AWS CDK (TypeScript), o developer precisa criar uma S3 Bucket com versionamento e encryption. Qual abordagem segue best practice de IaC?',
  '[{"id":"A","text":"Instanciar new s3.Bucket(this, ''Data'', { versioned: true, encryption: BucketEncryption.S3_MANAGED }) no Stack"},{"id":"B","text":"Escrever o CloudFormation YAML manualmente e fazer cdk import"},{"id":"C","text":"Criar o bucket via AWS Console e referenciar como dependency externa"},{"id":"D","text":"Executar aws s3 mb no synth do CDK"}]'::jsonb, 'A',
  '"(a) CDK constructs (L2) encapsulam best practices e expõem props tipadas. new s3.Bucket(...) gera o template CloudFormation correto, com policy de encryption e versioning. (b) cdk import existe mas é para adoção de resources legados, não para criar novos. Console + reference quebra IaC. aws s3 mb é CLI imperativa, não declarativa. (c) Regra: CDK = código TypeScript/Python/Java que sintetiza CloudFormation; prefira L2 constructs. (d) Ver AWS CDK Developer Guide — Constructs."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'best-practice', '["cdk","iac","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
