INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-066', 'aws-dva', 'Antes do primeiro cdk deploy em uma conta/região, qual comando o developer precisa executar e o que ele provisiona?',
  '[{"id":"A","text":"cdk init — só inicializa o repositório do projeto"},{"id":"B","text":"cdk bootstrap — provisiona o CDKToolkit stack com bucket de assets, ECR para imagens e roles de deployment"},{"id":"C","text":"cdk synth — gera o template, sem provisionar nada"},{"id":"D","text":"cdk diff — compara estado, não cria resources"}]'::jsonb, 'B',
  '"(a) cdk bootstrap cria o stack CDKToolkit por conta+região contendo: bucket S3 para file assets, repositório ECR para image assets, IAM roles (lookup, file-publishing, image-publishing, deploy, cfn-exec). Sem isso, deploys que precisem de assets falham. (b) cdk init é template do projeto local. cdk synth gera CloudFormation. cdk diff compara. (c) Regra: bootstrap é pré-requisito uma vez por conta+região (e por versão de bootstrap template). (d) Ver AWS CDK Developer Guide — Bootstrapping."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cdk","bootstrap"]'::jsonb, 'ai-draft', 'active', now(), now()
)
