INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-067', 'aws-dva', 'Em CDK, o que diferencia uma L1 construct de uma L2 construct?',
  '[{"id":"A","text":"L1 roda em Python, L2 em TypeScript"},{"id":"B","text":"L1 é deprecated; L2 é a única forma suportada"},{"id":"C","text":"L1 é mapeamento 1:1 com o CloudFormation resource (CfnBucket); L2 é abstração de alto nível com defaults e helpers (s3.Bucket)"},{"id":"D","text":"L1 e L2 são exatamente iguais, só diferem no nome"}]'::jsonb, 'C',
  '"(a) L1 (Cfn-prefixed): mapeamento direto do recurso CloudFormation, sem defaults inteligentes. L2: abstração curada (s3.Bucket, lambda.Function) com props ergonômicas, métodos helpers (grantRead, addToResourcePolicy) e melhores defaults. L3 é pattern (constructs compostos). (b) Linguagem é independente do nível. L1 segue vivo e útil para casos sem L2. Não são iguais. (c) Regra: prefira L2 quando existe; cai em L1 para recursos sem L2. (d) Ver AWS CDK Developer Guide — Constructs."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["cdk","constructs","l1-l2"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
