INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-068', 'aws-dva', 'Em IaC, o developer mantém um repositório com templates CloudFormation. Qual prática melhora confiabilidade do pipeline de IaC?',
  '[{"id":"A","text":"Aplicar direto em produção e reverter se falhar"},{"id":"B","text":"Manter um único template gigante por conta"},{"id":"C","text":"Editar templates ao vivo no console e exportar depois"},{"id":"D","text":"Linter (cfn-lint), validação de policy (cfn-guard/OPA) e teste com snapshot ou cdk-nag antes de aplicar"}]'::jsonb, 'D',
  '"(a) Pipeline IaC robusto: lint (cfn-lint pega erros sintáticos e refs inválidas), policy check (cfn-guard ou OPA bloqueia anti-patterns), snapshot/diff antes de aplicar. CDK: cdk synth + cdk diff + cdk-nag para regras de compliance. (b) Aplicar direto e reverter é o oposto de IaC seguro. Template gigante reduz reusabilidade. Editar no console quebra IaC. (c) Regra: lint + policy-as-code + diff são guardrails essenciais. (d) Ver AWS CDK Developer Guide — Testing constructs."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["iac","linting","policy-as-code"]'::jsonb, 'ai-draft', 'active', now(), now()
)
