INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-069', 'aws-dva', 'Em CDK Pipelines, o que significa o conceito ''self-mutating pipeline''?',
  '[{"id":"A","text":"O próprio pipeline tem uma stage que atualiza sua definição antes de rodar as stages de aplicação — mudanças no código do pipeline se aplicam sozinhas no próximo run"},{"id":"B","text":"O pipeline cria automaticamente cópias em outras regiões"},{"id":"C","text":"O pipeline deleta a si mesmo após cada deploy"},{"id":"D","text":"O pipeline alterna entre CodePipeline e Step Functions a cada execução"}]'::jsonb, 'A',
  '"(a) CDK Pipelines monta um pipeline cuja primeira stage faz cdk synth + update do próprio pipeline (UpdatePipeline). Qualquer mudança no código do pipeline (adicionar stage, mudar source, etc.) é aplicada na próxima run sem intervenção manual. (b) Replicação multi-region exige código explícito. Pipelines não se deletam sozinhos. Não há alternância CodePipeline/Step Functions. (c) Regra: self-mutating é o killer feature do CDK Pipelines. (d) Ver AWS CDK Developer Guide — CDK Pipelines."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'recall', '["cdk","cdk-pipelines","self-mutating"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
