INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-070', 'aws-dva', 'Em CDK, qual comando o developer executa para inspecionar mudanças entre o estado atual da stack na AWS e o template recém-sintetizado, antes de aplicar?',
  '[{"id":"A","text":"cdk synth --dry-run"},{"id":"B","text":"cdk diff"},{"id":"C","text":"cdk plan"},{"id":"D","text":"cdk ls --changes"}]'::jsonb, 'B',
  '"(a) cdk diff compara o template local (sintetizado) com o stack remoto, mostrando IAM changes, security group rules e resource updates. Output similar a um change set. (b) cdk synth gera o template mas não compara. cdk plan é nomenclatura Terraform, não CDK. cdk ls lista stacks. (c) Regra: cdk diff antes de cdk deploy é hábito recomendado, especialmente em prod. (d) Ver AWS CDK Developer Guide — CDK CLI command reference."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["cdk","cli","diff"]'::jsonb, 'ai-draft', 'active', now(), now()
)
