INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-071', 'aws-dva', 'Um deploy CodeDeploy blue/green em EC2 acabou de fazer shift 100% para a green fleet. Durante o termination wait time, um erro crítico é detectado nas novas instâncias. O que o developer pode fazer para reverter rapidamente?',
  '[{"id":"A","text":"Aguardar o termination wait expirar e recriar manualmente as instâncias"},{"id":"B","text":"Deletar o load balancer e recriar com a versão antiga"},{"id":"C","text":"Disparar ''Stop and roll back deployment'' no console — CodeDeploy redireciona traffic para a blue fleet ainda viva no termination wait"},{"id":"D","text":"Rollback só é possível antes do shift 100%"}]'::jsonb, 'C',
  '"(a) Durante o termination wait, a blue fleet permanece intacta (sem traffic). ''Stop and roll back'' move traffic de volta para a blue e termina a green. É exatamente para esse caso de janela de observação pós-shift. (b) Aguardar perde a janela; após termination wait, blue é destruída. Deletar ALB é catastrófico. Rollback é possível enquanto blue ainda existir. (c) Regra: termination wait é a janela de segurança principal em B/G. (d) Ver CodeDeploy User Guide — Stop and roll back a deployment."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codedeploy","blue-green","rollback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
