INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-072', 'aws-dva', 'Em rollback strategies, qual a diferença operacional entre ''forward rollback'' e ''reverse rollback'' em pipelines de software?',
  '[{"id":"A","text":"Forward rollback é o mesmo que canary; reverse é blue/green"},{"id":"B","text":"Forward rollback só funciona em Lambda; reverse só em EC2"},{"id":"C","text":"Não há diferença, são sinônimos"},{"id":"D","text":"Reverse rollback restaura a versão anterior; forward rollback aplica um fix-forward (nova versão corrigida) — útil quando reverter geraria incompatibilidade (ex: migration de schema)"}]'::jsonb, 'D',
  '"(a) Reverse rollback (revert) volta ao binário/versão prévia — rápido se idempotente. Forward rollback (roll-forward) aplica um patch novo corrigindo o bug, deixando o release line avançar. Migrations de schema irreversíveis frequentemente forçam roll-forward. (b) Canary e B/G são padrões de shift, não rollback strategies. Funciona em qualquer plataforma. Não são sinônimos. (c) Regra: escolha depende de reversibilidade do estado (DB, cache, contratos). (d) Ver Well-Architected — Reliability pillar (deployment rollback)."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["rollback","forward-rollback","best-practice"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
