INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-073', 'aws-dva', 'Um pipeline com deploy via CloudFormation falha no UPDATE_IN_PROGRESS de uma stack de prod. O developer quer minimizar tempo de rollback. Qual configuração ajuda?',
  '[{"id":"A","text":"Configurar RollbackConfiguration com MonitoringTimeInMinutes e RollbackTriggers (CloudWatch alarms); falha em alarm aborta antes mesmo de continuar o update"},{"id":"B","text":"Aumentar TimeoutInMinutes da stack para 120"},{"id":"C","text":"Desabilitar disable-rollback no create-stack"},{"id":"D","text":"Usar StackPolicy bloqueando todos os updates"}]'::jsonb, 'A',
  '"(a) RollbackConfiguration com RollbackTriggers (alarms) define que durante e por MonitoringTimeInMinutes após o update, se qualquer alarm dispara, CloudFormation aciona rollback automático — corta tempo de detecção. (b) Aumentar timeout não acelera rollback. disable-rollback impede rollback (oposto). Stack policy bloqueante quebra deploys. (c) Regra: RollbackConfiguration = rollback automático guiado por alarms. (d) Ver CloudFormation User Guide — Monitor and roll back stack updates."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'best-practice', '["cloudformation","rollback-configuration","alarms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
