INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-074', 'aws-dva', 'Um deploy Lambda canary é abortado por alarm. O developer quer entender o que acontece com a versão que estava recebendo 10%. Após o rollback automático, qual o estado?',
  '[{"id":"A","text":"A versão nova é deletada automaticamente pelo CodeDeploy"},{"id":"B","text":"Alias volta 100% para a versão anterior; a versão nova permanece publicada mas sem traffic, podendo ser deletada manualmente"},{"id":"C","text":"Ambas as versões compartilham 50% indefinidamente"},{"id":"D","text":"A função Lambda inteira é desabilitada até intervenção manual"}]'::jsonb, 'B',
  '"(a) Rollback move o RoutingConfig do alias 100% para a versão pre-deploy. A versão nova continua publicada (imutável) — Lambda nunca deleta versões automaticamente. Limpeza fica por conta de scripts ou de policies de retenção customizadas. (b) Versions são imutáveis e persistentes. Alias não fica em 50%; rollback é total. Função não é desabilitada. (c) Regra: rollback = alias volta; cleanup de versões é manual. (d) Ver Lambda Developer Guide — Lambda function versions."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["lambda","rollback","versions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
