INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-075', 'aws-dva', 'Em CodeDeploy EC2 in-place, qual deployment configuration é mais conservadora e mantém maior disponibilidade durante o deploy?',
  '[{"id":"A","text":"CodeDeployDefault.AllAtOnce"},{"id":"B","text":"CodeDeployDefault.HalfAtATime"},{"id":"C","text":"CodeDeployDefault.OneAtATime"},{"id":"D","text":"CodeDeployDefault.OneInstance"}]'::jsonb, 'C',
  '"(a) OneAtATime atualiza uma instância por vez — mais conservadora, deploy mais longo, mas máxima disponibilidade. AllAtOnce derruba tudo simultaneamente (risco alto). HalfAtATime fica entre os dois. (b) AllAtOnce é o oposto. HalfAtATime é intermediário, não o mais conservador. OneInstance não é nome oficial de config. (c) Regra: OneAtATime > HalfAtATime > AllAtOnce em ordem de safety. (d) Ver CodeDeploy User Guide — Deployment configurations for EC2/On-Premises."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'recall', '["codedeploy","ec2","deployment-config"]'::jsonb, 'ai-draft', 'active', now(), now()
)
