INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-076', 'aws-dva', 'Uma arquitetura blue/green sofre de problema de DB schema: a versão nova quer adicionar coluna NOT NULL, mas a versão antiga (ainda rodando em paralelo) quebra com a mudança. Qual técnica padrão resolve?',
  '[{"id":"A","text":"Forçar todas as instâncias old a reiniciar durante o shift"},{"id":"B","text":"Deletar todos os dados antigos antes do deploy"},{"id":"C","text":"Aplicar a mudança de schema sem nenhum cuidado"},{"id":"D","text":"Expand-and-contract: deploy 1 adiciona coluna nullable, app suporta os dois shapes; deploy 2 popula e torna NOT NULL após old version sair"}]'::jsonb, 'D',
  '"(a) Expand-and-contract (parallel-change) é o padrão para schema changes compatíveis com blue/green: (1) expand — adicionar coluna nullable, app lida com presença/ausência; (2) deploy nova versão usando coluna; (3) backfill; (4) contract — tornar NOT NULL e remover código que tolerava ausência. (b) Reiniciar instâncias old derruba a estratégia B/G. Deletar dados é destrutivo. Aplicar sem cuidado é a causa do problema. (c) Regra: schema changes precisam ser backward-compatible durante o overlap. (d) Ver Well-Architected — Operational excellence (parallel change)."'::jsonb,
  'Deployment', 'Deployment', 'hard', 'best-practice', '["blue-green","schema-migration","expand-contract"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
