INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-077', 'aws-dva', 'Em CodePipeline, qual feature permite reexecutar uma execução anterior bem-sucedida quando o developer descobre regressão tarde?',
  '[{"id":"A","text":"Retry/rollback à última execução estável via ''Release change'' a partir do source revision anterior"},{"id":"B","text":"CodePipeline armazena snapshots de stack e restaura via ''Restore execution''"},{"id":"C","text":"Backup automático do pipeline em S3 Glacier"},{"id":"D","text":"Pipelines não suportam reexecução; deve-se criar pipeline novo"}]'::jsonb, 'A',
  '"(a) O caminho oficial é dar Release change apontando para um source revision/commit anterior (rebuild + redeploy), ou marcar um source-action override com a revision específica. Algumas integrações expõem ''Retry stage'' para reexecutar mesma revision. (b) Não há ''Restore execution'' nem snapshot da stack. Não há backup em Glacier. Pipelines suportam reexecução. (c) Regra: para ''rollback'' de pipeline, deploy do commit anterior conhecido bom. (d) Ver CodePipeline User Guide — Start and stop pipeline executions."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'scenario', '["codepipeline","rollback","release-change"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
