INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-078', 'aws-dva', 'Em ECS rolling update, o que controlam minimumHealthyPercent e maximumPercent no deploymentConfiguration?',
  '[{"id":"A","text":"São limites de CPU/memória das tasks"},{"id":"B","text":"minimumHealthyPercent: % mínimo de tasks running em relação ao desired durante deploy; maximumPercent: % máximo permitido (acima de 100 permite spin-up de novas antes de matar as velhas)"},{"id":"C","text":"Controlam scaling do cluster, não do deploy"},{"id":"D","text":"Definem a razão de tasks em duas AZs"}]'::jsonb, 'B',
  '"(a) ECS controla o pace do rolling update: minimumHealthyPercent (ex: 50) garante que ao menos metade das tasks fica de pé; maximumPercent (ex: 200) permite dobrar a frota temporariamente. Combinações comuns: (50, 200) = blue/green-ish; (100, 200) = sem downtime aceitando custo dobrado. (b) Não são limites de CPU. Não controlam cluster scaling. Não definem distribuição por AZ. (c) Regra: ajuste esses dois valores para balancear custo, velocidade e disponibilidade. (d) Ver Amazon ECS Developer Guide — Service deployment configuration."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'recall', '["ecs","rolling-update","deployment-configuration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
