INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-079', 'aws-dva', 'Um deploy CloudFormation falha porque um S3 bucket criado em deploy anterior contém objetos e a property foi removida do template. Como o developer evita esse tipo de bloqueio em iterações futuras?',
  '[{"id":"A","text":"Configurar Lifecycle policy para esvaziar o bucket antes do deploy"},{"id":"B","text":"Trocar para DynamoDB"},{"id":"C","text":"Adicionar DeletionPolicy: Retain ao bucket — em remoção do recurso, CloudFormation mantém o bucket em vez de tentar deletar"},{"id":"D","text":"Habilitar termination protection na stack"}]'::jsonb, 'C',
  '"(a) DeletionPolicy: Retain instrui o CloudFormation a soltar o recurso fora do gerenciamento da stack sem tentar deletar — bucket permanece intacto com objetos. Para também cobrir replacement, usar UpdateReplacePolicy: Retain. (b) Lifecycle só expira objetos com regras de idade; pode ajudar mas não resolve o caso geral. DynamoDB muda o serviço. Termination protection bloqueia delete da stack, não previne falha em delete de resource individual. (c) Regra: Retain é o seguro para storage com dados em mudanças de template. (d) Ver CloudFormation User Guide — DeletionPolicy attribute."'::jsonb,
  'Deployment', 'Deployment', 'medium', 'best-practice', '["cloudformation","deletion-policy","retain"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
