INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-080', 'aws-dva', 'Um deploy blue/green via CodeDeploy ECS está demorando mais que o esperado durante o test traffic stage. O developer quer ver métricas em tempo real do deployment progress. Qual ferramenta nativa fornece isso?',
  '[{"id":"A","text":"AWS Health Dashboard só"},{"id":"B","text":"X-Ray traces das funções Lambda"},{"id":"C","text":"AWS Cost Explorer"},{"id":"D","text":"CodeDeploy console (deployment status), CloudWatch metrics do ALB target groups e ECS service events"}]'::jsonb, 'D',
  '"(a) Console CodeDeploy mostra stage atual, % de traffic shifted e tempo restante de bake. CloudWatch metrics dos target groups (HealthyHostCount, TargetResponseTime) e ECS service events (describe-services events) complementam o diagnóstico em tempo real. (b) Health Dashboard mostra incidentes AWS, não o deploy. X-Ray traceia requisições. Cost Explorer é financeiro. (c) Regra: triagem de deploy ECS = console CodeDeploy + ALB metrics + ECS events. (d) Ver CodeDeploy User Guide — View deployment details."'::jsonb,
  'Deployment', 'Deployment', 'easy', 'troubleshoot', '["codedeploy","ecs","monitoring"]'::jsonb, 'ai-draft', 'active', now(), now()
)
