INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-001', 'aws-dva', 'Uma stack CloudFormation declara um RDS PostgreSQL para produção. O time quer que, mesmo se a stack for deletada por engano, o banco permaneça com seus dados intactos. Qual atributo de recurso garante esse comportamento?',
  '[{"id":"A","text":"DeletionPolicy: Retain no recurso AWS::RDS::DBInstance"},{"id":"B","text":"UpdateReplacePolicy: Delete"},{"id":"C","text":"DependsOn: RDSBackupBucket"},{"id":"D","text":"Metadata: { ''aws:cdk:doNotDelete'': true }"}]'::jsonb, 'A',
  '{
    "summary": "DeletionPolicy: Retain preserva o recurso quando a stack é deletada.",
    "whyCorrect": "DeletionPolicy aceita três valores — Delete (padrão), Retain (mantém o recurso fora da stack) e Snapshot (cria snapshot antes de deletar — válido para RDS, EBS, ElastiCache). Para garantir que o RDS sobreviva à deleção da stack, Retain é a escolha.",
    "whyWrong": {
     "B": "UpdateReplacePolicy controla o comportamento quando uma atualização exige SUBSTITUIÇÃO do recurso, não quando a stack é deletada. Delete aqui não preserva nada.",
     "C": "DependsOn cria ordenação de criação/deleção entre recursos — não impede deleção.",
     "D": "Esse metadata não existe no CloudFormation. CDK tem RemovalPolicy mas em CFN puro a propriedade é DeletionPolicy."
    },
    "keyConcept": "CloudFormation DeletionPolicy — Delete, Retain, Snapshot",
    "compareWith": [
     "DeletionPolicy vs UpdateReplacePolicy",
     "Retain vs Snapshot para RDS/EBS"
    ],
    "realWorldContext": "Bancos de produção, buckets S3 com dados regulatórios, EBS de logs LGPD — sempre Retain ou Snapshot.",
    "commonMistakes": "Esquecer que Snapshot só funciona em recursos que suportam snapshots nativos (RDS, EBS, ElastiCache, Neptune, Redshift). Em S3 não existe — use Retain.",
    "tutorSeeds": [
     "Quais recursos suportam DeletionPolicy: Snapshot?",
     "Como combinar DeletionPolicy + UpdateReplacePolicy?"
    ]
   }'::jsonb,
  'CloudFormation DeletionPolicy', 'Deployment', 'easy', 'best-practice', '["cloudformation","deletion-policy","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
