INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-002', 'aws-dva', 'Uma stack tem um RDS com DeletionPolicy: Retain. Após uma mudança no template que força substituição da instância (mudança de engine version major incompatível), o developer descobre que o RDS antigo foi DELETADO durante o update. Qual atributo deveria ter sido configurado?',
  '[{"id":"A","text":"DeletionPolicy: Snapshot"},{"id":"B","text":"UpdateReplacePolicy: Retain"},{"id":"C","text":"UpdatePolicy: AutoScalingRollingUpdate"},{"id":"D","text":"CreationPolicy: ResourceSignal"}]'::jsonb, 'B',
  '{
    "summary": "DeletionPolicy só age quando a stack é DELETADA; substituição em update usa UpdateReplacePolicy.",
    "whyCorrect": "UpdateReplacePolicy controla o que acontece com o recurso ANTIGO quando uma propriedade de imutabilidade força replacement (CloudFormation cria o novo, depois decide o que fazer com o antigo). Setar Retain preserva o RDS legado em vez de deletá-lo.",
    "whyWrong": {
     "A": "DeletionPolicy: Snapshot só dispara em delete-stack, não em update-replace.",
     "C": "UpdatePolicy é para AutoScalingGroup/Lambda alias/ElastiCache — não para RDS replacement.",
     "D": "CreationPolicy é para aguardar sinal de cfn-signal durante CRIAÇÃO, não relacionado a replacement."
    },
    "keyConcept": "DeletionPolicy (delete-stack) vs UpdateReplacePolicy (update-replace)",
    "compareWith": [
     "DeletionPolicy vs UpdateReplacePolicy",
     "Update sem replace vs com replace"
    ],
    "realWorldContext": "Bug clássico — equipe acha que Retain cobre tudo e perde produção em update aparentemente seguro.",
    "commonMistakes": "Tratar DeletionPolicy e UpdateReplacePolicy como sinônimos. Sempre setar OS DOIS para recursos críticos.",
    "tutorSeeds": [
     "Quais mudanças em RDS forçam replacement?",
     "Como ver se um update vai substituir um recurso antes de aplicar?"
    ]
   }'::jsonb,
  'CloudFormation UpdateReplacePolicy', 'Deployment', 'hard', 'troubleshoot', '["cloudformation","update-replace-policy","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
