INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-003', 'aws-dva', 'Uma stack network exporta o ID da VPC com Outputs.VpcId.Export.Name=''prod-vpc-id''. Outra stack precisa consumir esse valor para criar um security group. Qual função intrínseca deve ser usada?',
  '[{"id":"A","text":"Fn::GetAtt: [NetworkStack, VpcId]"},{"id":"B","text":"Fn::Ref: prod-vpc-id"},{"id":"C","text":"Fn::ImportValue: prod-vpc-id"},{"id":"D","text":"Fn::FindInMap: [Exports, VPC, Id]"}]'::jsonb, 'C',
  '{
    "summary": "Cross-stack references via Outputs.Export consomem com Fn::ImportValue.",
    "whyCorrect": "Fn::ImportValue resolve um valor exportado por outra stack. O nome passado deve bater EXATAMENTE com o Export.Name. Cria dependência forte — a stack importadora não pode ser criada antes da exportadora, nem o export pode ser apagado enquanto há importação ativa.",
    "whyWrong": {
     "A": "Fn::GetAtt só funciona DENTRO da mesma stack — pega atributo de um recurso local, não cross-stack.",
     "B": "Ref retorna ID do recurso local ou valor de um parameter — não consulta exports de outras stacks.",
     "D": "Fn::FindInMap consulta Mappings (lookup table estático no template), não exports."
    },
    "keyConcept": "Cross-stack references — Outputs.Export + Fn::ImportValue",
    "compareWith": [
     "Cross-stack references vs Nested stacks vs SSM Parameter Store",
     "Fn::ImportValue vs Fn::GetAtt"
    ],
    "realWorldContext": "Padrão para acoplar stacks de network/IAM/data — porém o acoplamento via export trava deleções; muitas equipes preferem SSM Parameter Store para flexibilidade.",
    "commonMistakes": "Tentar deletar a stack exportadora enquanto há ImportValue ativo — falha com ''Export cannot be deleted because it''s in use''.",
    "tutorSeeds": [
     "Como descobrir todas as stacks que importam um export?",
     "Quando preferir SSM Parameter Store em vez de Export?"
    ]
   }'::jsonb,
  'CloudFormation Cross-Stack', 'Deployment', 'medium', 'scenario', '["cloudformation","intrinsic-functions","import-value"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
