INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-004', 'aws-dva', 'Em um template CloudFormation o developer precisa construir uma string ARN combinando a partição (aws/aws-cn/aws-us-gov), a região atual, a conta atual e o nome de um bucket parametrizado. Qual abordagem é a mais idiomática?',
  '[{"id":"A","text":"Fn::Join: ['''', [''arn:aws:s3:::'', !Ref BucketName]]"},{"id":"B","text":"Fn::GetAtt: [Bucket, Arn]"},{"id":"C","text":"!Ref BucketArn"},{"id":"D","text":"Fn::Sub: ''arn:${AWS::Partition}:s3:::${BucketName}''"}]'::jsonb, 'D',
  '{
    "summary": "Fn::Sub com pseudo parameters AWS::Partition cria ARNs portáveis entre partições.",
    "whyCorrect": "Fn::Sub permite interpolação inline de variáveis (${...}), incluindo pseudo parameters como AWS::Partition, AWS::Region, AWS::AccountId. É legível e produz ARNs que funcionam em qualquer partição AWS (commercial, China, GovCloud) sem hardcode de ''aws''.",
    "whyWrong": {
     "A": "Fn::Join funciona mas hardcoda ''aws'' — quebra em GovCloud (precisaria ser ''aws-us-gov'') e é menos legível.",
     "B": "GetAtt Arn funciona apenas se o bucket for criado na MESMA stack — não serve para construir ARN a partir de um nome arbitrário.",
     "C": "Não existe BucketArn como parâmetro a menos que tenha sido declarado; a questão pede CONSTRUIR a partir do nome."
    },
    "keyConcept": "Intrinsic functions — Fn::Sub vs Fn::Join, pseudo parameters",
    "compareWith": [
     "Fn::Sub vs Fn::Join",
     "AWS::Partition vs hardcoded ''aws''"
    ],
    "realWorldContext": "Templates multi-region/multi-partition (clientes globais ou setor público) precisam de AWS::Partition para portabilidade.",
    "commonMistakes": "Hardcodar ''arn:aws:...'' e quebrar em GovCloud — sempre use ${AWS::Partition} em ARNs construídos.",
    "tutorSeeds": [
     "Quais são os pseudo parameters do CloudFormation?",
     "Como usar Fn::Sub com mapping para multi-substituição?"
    ]
   }'::jsonb,
  'CloudFormation Intrinsic Functions', 'Deployment', 'medium', 'best-practice', '["cloudformation","fn-sub","pseudo-parameters"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
