INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-005', 'aws-dva', 'Um template define dois ambientes (dev e prod) por meio de um Parameter EnvName. Em produção a stack deve criar uma réplica RDS e habilitar Multi-AZ; em dev, não. Qual recurso do CloudFormation atende?',
  '[{"id":"A","text":"Conditions + Condition attribute em recursos opcionais"},{"id":"B","text":"Dois templates separados sem reuso"},{"id":"C","text":"Mappings com chave EnvName e o Multi-AZ resolvido via Fn::FindInMap"},{"id":"D","text":"Nested stacks com TemplateURL distinto por env"}]'::jsonb, 'A',
  '{
    "summary": "Conditions ativam/desativam criação de recursos com base em parâmetros.",
    "whyCorrect": "Conditions são expressões booleanas no template (ex: !Equals [!Ref EnvName, prod]). Recursos com Condition: IsProd só são criados quando a condição é verdadeira. Permite UM template servir múltiplos ambientes — a réplica RDS literalmente NÃO existe em dev.",
    "whyWrong": {
     "B": "Dois templates duplicam código e violam DRY — exatamente o que Conditions evita.",
     "C": "Mappings é apenas lookup table — pode resolver o BOOLEAN para Multi-AZ, mas não consegue criar ou não-criar um recurso (réplica).",
     "D": "Nested stacks podem funcionar mas adicionam complexidade desnecessária para a diferença descrita."
    },
    "keyConcept": "CloudFormation Conditions — ativação condicional de recursos",
    "compareWith": [
     "Conditions vs Mappings vs Parameters with Default",
     "Single template multi-env vs separate templates"
    ],
    "realWorldContext": "Estratégia padrão dev/staging/prod com UM template — economiza manutenção e garante paridade estrutural.",
    "commonMistakes": "Esquecer que Outputs também aceitam Condition — se um Output referencia recurso condicional, ele mesmo precisa ter a Condition para evitar erro.",
    "tutorSeeds": [
     "Como combinar duas Conditions com Fn::And/Or?",
     "Conditions podem ser aplicadas em propriedades de um recurso?"
    ]
   }'::jsonb,
  'CloudFormation Conditions', 'Deployment', 'medium', 'scenario', '["cloudformation","conditions","multi-env"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
