INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-006', 'aws-dva', 'Um Parameter InstanceType no template deve aceitar apenas os tipos t3.small, t3.medium ou t3.large. Como impor essa restrição declarativamente?',
  '[{"id":"A","text":"AllowedPattern: ''^t3\\.(small|medium|large)$''"},{"id":"B","text":"AllowedValues: [t3.small, t3.medium, t3.large]"},{"id":"C","text":"Default: t3.small e validação manual em Lambda macro"},{"id":"D","text":"ConstraintDescription: ''apenas t3.small/medium/large''"}]'::jsonb, 'B',
  '{
    "summary": "AllowedValues garante seleção em lista fechada — o console renderiza um dropdown.",
    "whyCorrect": "AllowedValues é a forma idiomática para enumeração fechada — CloudFormation valida antes de iniciar a stack e o console mostra dropdown. Falha com mensagem clara se o valor não está na lista.",
    "whyWrong": {
     "A": "AllowedPattern funciona via regex mas é exagerado para um enum pequeno — perde o dropdown e a clareza.",
     "C": "Não é necessário macro — AllowedValues é nativo.",
     "D": "ConstraintDescription é apenas TEXTO de erro mostrado quando outra constraint falha — sozinho não restringe nada."
    },
    "keyConcept": "Parameter constraints — AllowedValues, AllowedPattern, MinLength, MaxLength, MinValue, MaxValue",
    "compareWith": [
     "AllowedValues vs AllowedPattern",
     "Console dropdown vs free text"
    ],
    "realWorldContext": "Templates usados por múltiplos times — restringir parâmetros evita typos e configurações inválidas.",
    "commonMistakes": "Esquecer que AllowedValues é case-sensitive — ''T3.small'' difere de ''t3.small''.",
    "tutorSeeds": [
     "Como combinar AllowedPattern com ConstraintDescription?",
     "Quais tipos de Parameter aceitam AllowedValues?"
    ]
   }'::jsonb,
  'CloudFormation Parameter Constraints', 'Deployment', 'easy', 'recall', '["cloudformation","parameters","allowed-values"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
