INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-007', 'aws-dva', 'Uma equipe quer reaproveitar um trecho YAML comum (tags padrão da empresa) em vários templates sem copy/paste. Qual recurso do CloudFormation permite incluir conteúdo de outro arquivo S3 durante o processamento?',
  '[{"id":"A","text":"AWS::Serverless transform"},{"id":"B","text":"Nested stack com TemplateURL"},{"id":"C","text":"AWS::Include transform"},{"id":"D","text":"Fn::ImportValue do bucket S3"}]'::jsonb, 'C',
  '{
    "summary": "AWS::Include é o macro nativo para textual include de snippets YAML/JSON do S3.",
    "whyCorrect": "AWS::Include é declarado em Transform e Fn::Transform: { Name: AWS::Include, Parameters: { Location: ''s3://bucket/snippet.yml'' } } injeta o conteúdo do arquivo no ponto da invocação durante o processamento do template. Ideal para tags padrão, IAM boilerplate, parameter groups reutilizáveis.",
    "whyWrong": {
     "A": "AWS::Serverless é o transform do SAM — converte AWS::Serverless::Function em Lambda + role + permissões.",
     "B": "Nested stack instancia outro stack inteiro com recursos — não faz textual include de snippet.",
     "D": "Fn::ImportValue lê outputs exportados por stacks, não conteúdo de arquivos em S3."
    },
    "keyConcept": "CloudFormation Transforms — AWS::Include vs AWS::Serverless vs custom macros",
    "compareWith": [
     "AWS::Include vs Nested stacks",
     "Transforms vs Macros"
    ],
    "realWorldContext": "Reuso de blocos padronizados (tags corporativas, IAM boilerplate) sem ter que manter cópias em cada template.",
    "commonMistakes": "Esquecer que o bucket precisa estar acessível pela role do CloudFormation no momento do CHANGE SET — falhas só aparecem no execute.",
    "tutorSeeds": [
     "Como criar um custom macro CloudFormation?",
     "Quando usar AWS::Include vs Nested stacks?"
    ]
   }'::jsonb,
  'CloudFormation AWS::Include', 'Deployment', 'medium', 'scenario', '["cloudformation","transform","aws-include"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
