INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-008', 'aws-dva', 'Em uma instância EC2 criada por CloudFormation, o developer quer instalar pacotes, gravar arquivos de configuração e iniciar serviços de forma declarativa via Metadata. Qual helper script aplica essas instruções no boot?',
  '[{"id":"A","text":"cfn-signal para sinalizar conclusão"},{"id":"B","text":"cfn-hup para detectar mudanças"},{"id":"C","text":"cfn-get-metadata isoladamente"},{"id":"D","text":"cfn-init lendo AWS::CloudFormation::Init"}]'::jsonb, 'D',
  '{
    "summary": "cfn-init lê o bloco AWS::CloudFormation::Init e executa packages/files/services/commands declarativamente.",
    "whyCorrect": "cfn-init é o helper que processa Metadata.AWS::CloudFormation::Init: ele instala pacotes (yum/apt/rpm), grava files com permissões, cria users/groups, executa commands em ordem alfabética e sobe services. É o jeito declarativo do CFN configurar instâncias.",
    "whyWrong": {
     "A": "cfn-signal só envia sucesso/falha para CreationPolicy ou WaitCondition — não instala nada.",
     "B": "cfn-hup é daemon que detecta mudanças no metadata e re-executa cfn-init — complementar, não substituto.",
     "C": "cfn-get-metadata apenas lê metadata bruto; não interpreta o schema Init."
    },
    "keyConcept": "Helper scripts — cfn-init, cfn-signal, cfn-hup, cfn-get-metadata",
    "compareWith": [
     "cfn-init vs UserData script puro",
     "Helper scripts vs Systems Manager"
    ],
    "realWorldContext": "Padrão clássico para EC2 imutáveis configuradas pelo CFN; tendência moderna é usar AMI golden + SSM em vez de cfn-init complexo.",
    "commonMistakes": "Esquecer que cfn-init falha silenciosa se UserData não chamar /opt/aws/bin/cfn-init explicitamente.",
    "tutorSeeds": [
     "Como debugar cfn-init no /var/log/cfn-init.log?",
     "Qual a ordem de execução dentro de AWS::CloudFormation::Init?"
    ]
   }'::jsonb,
  'CloudFormation Helper Scripts', 'Deployment', 'medium', 'recall', '["cloudformation","cfn-init","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()
)
