INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-009', 'aws-dva', 'Uma stack provisiona um ASG de 5 instâncias EC2 e o status precisa permanecer CREATE_IN_PROGRESS até que TODAS as instâncias confirmem aplicação bem-sucedida do bootstrap. Qual atributo deve ser usado no ASG?',
  '[{"id":"A","text":"CreationPolicy com ResourceSignal Count=5 e Timeout PT15M"},{"id":"B","text":"DependsOn com a lista de instâncias"},{"id":"C","text":"UpdatePolicy AutoScalingRollingUpdate"},{"id":"D","text":"WaitCondition após o ASG sem Handle"}]'::jsonb, 'A',
  '{
    "summary": "CreationPolicy + cfn-signal é o padrão moderno para aguardar bootstrap em ASG.",
    "whyCorrect": "CreationPolicy define ResourceSignal.Count (quantos sinais esperar) e Timeout. Cada instância chama cfn-signal --success no fim do UserData. Se o número de sinais SUCCESS bate antes do timeout, o recurso é marcado CREATE_COMPLETE. Caso contrário, rollback.",
    "whyWrong": {
     "B": "DependsOn só ordena criação — não espera sinal de aplicação configurada.",
     "C": "UpdatePolicy é para UPDATES (rolling/replacing/scheduled actions) — não para criação inicial.",
     "D": "WaitCondition funciona mas exige WaitConditionHandle separado e é considerado legado; CreationPolicy é a versão moderna recomendada."
    },
    "keyConcept": "CreationPolicy + cfn-signal vs WaitCondition (legado)",
    "compareWith": [
     "CreationPolicy vs WaitCondition",
     "ResourceSignal.Count vs Timeout"
    ],
    "realWorldContext": "Garantir que o ASG está realmente pronto antes do ELB começar a rotear — evita 502 durante deploy.",
    "commonMistakes": "Não chamar cfn-signal no UserData — o stack fica travado até o timeout e dá rollback.",
    "tutorSeeds": [
     "Como passar a --resource para cfn-signal?",
     "Quando WaitCondition ainda é necessário?"
    ]
   }'::jsonb,
  'CloudFormation CreationPolicy', 'Deployment', 'medium', 'scenario', '["cloudformation","creation-policy","asg"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
