INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-deploy-v2-010', 'aws-dva', 'Um time gerencia 30 contas AWS e quer fazer deploy de uma stack de baseline (CloudTrail + Config + IAM roles padrão) em todas elas, com governança a partir de uma conta de management. Qual ferramenta atende sem precisar deployar manualmente em cada conta?',
  '[{"id":"A","text":"Lambda que itera por contas chamando CreateStack"},{"id":"B","text":"CloudFormation StackSets com permission model SERVICE_MANAGED via Organizations"},{"id":"C","text":"AWS Config aggregator com regras"},{"id":"D","text":"Service Catalog produto compartilhado em cada conta"}]'::jsonb, 'B',
  '{
    "summary": "StackSets em modo SERVICE_MANAGED orquestra deploy multi-conta/multi-região via Organizations.",
    "whyCorrect": "StackSets é a feature nativa do CFN para deploy em N contas e M regiões a partir de uma admin account. Em SERVICE_MANAGED ele usa as service-linked roles via Organizations — não exige criar manualmente AWSCloudFormationStackSetExecutionRole em cada conta. Ideal para baseline corporativo.",
    "whyWrong": {
     "A": "Lambda iterando é reinventar a roda e perde retry, drift detection e managed orchestration do StackSets.",
     "C": "Config aggregator agrega DADOS de Config, não faz deploy de stacks.",
     "D": "Service Catalog publica produtos para self-service de usuários — não força deploy automático em 30 contas."
    },
    "keyConcept": "CloudFormation StackSets — SELF_MANAGED vs SERVICE_MANAGED, OUs targeting",
    "compareWith": [
     "StackSets vs Control Tower customizations",
     "SELF_MANAGED roles vs SERVICE_MANAGED"
    ],
    "realWorldContext": "Padrão para landing zones, baseline de segurança, distribuição de IAM padrão em organizações grandes.",
    "commonMistakes": "Confundir StackSet com Stack — StackSet é template + targets; cada instância em conta/região é um StackInstance.",
    "tutorSeeds": [
     "Como funciona delegated administrator para StackSets?",
     "Diferença entre auto-deployment e manual stack instances?"
    ]
   }'::jsonb,
  'CloudFormation StackSets', 'Deployment', 'medium', 'scenario', '["cloudformation","stacksets","organizations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
