INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-001', 'aws-dva', 'Um developer está criando uma função Lambda em Node.js 20 para processar eventos de API Gateway. Qual é a assinatura correta do handler para uma função async que retorna uma resposta HTTP?',
  '[{"id":"A","text":"exports.handler = async (event, context) =\u003e { return { statusCode: 200, body: JSON.stringify({ ok: true }) }; }"},{"id":"B","text":"exports.main = (req, res) =\u003e { res.send(''ok''); }"},{"id":"C","text":"module.exports = function(event) { return ''ok''; }"},{"id":"D","text":"export default async function(request) { return new Response(''ok''); }"}]'::jsonb, 'A',
  '"(a) Lambda em Node.js usa o padrão exports.handler(event, context) — assinatura assíncrona retorna Promise que o runtime resolve automaticamente. Para API Gateway proxy integration, deve retornar objeto com statusCode/body. (b) (req,res) é assinatura Express, não Lambda. (c) Sem statusCode falha proxy integration. (d) Sintaxe Fetch API/Workers — não Lambda Node.js. Regra: handler sempre recebe (event, context [, callback])."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'recall', '["lambda","handler","nodejs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
