INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-002', 'aws-dva', 'Uma função Lambda Python 3.12 precisa compartilhar uma biblioteca pesada (pandas + numpy, ~80 MB) entre 10 funções diferentes. Atualmente cada deploy package tem 80 MB duplicados. Qual recurso o developer deve usar para evitar duplicação?',
  '[{"id":"A","text":"Subir as bibliotecas para S3 e baixar no cold start"},{"id":"B","text":"Lambda Layer contendo as bibliotecas, referenciada por cada função"},{"id":"C","text":"Usar Lambda Extensions"},{"id":"D","text":"Empacotar tudo em uma imagem Docker única"}]'::jsonb, 'B',
  '"(a) Lambda Layers permitem empacotar dependências separadamente e anexar a múltiplas funções — uma layer é versionada, compartilhada por ARN, e descompactada em /opt no runtime. Reduz tamanho do deploy package e centraliza atualizações. (b) Download em cold start adiciona latência significativa. (c) Extensions são para observability/lifecycle hooks, não bibliotecas de runtime. (d) Imagem Docker resolve mas força container packaging. Regra: deps compartilhadas = Layer."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["lambda","layers","dependencies"]'::jsonb, 'ai-draft', 'active', now(), now()
)
