INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-003', 'aws-dva', 'Um developer configura uma Lambda crítica que precisa garantir <50ms de latência mesmo em horários de pico. Cold starts ocasionais estão causando timeouts no cliente. Qual configuração resolve isso de forma direta?',
  '[{"id":"A","text":"Aumentar o timeout da função para 30s"},{"id":"B","text":"Aumentar a memória para 10240 MB"},{"id":"C","text":"Configurar Provisioned Concurrency para o número esperado de invocações simultâneas"},{"id":"D","text":"Usar Lambda@Edge"}]'::jsonb, 'C',
  '"(a) Provisioned Concurrency mantém N execution environments pré-inicializados, eliminando cold start para até N invocações concorrentes. (b) Aumentar timeout não elimina cold start, só evita timeout do próprio Lambda. Memória reduz duração mas ainda há cold start. Lambda@Edge é para CloudFront, não resolve latência genérica. (c) Regra: latência consistente = Provisioned Concurrency; eventualmente combinar com Application Auto Scaling para escalar conforme tráfego. (d) Ver Lambda Developer Guide — Provisioned Concurrency."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","provisioned-concurrency","cold-start"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
