INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-004', 'aws-dva', 'Uma função Lambda lê DB_PASSWORD de uma variável de ambiente em texto claro. O security review pediu para criptografar esse valor at-rest no Lambda. Qual é a abordagem nativa do Lambda?',
  '[{"id":"A","text":"Mover o segredo para o código da função"},{"id":"B","text":"Usar S3 com SSE-S3 para armazenar o valor"},{"id":"C","text":"Codificar o valor em base64 antes de salvar"},{"id":"D","text":"Habilitar criptografia de env vars com KMS Customer Managed Key"}]'::jsonb, 'D',
  '"(a) Lambda criptografa env vars at-rest por padrão com AWS-owned key, mas você pode escolher uma CMK para controle, audit e rotação. Ainda assim, idealmente segredos vão para Secrets Manager. (b) Hardcode em código é antipadrão. S3 não é nativo da função. Base64 não é criptografia. (c) Regra: para segredos reais, Secrets Manager > env var criptografada > env var texto claro. (d) Ver Lambda Developer Guide — Environment variable encryption."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["lambda","env-vars","kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
