INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-005', 'aws-dva', 'Um developer está debugando timeouts em uma Lambda que faz query em RDS. Os logs mostram que a primeira invocação demora 4s, mas subsequentes 200ms. Qual técnica reduz a latência da primeira invocação?',
  '[{"id":"A","text":"Inicializar o connection pool fora do handler (escopo de módulo)"},{"id":"B","text":"Criar connection dentro do handler em toda invocação"},{"id":"C","text":"Aumentar o timeout para 1 minuto"},{"id":"D","text":"Usar synchronous invocation"}]'::jsonb, 'A',
  '"(a) Código fora do handler executa apenas no cold start (init phase), permitindo que recursos pesados como connection pools sejam reutilizados em warm invocations no mesmo container. (b) Criar conexão a cada invocação destrói o ganho. Aumentar timeout não reduz latência, só evita timeout. Synchronous é o modo padrão da maioria. (c) Regra: inicialização pesada → escopo de módulo; lógica request-specific → handler. (d) Ver Lambda Developer Guide — Execution environment lifecycle."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'troubleshoot', '["lambda","cold-start","connection-pool"]'::jsonb, 'ai-draft', 'active', now(), now()
)
