INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-006', 'aws-dva', 'Uma função Lambda configurada com memorySize=512 está fazendo CPU-bound work (transformação de imagens). O developer observa que aumentar memória para 3008 MB reduz a duração em 6x. Por quê?',
  '[{"id":"A","text":"Memória extra ativa GPU automaticamente"},{"id":"B","text":"Lambda aloca CPU proporcionalmente à memória configurada"},{"id":"C","text":"Lambda usa swap em disco quando memória é baixa"},{"id":"D","text":"É um bug do runtime que será corrigido"}]'::jsonb, 'B',
  '"(a) Lambda aloca CPU (vCPUs) proporcional à memória: 1769 MB ≈ 1 vCPU completo, 3008 MB ≈ ~1.7 vCPU, 10240 MB ≈ 6 vCPUs. Para CPU-bound workloads, aumentar memória dá CPU extra, reduzindo duração — frequentemente até reduzindo custo total. (b) Lambda não tem GPU. Sem swap. Não é bug. (c) Regra: pricing = GB-segundos; mais memória pode SER mais barato se duração cai proporcionalmente. Use AWS Lambda Power Tuning. (d) Ver Lambda Developer Guide — Memory and computing power."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","memory","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
