INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-007', 'aws-dva', 'Um developer precisa que uma Lambda acesse RDS em uma subnet privada e também faça chamadas a DynamoDB. Após colocar a função em VPC, as chamadas a DynamoDB começam a falhar. Qual é a causa mais provável?',
  '[{"id":"A","text":"Lambda em VPC perde acesso à internet automaticamente"},{"id":"B","text":"DynamoDB exige IAM user, não role"},{"id":"C","text":"A subnet não tem NAT Gateway nem VPC Endpoint para DynamoDB"},{"id":"D","text":"Lambda em VPC só pode chamar RDS"}]'::jsonb, 'C',
  '"(a) Quando Lambda roda em VPC, todo tráfego sai pela ENI da subnet. Acesso a serviços AWS públicos (DynamoDB, S3) exige NAT Gateway para internet OU um Gateway VPC Endpoint para o serviço. Gateway endpoint para DynamoDB é gratuito e mantém o tráfego no AWS backbone. (b) Lambda em VPC não tem internet por padrão — depende da subnet. Lambda pode chamar qualquer serviço, depende do networking. (c) Regra: VPC Lambda + serviços públicos = NAT ou VPC Endpoint. (d) Ver Lambda Developer Guide — VPC networking."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["lambda","vpc","dynamodb","networking"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
