INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-008', 'aws-dva', 'Uma Lambda é invocada por SQS e processa pedidos. O developer quer garantir que apenas 10 mensagens sejam processadas simultaneamente para não sobrecarregar uma API downstream. Como configurar?',
  '[{"id":"A","text":"Diminuir o visibility timeout da fila SQS"},{"id":"B","text":"Reduzir memorySize da Lambda"},{"id":"C","text":"Setar maxBatchSize do event source em 10"},{"id":"D","text":"Definir Reserved Concurrency = 10 na função"}]'::jsonb, 'D',
  '"(a) Reserved Concurrency limita o número máximo de execuções concorrentes da função. Setar em 10 impede que SQS escale o consumo além disso (excedente fica na fila). (b) Visibility timeout afeta retry, não throttling. memorySize é CPU/memória. maxBatchSize é mensagens por invocação (até 10000 para FIFO/Standard com batching), não invocações simultâneas. (c) Regra: throttling de paralelismo = Reserved Concurrency; batch size = msgs por execução. (d) Ver Lambda Developer Guide — Reserved concurrency."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","reserved-concurrency","sqs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
