INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-009', 'aws-dva', 'Um developer precisa empacotar uma Lambda Python que usa uma biblioteca C compilada (psycopg2-binary). Localmente em macOS funciona, mas em produção dá ImportError: cannot import name ''extensions''. Como corrigir?',
  '[{"id":"A","text":"Compilar a dependência em um ambiente Amazon Linux 2 ou usar container image"},{"id":"B","text":"Aumentar memorySize da Lambda"},{"id":"C","text":"Usar runtime Python 2.7"},{"id":"D","text":"Adicionar a biblioteca via apt-get no handler"}]'::jsonb, 'A',
  '"(a) Lambda roda em Amazon Linux 2/2023. Bibliotecas C compiladas localmente em macOS/Windows são incompatíveis com o runtime. Solução: compilar em container `public.ecr.aws/lambda/python:3.12`, usar SAM build com --use-container, ou empacotar como container image. (b) Memória não resolve incompatibilidade binária. Python 2.7 está EOL no Lambda. apt-get não existe em runtime. (c) Regra: dependências nativas → build no ambiente alvo. (d) Ver Lambda Developer Guide — Deployment package."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["lambda","python","native-deps","packaging"]'::jsonb, 'ai-draft', 'active', now(), now()
)
