INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-010', 'aws-dva', 'Uma equipe usa uma única função Lambda para múltiplos ambientes (dev/stg/prod). Querem que cada ambiente tenha sua própria configuração e seja possível reverter rapidamente sem redeploy. Qual feature do Lambda atende?',
  '[{"id":"A","text":"Duplicar a função para cada ambiente"},{"id":"B","text":"Versions + Aliases (cada alias aponta para uma version e tem env vars próprias)"},{"id":"C","text":"Usar tags do CloudFormation"},{"id":"D","text":"Diferentes Layers por ambiente"}]'::jsonb, 'B',
  '"(a) Lambda Versions são snapshots imutáveis ($LATEST não é version); Aliases são ponteiros nomeados para versions, com seus próprios env vars e weighted routing. Pattern: alias `prod` → version 7, `stg` → version 8. Rollback é trocar o ponteiro do alias. (b) Funções duplicadas violam DRY. Tags são metadata, não configuração. Layers podem variar mas não substituem env vars por env. (c) Regra: deploy + rollback rápido = alias + version + weighted alias. (d) Ver Lambda Developer Guide — Versions and aliases."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","versions","aliases","rollback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
