INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-011', 'aws-dva', 'Um developer configura uma Lambda com 15 minutos de timeout para processar arquivos grandes do S3. A função frequentemente falha aos 14:55 e perde trabalho. Qual abordagem é melhor para esse workload?',
  '[{"id":"A","text":"Aumentar o timeout para 30 minutos"},{"id":"B","text":"Aumentar memorySize"},{"id":"C","text":"Quebrar o processamento em múltiplas Lambdas orquestradas por Step Functions"},{"id":"D","text":"Migrar para Lambda@Edge"}]'::jsonb, 'C',
  '"(a) 15 min é o teto máximo do Lambda. Para workloads mais longos, fragmente em etapas menores e use Step Functions (até 1 ano de execução em Standard) para orquestrar com state, retry e error handling. Alternativa: ECS/Fargate para containers de longa duração. (b) Timeout máximo do Lambda é 900s (15 min) — não há como aumentar. Memória reduz duração mas se já dá timeout, é estrutural. Lambda@Edge tem limites ainda menores. (c) Regra: jobs >15 min = Step Functions, Fargate ou Batch. (d) Ver Lambda Developer Guide — Function timeout."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","timeout","step-functions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
