INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-012', 'aws-dva', 'Uma Lambda chamada async via SNS falha intermitentemente. O developer quer capturar essas falhas em uma fila para inspeção posterior sem perder mensagens. Como configurar?',
  '[{"id":"A","text":"Aumentar memória da função"},{"id":"B","text":"Mudar invocação para sync"},{"id":"C","text":"Desabilitar retries automáticos"},{"id":"D","text":"Configurar Dead Letter Queue (DLQ) SQS na função Lambda"}]'::jsonb, 'D',
  '"(a) Lambda em async invocation faz até 2 retries automáticos. Se todos falharem, envia o evento para a DLQ configurada (SQS ou SNS) ou para o Destination on Failure (mais moderno, suporta EventBridge/Lambda/SQS/SNS). (b) Memória pode ajudar mas não captura falhas. Sync invocation força o caller a tratar erro. Desabilitar retry perde resiliência sem capturar evidência. (c) Regra: async + falhas observáveis = DLQ ou On-Failure Destination. (d) Ver Lambda Developer Guide — Asynchronous invocation."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["lambda","dlq","async","destinations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
