INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-013', 'aws-dva', 'Um developer Python quer logar de uma Lambda. Quais opções funcionam para que os logs apareçam no CloudWatch Logs sem configuração extra?',
  '[{"id":"A","text":"print() e logging do stdlib — ambos vão para stdout/stderr capturados pelo Lambda"},{"id":"B","text":"Apenas chamadas explícitas para boto3 CloudWatch Logs PutLogEvents"},{"id":"C","text":"Escrever em /tmp/log.txt"},{"id":"D","text":"Configurar logback no handler"}]'::jsonb, 'A',
  '"(a) Lambda redireciona stdout/stderr para CloudWatch Logs automaticamente — print() e logger.info() funcionam direto. O execution role precisa de logs:CreateLogStream e logs:PutLogEvents (incluso em AWSLambdaBasicExecutionRole). (b) PutLogEvents manual funciona mas é redundante. /tmp não é persistido. logback é Java. (c) Regra: Lambda + CloudWatch Logs = stdout/stderr; precisa de permissões na execution role. (d) Ver Lambda Developer Guide — Logging."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'recall', '["lambda","logging","cloudwatch"]'::jsonb, 'ai-draft', 'active', now(), now()
)
