INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-014', 'aws-dva', 'Uma equipe usa o context object dentro do handler Lambda. Qual informação NÃO está disponível no context em runtime?',
  '[{"id":"A","text":"context.getRemainingTimeInMillis() — tempo restante antes do timeout"},{"id":"B","text":"context.invokerIpAddress — IP do cliente que chamou a função"},{"id":"C","text":"context.functionName e context.functionVersion"},{"id":"D","text":"context.awsRequestId — ID único da invocação"}]'::jsonb, 'B',
  '"(a) Lambda context não expõe IP do invoker — para chamadas via API Gateway, o IP vem em event.requestContext.identity.sourceIp. (b) getRemainingTimeInMillis é útil para early exit antes de timeout; functionName/Version identificam a função; awsRequestId aparece nos logs e é útil para correlação. (c) Regra: context = metadata da execução; event = payload com dados de quem invocou. (d) Ver Lambda Developer Guide — Context object."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'recall', '["lambda","context","runtime"]'::jsonb, 'ai-draft', 'active', now(), now()
)
