INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-015', 'aws-dva', 'Um developer migra uma função Lambda Node.js 14 (EOL) para Node.js 20. Qual abordagem minimiza risco em produção?',
  '[{"id":"A","text":"Atualizar diretamente $LATEST em produção e monitorar"},{"id":"B","text":"Trocar o runtime no console sem teste"},{"id":"C","text":"Publicar nova version, criar alias canário com 5% de tráfego, monitorar erros, depois shift gradual"},{"id":"D","text":"Aumentar memória antes de trocar runtime"}]'::jsonb, 'C',
  '"(a) Weighted aliases permitem traffic shifting gradual (canary deployments). Crie version com runtime novo, configure alias com routingConfig (95% old / 5% new), monitore CloudWatch Metrics e Alarms, então ajuste pesos. CodeDeploy automatiza isso. (b) Trocar $LATEST direto expõe 100% imediatamente. Sem teste é arriscado. Memória não está relacionada a runtime upgrade. (c) Regra: mudanças de runtime/lib = canary ou linear deploy via alias weighted routing. (d) Ver Lambda Developer Guide — Traffic shifting."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["lambda","deployment","canary","alias"]'::jsonb, 'ai-draft', 'active', now(), now()
)
