INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-016', 'aws-dva', 'Uma Lambda é invocada pelo S3 Object Created event. O developer precisa garantir que se a função falhar, o evento não seja perdido. Qual configuração é necessária?',
  '[{"id":"A","text":"Configurar visibility timeout no S3"},{"id":"B","text":"S3 sempre garante delivery, nada a fazer"},{"id":"C","text":"Habilitar Reserved Concurrency=0"},{"id":"D","text":"Configurar On-Failure Destination ou DLQ — S3 chama Lambda em modo async"}]'::jsonb, 'D',
  '"(a) S3 invoca Lambda assincronamente. Lambda faz 2 retries automáticos; depois descarta. Para captura, configure On-Failure Destination (SQS/SNS/EventBridge/Lambda) ou DLQ. (b) S3 não tem visibility timeout (isso é SQS). Sem destino configurado, eventos falhos são perdidos. RC=0 desliga a função. (c) Regra: S3 → Lambda é async; sempre configure DLQ/Destination em produção. (d) Ver Lambda Developer Guide — Event source S3."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","s3","async","dlq"]'::jsonb, 'ai-draft', 'active', now(), now()
)
