INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-017', 'aws-dva', 'Uma Lambda é invocada por Kinesis Data Streams. O developer observa que se uma mensagem falhar, todo o batch é re-processado, causando duplicação. Qual configuração mitiga isso?',
  '[{"id":"A","text":"Habilitar BisectBatchOnFunctionError e ReportBatchItemFailures"},{"id":"B","text":"Aumentar BatchSize"},{"id":"C","text":"Reduzir o número de shards"},{"id":"D","text":"Desabilitar retries da Kinesis"}]'::jsonb, 'A',
  '"(a) Para Kinesis/DynamoDB Streams como event source, BisectBatchOnFunctionError divide o batch em dois ao falhar (binary search da msg ruim). ReportBatchItemFailures permite que o handler retorne `batchItemFailures: [{itemIdentifier}]` para reprocessar apenas as falhas. (b) BatchSize maior agrava o problema. Menos shards reduz paralelismo. Sem retry, dados são perdidos. (c) Regra: streams + falhas parciais = ReportBatchItemFailures (partial batch response). (d) Ver Lambda Developer Guide — Stream event source."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["lambda","kinesis","batch","partial-failure"]'::jsonb, 'ai-draft', 'active', now(), now()
)
