INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-018', 'aws-dva', 'Um developer quer invocar uma Lambda de outro serviço AWS de forma síncrona, esperando o resultado. Qual InvocationType usar na chamada SDK?',
  '[{"id":"A","text":"InvocationType: ''Event''"},{"id":"B","text":"InvocationType: ''RequestResponse''"},{"id":"C","text":"InvocationType: ''DryRun''"},{"id":"D","text":"InvocationType: ''Async''"}]'::jsonb, 'B',
  '"(a) RequestResponse é sync — o SDK bloqueia até a função retornar (ou timeout). Retorna Payload com o output. (b) Event é async — retorna 202 imediatamente, sem aguardar; usado para fire-and-forget. DryRun valida permissões sem executar. ''Async'' não é um valor válido na API. (c) Regra: precisa do resultado = RequestResponse; fire-and-forget = Event; teste de permissão = DryRun. (d) Ver Lambda Developer Guide — Invoke API."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'recall', '["lambda","invocation","sdk"]'::jsonb, 'ai-draft', 'active', now(), now()
)
