INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-019', 'aws-dva', 'Uma Lambda invocada via API Gateway precisa retornar binary data (PDF gerado on-the-fly). Qual configuração é necessária?',
  '[{"id":"A","text":"Retornar o PDF como string UTF-8"},{"id":"B","text":"Habilitar S3 antes do API Gateway"},{"id":"C","text":"Configurar binaryMediaTypes no API Gateway e retornar isBase64Encoded=true no response"},{"id":"D","text":"API Gateway não suporta binary"}]'::jsonb, 'C',
  '"(a) API Gateway suporta binary se: (1) binaryMediaTypes inclui o Content-Type (ex: application/pdf) e (2) Lambda retorna { body: base64String, isBase64Encoded: true, headers: { ''Content-Type'': ''application/pdf'' } }. API Gateway decodifica o base64 antes de enviar ao cliente. (b) String UTF-8 corrompe binary. S3 é alternativa via presigned URL (também válido), mas opção A é direta. API Gateway suporta binary. (c) Regra: binary response = binaryMediaTypes + isBase64Encoded. (d) Ver API Gateway Developer Guide — Binary media types."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["api-gateway","lambda","binary"]'::jsonb, 'ai-draft', 'active', now(), now()
)
