INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-020', 'aws-dva', 'Um developer está escolhendo entre REST API e HTTP API no API Gateway para um novo microservice. O serviço precisa apenas de JWT auth (Cognito), CORS e proxy para Lambda — sem caching, request validation ou WAF. Qual escolher e por quê?',
  '[{"id":"A","text":"REST API — sempre é melhor"},{"id":"B","text":"WebSocket API — para qualquer chamada HTTP"},{"id":"C","text":"REST API porque HTTP API não suporta Lambda"},{"id":"D","text":"HTTP API — mais barata, menor latência, JWT/CORS nativos suportados"}]'::jsonb, 'D',
  '"(a) HTTP API é ~70% mais barata e até 60% menor latência que REST. Suporta JWT authorizer (Cognito/Auth0), CORS, Lambda proxy. Trade-off: não tem cache, request validators, WAF integration, edge-optimized endpoint, API keys/usage plans. (b) REST é overkill se você não usa suas features extras. WebSocket é para conexões persistentes. HTTP API integra com Lambda nativamente. (c) Regra: features básicas modernas = HTTP API; features enterprise/legacy = REST API. (d) Ver API Gateway Developer Guide — Choose API type."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["api-gateway","http-api","rest-api"]'::jsonb, 'ai-draft', 'active', now(), now()
)
