INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-021', 'aws-dva', 'Um developer cria uma REST API no API Gateway com stages dev e prod. Após mudanças no resource /users, dev funciona mas prod retorna ''Missing Authentication Token''. Qual passo foi esquecido?',
  '[{"id":"A","text":"Fazer ''Deploy API'' para o stage prod após alterações"},{"id":"B","text":"Reiniciar o API Gateway"},{"id":"C","text":"Apagar e recriar o stage"},{"id":"D","text":"Habilitar CORS no stage prod"}]'::jsonb, 'A',
  '"(a) No REST API do API Gateway, mudanças em resources/methods/integrations não entram em produção até um ''Deploy API'' para o stage específico. Stages são snapshots imutáveis do deployment. (b) Não há restart manual. Apagar stage perde URL. CORS desconfigurado retornaria erro CORS, não Missing Authentication Token (que é o 403 do API Gateway quando rota não existe). (c) Regra: REST API = sempre deploy after change; HTTP API faz auto-deploy se habilitado. (d) Ver API Gateway Developer Guide — Deploying API."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'troubleshoot', '["api-gateway","deploy","stages"]'::jsonb, 'ai-draft', 'active', now(), now()
)
