INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-022', 'aws-dva', 'Uma API recebe 10.000 RPS em um endpoint público. O developer quer proteger a backend Lambda de picos súbitos. Onde configurar throttling no API Gateway REST?',
  '[{"id":"A","text":"Adicionar uma WAF rule de throttle"},{"id":"B","text":"Stage-level throttling (rate/burst) e/ou Usage Plans com API Keys por cliente"},{"id":"C","text":"Reduzir memorySize da Lambda"},{"id":"D","text":"Não é possível fazer throttling no API Gateway"}]'::jsonb, 'B',
  '"(a) Throttling default account é 10.000 RPS / 5.000 burst por região. Por stage ou method você define rate/burst customizados. Para multi-tenant, Usage Plans associam API Keys a quotas/throttles por cliente. Excedentes recebem 429 Too Many Requests. (b) WAF rate-based rules existem mas são para abuse/DDoS, não throttling fino por cliente. memorySize não throttla. API Gateway tem throttling nativo. (c) Regra: limit por API/cliente = Stage throttle / Usage Plan. (d) Ver API Gateway Developer Guide — Throttling."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["api-gateway","throttling","usage-plan"]'::jsonb, 'ai-draft', 'active', now(), now()
)
