INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-023', 'aws-dva', 'Um developer configura um Lambda Authorizer (TOKEN type) no API Gateway. A função retorna o policy mas todas as chamadas recebem 401. Os logs mostram que o authorizer não é invocado para todas requests. Qual otimização está causando isso?',
  '[{"id":"A","text":"Lambda Authorizer não suporta TOKEN type"},{"id":"B","text":"Falta habilitar WAF"},{"id":"C","text":"Authorization caching no authorizer está retornando resultado de chamadas anteriores com tokens diferentes"},{"id":"D","text":"API Gateway tem bug"}]'::jsonb, 'C',
  '"(a) Lambda Authorizer tem auth caching configurável (TTL default 300s) usando o token como chave (TOKEN) ou identidades especificadas (REQUEST). Se a policy retornada negar acesso, o resultado é cacheado e chamadas subsequentes com mesmo token recebem 401 sem invocar o authorizer. (b) TOKEN é tipo válido. WAF é outra camada. Não é bug. (c) Regra: para debug, desabilite cache temporariamente (TTL=0); para prod, retorne policy com context dinâmico e cuidado com TTL. (d) Ver API Gateway Developer Guide — Lambda Authorizer."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["api-gateway","lambda-authorizer","cache"]'::jsonb, 'ai-draft', 'active', now(), now()
)
