INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-024', 'aws-dva', 'Um developer precisa que um endpoint API Gateway aceite query strings ?status=active e passe ao Lambda. Está usando Lambda non-proxy (custom) integration. O Lambda recebe payload vazio. O que falta configurar?',
  '[{"id":"A","text":"Habilitar CORS"},{"id":"B","text":"Mudar HTTP method para POST"},{"id":"C","text":"Lambda non-proxy não suporta query strings"},{"id":"D","text":"Body Mapping Template no Integration Request usando VTL para mapear $input.params(''status'')"}]'::jsonb, 'D',
  '"(a) Em non-proxy integration, você define explicitamente o payload via Body Mapping Template (Velocity Template Language). Exemplo: { \"status\": \"$input.params(''status'')\" }. Em proxy integration, API Gateway envia tudo (queryStringParameters, headers, body) automaticamente. (b) CORS é browser-side. Method não afeta query strings. Non-proxy suporta tudo via mapping. (c) Regra: non-proxy = mapping templates explícitos; proxy = passthrough automático. (d) Ver API Gateway Developer Guide — Mapping templates."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["api-gateway","mapping-template","vtl"]'::jsonb, 'ai-draft', 'active', now(), now()
)
