INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-025', 'aws-dva', 'Um chat em tempo real precisa que servidor envie mensagens push para clientes web sem que esses façam polling. Qual tipo de API no API Gateway o developer deve escolher?',
  '[{"id":"A","text":"WebSocket API — conexões bidirecionais persistentes com routes $connect, $disconnect, $default"},{"id":"B","text":"REST API com long polling"},{"id":"C","text":"HTTP API com SSE"},{"id":"D","text":"Lambda Function URL"}]'::jsonb, 'A',
  '"(a) WebSocket API mantém conexão TCP persistente; clientes conectam (@connect), enviam mensagens com routeSelectionExpression, e backend pode push via @connections POST API ({connectionId}). Use cases: chat, notifications, dashboards live. (b) Long polling é workaround com latência. SSE é unidirecional server→client e API Gateway HTTP não tem suporte nativo de longa duração. Function URLs são HTTPS sync simples. (c) Regra: bidirecional realtime = WebSocket; server-push unidirecional = SNS+Mobile/IoT/CloudFront. (d) Ver API Gateway Developer Guide — WebSocket APIs."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["api-gateway","websocket","realtime"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
