INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-026', 'aws-dva', 'Uma API recebe 90% de tráfego em /products/{id} GET, com payload que muda raramente. O developer quer reduzir custo e latência. Qual feature do REST API atende?',
  '[{"id":"A","text":"Aumentar memória do Lambda"},{"id":"B","text":"API Gateway caching no stage (configurar TTL e cache key parameters)"},{"id":"C","text":"Mudar para HTTP API (que tem cache)"},{"id":"D","text":"Usar S3 em vez de API Gateway"}]'::jsonb, 'B',
  '"(a) REST API suporta caching por stage com cache cluster (0.5 GB a 237 GB), TTL configurável e cache key parameters (ex: path id). Response é cacheada e o Lambda não é invocado em hits. Pode invalidar via header `Cache-Control: max-age=0` com permissão. (b) Memória Lambda não afeta cache. HTTP API NÃO tem cache nativo. S3 é storage, não API. (c) Regra: cache de API = REST API stage cache; HTTP API não tem (usa CloudFront separado). (d) Ver API Gateway Developer Guide — API caching."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["api-gateway","cache","stage"]'::jsonb, 'ai-draft', 'active', now(), now()
)
