INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-027', 'aws-dva', 'Um developer publica API REST. Quer que browsers em outro domínio (ex: app.example.com) chamem a API. Após implementar, requests preflight OPTIONS recebem 403. O que fazer?',
  '[{"id":"A","text":"Adicionar IAM policy"},{"id":"B","text":"Aumentar throttle"},{"id":"C","text":"Habilitar CORS no recurso: gera OPTIONS method com Access-Control-Allow-* headers"},{"id":"D","text":"Mudar para HTTP API que não precisa CORS"}]'::jsonb, 'C',
  '"(a) Browsers enviam OPTIONS preflight para cross-origin. Habilitar CORS no API Gateway cria o método OPTIONS que retorna Access-Control-Allow-Origin, Allow-Methods, Allow-Headers. Em proxy integration, também é preciso retornar esses headers nas respostas reais. (b) IAM é auth, não CORS. Throttle não afeta. HTTP API também precisa de CORS config (mais simples, declarativa). (c) Regra: cross-origin browser = CORS no API + headers no Lambda response. (d) Ver API Gateway Developer Guide — CORS."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'troubleshoot', '["api-gateway","cors","browser"]'::jsonb, 'ai-draft', 'active', now(), now()
)
