INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-028', 'aws-dva', 'Um developer cria um endpoint público com Lambda Function URL em vez de API Gateway. Quais limitações deve considerar?',
  '[{"id":"A","text":"Function URLs não suportam HTTPS"},{"id":"B","text":"Cada função pode ter no máximo 10 URLs"},{"id":"C","text":"Function URLs custam mais que API Gateway"},{"id":"D","text":"Sem custom domain nativo, sem WAF direto, sem usage plans/API keys, auth limitada a IAM ou NONE"}]'::jsonb, 'D',
  '"(a) Function URLs são endpoints HTTPS gratuitos diretos para Lambda, mas: domínio é fixo (lambda-url.region.on.aws), sem WAF integration direta (precisa CloudFront na frente), sem API keys/usage plans, AuthType é apenas NONE (público) ou AWS_IAM. (b) HTTPS é compulsório. (c) Uma URL por função (única). Function URLs são gratuitas (apenas custo do invoke). (d) Regra: webhook simples ou interno = Function URL; features completas de API = API Gateway. (e) Ver Lambda Developer Guide — Function URLs."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["lambda","function-url","api-gateway"]'::jsonb, 'ai-draft', 'active', now(), now()
)
