INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-029', 'aws-dva', 'Um developer modela uma tabela DynamoDB para uma aplicação multi-tenant SaaS de tickets. Cada tenant tem milhares de tickets. Queries comuns: ''todos tickets de um tenant'', ''ticket por ID''. Qual desenho de chave é eficiente?',
  '[{"id":"A","text":"PK=TENANT#\u003ctenantId\u003e, SK=TICKET#\u003cticketId\u003e — Query por PK lista tickets do tenant; GetItem por PK+SK busca ticket único"},{"id":"B","text":"PK=\u003cticketId\u003e apenas — usar Scan para listar por tenant"},{"id":"C","text":"PK=\u003ctenantId\u003e, sem SK — duplicar registros"},{"id":"D","text":"Criar uma tabela separada por tenant"}]'::jsonb, 'A',
  '"(a) Composite key com PK=tenant e SK=ticket permite Query eficiente por tenant (single partition scan) e GetItem direto por (tenant, ticketId). Padrão single-table design comum em DynamoDB. (b) Scan é O(n), antieconômico. Sem SK não há ordenação/range. Tabela por tenant explode operações (limites de contas, custos, manutenção). (c) Regra: relação 1:N = PK do pai + SK do filho; consultas seguem o key design. (d) Ver DynamoDB Developer Guide — Best practices for keys."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","key-design","pk-sk"]'::jsonb, 'ai-draft', 'active', now(), now()
)
