INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-030', 'aws-dva', 'Em uma tabela com PK=userId e SK=createdAt, o developer precisa buscar usuários por email frequentemente. Adicionar um Scan com FilterExpression está caro e lento. Solução?',
  '[{"id":"A","text":"Criar um Local Secondary Index (LSI) com SK=email"},{"id":"B","text":"Criar um Global Secondary Index (GSI) com PK=email"},{"id":"C","text":"Habilitar DAX"},{"id":"D","text":"Aumentar RCU da tabela"}]'::jsonb, 'B',
  '"(a) GSI permite uma chave de partição alternativa (email), retornando os itens correspondentes — eventually consistent. O developer faz Query(IndexName, KeyConditionExpression=\"email = :e\"). (b) LSI compartilha PK com tabela base e só varia SK; não atende ''buscar por email arbitrário''. DAX é cache mas não muda padrão de acesso. Mais RCU acelera Scan mas Scan ainda é antipadrão. (c) Regra: nova chave de acesso = GSI; mesmo PK com SK alternativa = LSI; LSI só pode ser criada na criação da tabela. (d) Ver DynamoDB Developer Guide — Global secondary indexes."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","gsi","lsi"]'::jsonb, 'ai-draft', 'active', now(), now()
)
