INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-031', 'aws-dva', 'Um developer precisa atualizar um saldo de conta em DynamoDB de forma atômica: ler valor atual, somar e gravar. Múltiplas Lambdas podem fazer isso concorrentemente. Como evitar lost update?',
  '[{"id":"A","text":"GetItem + PutItem sequenciais"},{"id":"B","text":"Aumentar RCU/WCU"},{"id":"C","text":"UpdateItem com expressão ADD e ConditionExpression, ou usar transações"},{"id":"D","text":"Usar BatchWriteItem"}]'::jsonb, 'C',
  '"(a) UpdateItem com UpdateExpression \"ADD balance :amt\" é atômico no nível do item — não tem race. Se precisa validar antes (ex: saldo >= debit), use ConditionExpression. Para múltiplos itens atômicos, TransactWriteItems garante all-or-nothing. (b) Get+Put separados deixam janela de race. RCU/WCU é capacidade, não atomicidade. BatchWriteItem não é atômico (cada item é independente). (c) Regra: increment/decrement atômico = UpdateItem ADD; multi-item atomic = transactions. (d) Ver DynamoDB Developer Guide — Atomic counters."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","atomic","update-item","transactions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
