INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-032', 'aws-dva', 'Uma tabela DynamoDB recebe gravações intensas em apenas algumas partition keys (ex: tenant ''ACME'' tem 80% do tráfego). O developer recebe ProvisionedThroughputExceededException. Qual é o problema?',
  '[{"id":"A","text":"ConsumedCapacity está em zero"},{"id":"B","text":"RCU está sobrando"},{"id":"C","text":"Falta DAX"},{"id":"D","text":"Hot partition — distribuição desigual de tráfego excede capacidade de partição (~1000 WCU)"}]'::jsonb, 'D',
  '"(a) DynamoDB distribui capacidade entre partições. Cada partição tem limite ~3000 RCU / 1000 WCU. Se uma única PK concentra escrita, satura a partição mesmo com WCU total alto na tabela. Soluções: write sharding (sufixo aleatório na PK), redesign de chave para distribuir, on-demand mode (adapta-se), exponential backoff no SDK. (b) ConsumedCapacity=0 indica zero uso. RCU sobrando não causa write throttle. DAX é read-cache, não ajuda em writes. (c) Regra: hot partition = redesign de chave + jitter + on-demand. (d) Ver DynamoDB Developer Guide — Best practices for partition keys."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["dynamodb","hot-partition","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
