INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-033', 'aws-dva', 'Um developer ativa DynamoDB Streams. Quer que cada mudança seja replicada para um sistema externo via Lambda. Qual StreamViewType captura o estado completo antes e depois da mudança?',
  '[{"id":"A","text":"NEW_AND_OLD_IMAGES"},{"id":"B","text":"KEYS_ONLY"},{"id":"C","text":"NEW_IMAGE"},{"id":"D","text":"OLD_IMAGE"}]'::jsonb, 'A',
  '"(a) NEW_AND_OLD_IMAGES envia tanto o item antes quanto depois da mudança — útil para audit, diff, replicação completa. (b) KEYS_ONLY só PK/SK; NEW_IMAGE só o estado pós; OLD_IMAGE só pré. (c) Regra: replicação completa ou audit = NEW_AND_OLD_IMAGES; lookup de mudança = NEW_IMAGE; sinal-only = KEYS_ONLY. Cada opção afeta custo de storage do stream. (d) Ver DynamoDB Developer Guide — Streams."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'recall', '["dynamodb","streams","view-type"]'::jsonb, 'ai-draft', 'active', now(), now()
)
