INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-034', 'aws-dva', 'Um caso de uso lê o mesmo conjunto de 1000 itens DynamoDB milhares de vezes por segundo (read-heavy). O developer quer reduzir latência para <1ms e RCU. Qual serviço usar?',
  '[{"id":"A","text":"ElastiCache Redis externo"},{"id":"B","text":"DynamoDB Accelerator (DAX) — write-through cache in-memory para DynamoDB"},{"id":"C","text":"S3 Transfer Acceleration"},{"id":"D","text":"CloudFront na frente do DynamoDB"}]'::jsonb, 'B',
  '"(a) DAX é cache write-through fully managed para DynamoDB, com latência sub-ms para read hits. SDK do DAX é drop-in compatível. Item cache e query cache. Não exige código de invalidação para writes (DAX intercepta). (b) Redis exige lógica de cache-aside manual. S3 TA é upload acceleration. CloudFront não tem integration direta com DynamoDB API. (c) Regra: cache nativo para DynamoDB = DAX; cache genérico = Redis/Memcached. (d) Ver DynamoDB Developer Guide — DAX."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["dynamodb","dax","cache"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
