INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-035', 'aws-dva', 'Um developer precisa transferir $100 entre duas contas em DynamoDB: debitar A e creditar B, ambos com sucesso ou ambos rollback. Como implementar?',
  '[{"id":"A","text":"Dois UpdateItem sequenciais com try/catch"},{"id":"B","text":"BatchWriteItem"},{"id":"C","text":"TransactWriteItems com 2 updates, cada um com ConditionExpression"},{"id":"D","text":"PutItem com lock manual"}]'::jsonb, 'C',
  '"(a) TransactWriteItems suporta até 100 ações (Put/Update/Delete/ConditionCheck) all-or-nothing entre múltiplos items/tabelas. ConditionExpression em cada update valida pré-condições (saldo suficiente). Custa 2x WCU vs writes normais. (b) Sequenciais não são atômicos — se o 2º falha, A já foi debitado. BatchWriteItem é batch para throughput, sem atomicidade transacional. Lock manual é antipadrão. (c) Regra: atomicidade multi-item = TransactWriteItems; leitura transacional = TransactGetItems. (d) Ver DynamoDB Developer Guide — Transactions."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","transactions","atomicity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
