INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-036', 'aws-dva', 'Uma Lambda lê items com GetItem do DynamoDB. Após uma escrita recente, às vezes o GetItem retorna o valor antigo. Como forçar consistência?',
  '[{"id":"A","text":"Aumentar RCU"},{"id":"B","text":"Habilitar DAX"},{"id":"C","text":"Usar Scan em vez de GetItem"},{"id":"D","text":"Passar ConsistentRead=true no GetItem (strongly consistent)"}]'::jsonb, 'D',
  '"(a) Por default DynamoDB usa eventual consistency (mais barato, maior throughput). ConsistentRead=true retorna o valor mais recente após qualquer escrita confirmada, custando 2x RCU. Funciona em GetItem, Query, Scan; NÃO funciona em GSI (que é sempre eventually consistent). (b) Mais RCU não muda consistência. DAX agrava staleness (cache). Scan não muda consistência. (c) Regra: read-after-write = ConsistentRead=true; GSI é sempre eventual. (d) Ver DynamoDB Developer Guide — Read consistency."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'troubleshoot', '["dynamodb","consistency","read"]'::jsonb, 'ai-draft', 'active', now(), now()
)
