INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-037', 'aws-dva', 'Um developer quer expirar registros DynamoDB automaticamente após 30 dias (ex: sessões). Como implementar sem código de cleanup?',
  '[{"id":"A","text":"Habilitar TTL na tabela apontando para um attribute com epoch Unix de expiração"},{"id":"B","text":"Rodar um Lambda diário com Scan + Delete"},{"id":"C","text":"Usar S3 Lifecycle Rules"},{"id":"D","text":"Configurar VPC endpoint"}]'::jsonb, 'A',
  '"(a) DynamoDB TTL: habilite a feature e nomeie um attribute (ex: ''expiresAt'') que contém Unix epoch (segundos). DynamoDB remove items expirados em background (sem custo WCU). Pode levar até 48h após expiração. Para auditoria, items deletados aparecem em Streams com userIdentity=dynamodb. (b) Scan+Delete custa WCU e RCU. S3 Lifecycle é para S3. VPC endpoint é networking. (c) Regra: expiração automática = TTL; expiração imediata exige delete manual. (d) Ver DynamoDB Developer Guide — Time to Live."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["dynamodb","ttl","expiration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
