INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-038', 'aws-dva', 'Um workload imprevisível tem picos súbitos seguidos de longas horas com tráfego baixo. O developer não quer gerenciar capacity nem auto-scaling. Qual capacity mode escolher?',
  '[{"id":"A","text":"Provisioned com WCU=10000"},{"id":"B","text":"On-Demand — paga por request, escala instantaneamente"},{"id":"C","text":"Reserved Capacity"},{"id":"D","text":"DynamoDB Local"}]'::jsonb, 'B',
  '"(a) On-Demand cobra por request (RRU/WRU). Sem provisionamento, escala automaticamente até 2x do pico anterior em segundos. Ideal para workloads novos/imprevisíveis. ~7x mais caro por request que Provisioned, mas economiza em provisionar para pico. (b) Provisioned fixo desperdiça em vales e satura em picos. Reserved Capacity é um discount sobre Provisioned (1y/3y commitment). DynamoDB Local é para dev local. (c) Regra: imprevisível/spikey = On-Demand; previsível 24/7 = Provisioned (+ auto-scaling/RC). (d) Ver DynamoDB Developer Guide — Capacity modes."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","on-demand","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
