INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-039', 'aws-dva', 'Um Lambda lê 500 items DynamoDB por chamada via Query. O developer quer reduzir custo de RCU descartando attributes desnecessários do response. Qual parâmetro usar?',
  '[{"id":"A","text":"ProjectionExpression — limita attributes retornados (mas consumo RCU é pelo item completo lido)"},{"id":"B","text":"Limit — descarta items"},{"id":"C","text":"Nenhuma opção reduz custo"},{"id":"D","text":"FilterExpression — pré-filtra antes de ler"}]'::jsonb, 'C',
  '"(d) Curioso: ProjectionExpression e FilterExpression reduzem dados de NETWORK e CPU do client, mas DynamoDB cobra RCU pelo tamanho do item completo lido do disco — não pelos attributes retornados. Filter ocorre após ler. Para reduzir RCU real, use índice covering com Projection=INCLUDE/KEYS_ONLY (Query no índice menor). (a-c) Não reduzem RCU consumido. (b) Regra: economizar RCU = ler menos itens (Query mais precisa, GSI covering). (c) Ver DynamoDB Developer Guide — Read/write capacity."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'recall', '["dynamodb","rcu","projection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
