INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-040', 'aws-dva', 'Um developer quer fazer upload de um arquivo de 5 GB para S3 a partir do browser do usuário, sem que o arquivo passe pelo servidor backend. Qual padrão usar?',
  '[{"id":"A","text":"Stream o arquivo pelo backend Lambda (limite de 6 MB sync)"},{"id":"B","text":"Upload via API Gateway com Lambda proxy"},{"id":"C","text":"Salvar em /tmp e mover ao S3 depois"},{"id":"D","text":"Gerar presigned POST/PUT URL no backend; browser faz upload direto para S3"}]'::jsonb, 'D',
  '"(a) S3 presigned URL é assinatura temporária que autoriza um cliente não-autenticado a fazer um PUT/POST/GET específico, com expiração configurável. Backend gera via SDK (createPresignedPost / getSignedUrl); browser faz upload direto para S3 — economiza bandwidth/Lambda. Para arquivos grandes, combine com multipart upload. (b) Lambda sync payload max 6 MB. API Gateway max 10 MB. /tmp Lambda max 10 GB mas é roundtrip extra. (c) Regra: upload large file = presigned URL direto ao S3. (d) Ver S3 User Guide — Presigned URLs."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["s3","presigned-url","upload"]'::jsonb, 'ai-draft', 'active', now(), now()
)
