INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-041', 'aws-dva', 'Um developer faz upload de um arquivo de 2 GB para S3 usando putObject do SDK. A conexão cai aos 80% e o upload reinicia do zero. Qual técnica do S3 SDK resolve o problema de retomar uploads grandes?',
  '[{"id":"A","text":"Multipart Upload — partes de 5 MB a 5 GB enviadas em paralelo; partes falhas são reenviadas isoladamente"},{"id":"B","text":"Aumentar o timeout do SDK"},{"id":"C","text":"Usar S3 Transfer Acceleration sem mudar código"},{"id":"D","text":"Habilitar versioning no bucket"}]'::jsonb, 'A',
  '"(a) Multipart Upload divide o objeto em partes (min 5 MB exceto última), uploads em paralelo e permite retomar partes falhas sem reenviar tudo. SDKs high-level (S3TransferManager / Upload class) gerenciam automaticamente. Obrigatório para objetos >5 GB. (b) Timeout maior não resolve queda de conexão. Transfer Acceleration acelera via edge mas não dá retry parcial. Versioning é histórico, não upload resiliente. (c) Regra: arquivo >100 MB = multipart; >5 GB = multipart obrigatório. (d) Ver S3 User Guide — Multipart Upload."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["s3","multipart","sdk"]'::jsonb, 'ai-draft', 'active', now(), now()
)
