INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-042', 'aws-dva', 'Um developer gera uma presigned URL com expiração de 7 dias para download de relatório S3, mas a URL expira em 1 hora. As credenciais usadas vêm de uma IAM role assumida via STS. Por que a URL não dura 7 dias?',
  '[{"id":"A","text":"S3 não suporta URLs de 7 dias"},{"id":"B","text":"Presigned URLs herdam a duração máxima das credenciais; credenciais STS temporárias limitam o tempo de validade"},{"id":"C","text":"Bucket policy força expiração curta"},{"id":"D","text":"É necessário habilitar Object Lock"}]'::jsonb, 'B',
  '"(a) Presigned URL é válida apenas enquanto as credenciais que a assinaram são válidas. Credenciais de IAM role/STS expiram em 1h (padrão) ou até 12h. Para presigned URLs de 7 dias, use credenciais de IAM user (long-lived) — mas isso quebra best practice de segurança. Alternativa: regenerar URL antes de expirar via Lambda. (b) S3 suporta até 7 dias mas com credenciais long-lived. Bucket policy/Object Lock não afetam validade da assinatura. (c) Regra: presigned URL longa = credencial long-lived (não recomendado); abordagem moderna = regenerar via API. (d) Ver S3 User Guide — Presigned URLs."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["s3","presigned-url","sts","iam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
