INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-043', 'aws-dva', 'Um developer precisa migrar automaticamente objetos antigos (>90 dias) de S3 Standard para S3 Glacier Deep Archive sem rodar código próprio. Qual configurar?',
  '[{"id":"A","text":"Lambda diário que faz CopyObject"},{"id":"B","text":"Replicar para outro bucket Glacier"},{"id":"C","text":"S3 Lifecycle Configuration com transition action para Glacier Deep Archive aos 90 dias"},{"id":"D","text":"Habilitar Intelligent-Tiering manualmente por objeto"}]'::jsonb, 'C',
  '"(a) S3 Lifecycle rules permitem transitions automáticas entre storage classes baseadas em idade, tamanho, tags ou prefixos, sem código. Regra: Standard → Glacier Deep Archive aos 90 dias. Há restrições (min 30 dias antes de IA, 90 antes de Deep Archive). Também suporta Expiration. (b) Lambda+CopyObject funciona mas é overhead. Replication cobra duplicado. Intelligent-Tiering é automático mas tem outro modelo (camadas internas, sem ação do dev). (c) Regra: lifecycle = transition/expiration automatizada e sem código. (d) Ver S3 User Guide — Lifecycle configuration."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["s3","lifecycle","glacier"]'::jsonb, 'ai-draft', 'active', now(), now()
)
