INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-044', 'aws-dva', 'Um developer precisa que objetos novos no bucket disparem uma Lambda. Após configurar S3 Event Notifications, eventos só disparam para alguns objetos. A análise mostra que múltiplos arquivos são criados na mesma chave (overwrite). Qual é o comportamento esperado?',
  '[{"id":"A","text":"S3 nunca emite eventos para overwrites"},{"id":"B","text":"S3 emite eventos apenas para o primeiro PUT da chave"},{"id":"C","text":"Eventos S3 não suportam Lambda"},{"id":"D","text":"S3 entrega notifications at-least-once por evento PUT, mas overwrites na mesma chave podem coalescer se concorrentes; pedidos sequenciais geram eventos distintos"}]'::jsonb, 'D',
  '"(a) S3 Event Notifications são at-least-once mas não fornecem ordem global garantida. Em uploads concorrentes para mesma chave, pode haver perda de eventos intermediários — só o vencedor da corrida (latest write wins) gera evento determinístico. Para garantir todos os eventos, habilite versioning (cada PUT gera versão única). (b) S3 emite para overwrites sequenciais distintos. Não emite só primeiro. Suporta Lambda/SQS/SNS/EventBridge. (c) Regra: para audit completo de mudanças, S3 + versioning + EventBridge é mais robusto que SNS/Lambda direto. (d) Ver S3 User Guide — Event Notifications."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["s3","event-notifications","versioning"]'::jsonb, 'ai-draft', 'active', now(), now()
)
