INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-045', 'aws-dva', 'Um developer precisa criptografar objetos S3 at-rest com chave gerenciada pelo cliente para audit/rotation, mas sem gerenciar HSM. Qual opção SSE escolher?',
  '[{"id":"A","text":"SSE-KMS com Customer Managed Key (CMK) — KMS gerencia o material, você define key policy e rotation"},{"id":"B","text":"SSE-S3 — chave gerenciada totalmente pela AWS, sem controle de audit"},{"id":"C","text":"SSE-C com chave HSM dedicada gerenciada pelo developer"},{"id":"D","text":"Cliente-side encryption obrigatória"}]'::jsonb, 'A',
  '"(a) SSE-KMS com CMK dá controle de key policy, audit via CloudTrail (kms:Decrypt logs), rotation automática anual, e separação entre encrypt/decrypt permissions. Custa $1/mês por CMK + requests. (b) SSE-S3 (AES-256, AWS-managed) não loga uso de chave. SSE-C exige enviar chave em cada request — overhead. Client-side é mais complexo. (c) Regra: audit/compliance/rotation = SSE-KMS CMK; simples e free = SSE-S3; controle máximo = client-side. (d) Ver S3 User Guide — Server-Side Encryption with KMS."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["s3","encryption","kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
