INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-046', 'aws-dva', 'Um developer recebe SlowDown (503) do S3 ao gravar 8.000 objetos/s em um único prefixo. O bucket suporta mais que isso. Qual é o problema e a solução?',
  '[{"id":"A","text":"Bucket está em região errada"},{"id":"B","text":"S3 escala por prefixo (3.500 PUT/COPY/POST/DELETE por prefixo); usar múltiplos prefixos com hash distribui carga"},{"id":"C","text":"Falta habilitar Transfer Acceleration"},{"id":"D","text":"Versioning está desabilitado"}]'::jsonb, 'B',
  '"(a) S3 escala automaticamente até 3.500 PUT/COPY/POST/DELETE e 5.500 GET/HEAD por segundo por prefixo. Para >3.500 writes, distribua chaves em múltiplos prefixos (ex: ano/mes/hash ou hash/data). Antes de 2018 era necessário hash explícito para hot-spot prevention; hoje S3 escala mas chaves muito concentradas em um prefixo ainda saturam. (b) Região não causa 503. TA acelera latência, não throughput por prefixo. Versioning não afeta. (c) Regra: high write = particionar prefixos; exponential backoff no SDK lida com bursts. (d) Ver S3 User Guide — Request rate performance."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["s3","throughput","prefix","slowdown"]'::jsonb, 'ai-draft', 'active', now(), now()
)
