INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-047', 'aws-dva', 'Um developer faz upload de um arquivo único de 200 GB ao S3 e quer paralelizar para reduzir tempo. Qual configuração do SDK aproveita ao máximo a banda?',
  '[{"id":"A","text":"Um único PutObject de 200 GB"},{"id":"B","text":"Aumentar a Size do bucket"},{"id":"C","text":"Multipart Upload com partes de 100 MB em paralelo (até 10.000 partes); ajustar partSize/queueSize do TransferManager"},{"id":"D","text":"Habilitar versioning"}]'::jsonb, 'C',
  '"(a) Multipart paralelo é a forma canônica para arquivos grandes. SDKs (S3TransferManager em Java, Upload em Node/Python aws-sdk v3, boto3 TransferConfig) paralelizam partes. Ajustar partSize (default 8 MB-25 MB) para 64-100 MB com queueSize alto satura a NIC. Limite: 10.000 partes; arquivo único máx 5 TiB. (b) PutObject sync máx 5 GB sem multipart. Bucket size não existe como conceito (S3 é infinito). Versioning não acelera. (c) Regra: arquivos grandes = multipart paralelo + TransferManager tuning. (d) Ver S3 User Guide — Multipart Upload limits."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["s3","multipart","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
