INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-048', 'aws-dva', 'Uma equipe orquestra um workflow ETL: extrai dados de RDS (Lambda 1), valida (Lambda 2), grava em S3 (Lambda 3). Em caso de falha em Lambda 2, querem reexecutar apenas essa etapa com backoff exponencial e capturar erro distinto se for timeout vs erro de validação. Qual serviço orquestra isso?',
  '[{"id":"A","text":"SQS encadeando as 3 Lambdas"},{"id":"B","text":"Lambda chamando Lambda diretamente via SDK"},{"id":"C","text":"EventBridge com regex"},{"id":"D","text":"Step Functions Standard com Retry e Catch específicos por estado, tratando ErrorEquals diferentes"}]'::jsonb, 'D',
  '"(a) Step Functions tem Retry (com IntervalSeconds, MaxAttempts, BackoffRate, JitterStrategy) e Catch por ErrorEquals (ex: States.Timeout, Lambda.ServiceException, ValidationError customizado). Cada Task state pode ter retry policy distinta e fallback states. Visualização e history nativos. (b) SQS encadeado não tem retry granular nem visibility de workflow. Lambda-to-Lambda acopla e perde retry estruturado. EventBridge é roteamento, não orquestração com state. (c) Regra: workflow com state, retry, error handling = Step Functions. (d) Ver Step Functions Developer Guide — Error handling."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["step-functions","retry","catch","orchestration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
  explanation   = EXCLUDED.explanation,
