INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-049', 'aws-dva', 'Um developer escolhe entre Step Functions Standard e Express para um workflow que dispara 10.000 vezes por segundo, com duração média de 2s e custos críticos. Qual escolher?',
  '[{"id":"A","text":"Express Workflows — alto volume (até 100k/s), execuções até 5 min, cobrança por invocação+duração, sem histórico visual completo"},{"id":"B","text":"Standard — sempre é mais barato"},{"id":"C","text":"Standard porque Express não suporta Lambda"},{"id":"D","text":"Não pode usar Step Functions; use Lambda direto"}]'::jsonb, 'A',
  '"(a) Express é otimizado para high-volume, short-lived (max 5 min). Cobra por número de execuções + duração (GB-s), tipicamente bem mais barato em alto volume. Standard cobra por state transitions (caro em alto volume) mas tem histórico visual completo, suporta execuções de 1 ano, exactly-once. Express é at-least-once. (b) Standard é caro em volume alto. Express suporta Lambda. Step Functions é apropriado. (c) Regra: high-volume e <5 min = Express; long-running + audit completo = Standard. (d) Ver Step Functions Developer Guide — Standard vs Express."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["step-functions","express","standard"]'::jsonb, 'ai-draft', 'active', now(), now()
)
