INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-050', 'aws-dva', 'Um Step Function precisa processar 1000 items de uma lista em paralelo (até 40 simultâneos) e agregar os resultados. Qual state usar?',
  '[{"id":"A","text":"Parallel state com 1000 branches"},{"id":"B","text":"Map state com MaxConcurrency=40 — itera sobre array em paralelo, agrega outputs em array"},{"id":"C","text":"Choice state em loop"},{"id":"D","text":"Pass state com transform"}]'::jsonb, 'B',
  '"(a) Map state itera sobre InputPath (array) executando Iterator (sub-workflow) por item. MaxConcurrency limita paralelismo. Inline Map até 40 concorrentes; Distributed Map (modo) suporta 10.000 e processa S3 manifests. Output é array agregado dos resultados. (b) Parallel é para N branches DISTINTOS conhecidos em design-time (não data-driven). Choice é routing condicional. Pass transforma sem executar. (c) Regra: fan-out paralelo de array = Map; ramos distintos pré-definidos = Parallel. (d) Ver Step Functions Developer Guide — Map state."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["step-functions","map","parallel"]'::jsonb, 'ai-draft', 'active', now(), now()
)
