INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-051', 'aws-dva', 'Um Step Function chama uma Lambda que ocasionalmente retorna Lambda.TooManyRequestsException. O developer quer retry com backoff exponencial: 1s, 2s, 4s, 8s, máx 5 tentativas. Como configurar?',
  '[{"id":"A","text":"Aumentar timeout da Lambda"},{"id":"B","text":"Reduzir BatchSize"},{"id":"C","text":"Retry: [{ ErrorEquals: [''Lambda.TooManyRequestsException''], IntervalSeconds: 1, BackoffRate: 2.0, MaxAttempts: 5 }]"},{"id":"D","text":"Step Functions não suporta retry"}]'::jsonb, 'C',
  '"(a) Retry no Task state: IntervalSeconds (inicial), BackoffRate (multiplicador, 2.0 = duplica), MaxAttempts (5), MaxDelaySeconds (cap). Para 1,2,4,8s use BackoffRate=2.0. JitterStrategy=FULL adiciona randomização (recomendado para thundering herd). ErrorEquals pode listar erros específicos ou ''States.ALL'' como wildcard. (b) Timeout não retry. BatchSize não se aplica a Task state. SF suporta retry nativo. (c) Regra: backoff = IntervalSeconds * BackoffRate^(attempt-1); sempre adicione jitter. (d) Ver Step Functions Developer Guide — Retry."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["step-functions","retry","backoff"]'::jsonb, 'ai-draft', 'active', now(), now()
)
