INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-052', 'aws-dva', 'Um workflow precisa esperar aprovação humana antes de continuar — pode levar dias. Como modelar em Step Functions Standard sem polling?',
  '[{"id":"A","text":"Wait state com 7 dias hardcoded"},{"id":"B","text":"Lambda em loop fazendo polling de DynamoDB"},{"id":"C","text":"Standard não suporta workflows longos"},{"id":"D","text":"Task state com .waitForTaskToken: envia taskToken para SNS/SQS, o aprovador chama SendTaskSuccess/Failure quando decide"}]'::jsonb, 'D',
  '"(a) Pattern .waitForTaskToken (callback): o Task state pausa indefinidamente até que SendTaskSuccess({taskToken, output}) ou SendTaskFailure seja chamado. Standard suporta execuções até 1 ano. Útil para human approval, integrações com sistemas externos com webhook, jobs assíncronos. HeartbeatSeconds detecta workers mortos. (b) Wait hardcoded é frágil. Polling caro e desnecessário. Standard suporta workflows longos. (c) Regra: human-in-the-loop = .waitForTaskToken; espera fixa = Wait state. (d) Ver Step Functions Developer Guide — Callback pattern."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["step-functions","task-token","callback","approval"]'::jsonb, 'ai-draft', 'active', now(), now()
)
