INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-053', 'aws-dva', 'Um Step Function chama Lambda via integração otimizada (arn:aws:states:::lambda:invoke). O output do state contém tanto o payload retornado quanto metadata (StatusCode, ExecutedVersion). Como acessar apenas o body retornado pela função?',
  '[{"id":"A","text":"OutputPath ou ResultSelector para extrair $.Payload"},{"id":"B","text":"Usar arn:aws:states:::lambda direto"},{"id":"C","text":"Modificar a Lambda para retornar string"},{"id":"D","text":"Step Functions não suporta extração de campo"}]'::jsonb, 'A',
  '"(a) ResultSelector aplica JSONPath ao resultado bruto antes de mesclar no input. Exemplo: { \"data.$\": \"$.Payload\" }. OutputPath filtra o output final do state. Em integração otimizada de Lambda, o resultado é {Payload, StatusCode, ExecutedVersion, ...}; ResultSelector \"$.Payload\" extrai só o útil. (b) :::lambda direto não existe (é :::lambda:invoke). Modificar Lambda quebra reuso. SF suporta extração completa via JSONPath. (c) Regra: ResultSelector é o ponto de extração após Task; OutputPath é o filtro final. (d) Ver Step Functions Developer Guide — Input/Output processing."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["step-functions","result-selector","jsonpath"]'::jsonb, 'ai-draft', 'active', now(), now()
)
