INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-054', 'aws-dva', 'Um Step Function Standard tem 50 Task states e roda 10.000 execuções/dia. O custo está alto. Como reduzir gastos preservando funcionalidade?',
  '[{"id":"A","text":"Aumentar memória das Lambdas"},{"id":"B","text":"Migrar para Express Workflows se duração \u003c5 min ou agrupar estados com Pass/Choice para reduzir state transitions"},{"id":"C","text":"Usar mais Wait states"},{"id":"D","text":"Reduzir o número de execuções rejeitando inputs"}]'::jsonb, 'B',
  '"(a) Standard cobra ~$25 por milhão de state transitions. 50 transitions x 10.000 exec/dia = 500k/dia = ~$375/mês só em transitions. Express cobra por exec + duração GB-s, geralmente muito mais barato em alta cardinalidade. Se não pode migrar, reduza transitions: combine lógica em Lambdas maiores, use Pass com Parameters em vez de múltiplos states intermediários. (b) Memória Lambda é custo separado, não Step Functions. Wait não reduz transitions. Rejeitar inputs é mudança funcional. (c) Regra: state transitions = custo SF Standard; volume alto = Express; design = menos transitions. (d) Ver Step Functions Developer Guide — Pricing."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'best-practice', '["step-functions","cost","optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
