INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-055', 'aws-dva', 'Um developer precisa que um Step Function Express seja invocado SINCRONAMENTE por uma Lambda (a Lambda precisa esperar o resultado). Qual API usar?',
  '[{"id":"A","text":"StartExecution + polling com DescribeExecution"},{"id":"B","text":"StartExecution com WaitForResult=true"},{"id":"C","text":"StartSyncExecution — disponível apenas para Express, retorna o resultado completo no response"},{"id":"D","text":"Standard suporta sync; Express não"}]'::jsonb, 'C',
  '"(a) StartSyncExecution é exclusiva de Express Workflows. Lambda chama e bloqueia até o workflow completar, recebendo o output direto. Limite de 5 min (mesmo da Express). Standard só tem StartExecution + polling DescribeExecution (assíncrono). (b) Polling é o pattern de Standard mas caro/lento. WaitForResult não existe na API. (c) Regra: sync execution = apenas Express; Standard = sempre async. (d) Ver Step Functions Developer Guide — Synchronous Express."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'recall', '["step-functions","express","sync"]'::jsonb, 'ai-draft', 'active', now(), now()
)
