INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-056', 'aws-dva', 'Uma equipe usa EventBridge para rotear eventos de diferentes serviços para múltiplas Lambdas. Eles querem que apenas eventos de S3 com bucket=''prod-uploads'' E object size>1MB cheguem em uma Lambda específica. Como configurar?',
  '[{"id":"A","text":"Criar 10 regras, uma por bucket"},{"id":"B","text":"Filtrar dentro do código da Lambda"},{"id":"C","text":"EventBridge não suporta filtros compostos"},{"id":"D","text":"Event Pattern com source=[''aws.s3''] e detail filters combinados (bucket.name + object.size com numeric matching)"}]'::jsonb, 'D',
  '"(a) EventBridge Event Patterns suportam matching exato, prefix, anything-but, numeric (>, <, =), exists, ip-address. Exemplo: { source: [''aws.s3''], detail: { bucket: { name: [''prod-uploads''] }, object: { size: [{ numeric: [''>'', 1048576] }] } } }. Filtragem no broker evita invocações desnecessárias da Lambda (poupa custo). (b) 10 regras é overhead. Filtrar na Lambda gasta invocações com eventos descartados. EventBridge suporta filtros ricos. (c) Regra: filtrar SEMPRE no Event Pattern, não na função. (d) Ver EventBridge User Guide — Event patterns."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["eventbridge","event-pattern","filtering"]'::jsonb, 'ai-draft', 'active', now(), now()
)
