INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-057', 'aws-dva', 'Um developer precisa rodar uma Lambda toda terça-feira às 09:00 horário de São Paulo. Qual recurso da AWS usar?',
  '[{"id":"A","text":"EventBridge Scheduler com cron(0 12 ? * TUE *) em UTC ou ''America/Sao_Paulo'' timezone-aware"},{"id":"B","text":"Lambda com setInterval interno"},{"id":"C","text":"EC2 com cron Linux"},{"id":"D","text":"SNS Topic com agendamento"}]'::jsonb, 'A',
  '"(a) EventBridge Scheduler (sucessor moderno de EventBridge Rules para schedules) suporta timezone explícito, expressões cron/rate/at, flexible time windows, retry policy e DLQ. Cron syntax AWS: minute hour day-of-month month day-of-week year; ''?'' em campos não-aplicáveis. (b) Lambda não persiste estado entre invocações — sem agendamento interno. EC2 cron desperdiça. SNS não agenda. (c) Regra: agendamento managed = EventBridge Scheduler; cron expression usa formato AWS (6 campos com year). (d) Ver EventBridge User Guide — Scheduler."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'scenario', '["eventbridge","scheduler","cron"]'::jsonb, 'ai-draft', 'active', now(), now()
)
