INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-058', 'aws-dva', 'Um SaaS de e-commerce precisa que um único evento ''OrderPlaced'' dispare 5 ações distintas em diferentes domínios (inventory, billing, shipping, notification, analytics). Qual padrão usar?',
  '[{"id":"A","text":"5 Lambdas chamando uma à outra em cadeia"},{"id":"B","text":"EventBridge custom bus com uma rule por consumer, cada uma roteando para o serviço específico"},{"id":"C","text":"SQS com 5 consumers competindo"},{"id":"D","text":"DynamoDB Streams para todos"}]'::jsonb, 'B',
  '"(a) EventBridge custom bus implementa pub/sub multi-consumer com filtros independentes por consumer. Cada rule tem seu próprio target e event pattern. Permite desacoplamento total: novos consumers se adicionam sem mudar producer. Suporta archive/replay para reprocessamento. (b) Chain de Lambdas acopla domínios. SQS competing-consumers entrega 1 msg para 1 consumer (não fan-out — para fan-out SQS usa SNS na frente). Streams é DynamoDB-specific. (c) Regra: pub/sub event-driven = EventBridge (custom bus); pub/sub simples = SNS topic. (d) Ver EventBridge User Guide — Event buses."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["eventbridge","pub-sub","event-bus"]'::jsonb, 'ai-draft', 'active', now(), now()
)
