INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-059', 'aws-dva', 'Um developer cria uma rule no EventBridge que invoca uma Lambda. Eventos que falham na entrega à Lambda (após retries) precisam ser capturados para análise. Como?',
  '[{"id":"A","text":"EventBridge nunca falha entregas"},{"id":"B","text":"Aumentar memória da Lambda"},{"id":"C","text":"Configurar Dead Letter Queue (DLQ) SQS no target da rule + RetryPolicy customizada"},{"id":"D","text":"Adicionar Wait state"}]'::jsonb, 'C',
  '"(a) Cada target de uma EventBridge rule pode ter DLQ SQS + RetryPolicy (MaximumRetryAttempts até 185, MaximumEventAgeInSeconds até 24h). Após esgotar retries, evento + metadata vai à DLQ. DLQ deve ter permissão SQS:SendMessage para o role do EventBridge. (b) EventBridge faz best-effort com retries; falhas persistentes precisam DLQ. Memória Lambda não atende isso. Wait é Step Functions. (c) Regra: target failures observáveis = DLQ no target; RetryPolicy controla tentativas. (d) Ver EventBridge User Guide — Rule targets and DLQ."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["eventbridge","dlq","retry"]'::jsonb, 'ai-draft', 'active', now(), now()
)
