INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-060', 'aws-dva', 'Um EventBridge bus recebe 1.000.000 eventos/dia. O time precisa reprocessar todos os eventos do último mês após um bug ser corrigido em um consumer. Como fazer sem republicar manualmente?',
  '[{"id":"A","text":"Manualmente reler do CloudWatch Logs"},{"id":"B","text":"EventBridge não suporta replay"},{"id":"C","text":"Reinserir manualmente cada evento via PutEvents"},{"id":"D","text":"Habilitar Archive no event bus + criar Replay sobre o período afetado"}]'::jsonb, 'D',
  '"(a) EventBridge Archive grava eventos do bus por período configurável (até infinito), com filter pattern opcional. Replay lê o archive e republica eventos no bus original (ou outro) dentro de um intervalo de tempo. Consumers reprocessam normalmente. Cobra storage de archive + replay events. (b) CloudWatch Logs não é integração nativa de replay. EventBridge suporta replay desde 2020. Re-publishing manual via PutEvents é inviável em volume. (c) Regra: audit + reprocessing histórico = Archive + Replay. (d) Ver EventBridge User Guide — Archive and Replay."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["eventbridge","archive","replay"]'::jsonb, 'ai-draft', 'active', now(), now()
)
