INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-061', 'aws-dva', 'Um developer cria uma SQS Standard queue para desacoplar producers e consumers. Em testes, observa que mensagens chegam ocasionalmente fora de ordem e raramente duplicadas. Esse comportamento é esperado?',
  '[{"id":"A","text":"Sim — SQS Standard garante at-least-once delivery e best-effort ordering; para ordem estrita use SQS FIFO"},{"id":"B","text":"Não — é bug do SQS"},{"id":"C","text":"Sim — porque o consumer está mal configurado"},{"id":"D","text":"Não — SQS Standard sempre preserva ordem"}]'::jsonb, 'A',
  '"(a) SQS Standard: at-least-once delivery (duplicatas possíveis), best-effort ordering (não garantido), virtually unlimited throughput. FIFO queues: exactly-once processing (com deduplication 5min window), strict FIFO ordering por MessageGroupId, throughput de 300 msg/s (3000 com batching) ou High Throughput Mode (até 70k msg/s por API call). (b) Não é bug. Configuração do consumer não afeta ordering do SQS Standard. SQS Standard nunca garante ordem. (c) Regra: ordem importa = FIFO; throughput máximo = Standard. (d) Ver SQS Developer Guide — Queue types."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'recall', '["sqs","standard","fifo","ordering"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
  correct_id    = EXCLUDED.correct_id,
  explanation   = EXCLUDED.explanation,
  topic         = EXCLUDED.topic,
