INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-062', 'aws-dva', 'Um consumer Lambda lê mensagens de SQS via event source mapping. O processamento de cada mensagem demora 60s. O VisibilityTimeout padrão da fila está em 30s. O que acontece?',
  '[{"id":"A","text":"Lambda automaticamente estende o VisibilityTimeout"},{"id":"B","text":"A mensagem fica visível antes do processamento terminar e é re-entregue, causando processamento duplicado"},{"id":"C","text":"Mensagem é deletada após 30s mesmo sem processamento"},{"id":"D","text":"SQS retorna erro"}]'::jsonb, 'B',
  '"(a) VisibilityTimeout é o tempo em que a mensagem fica ''invisível'' a outros consumers após ser recebida. Se processamento excede esse tempo, a mensagem reaparece e outro consumer pega — gera duplicação. Regra: VisibilityTimeout >= 6x duração média do handler (best practice AWS). Para Lambda event source, configure VisibilityTimeout >= function timeout. Pode estender dinamicamente via ChangeMessageVisibility. (b) Lambda NÃO estende sozinho. Mensagem não é deletada até consumer chamar DeleteMessage. SQS não erra. (c) Regra: VisibilityTimeout > duração de processo + buffer. (d) Ver SQS Developer Guide — Visibility timeout."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'troubleshoot', '["sqs","visibility-timeout","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
