INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-063', 'aws-dva', 'Um developer quer reduzir o número de API calls vazios (ReceiveMessage retornando 0 mensagens) e o custo do SQS. Como configurar?',
  '[{"id":"A","text":"Aumentar VisibilityTimeout"},{"id":"B","text":"Reduzir batch size"},{"id":"C","text":"Long polling: setar WaitTimeSeconds=20 no ReceiveMessage (ou no atributo da fila) — espera até 20s por mensagens antes de retornar vazio"},{"id":"D","text":"Habilitar FIFO"}]'::jsonb, 'C',
  '"(a) Short polling (default WaitTimeSeconds=0) consulta um subset de servidores SQS — pode retornar vazio mesmo havendo mensagens, e cobra cada chamada. Long polling (WaitTimeSeconds=1-20) espera mensagens disponíveis antes de retornar; reduz API calls e custos, reduz latência média de entrega. (b) VisibilityTimeout é re-delivery. Batch size é qtd msgs por chamada (não evita vazios). FIFO é ordering, não polling. (c) Regra: SEMPRE habilite long polling em produção. (d) Ver SQS Developer Guide — Long polling."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["sqs","long-polling","cost"]'::jsonb, 'ai-draft', 'active', now(), now()
)
