INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-064', 'aws-dva', 'Uma SQS FIFO queue precisa ordem estrita por usuário (cada usuário processado em ordem) mas pode paralelizar entre usuários diferentes. Qual atributo configurar nas mensagens?',
  '[{"id":"A","text":"MessageDeduplicationId = userId"},{"id":"B","text":"DelaySeconds = userId hash"},{"id":"C","text":"ReceiptHandle por usuário"},{"id":"D","text":"MessageGroupId = userId — mensagens com mesmo GroupId são processadas em ordem; grupos diferentes em paralelo"}]'::jsonb, 'D',
  '"(a) FIFO queue ordena dentro de cada MessageGroupId; grupos diferentes processam em paralelo. Use userId como GroupId para garantir ordem por usuário mas paralelismo entre usuários. (b) MessageDeduplicationId (ou ContentBasedDeduplication=true) previne duplicatas dentro de 5min window. DelaySeconds posterga visibilidade. ReceiptHandle é token de uma mensagem específica para Delete/ChangeVisibility. (c) Regra: ordem + paralelismo controlado = MessageGroupId; deduplication = MessageDeduplicationId. (d) Ver SQS Developer Guide — FIFO message group."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["sqs","fifo","message-group"]'::jsonb, 'ai-draft', 'active', now(), now()
)
