INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-065', 'aws-dva', 'Um SNS topic precisa entregar mensagens para 5 SQS queues diferentes (cada uma para um microservice). Após inscrever as queues, mensagens não chegam nas filas. Logs SNS não mostram erro. Qual é a causa mais provável?',
  '[{"id":"A","text":"A SQS queue policy não autoriza o SNS topic a chamar SendMessage"},{"id":"B","text":"SNS não suporta SQS como subscriber"},{"id":"C","text":"Falta habilitar FIFO"},{"id":"D","text":"Topic deve estar em VPC"}]'::jsonb, 'A',
  '"(a) SNS→SQS exige que a SQS queue policy permita Action=sqs:SendMessage com Principal=SNS service e Condition aws:SourceArn=<topicArn>. Sem essa policy, SNS tenta entregar e falha silenciosamente. (b) SNS suporta SQS, Lambda, HTTP/S, email, SMS, mobile, Kinesis Firehose. FIFO é opção (mas ambos precisam ser FIFO). SNS não é VPC-only. (c) Regra: pub/sub fan-out cross-resource = sempre verificar resource policy do destino. (d) Ver SNS Developer Guide — Subscribing SQS."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'troubleshoot', '["sns","sqs","fan-out","policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
