INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-066', 'aws-dva', 'Um developer quer filtrar mensagens SNS no broker para que cada subscriber receba apenas mensagens relevantes (ex: subscriber A só quer eventos de ''high priority''). Como implementar?',
  '[{"id":"A","text":"Filtrar dentro de cada consumer"},{"id":"B","text":"Subscription Filter Policy no SNS — JSON com matching de message attributes ou body (com filterPolicyScope=MessageBody)"},{"id":"C","text":"Criar um topic por categoria"},{"id":"D","text":"SNS não suporta filtragem"}]'::jsonb, 'B',
  '"(a) SNS Filter Policy aplica matching no broker: por MessageAttributes (default) ou MessageBody (filterPolicyScope=MessageBody). Operadores: exact, prefix, anything-but, numeric, exists. Subscribers só recebem mensagens que casam — economiza invocations e network. (b) Filtrar no consumer gera invocações desperdiçadas. Topic por categoria explode topology. SNS suporta nativo. (c) Regra: filtrar no SNS economiza Lambda invocations e bandwidth. (d) Ver SNS Developer Guide — Subscription filter policies."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["sns","filter-policy","attributes"]'::jsonb, 'ai-draft', 'active', now(), now()
)
