INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-067', 'aws-dva', 'Um Kinesis Data Stream tem 4 shards e recebe 4 MB/s. O developer adiciona produtores e quer chegar a 20 MB/s mantendo a mesma quantidade de shards. Isso é possível?',
  '[{"id":"A","text":"Sim — basta aumentar BatchSize"},{"id":"B","text":"Sim — kinesis escala automaticamente"},{"id":"C","text":"Não — cada shard suporta 1 MB/s ou 1000 records/s de write; 20 MB/s exige resharding (split shards) para 20+ shards"},{"id":"D","text":"Kinesis suporta 5 MB/s por shard"}]'::jsonb, 'C',
  '"(a) Kinesis Data Streams (Provisioned mode) tem limite duro por shard: write 1 MB/s e 1000 records/s, read 2 MB/s e 5 GetRecords/s. Excedente recebe ProvisionedThroughputExceededException. Para 20 MB/s precisa de 20 shards (split). No modo On-Demand, scaling é automático (até 200 MB/s write, mais barato para variável). (b) BatchSize não muda limites por shard. Provisioned não auto-escala (existe Application Auto Scaling mas é manual). Read shard = 2 MB/s. (c) Regra: throughput Kinesis = shards × 1 MB/s write; precisa resharding manual ou On-Demand. (d) Ver Kinesis Streams Developer Guide — Quotas."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["kinesis","shards","throughput"]'::jsonb, 'ai-draft', 'active', now(), now()
)
