INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-068', 'aws-dva', 'Um developer envia records ao Kinesis com PartitionKey=userId. Observa que um único user (heavy uploader) está saturando uma shard. Como resolver mantendo afinidade lógica por usuário?',
  '[{"id":"A","text":"Aumentar BatchSize"},{"id":"B","text":"Mudar para SNS"},{"id":"C","text":"Kinesis não suporta distribuição de hot keys"},{"id":"D","text":"Usar Explicit Hash Key ou compor PartitionKey com sufixo aleatório limitado (ex: userId#0..userId#9) para distribuir entre múltiplas shards"}]'::jsonb, 'D',
  '"(a) PartitionKey passa por MD5 hash → shard. Hot user concentra em uma shard. Soluções: (1) sufixo aleatório controlado (ex: ''userId#'' + (n % 10)) — split em 10 shards, mantém aproximação por usuário; (2) ExplicitHashKey força hash específico distribuindo manualmente. Trade-off: ordem dentro de userId perdida se sufixo aleatório. (b) BatchSize não distribui. SNS é diferente paradigma (sem ordem). Kinesis suporta via Explicit Hash. (c) Regra: hot partition Kinesis = sharded partition key. (d) Ver Kinesis Streams Developer Guide — Resharding and PartitionKey."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["kinesis","partition-key","hot-shard"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
