INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-069', 'aws-dva', 'Um developer escolhe entre Kinesis Data Streams e SQS Standard para um pipeline de eventos de clickstream. Múltiplos consumers precisam ler os MESMOS dados independentemente. Qual escolher?',
  '[{"id":"A","text":"Kinesis Data Streams — múltiplos consumers leem do mesmo stream com checkpoints independentes (Enhanced Fan-Out para isolamento de read)"},{"id":"B","text":"SQS Standard — basta criar 1 fila por consumer"},{"id":"C","text":"SQS sempre é melhor"},{"id":"D","text":"Kinesis suporta apenas 1 consumer"}]'::jsonb, 'A',
  '"(a) Kinesis Data Streams retém records (default 24h, até 365 dias). Múltiplos consumers leem independentemente via shard iterators próprios, com checkpoints (KCL/DynamoDB). Enhanced Fan-Out provisiona 2 MB/s dedicados por consumer (sem competir read throughput). (b) SQS é competing consumers — mensagem é deletada após uma vez. SNS→múltiplas SQS replica, mas perde retenção/replay. (c) Kinesis suporta múltiplos consumers nativamente. (c) Regra: replay/multi-consumer com mesmos dados = Kinesis; work distribution 1-pra-1 = SQS. (d) Ver Kinesis Streams Developer Guide — Consumers."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["kinesis","sqs","fan-out"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
