INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-070', 'aws-dva', 'Um consumer Kinesis usando KCL processa records mas reinicia frequentemente. Após reinício, reprocessa muitos records antigos. Como o developer deve gerenciar a posição de leitura?',
  '[{"id":"A","text":"Usar TRIM_HORIZON sempre"},{"id":"B","text":"Checkpoint frequente no DynamoDB (gerenciado pelo KCL) salvando o sequence number do último record processado com sucesso"},{"id":"C","text":"Aumentar memória do consumer"},{"id":"D","text":"Desabilitar retention"}]'::jsonb, 'B',
  '"(a) KCL (Kinesis Client Library) usa uma DynamoDB table para checkpoints — sequence number do último record processado. Após restart, o consumer retoma do checkpoint, não do início. Aplicação deve chamar checkpointer.checkpoint() após processar batch com sucesso. Frequência alta = menos re-trabalho mas mais WCU; menos = mais re-trabalho. (b) TRIM_HORIZON é apenas iterator inicial (começo da stream). Memória não persiste estado entre reboots. Desabilitar retention perde dados. (c) Regra: KCL + DynamoDB checkpoints = posição persistida; chamar checkpoint após processar com sucesso. (d) Ver Kinesis Streams Developer Guide — KCL checkpoints."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["kinesis","kcl","checkpoint"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
