INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-071', 'aws-dva', 'Uma API de pagamento processa requisições POST /charge. O cliente pode chamar 2 vezes (retry de rede). O developer precisa garantir que apenas um charge seja cobrado mesmo com retries. Qual padrão de idempotência usar?',
  '[{"id":"A","text":"Confiar que a rede não vai duplicar"},{"id":"B","text":"Usar UPSERT no banco"},{"id":"C","text":"Cliente envia Idempotency-Key (UUID) no header; servidor armazena (key → resultado) em DynamoDB com TTL e retorna o resultado cacheado em retries"},{"id":"D","text":"Aumentar timeout"}]'::jsonb, 'C',
  '"(a) Idempotency key pattern: cliente gera UUID por operação lógica e envia em header. Servidor: lookup em store (DynamoDB com ConditionExpression attribute_not_exists para insert atômico, TTL 24h). Hit = retornar resposta cacheada; miss = processar, gravar resultado, retornar. Stripe e outros usam esse padrão. AWS Lambda Powertools tem idempotency utility. (b) Rede SEMPRE pode duplicar. UPSERT em banco resolve só se a chave de negócio for naturalmente única (não cobre HTTP retry com payload diferente). Timeout não resolve duplicação. (c) Regra: at-least-once + idempotency-key = exactly-once funcional. (d) Ver Lambda Developer Guide — Idempotency."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["idempotency","retry","dynamodb"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
