INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-072', 'aws-dva', 'Uma Lambda lê mensagens SQS e gravava no DynamoDB. Em caso de erro no DynamoDB, a função throw e SQS re-entrega. Mas a Lambda já tinha gravado parcialmente. Como tornar a operação idempotente?',
  '[{"id":"A","text":"Aumentar VisibilityTimeout"},{"id":"B","text":"Desabilitar retries do SQS"},{"id":"C","text":"Não há solução"},{"id":"D","text":"Usar MessageId do SQS como chave de idempotência: ConditionExpression=''attribute_not_exists(messageId)'' no PutItem"}]'::jsonb, 'D',
  '"(a) SQS MessageId é único e estável entre re-deliveries. Usar messageId como PK do DynamoDB (ou em GSI) + ConditionExpression=''attribute_not_exists(messageId)'' garante PutItem atômico — duplicatas geram ConditionalCheckFailedException que o handler trata como sucesso (já processado). Pattern: ''inbox table'' ou ''processed messages''. (b) VisibilityTimeout reduz mas não elimina duplicação. Desabilitar retry perde garantia at-least-once. Sempre há solução com idempotency. (c) Regra: at-least-once + idempotency check = effective exactly-once. (d) Ver SQS Developer Guide — Best practices for handling duplicates."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["idempotency","sqs","dynamodb","message-id"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
