INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-073', 'aws-dva', 'Um SDK chama uma API que ocasionalmente retorna 503 ServiceUnavailable. O developer quer implementar retry com exponential backoff e jitter para evitar thundering herd. Qual fórmula é correta?',
  '[{"id":"A","text":"delay = min(maxDelay, base * 2^attempt) com Full Jitter: sleep = random(0, delay)"},{"id":"B","text":"delay fixo de 1s entre retries"},{"id":"C","text":"Sem retry — propagar erro"},{"id":"D","text":"delay = base * attempt (linear)"}]'::jsonb, 'A',
  '"(a) Full Jitter (AWS Architecture Blog clássico): delay = random(0, min(maxDelay, base * 2^attempt)). Distribui retries aleatoriamente, evitando que todos clientes retentem ao mesmo tempo após falha (thundering herd). Equal Jitter e Decorrelated Jitter são variações. SDKs AWS implementam isso automaticamente (legacy/standard/adaptive retry mode). (b) Fixo não escala bem. Sem retry perde resiliência. Linear ainda concentra retries. (c) Regra: retry sempre com exponential + jitter; SDK config Tipicamente é ''standard'' ou ''adaptive'' mode. (d) Ver AWS SDK Guide — Retry behavior."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["retry","backoff","jitter","sdk"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
