INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-074', 'aws-dva', 'Uma Lambda chama o DynamoDB e recebe ProvisionedThroughputExceededException com frequência. O developer pergunta se precisa implementar retry manualmente. Qual a resposta correta?',
  '[{"id":"A","text":"SDKs AWS não fazem retry automático"},{"id":"B","text":"O AWS SDK já implementa retry com exponential backoff por padrão para erros throttling/5xx; configurar retry mode e maxAttempts ajusta o comportamento"},{"id":"C","text":"Apenas o boto3 faz retry"},{"id":"D","text":"Retry só pode ser feito no Step Functions"}]'::jsonb, 'B',
  '"(a) Todos AWS SDKs (boto3, JS v3, Java, Go) fazem retry automático para erros retriáveis (throttling, 5xx, network). Modos: ''legacy'' (3 tentativas), ''standard'' (3 tentativas + token bucket), ''adaptive'' (client-side rate limiting que reage a throttling). Config: AWS_RETRY_MODE env var, maxAttempts. Para DynamoDB throttling persistente, considere também: redesign de chave (hot partition), aumento de capacity, or on-demand. (b) Todos SDKs fazem retry. Step Functions tem retry mas é orquestrador. (c) Regra: confiar no SDK retry mas monitorar throttling exception rate para detectar problemas estruturais. (d) Ver AWS SDK Guide — Retry behavior."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'recall', '["sdk","retry","throttling","dynamodb"]'::jsonb, 'ai-draft', 'active', now(), now()
)
