INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-075', 'aws-dva', 'Uma Lambda chama uma API externa (third-party) que está com latência alta intermitente. O developer quer falhar rápido em vez de bloquear a função inteira por 30s. Qual padrão usar?',
  '[{"id":"A","text":"Aumentar timeout da Lambda"},{"id":"B","text":"Retry infinito"},{"id":"C","text":"Circuit Breaker — após N falhas consecutivas, abrir o circuit e retornar erro imediato por T tempo (half-open para reabertura)"},{"id":"D","text":"Desabilitar a chamada"}]'::jsonb, 'C',
  '"(a) Circuit Breaker (closed/open/half-open) protege o caller de cascading failure. Implementação: contador de falhas em DynamoDB ou ElastiCache; thresholds (ex: 5 falhas em 1min); estado ''open'' rejeita imediatamente; após cooldown, ''half-open'' testa com 1 request; sucesso → closed. AWS Lambda Powertools / Resilience4j (Java) / opossum (Node) implementam. (b) Timeout maior agrava bloqueio. Retry infinito amplifica problema. Desabilitar perde funcionalidade. (c) Regra: dependência externa instável = circuit breaker + timeout agressivo + fallback. (d) Ver Lambda Developer Guide — Resilient patterns."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'best-practice', '["circuit-breaker","resilience","retry"]'::jsonb, 'ai-draft', 'active', now(), now()
)
