INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-076', 'aws-dva', 'Um developer quer garantir que uma operação ''transferência bancária'' (debit + credit) seja idempotente E atômica em DynamoDB, mesmo com retries do SDK. Qual combinação usar?',
  '[{"id":"A","text":"UpdateItem com retry exponencial"},{"id":"B","text":"PutItem em loop"},{"id":"C","text":"BatchWriteItem"},{"id":"D","text":"TransactWriteItems com ClientRequestToken (idempotency token único da operação) — DynamoDB ignora retries com mesmo token dentro de 10min"}]'::jsonb, 'D',
  '"(a) TransactWriteItems aceita ClientRequestToken (até 36 bytes). Se a mesma operação é chamada novamente com mesmo token (e payload idêntico) dentro de 10 minutos, DynamoDB retorna o resultado da primeira chamada sem re-executar — idempotência nativa. Combinado com all-or-nothing das transactions, garante ambos. (b) UpdateItem é por item, não multi-item. PutItem loop não é atômico. BatchWriteItem não é transaction. (c) Regra: idempotência + atomicidade multi-item = TransactWriteItems + ClientRequestToken. (d) Ver DynamoDB Developer Guide — Transactions ClientRequestToken."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'best-practice', '["idempotency","dynamodb","transactions","client-request-token"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
