INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-077', 'aws-dva', 'Um Lambda recebe eventos SNS e processa pagamentos. Quando o pagamento falha por motivo transitório (gateway temporário), o developer quer retry com backoff antes de descartar. Em qual camada configurar?',
  '[{"id":"A","text":"Lambda async retry config (MaximumRetryAttempts 0-2, MaximumEventAgeInSeconds) + On-Failure Destination — SNS invoca Lambda async"},{"id":"B","text":"SQS VisibilityTimeout"},{"id":"C","text":"API Gateway throttle"},{"id":"D","text":"DynamoDB TTL"}]'::jsonb, 'A',
  '"(a) SNS invoca Lambda em modo async. Lambda async tem config: MaximumRetryAttempts (0/1/2 — default 2) e MaximumEventAgeInSeconds (60s-6h — controla janela total). Entre retries, Lambda faz delay com exponential backoff. Falhas finais vão para DLQ ou On-Failure Destination (SNS/SQS/EventBridge/Lambda). (b) VisibilityTimeout é SQS, não async invoke. API Gateway throttle é rate limiting de chamadas. TTL é expiração de items. (c) Regra: retry de Lambda async = MaximumRetryAttempts + MaximumEventAgeInSeconds; observabilidade de falhas = On-Failure Destination. (d) Ver Lambda Developer Guide — Asynchronous invocation retries."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","async","retry","destinations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
