INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-078', 'aws-dva', 'Um event source mapping DynamoDB Streams → Lambda tem batchSize=100. Uma única mensagem corrupta dentro do batch causa toda a função a falhar e re-processar o lote inteiro indefinidamente. Como mitigar?',
  '[{"id":"A","text":"Aumentar BatchSize"},{"id":"B","text":"MaximumRetryAttempts no event source + DestinationConfig.OnFailure (SQS/SNS) + ReportBatchItemFailures para isolar a msg ruim"},{"id":"C","text":"Reduzir RCU"},{"id":"D","text":"Poison pill messages não existem em Streams"}]'::jsonb, 'B',
  '"(a) Stream event source mapping (DynamoDB/Kinesis) tem: MaximumRetryAttempts (0-10000 ou -1=infinite, default -1), MaximumRecordAgeInSeconds, BisectBatchOnFunctionError, DestinationConfig.OnFailure (SQS/SNS para metadata do batch falho). Combinado com ReportBatchItemFailures (handler retorna batchItemFailures[]), isola só os records ruins. (b) Maior batch agrava. RCU não está relacionado. Poison pills são reais. (c) Regra: poison pill em stream = limite retries + isolation via ReportBatchItemFailures + DLQ. (d) Ver Lambda Developer Guide — Event source mapping error handling."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["lambda","event-source","poison-pill","retry"]'::jsonb, 'ai-draft', 'active', now(), now()
)
