INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-079', 'aws-dva', 'Uma SQS queue tem 1000 mensagens não processadas e a fila está crescendo. A Lambda consumer tem RC=10 e processa cada msg em 200ms. Como aumentar throughput sem mudar a Lambda?',
  '[{"id":"A","text":"Diminuir VisibilityTimeout"},{"id":"B","text":"Habilitar FIFO"},{"id":"C","text":"Aumentar Reserved Concurrency e/ou BatchSize do event source mapping (até 10000 para SQS Standard)"},{"id":"D","text":"Aumentar tamanho da queue"}]'::jsonb, 'C',
  '"(a) Lambda + SQS scaling: event source mapping adiciona consumers até o menor entre (Reserved Concurrency, default account concurrency 1000, MaximumConcurrency setting). BatchSize maior (até 10000 para SQS Standard, mas total msg size <256KB ou MaxBatchingWindow) reduz invocações. RC=10 limita a 10 concurrent — pode estar artificialmente baixo. (b) VisibilityTimeout menor causa re-entrega prematura. FIFO LIMITA throughput. Queues não têm ''size''. (c) Regra: scaling SQS+Lambda = RC mais alto + BatchSize otimizado + handler eficiente. (d) Ver Lambda Developer Guide — Scaling with SQS."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","sqs","scaling","batch-size"]'::jsonb, 'ai-draft', 'active', now(), now()
)
