INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-080', 'aws-dva', 'Um developer faz operações em S3 e DynamoDB dentro de uma mesma Lambda. Quer garantir consistência: se DynamoDB falhar, o objeto S3 também precisa ser revertido. Qual padrão usar?',
  '[{"id":"A","text":"TransactWriteItems com S3 incluído"},{"id":"B","text":"Two-phase commit nativo da AWS"},{"id":"C","text":"Não há padrão"},{"id":"D","text":"Saga pattern — operações com compensating actions (delete S3 object se DDB falhar); ou armazenar metadata no DDB primeiro e S3 depois (write-ahead pattern)"}]'::jsonb, 'D',
  '"(a) AWS não tem transação distribuída entre serviços diferentes. Saga pattern: defina sequência de operações e compensating action para cada falha. Ex: PutObject S3 → PutItem DDB; se DDB falha, DeleteObject S3 (compensating). Step Functions orquestra Sagas elegantemente com Catch + estados de compensação. Alternativa: write-ahead log no DDB (event-sourcing style). (b) TransactWriteItems é só DynamoDB. AWS não tem 2PC cross-service. (c) Regra: consistência cross-service = Saga + idempotency + observability. (d) Ver Step Functions Developer Guide — Saga pattern."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'best-practice', '["saga","consistency","step-functions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
