INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-081', 'aws-dva', 'Um developer Java cria um cliente AWS SDK v2 dentro de cada invocação de handler Lambda. A função tem latência alta e custo de cold start ruim. Qual é o problema e a melhor prática?',
  '[{"id":"A","text":"Criar SDK clients fora do handler (escopo estático/módulo) para reuso entre invocações; clients são thread-safe e caros de instanciar"},{"id":"B","text":"SDK clients devem ser criados a cada chamada"},{"id":"C","text":"Diminuir memory"},{"id":"D","text":"SDK v2 não funciona em Lambda"}]'::jsonb, 'A',
  '"(a) AWS SDK clients (DynamoDbClient, S3Client, etc.) carregam credentials provider chain, HTTP client (Netty/UrlConnection), retry policy, region resolver — caro instanciar. São thread-safe (em SDK v2 garantido). Pattern: criar como static/module-level — reutilizado entre invocações warm. Reduz cold start e overhead per-invocation. (b) Falso — desperdiça recursos. (c) Memory baixa não causa esse problema. SDK v2 é totalmente suportado. (c) Regra: clients pesados (SDK, DB pools) = init phase; data específica = handler. (d) Ver AWS SDK Developer Guide — Performance best practices."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["sdk","lambda","performance","client-reuse"]'::jsonb, 'ai-draft', 'active', now(), now()
)
