INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-082', 'aws-dva', 'Um developer hardcoda access key e secret key em uma aplicação que roda em EC2. Code review pede correção. Qual é a forma correta de fornecer credenciais ao SDK?',
  '[{"id":"A","text":"Manter no código mas em base64"},{"id":"B","text":"Anexar uma IAM Instance Profile à EC2; o SDK descobre via Instance Metadata Service (IMDSv2)"},{"id":"C","text":"Salvar em /etc/passwd"},{"id":"D","text":"Usar AWS Access Keys de IAM user em env vars no userdata"}]'::jsonb, 'B',
  '"(a) SDK credential provider chain default: env vars → shared credentials file → container credentials (ECS) → IMDS (EC2/instance profile). Para EC2: anexar role via Instance Profile. SDK chama IMDS (169.254.169.254) com IMDSv2 (token-based) e recebe credentials rotativas, com renovação automática. Zero secrets no código. (b) Base64 não é segurança. /etc/passwd não tem credentials de qualquer forma. Access keys em env vars já em produção é antipadrão (vazam em logs, dumps). (c) Regra: nunca hardcode; preferir roles + provider chain. (d) Ver AWS SDK Developer Guide — Credentials."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["sdk","credentials","iam","instance-profile"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
