INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-083', 'aws-dva', 'Um SDK call falha intermitentemente em produção sem mensagem de erro clara. O developer quer habilitar logs detalhados do SDK para diagnóstico. Qual abordagem?',
  '[{"id":"A","text":"Aumentar memory"},{"id":"B","text":"Desabilitar retry"},{"id":"C","text":"Habilitar logging do SDK (SDK level WIRE/DEBUG) ou usar AWS_SDK_LOG_LEVEL=DEBUG; nunca deixar em produção long-term (custo de log + PII risk)"},{"id":"D","text":"SDK não tem logging"}]'::jsonb, 'C',
  '"(a) AWS SDKs têm logging configurável. Java v2: software.amazon.awssdk via SLF4J (WIRE log mostra HTTP req/resp). JS v3: logger config no client. Python boto3: boto3.set_stream_logger(''botocore'', logging.DEBUG). Útil para debug de retry, signature, network. Não deixar em prod: log volume explode e pode logar headers/payload com PII. (b) Memory não atende. Desabilitar retry esconde causa. SDK tem logging completo. (c) Regra: debug pontual = logging detalhado + remover depois; observability persistente = X-Ray + métricas. (d) Ver AWS SDK Developer Guide — Logging."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'troubleshoot', '["sdk","logging","debug"]'::jsonb, 'ai-draft', 'active', now(), now()
)
