INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-084', 'aws-dva', 'Uma equipe usa SDK v2 do AWS Java em uma aplicação heavy IO. Por default usa o Netty Async HTTP client com 50 connections. Picos de tráfego saturam o pool. Como ajustar?',
  '[{"id":"A","text":"SDK v2 não tem pool"},{"id":"B","text":"Aumentar memory da JVM"},{"id":"C","text":"Diminuir threads"},{"id":"D","text":"Configurar NettyNioAsyncHttpClient.builder().maxConcurrency() e connectionAcquisitionTimeout no client builder; monitorar pool metrics"}]'::jsonb, 'D',
  '"(a) SDK v2 Java permite configurar o HTTP client (Netty para async, UrlConnection ou Apache para sync). Parâmetros chave: maxConcurrency (default 50 — conexões simultâneas), maxPendingConnectionAcquires (queue de espera), connectionAcquisitionTimeout, connectionTimeToLive. Métricas via SdkMetricsCollection mostram pool saturation. Tuning depende de workload — picos exigem maxConcurrency maior. (b) SDK v2 tem pool configurável. JVM memory não afeta pool. Threads não substitui connection pool. (c) Regra: high-concurrency + AWS SDK = ajustar HTTP client pool. (d) Ver AWS SDK Java v2 Developer Guide — HTTP configuration."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'best-practice', '["sdk","java","netty","connection-pool"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
