INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-085', 'aws-dva', 'Um developer Node.js usa AWS SDK v2 (aws-sdk) e a aplicação tem cold start lento. Suspeita-se do tamanho do bundle. Qual mudança reduz cold start sem perder funcionalidade?',
  '[{"id":"A","text":"Migrar para AWS SDK v3 (@aws-sdk/client-X) — modular, importa só os clients usados, bundle ~10x menor"},{"id":"B","text":"Importar aws-sdk inteiro em cada handler"},{"id":"C","text":"Mudar para Python"},{"id":"D","text":"Aumentar memory para 10GB"}]'::jsonb, 'A',
  '"(a) AWS SDK v2 (aws-sdk) é monolítico (~50MB). v3 é modular: cada serviço é um pacote separado (@aws-sdk/client-s3, @aws-sdk/client-dynamodb). Import específico (ex: import { S3Client } from ''@aws-sdk/client-s3'') reduz bundle a kilobytes. v3 tem middleware, tree-shaking eficiente, retorna Promises nativos (sem .promise()). Lambda Node.js 18+ runtime inclui SDK v3 (não precisa empacotar para serviços core). (b) Inverso de v3. Linguagem não resolve. Memória extra ajuda mas não corrige bundle. (c) Regra: cold start Node.js = SDK v3 + tree-shake; runtime moderno traz SDK incluído. (d) Ver AWS SDK JS v3 Developer Guide."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["sdk","v3","node","cold-start"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
