INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-086', 'aws-dva', 'Uma aplicação multi-region precisa que cada Lambda use a região onde está rodando ao chamar SDK. Hardcoda ''us-east-1'' em todos clientes. Qual a forma idiomática?',
  '[{"id":"A","text":"Detectar via instance metadata"},{"id":"B","text":"Deixar o SDK detectar via env var AWS_REGION (Lambda injeta automaticamente) — não passar region no client builder"},{"id":"C","text":"Hardcode é a única forma"},{"id":"D","text":"SDK não suporta multi-region"}]'::jsonb, 'B',
  '"(a) Lambda exporta AWS_REGION e AWS_DEFAULT_REGION para a função. SDK default region provider chain lê delas se não for explicitamente fornecida. Resultado: deploy multi-region funciona sem mudar código. Exceção: serviços globais (IAM, CloudFront) usam us-east-1 por design. Cross-region requer client específico para a região remota. (b) IMDS é EC2. Hardcode quebra portabilidade. SDK suporta multi-region nativamente. (c) Regra: dev local com profile region, prod com env var Lambda. (d) Ver AWS SDK Developer Guide — Region resolution."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["sdk","region","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
