INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-087', 'aws-dva', 'Um developer faz BatchGetItem do DynamoDB com 200 keys. A response tem 100 items + UnprocessedKeys. O que isso significa e como tratar?',
  '[{"id":"A","text":"Erro de configuração"},{"id":"B","text":"DynamoDB perdeu os items"},{"id":"C","text":"BatchGetItem pode retornar parcialmente por throttling/16MB limit; o caller deve retry os UnprocessedKeys com exponential backoff"},{"id":"D","text":"Reduzir BatchGetItem para 1 item"}]'::jsonb, 'C',
  '"(a) BatchGetItem limita 100 items por call e 16MB total response. Se exceder ou houver throttling em alguma partition, retorna parcial com UnprocessedKeys map (table → keys não processadas). É responsabilidade do caller fazer retry desses keys com backoff. Mesmo pattern para BatchWriteItem (UnprocessedItems). (b) Comportamento documentado. Items não são perdidos — só não retornados nessa call. 1 por vez é antipattern. (c) Regra: BatchGet/Write = sempre tratar UnprocessedKeys/Items com retry+backoff. (d) Ver DynamoDB Developer Guide — BatchGetItem."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","batch-get","unprocessed-keys"]'::jsonb, 'ai-draft', 'active', now(), now()
)
