INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-088', 'aws-dva', 'Um Query em DynamoDB retorna sempre apenas 1MB de dados mesmo quando há mais itens correspondentes. Como o developer pagina os resultados restantes?',
  '[{"id":"A","text":"Aumentar RCU"},{"id":"B","text":"Mudar para Scan"},{"id":"C","text":"Query não pagina"},{"id":"D","text":"Usar LastEvaluatedKey da response como ExclusiveStartKey na próxima Query até LastEvaluatedKey ficar ausente"}]'::jsonb, 'D',
  '"(a) Query/Scan retornam até 1MB por response. Se há mais dados, response inclui LastEvaluatedKey (PK+SK do último item retornado). Próxima Query usa ExclusiveStartKey=lastEvaluatedKey para continuar. Loop até LastEvaluatedKey ausente. SDK paginators (Java/JS v3/Python) abstraem isso com iterators. (b) RCU não muda limite de 1MB por response. Scan tem mesmo limite. Query pagina por design. (c) Regra: sempre tratar LastEvaluatedKey; SDK paginators simplificam loop. (d) Ver DynamoDB Developer Guide — Pagination."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","pagination","query"]'::jsonb, 'ai-draft', 'active', now(), now()
)
