INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-089', 'aws-dva', 'Um developer modela um chat onde mensagens devem ser ordenadas por timestamp dentro de uma conversa. Quer Query eficiente do tipo ''últimas 50 mensagens''. Qual desenho de chave?',
  '[{"id":"A","text":"PK=CONV#\u003cconvId\u003e, SK=\u003ctimestamp\u003e, Query com ScanIndexForward=false e Limit=50"},{"id":"B","text":"PK=\u003cmsgId\u003e apenas"},{"id":"C","text":"GSI com PK=conversationId"},{"id":"D","text":"TTL inverso"}]'::jsonb, 'A',
  '"(a) SK numérico ordenável (timestamp ISO8601 ou epoch) permite range queries e ordenação eficiente. ScanIndexForward=false reverte a ordem (desc) sem custo extra. Limit=50 corta no servidor. Query consome RCU proporcional ao tamanho de dados lidos. (b) Sem SK, perde range. GSI seria necessário SE o PK base fosse outro, mas aqui PK=convId já está correto na tabela base. TTL é expiração, não ordenação. (c) Regra: ordem temporal = SK como timestamp; reverse = ScanIndexForward=false. (d) Ver DynamoDB Developer Guide — Query."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["dynamodb","sort-key","query"]'::jsonb, 'ai-draft', 'active', now(), now()
)
