INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-090', 'aws-dva', 'Um API Gateway REST tem um modelo JSON schema configurado para validar request body. POST com payload inválido retorna 400 Bad Request mesmo antes de invocar a Lambda. Qual feature está ativa?',
  '[{"id":"A","text":"WAF rule"},{"id":"B","text":"Request validation com Model + Validator no Method Request — API Gateway rejeita payloads inválidos sem custo de Lambda invocation"},{"id":"C","text":"Throttling"},{"id":"D","text":"Cache"}]'::jsonb, 'B',
  '"(a) REST API tem Models (JSON Schema draft-04) e Request Validators (validate body, query string params, headers ou combinação). Quando habilitado no Method Request, API Gateway valida antes de chamar a integração e retorna 400 com detalhes. Economiza Lambda invocations e simplifica handlers. HTTP API não tem isso nativamente. (b) WAF é regras de segurança (SQLi, XSS, IP block). Throttle é rate limit. Cache é response cache. (c) Regra: validation no API Gateway antes do backend = REST API only. (d) Ver API Gateway Developer Guide — Request validation."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'recall', '["api-gateway","validation","model"]'::jsonb, 'ai-draft', 'active', now(), now()
)
