INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-091', 'aws-dva', 'Um developer publica REST API em três stages (dev/stg/prod). Quer que o backend Lambda saiba em qual stage está rodando para apontar para o DynamoDB correto. Qual mecanismo usar?',
  '[{"id":"A","text":"Lambda env vars únicos por função"},{"id":"B","text":"Headers HTTP custom"},{"id":"C","text":"Stage variables — chave-valor por stage, acessível em mapping templates e como ${stageVariables.tableName} no Lambda invocation ARN"},{"id":"D","text":"Tags da Lambda"}]'::jsonb, 'C',
  '"(a) Stage variables permitem parametrizar deployments. Definem-se por stage e ficam acessíveis em: (1) mapping templates como $stageVariables.foo; (2) integration URI como arn:aws:lambda:::function:${stageVariables.functionName}; (3) Lambda invocation: enviadas no event.stageVariables. Permite uma única API definition para múltiplos ambientes. (b) Env vars funcionam mas atrelam ao deploy de cada Lambda. Headers custom são request-scoped. Tags são metadata, não runtime. (c) Regra: parametrizar API Gateway por env = stage variables. (d) Ver API Gateway Developer Guide — Stage variables."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["api-gateway","stage-variables","environments"]'::jsonb, 'ai-draft', 'active', now(), now()
)
