INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-092', 'aws-dva', 'Um cliente mobile faz upload via API Gateway REST → Lambda. Os requests com payload >10MB retornam erro. Por quê?',
  '[{"id":"A","text":"Lambda tem limite de 1MB"},{"id":"B","text":"Falta habilitar binary support"},{"id":"C","text":"Aumentar memory da Lambda"},{"id":"D","text":"API Gateway tem limite hard de 10MB de payload em request/response; uploads grandes devem ir direto ao S3 com presigned URL"}]'::jsonb, 'D',
  '"(a) API Gateway limita request/response a 10MB hard. Lambda sync payload limit é 6MB. Para upload grande, padrão é: client pede presigned URL ao backend (API Gateway → Lambda), recebe URL e faz PUT direto no S3 (bypassa API Gateway/Lambda). Trigger pós-upload via S3 Event Notification se precisar processar. (b) Lambda payload sync = 6MB (não 1MB). Binary support resolve serialização binary, não tamanho. Memory não muda limite de API Gateway. (c) Regra: upload >10MB = presigned URL direto S3. (d) Ver API Gateway Developer Guide — Quotas."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'troubleshoot', '["api-gateway","limits","payload"]'::jsonb, 'ai-draft', 'active', now(), now()
)
