INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-093', 'aws-dva', 'Uma SQS FIFO queue tem MessageGroupId=''order'' para todos pedidos. O throughput ficou limitado a 300 msg/s mesmo com High Throughput Mode habilitado. Por quê?',
  '[{"id":"A","text":"High Throughput Mode escala por número de MessageGroupIds distintos; um único group limita ao throughput de um group"},{"id":"B","text":"FIFO sempre é 300/s"},{"id":"C","text":"Standard é a única opção"},{"id":"D","text":"Falta habilitar long polling"}]'::jsonb, 'A',
  '"(a) FIFO High Throughput Mode escala paralelizando por MessageGroupId — cada group é processado em ordem mas grupos diferentes em paralelo. Throughput pode chegar a 70.000 msg/s mas precisa de muitos groups distintos. Single group = single-threaded = ~300 msg/s. Solução: usar identificador granular (ex: orderId, customerId) em vez de constante. (b) FIFO default é 300/s mas HT mode escala. Standard é alternativa mas perde ordem. Long polling reduz cost, não aumenta throughput de single group. (c) Regra: FIFO throughput = paralelismo por MessageGroupId. (d) Ver SQS Developer Guide — FIFO High Throughput."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["sqs","fifo","high-throughput","message-group"]'::jsonb, 'ai-draft', 'active', now(), now()
)
