INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-094', 'aws-dva', 'Um developer configura Kinesis Data Stream como event source de Lambda. ParallelizationFactor=1 (default). Para um shard, apenas 1 Lambda processa por vez. Como aumentar paralelismo dentro de um shard mantendo ordem por PartitionKey?',
  '[{"id":"A","text":"Mais shards"},{"id":"B","text":"Aumentar ParallelizationFactor (1-10) — Lambda processa múltiplos batches em paralelo do mesmo shard, mas preserva ordem por PartitionKey dentro do shard"},{"id":"C","text":"BatchSize maior"},{"id":"D","text":"Kinesis não permite paralelizar por shard"}]'::jsonb, 'B',
  '"(a) ParallelizationFactor (1-10, default 1) permite Lambda processar até 10 batches concorrentes por shard. Lambda particiona internamente por PartitionKey hash, mantendo ordem por key dentro do shard mas paralelizando entre keys. Útil quando processamento é I/O-bound. (b) Mais shards aumenta paralelismo total mas tem custo. BatchSize aumenta records por invocação (não paralelismo). Paralelização por shard é suportada via ParallelizationFactor. (c) Regra: throughput Lambda Kinesis = shards × ParallelizationFactor. (d) Ver Lambda Developer Guide — Stream parallelization factor."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["lambda","kinesis","parallelization-factor"]'::jsonb, 'ai-draft', 'active', now(), now()
)
