INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-095', 'aws-dva', 'Um developer cria uma Lambda em Python com SnapStart habilitado para reduzir cold start. Após o snapshot, observa que conexões TCP iniciais (DB, redis) ficam quebradas em runtime. Por quê?',
  '[{"id":"A","text":"SnapStart não suporta Python"},{"id":"B","text":"Memory configurada errado"},{"id":"C","text":"SnapStart restaura um snapshot pós-init; sockets/conexões abertos na init phase ficam estagnados; usar Runtime Hooks (beforeCheckpoint/afterRestore) para fechar/reabrir conexões"},{"id":"D","text":"Aumentar timeout"}]'::jsonb, 'C',
  '"(a) Lambda SnapStart (disponível para Java, Python, .NET) tira snapshot da memória após init. Subsequent cold starts restauram o snapshot — muito mais rápido. Mas conexões TCP, file handles, time-sensitive states ficam congelados; ao restaurar, podem estar inválidos. Solução: hooks para fechar antes do snapshot (beforeCheckpoint) e reabrir após restore (afterRestore). Também: rotação de unique IDs (ephemeral state) deve usar afterRestore. (b) SnapStart suporta Java/Python/.NET. Memory não causa isso. Timeout não resolve. (c) Regra: SnapStart + recursos stateful = runtime hooks. (d) Ver Lambda Developer Guide — SnapStart."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["lambda","snapstart","cold-start"]'::jsonb, 'ai-draft', 'active', now(), now()
)
