INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-096', 'aws-dva', 'Um Lambda escreve no DynamoDB. O developer quer registrar latência da chamada, número de retries e bytes enviados. Qual feature da AWS SDK ou Lambda usar?',
  '[{"id":"A","text":"Print manual no handler"},{"id":"B","text":"CloudTrail"},{"id":"C","text":"S3 access logs"},{"id":"D","text":"AWS X-Ray SDK + tracing ativo na Lambda — gera segments com sub-segments por SDK call (latência, retry, success/failure)"}]'::jsonb, 'D',
  '"(a) AWS X-Ray instrumenta SDK calls automaticamente: cria sub-segments com timing, AWS service name, operation, retry count, AWS error metadata. Habilitar: tracing=Active na Lambda + AWS_XRAY_SDK_ENABLED + capture do SDK client (aws-xray-sdk-python ou X-Ray SDK em outras linguagens). Trace map mostra dependencies. ServiceLens correlaciona com CloudWatch metrics. (b) Print manual perde estruturação. CloudTrail é audit log de API calls AWS — outro caso de uso. S3 access logs é S3-only. (c) Regra: observability distribuída = X-Ray; audit = CloudTrail; debug app = logs. (d) Ver Lambda Developer Guide — X-Ray tracing."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["x-ray","sdk","tracing","observability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
