INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-097', 'aws-dva', 'Uma Lambda processa Kinesis records mas ocasionalmente o consumer trava sem erro nem timeout — fica processando o mesmo batch por horas, bloqueando o shard. Como detectar e mitigar?',
  '[{"id":"A","text":"Configurar MaximumRecordAgeInSeconds e MaximumRetryAttempts no event source mapping; records expirados são descartados (ou vão para destination on failure)"},{"id":"B","text":"Aumentar memory"},{"id":"C","text":"Não há solução"},{"id":"D","text":"Diminuir shards"}]'::jsonb, 'A',
  '"(a) Para event sources stream (Kinesis/DynamoDB Streams), MaximumRecordAgeInSeconds (60s-7d) descarta records mais antigos que esse threshold — evita poison pill bloqueando shard indefinidamente. MaximumRetryAttempts limita tentativas por record. DestinationConfig.OnFailure captura batch falho para análise. Combinado: handler com timeout interno + métricas de age previnem stuck consumers. (b) Memory não desbloqueia. Sempre há padrões. Menos shards reduz paralelismo. (c) Regra: stream consumer robusto = record age + retry attempts + on-failure destination. (d) Ver Lambda Developer Guide — Event source mapping options."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["lambda","kinesis","record-age","stuck-consumer"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
