INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-098', 'aws-dva', 'Um developer expõe API via API Gateway HTTP API com JWT authorizer Cognito. Quer que somente usuários com claim ''role: admin'' acessem /admin/*. Como fazer?',
  '[{"id":"A","text":"WAF rule por claim"},{"id":"B","text":"Configurar scope no JWT authorizer ou validar claim no Lambda; HTTP API JWT authorizer suporta audience/scope mas não fine-grained claim matching — geralmente validar no backend"},{"id":"C","text":"API Gateway não suporta JWT"},{"id":"D","text":"Cognito não suporta claims"}]'::jsonb, 'B',
  '"(a) HTTP API JWT authorizer verifica assinatura, expiration, issuer (jwksUri), audience, scope. Não faz matching customizado de claims arbitrários (ex: role). Para ''admin only'', opções: (1) usar scope OAuth no Cognito (''admin/*''); (2) Lambda Authorizer custom que inspeciona o JWT e retorna policy condicional; (3) validar no backend Lambda (mais simples, menor latência). Geralmente combinar JWT authorizer (validação) + check de claim no Lambda. (b) WAF não inspeciona JWT claims. API Gateway suporta JWT em HTTP API. Cognito suporta custom claims via pre-token-generation Lambda. (c) Regra: fine-grained auth = Lambda Authorizer ou check no backend. (d) Ver API Gateway Developer Guide — JWT authorizers."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["api-gateway","jwt","cognito","authorization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
