INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-099', 'aws-dva', 'Um Lambda Java tem cold start de 4s. O developer já habilitou SnapStart e cortou dependencies. Próximo passo: priming. Como funciona?',
  '[{"id":"A","text":"Aumentar memory para infinito"},{"id":"B","text":"Lambda Java não tem otimização"},{"id":"C","text":"Priming: na init phase, executar uma chamada warm-up (ex: dummy SDK call) para inicializar lazy classes e caches; combinado com SnapStart, snapshot já tem state inicializado"},{"id":"D","text":"Migrar para .NET"}]'::jsonb, 'C',
  '"(a) Priming é técnica de executar caminhos críticos durante init/SnapStart checkpoint para forçar JIT compilation e cache populating. Exemplo: chamar uma dummy SDK call (DescribeTable) na init para que classes do client, parsers JSON, retry handlers já estejam carregados no snapshot. Reduz drasticamente p50/p99 do primeiro invoke real. Documentado pela AWS como pattern oficial. (b) Memory tem limite (10240MB). Java tem várias otimizações (SnapStart, GraalVM native image, priming). Trocar linguagem é overkill. (c) Regra: cold start Java otimizado = SnapStart + priming + minimal deps. (d) Ver Lambda Developer Guide — SnapStart performance."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'best-practice', '["lambda","java","snapstart","priming"]'::jsonb, 'ai-draft', 'active', now(), now()
)
