INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-100', 'aws-dva', 'Uma equipe quer migrar de envvars com secrets em Lambda para uma solução com rotation automática e auditoria. Qual serviço integra natively com Lambda e qual a abordagem recomendada?',
  '[{"id":"A","text":"S3 com SSE-KMS"},{"id":"B","text":"DynamoDB com criptografia"},{"id":"C","text":"Hardcode em código com base64"},{"id":"D","text":"AWS Secrets Manager + Lambda extension (AWS Parameters and Secrets) que cacheia secrets em /aws/lambda — reduz latência e custo de API calls"}]'::jsonb, 'D',
  '"(a) Secrets Manager armazena secrets (DB credentials, API keys) com rotation automática nativa (RDS, Redshift, custom Lambda rotator) e audit completo via CloudTrail. Lambda extension AWS-Parameters-and-Secrets faz HTTP local em localhost:2773 com cache em memória + TTL — reduz GetSecretValue calls (cobrados $0.05/10k). Alternativa: Parameter Store SecureString (mais barato, sem rotation nativa). (b) S3 não tem rotation. DynamoDB não é gerenciamento de secrets. Hardcode é antipattern grave. (c) Regra: secrets em prod = Secrets Manager + extension caching; config simples = Parameter Store. (d) Ver Lambda Developer Guide — Secrets Manager extension."'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["secrets-manager","lambda","extension","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
