INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-001', 'aws-dva', 'Uma aplicação Node.js usando AWS SDK v3 começa a receber muitos erros ThrottlingException ao chamar DynamoDB durante picos. O time quer que o SDK ajuste dinamicamente a taxa de chamadas com base em sinais de throttling do serviço, sem reescrever o código. Qual configuração de retry strategy resolve melhor?',
  '[{"id":"A","text":"retryMode: ''adaptive'' com maxAttempts apropriado"},{"id":"B","text":"retryMode: ''legacy'' com maxAttempts=3"},{"id":"C","text":"retryMode: ''standard'' com maxAttempts=10"},{"id":"D","text":"Desativar retry e implementar try/catch manual"}]'::jsonb, 'A',
  '{
    "summary": "Adaptive retry mode usa client-side rate limiting baseado em respostas de throttling do serviço.",
    "whyCorrect": "O modo ''adaptive'' do AWS SDK v3 inclui um token bucket client-side que reduz a taxa de envio quando recebe erros throttling (provisioned-throughput exceeded, throttling). Ele ajusta dinamicamente o RPS para evitar gerar ainda mais throttling. É a melhor escolha quando a aplicação está saturando limites do serviço.",
    "whyWrong": {
     "B": "Legacy é o modo antigo (v2 compatibility) sem rate limiting client-side — apenas retries com backoff básico.",
     "C": "Standard tem retries com exponential backoff + jitter mas SEM client-side rate limiting — você vai retentar e gerar mais throttle.",
     "D": "Desativar retry remove toda resiliência — erros transientes (5xx, 429) que seriam recuperáveis viram falhas permanentes."
    },
    "keyConcept": "AWS SDK retry modes — Legacy vs Standard vs Adaptive",
    "compareWith": [
     "Standard mode (exponential backoff + jitter) vs Adaptive (com rate limiting)",
     "Client-side throttling vs server-side throttling"
    ],
    "realWorldContext": "Apps que fazem muitas chamadas paralelas a DynamoDB, Kinesis ou S3 — adaptive evita feedback loops de throttling.",
    "commonMistakes": "Achar que adaptive é sempre melhor — ele adiciona latência ao reduzir o RPS; em apps com baixa concorrência, standard é mais simples e rápido.",
    "tutorSeeds": [
     "Como o token bucket do adaptive funciona internamente?",
     "Quando standard é preferível a adaptive?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["aws-sdk","retry","adaptive","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
