INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-002', 'aws-dva', 'Um dev está paginando resultados de S3 ListObjectsV2 manualmente, usando ContinuationToken em um loop. Ele quer simplificar o código usando recursos nativos do AWS SDK v3. Qual a abordagem idiomática?',
  '[{"id":"A","text":"Configurar maxAttempts=1000 e deixar o SDK paginar sozinho"},{"id":"B","text":"Usar paginator factory (paginateListObjectsV2) que retorna async iterator"},{"id":"C","text":"Usar SQS para enfileirar páginas e processar em batch"},{"id":"D","text":"Usar S3 Select para retornar tudo em uma chamada"}]'::jsonb, 'B',
  '{
    "summary": "AWS SDK v3 fornece paginators que abstraem ContinuationToken via async iterators.",
    "whyCorrect": "Para cada operação paginável, o SDK v3 exporta uma função paginate* (ex: paginateListObjectsV2). Ela retorna um AsyncIterable que você consome com ''for await (const page of paginator)''. O SDK trata o token automaticamente, permite configurar pageSize, e elimina o boilerplate de loop manual.",
    "whyWrong": {
     "A": "maxAttempts é para retries de erros transientes, não tem nenhuma relação com paginação.",
     "C": "SQS é fila de mensagens, não substitui paginação de uma API list.",
     "D": "S3 Select é para filtrar conteúdo de objetos CSV/JSON/Parquet, não para listar objetos do bucket."
    },
    "keyConcept": "AWS SDK v3 paginators — async iterator pattern",
    "compareWith": [
     "Manual ContinuationToken loop vs paginator async iterator",
     "SDK v2 .eachPage() vs SDK v3 paginate* factory"
    ],
    "realWorldContext": "Listar 100k+ objetos de um bucket, varrer tabelas DynamoDB grandes, listar todas as funções Lambda da conta.",
    "commonMistakes": "Esquecer de definir pageSize — o default pode ser pequeno (1000 no S3) e fazer muitas chamadas. Definir pageSize=1000 explicitamente reduz round-trips.",
    "tutorSeeds": [
     "Como configurar pageSize em paginators?",
     "Como combinar paginators com Promise.all para processar páginas em paralelo?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'easy', 'best-practice', '["aws-sdk","pagination","s3","async-iterator"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
