INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-003', 'aws-dva', 'Um time implementa retries customizados em uma aplicação Python boto3 e nota que múltiplas instâncias retentam ao mesmo tempo após falhas, gerando ''thundering herd'' no serviço dependente. Qual técnica de backoff resolve?',
  '[{"id":"A","text":"Exponential backoff fixo: delay = base * 2^attempt"},{"id":"B","text":"Retry imediato sem delay"},{"id":"C","text":"Exponential backoff with full jitter: delay = random(0, base * 2^attempt)"},{"id":"D","text":"Linear backoff: delay = base * attempt"}]'::jsonb, 'C',
  '{
    "summary": "Jitter (aleatoriedade no delay) dispersa retentativas no tempo, evitando sincronização.",
    "whyCorrect": "Exponential backoff with full jitter randomiza o delay no intervalo [0, base*2^attempt]. Isso quebra a sincronização entre clientes que falharam simultaneamente — em vez de todos voltarem juntos após 4s, eles voltam espalhados entre 0 e 4s. É a técnica padrão recomendada pela AWS (Architecture Blog ''Exponential Backoff And Jitter'').",
    "whyWrong": {
     "A": "Exponential backoff sem jitter ainda sincroniza — todas as instâncias que falharam no mesmo instante retornam exatamente após 2s, 4s, 8s... causando thundering herd.",
     "B": "Retry imediato amplifica o problema — gera ainda mais carga no serviço já degradado.",
     "D": "Linear backoff cresce lentamente e ainda sincroniza, sem dispersão temporal."
    },
    "keyConcept": "Exponential backoff with jitter — anti-pattern thundering herd",
    "compareWith": [
     "Full jitter vs Equal jitter vs Decorrelated jitter",
     "Standard SDK retry (já usa jitter) vs retry custom mal feito"
    ],
    "realWorldContext": "Falhas transitórias em DynamoDB, throttling em APIs, falhas de DB connection — sem jitter, a recuperação prolonga a saturação.",
    "commonMistakes": "Implementar retry custom sem jitter — o modo ''standard'' do SDK v3 já aplica jitter, então não reescrever.",
    "tutorSeeds": [
     "Diferença entre full jitter e equal jitter?",
     "Como o backoff impacta percentil p99 de latência?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["retry","jitter","backoff","resilience"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
