INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-004', 'aws-dva', 'Um dev configura AWS_PROFILE=prod no shell, mas também passou AWS_ACCESS_KEY_ID via variável de ambiente. Ao executar boto3, qual credencial é usada conforme o credentials provider chain?',
  '[{"id":"A","text":"O profile ''prod'' do ~/.aws/credentials, pois AWS_PROFILE tem prioridade"},{"id":"B","text":"Credenciais da IMDS (EC2 instance metadata), pois é o último fallback"},{"id":"C","text":"Erro: não é permitido ter os dois configurados"},{"id":"D","text":"As variáveis de ambiente AWS_ACCESS_KEY_ID/SECRET, pois envvars têm prioridade sobre profile"}]'::jsonb, 'D',
  '{
    "summary": "A ordem do credential provider chain coloca env vars antes de shared config profiles.",
    "whyCorrect": "A ordem oficial (boto3 e SDK v3): 1) parâmetros explícitos no client, 2) env vars (AWS_ACCESS_KEY_ID/SECRET/SESSION_TOKEN), 3) shared config profile (AWS_PROFILE), 4) credentials de container/ECS (AWS_CONTAINER_CREDENTIALS_RELATIVE_URI), 5) IMDS de EC2. Como env vars estão acima do profile, elas vencem.",
    "whyWrong": {
     "A": "AWS_PROFILE seleciona qual profile usar SE for cair na etapa 3 do chain — mas etapas anteriores (env vars) têm prioridade.",
     "B": "IMDS é o último fallback (etapa 5), só consultado se todas as anteriores falharem.",
     "C": "É permitido coexistir; a precedência decide qual prevalece."
    },
    "keyConcept": "Credentials provider chain — ordem de resolução",
    "compareWith": [
     "boto3 chain vs SDK v3 chain (idêntica)",
     "AWS_PROFILE vs AWS_ACCESS_KEY_ID precedence"
    ],
    "realWorldContext": "Debugging ''estou usando a credencial errada'' — quase sempre é envvar de uma sessão antiga sobrescrevendo o profile.",
    "commonMistakes": "Pensar que AWS_PROFILE tem precedência absoluta — não tem. unset AWS_ACCESS_KEY_ID se quiser que o profile vença.",
    "tutorSeeds": [
     "Qual a ordem exata do chain incluindo SSO?",
     "Como debugar qual credencial está sendo usada via STS GetCallerIdentity?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'troubleshoot', '["credentials","provider-chain","profile","env-vars"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
