INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-005', 'aws-dva', 'Uma aplicação roda em pods do EKS e precisa acessar S3 com uma role específica, sem montar credenciais no pod. Qual o mecanismo nativo e recomendado?',
  '[{"id":"A","text":"IRSA — IAM Roles for Service Accounts, com OIDC provider associado ao cluster"},{"id":"B","text":"Montar arquivo ~/.aws/credentials no volume do pod via Secret"},{"id":"C","text":"Usar a role do node EC2 (kubelet IAM role) para todos os pods"},{"id":"D","text":"kube2iam com sidecar de proxy em cada pod"}]'::jsonb, 'A',
  '{
    "summary": "IRSA é o mecanismo nativo AWS para mapear ServiceAccount Kubernetes a IAM role via OIDC.",
    "whyCorrect": "IRSA (IAM Roles for Service Accounts) usa o OIDC provider do EKS para emitir tokens projetados (web identity token) ao pod. O SDK detecta as env vars AWS_ROLE_ARN e AWS_WEB_IDENTITY_TOKEN_FILE e chama sts:AssumeRoleWithWebIdentity automaticamente. Granularidade por pod, sem credenciais persistentes, auditável via CloudTrail.",
    "whyWrong": {
     "B": "Distribuir credenciais via Secret é anti-pattern: credenciais longas, rotação manual, vazamento via ''kubectl get secret''.",
     "C": "Usar a node role concede a TODOS os pods do node — viola least privilege e impede granularidade.",
     "D": "kube2iam é solução de terceiros, antiga, com problemas de race conditions no startup. Foi substituída por IRSA (e EKS Pod Identity)."
    },
    "keyConcept": "EKS IRSA — IAM Roles for Service Accounts via OIDC",
    "compareWith": [
     "IRSA vs EKS Pod Identity (novo, sem OIDC, mais simples)",
     "IRSA vs node IAM role"
    ],
    "realWorldContext": "Padrão de produção para qualquer pod que precise de acesso AWS — Crossplane, External Secrets, Karpenter, app pods.",
    "commonMistakes": "Esquecer de adicionar ''sts:AssumeRoleWithWebIdentity'' na trust policy da role, ou OIDC provider mal configurado no cluster.",
    "tutorSeeds": [
     "Quando preferir EKS Pod Identity sobre IRSA?",
     "Como o token é renovado dentro do pod?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["eks","irsa","iam","oidc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
