INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-006', 'aws-dva', 'Uma Lambda Python recebe eventos de SQS em batch. O dev quer evitar reprocessar mensagens já bem-sucedidas quando UMA mensagem do batch falha. Qual recurso do AWS Lambda Powertools resolve idiomaticamente?',
  '[{"id":"A","text":"Idempotency decorator @idempotent"},{"id":"B","text":"BatchProcessor utility com partial batch response (ReportBatchItemFailures)"},{"id":"C","text":"Logger com correlation_id"},{"id":"D","text":"Parameters utility para cachear Secrets"}]'::jsonb, 'B',
  '{
    "summary": "BatchProcessor + ReportBatchItemFailures retorna apenas os messageIds que falharam, evitando reprocessar o batch inteiro.",
    "whyCorrect": "O BatchProcessor do Powertools encapsula o padrão de partial batch failure: você define um record_handler, e ele coleta exceções por mensagem. No fim, retorna {''batchItemFailures'': [...]} com os messageIds problemáticos. O SQS então requeue apenas esses, mantendo os demais como processados. Reduz duplicação e custo.",
    "whyWrong": {
     "A": "Idempotency previne efeitos duplicados mesmo se a mensagem for reprocessada — útil, mas é uma proteção complementar, não resolve o problema de ''só falhar as que falharam''.",
     "C": "Logger é para observability — não afeta o requeue de mensagens.",
     "D": "Parameters é para SSM/Secrets Manager com cache — nada a ver com batch."
    },
    "keyConcept": "Lambda Powertools BatchProcessor + ReportBatchItemFailures",
    "compareWith": [
     "Partial batch response vs falhar batch inteiro",
     "BatchProcessor vs implementação manual de batchItemFailures"
    ],
    "realWorldContext": "Pipelines SQS→Lambda com 10+ msgs por batch — sem partial failure, 1 msg ruim faz 9 msgs boas serem reprocessadas, dobrando custo e duplicando side effects.",
    "commonMistakes": "Ativar ReportBatchItemFailures no event source mapping mas não retornar o formato correto — Lambda interpreta como sucesso e nada é retentado.",
    "tutorSeeds": [
     "Como o ReportBatchItemFailures interage com DLQ?",
     "Quando combinar BatchProcessor + Idempotency?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","powertools","sqs","batch"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
