INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-007', 'aws-dva', 'Uma Lambda Python expõe um endpoint via API Gateway que processa pagamentos. O cliente faz retry automaticamente em 5xx, podendo cobrar duas vezes. Qual recurso do Powertools resolve sem refatorar lógica de negócio?',
  '[{"id":"A","text":"Tracer com X-Ray subsegments"},{"id":"B","text":"Metrics customizadas no CloudWatch"},{"id":"C","text":"@idempotent decorator com idempotency_key e DynamoDB store"},{"id":"D","text":"Event Source mapping com batch size = 1"}]'::jsonb, 'C',
  '{
    "summary": "Powertools Idempotency armazena resultado por chave em DynamoDB e retorna cached em retries.",
    "whyCorrect": "O decorator @idempotent extrai uma idempotency_key do evento (ex: header Idempotency-Key ou hash do payload), persiste em uma tabela DynamoDB com TTL, e marca a execução como IN_PROGRESS. Em retries com mesma key, retorna o resultado armazenado sem executar de novo. Evita cobrança dupla sem mudar lógica.",
    "whyWrong": {
     "A": "Tracer é observabilidade — registra spans, não previne duplicação.",
     "B": "Metrics não previnem efeitos duplicados — só medem.",
     "D": "Batch size é SQS/Kinesis, não API Gateway sync invocation."
    },
    "keyConcept": "Powertools Idempotency — at-most-once effects",
    "compareWith": [
     "Idempotency com DynamoDB vs Redis",
     "Idempotency key do cliente vs hash do payload"
    ],
    "realWorldContext": "Pagamentos, criação de pedidos, envio de email — qualquer side effect que não pode duplicar.",
    "commonMistakes": "Esquecer TTL na tabela DynamoDB — registros acumulam indefinidamente. Default: 1h, suficiente para retries de API Gateway.",
    "tutorSeeds": [
     "Como o IN_PROGRESS evita race conditions de chamadas simultâneas?",
     "Quando usar idempotency com payload hash vs header explícito?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'hard', 'scenario', '["lambda","powertools","idempotency","dynamodb"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
