INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-008', 'aws-dva', 'Uma aplicação chama um LLM (Bedrock Claude) via Lambda e quer retornar tokens ao cliente conforme são gerados, em vez de esperar a resposta completa. A Lambda está atrás de uma Function URL. Qual recurso permite isso?',
  '[{"id":"A","text":"API Gateway WebSocket API"},{"id":"B","text":"Aumentar timeout da Lambda para 15 minutos"},{"id":"C","text":"Lambda Provisioned Concurrency com warm pool"},{"id":"D","text":"Lambda Response Streaming via Function URL InvokeMode=RESPONSE_STREAM"}]'::jsonb, 'D',
  '{
    "summary": "Lambda Response Streaming permite enviar bytes progressivamente via Function URLs (até 20 MB de payload).",
    "whyCorrect": "Function URLs com InvokeMode=RESPONSE_STREAM permitem a Lambda escrever na response stream usando awslambda.streamifyResponse (Node) ou stream writer (Python via custom runtime). O cliente HTTP recebe os bytes em chunks, ideal para token streaming de LLMs (Bedrock InvokeModelWithResponseStream). TTFB cai de segundos para ms.",
    "whyWrong": {
     "A": "WebSocket API funciona, mas exige protocolo full-duplex e gerenciamento de connectionId. Para streaming unidirecional simples, Function URL streaming é mais leve.",
     "B": "Timeout não tem relação com chunked response — o cliente continua esperando a resposta completa.",
     "C": "Provisioned concurrency reduz cold start, não habilita streaming."
    },
    "keyConcept": "Lambda Response Streaming via Function URL",
    "compareWith": [
     "Function URL streaming vs WebSocket API",
     "Function URL streaming vs API Gateway (não suporta streaming response)"
    ],
    "realWorldContext": "Apps de chat com LLMs (Claude, GPT), geração de relatórios longos, export de CSV/JSON grande.",
    "commonMistakes": "Achar que API Gateway HTTP/REST suporta streaming response — não suporta; só Function URL.",
    "tutorSeeds": [
     "Quais limites: payload máximo, throughput?",
     "Como o cliente consome a stream (fetch + ReadableStream)?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","response-streaming","function-url","llm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
