INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-009', 'aws-dva', 'Uma Lambda Java 21 com Spring Boot tem cold start de 8s, inaceitável para um endpoint sync. O time não quer pagar Provisioned Concurrency 24/7. Qual feature reduz cold start sem custo adicional contínuo?',
  '[{"id":"A","text":"Lambda SnapStart (snapshot do runtime após init)"},{"id":"B","text":"Trocar para arquitetura ARM Graviton"},{"id":"C","text":"Aumentar memory para 10 GB"},{"id":"D","text":"Migrar para container image Lambda"}]'::jsonb, 'A',
  '{
    "summary": "SnapStart tira snapshot do estado pós-init e cria invocações a partir dele, eliminando JVM warm-up.",
    "whyCorrect": "Lambda SnapStart (disponível para Java 11+, Python 3.12+ e .NET 8+) executa o init code uma vez, tira snapshot Firecracker do microVM, e usa esse snapshot para futuras invocações cold. Reduz cold start de Java de 5-10s para ~100ms. Sem custo adicional além do storage do snapshot.",
    "whyWrong": {
     "B": "Graviton dá ~20% melhor preço/performance mas não elimina init de JVM/Spring (segundos).",
     "C": "10 GB de memory ajuda um pouco (mais CPU proporcional) mas não elimina o init lento da JVM.",
     "D": "Container image tem cold start similar ou pior (image pull + extract); não é solução."
    },
    "keyConcept": "Lambda SnapStart — Firecracker snapshot do estado pós-init",
    "compareWith": [
     "SnapStart vs Provisioned Concurrency",
     "SnapStart Java vs Python — gotchas de uniqueness (UUIDs, conexões)"
    ],
    "realWorldContext": "Spring Boot, Quarkus, .NET 8 — workloads enterprise que sofriam de cold start em Lambda.",
    "commonMistakes": "Esquecer que após SnapStart, conexões TCP/DB ficam inválidas — usar runtime hooks @OnRestore para reabrir.",
    "tutorSeeds": [
     "Como o Firecracker faz o snapshot?",
     "Diferença entre SnapStart Java e Python na criação de UUIDs?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'scenario', '["lambda","snapstart","java","cold-start"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
