INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-dev-v3-010', 'aws-dva', 'Um time empacota uma aplicação Python ML em container image Lambda (10 GB com modelo). Qual base image AWS é a recomendada para reduzir cold start mantendo compatibilidade total com runtime gerenciado?',
  '[{"id":"A","text":"ubuntu:22.04 com pip install"},{"id":"B","text":"public.ecr.aws/lambda/python:3.12 (AWS-provided base)"},{"id":"C","text":"alpine:latest com Python compilado"},{"id":"D","text":"Sem base image — só o código zipado"}]'::jsonb, 'B',
  '{
    "summary": "Base images AWS já incluem Lambda Runtime Interface Client (RIC) e runtime emulator — ideal para Lambda.",
    "whyCorrect": "AWS publica base images otimizadas (public.ecr.aws/lambda/python:3.12, nodejs:20, java:21 etc) com: RIC instalado, layers cacheadas pela Lambda service, lazy loading otimizado. Reduz cold start de container image em até 50%. Suporta também Lambda Insights e signals corretos.",
    "whyWrong": {
     "A": "Ubuntu não tem RIC — exige instalar manualmente, image fica maior, lazy load não otimizado. Funciona mas é desnecessário.",
     "C": "Alpine usa musl em vez de glibc — incompatível com muitas wheels Python (numpy, pandas). Evitar.",
     "D": "Sem base image não é opção em container image Lambda — precisa de uma image."
    },
    "keyConcept": "Lambda container image base images — RIC e lazy loading",
    "compareWith": [
     "AWS base image vs custom Ubuntu/Alpine",
     "Container image (10 GB max) vs ZIP package (250 MB max)"
    ],
    "realWorldContext": "ML inference em Lambda, OCR, PDF generation, qualquer função que precisa de dependências grandes (>250 MB).",
    "commonMistakes": "Não usar multi-stage build para reduzir tamanho final; ou esquecer de fixar tag específica (não usar :latest).",
    "tutorSeeds": [
     "Como o lazy loading do Lambda funciona em container images?",
     "Quando preferir container image vs ZIP + layer?"
    ]
   }'::jsonb,
  'Development with AWS Services', 'Development with AWS Services', 'medium', 'best-practice', '["lambda","container-image","ecr","base-image"]'::jsonb, 'ai-draft', 'active', now(), now()
)
