INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-001', 'aws-dva', 'Uma equipe está desenvolvendo uma aplicação Node.js em Amazon EC2 que precisa fazer PutObject em um bucket S3. O dev sênior pediu para remover as access keys do arquivo .env e usar o modo mais seguro. Qual abordagem o developer deve adotar?',
  '[{"id":"A","text":"Anexar um IAM instance profile com a permissão s3:PutObject à EC2"},{"id":"B","text":"Criar um IAM user e injetar as keys via AWS Systems Manager"},{"id":"C","text":"Criptografar o .env com KMS e descriptografar no boot"},{"id":"D","text":"Usar a root account key da conta AWS"}]'::jsonb, 'A',
  '"(a) Instance profile permite que a EC2 obtenha credenciais temporárias via IMDS sem armazenar chaves em disco — o SDK resolve automaticamente. (b) IAM user com keys distribuídas via SSM ainda mantém credenciais de longa duração; criptografar .env só protege at-rest mas a chave ainda fica na instância; root keys são proibidas para qualquer aplicação. (c) Regra: para serviços AWS (EC2/Lambda/ECS), sempre usar IAM role, nunca access keys estáticas. (d) Ver IAM User Guide — Roles for EC2."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["iam","ec2","instance-profile"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
