INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-002', 'aws-dva', 'Uma função Lambda em produção falha ao chamar dynamodb:Query com AccessDeniedException. O developer confirmou que a tabela existe e o nome está correto. Onde a permissão deve ser concedida?',
  '[{"id":"A","text":"Na resource-based policy da tabela DynamoDB"},{"id":"B","text":"Na execution role da função Lambda"},{"id":"C","text":"Na bucket policy do S3 onde está o código"},{"id":"D","text":"No SCP da AWS Organization"}]'::jsonb, 'B',
  '"(a) Lambda assume sua execution role para chamar outros serviços; a permissão IAM dynamodb:Query precisa estar na policy dessa role. (b) DynamoDB não tem resource-based policy clássica (só via RAM cross-account); bucket S3 controla código do deploy, não runtime; SCP existe mas em contas standalone normalmente não bloqueia. (c) Regra: serviço AWS chamando outro = permission policy na execution role do chamador. (d) Ver IAM User Guide — Roles for Lambda."'::jsonb,
  'Security', 'Security', 'easy', 'troubleshoot', '["iam","lambda","execution-role","dynamodb"]'::jsonb, 'ai-draft', 'active', now(), now()
)
