INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-003', 'aws-dva', 'Uma tarefa Amazon ECS Fargate precisa ler segredos do Secrets Manager e escrever logs no CloudWatch. O developer está configurando a task definition. Qual configuração de IAM é correta?',
  '[{"id":"A","text":"Usar apenas a Task Execution Role para tudo"},{"id":"B","text":"Anexar a role à instância EC2 subjacente"},{"id":"C","text":"Task Execution Role para pull de imagem/logs/secrets injection; Task Role para chamadas do app em runtime"},{"id":"D","text":"Criar um IAM user dedicado para a task"}]'::jsonb, 'C',
  '"(a) ECS separa duas roles: Task Execution Role é usada pelo agente ECS para puxar imagem ECR, enviar logs e injetar secrets como env var; Task Role é assumida pelo container em runtime para chamar APIs AWS. (b) Usar só Execution Role mistura responsabilidades e quebra least privilege; Fargate não tem EC2 subjacente acessível; IAM user com keys é antipadrão. (c) Regra: Execution = infra/lifecycle; Task = runtime do app. (d) Ver IAM User Guide — Roles for ECS Tasks."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["iam","ecs","fargate","task-role"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
