INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-004', 'aws-dva', 'Um developer cria uma IAM role para uma função Lambda. A trust policy define quem pode assumir a role; a permission policy define o que a role pode fazer. Quais Principal e Action devem aparecer na trust policy?',
  '[{"id":"A","text":"Principal: ec2.amazonaws.com; Action: lambda:InvokeFunction"},{"id":"B","text":"Principal: o ARN do bucket S3; Action: s3:GetObject"},{"id":"C","text":"Principal: *; Action: *"},{"id":"D","text":"Principal: lambda.amazonaws.com; Action: sts:AssumeRole"}]'::jsonb, 'D',
  '"(a) Trust policy de uma role para Lambda lista o service principal lambda.amazonaws.com com sts:AssumeRole — só assim o serviço Lambda pode obter credenciais temporárias da role. (b) ec2 é outro serviço; InvokeFunction é ação de runtime, não de trust. S3 não assume role; é objeto. Principal:* com Action:* é vazamento crítico. (c) Regra: trust policy = quem assume; permission policy = o que pode fazer. (d) Ver IAM User Guide — Trust policies."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["iam","trust-policy","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
