INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-005', 'aws-dva', 'Uma startup migra uma aplicação on-premises para Amazon EC2. A app usa access keys hardcoded em código para chamar S3 e SQS. Após migração, o auditor exige remoção dessas keys. Qual é a forma mais simples e segura de prover credenciais à app na EC2?',
  '[{"id":"A","text":"Criar um IAM role com as permissões necessárias e anexar à EC2 via instance profile"},{"id":"B","text":"Mover as keys para AWS Secrets Manager e consultar no boot"},{"id":"C","text":"Armazenar as keys em uma variável de ambiente do systemd"},{"id":"D","text":"Rodar a app em um container Docker isolado"}]'::jsonb, 'A',
  '"(a) IAM role + instance profile é a forma canônica e mais segura — credenciais temporárias auto-rotacionadas pelo IMDS, sem segredo estático em lugar algum. (b) Mover keys para Secrets Manager ainda exige uma credencial inicial para autenticar com o próprio Secrets Manager (chicken-and-egg). Env var no systemd ainda é credencial de longa duração. Docker isolado não resolve o problema de credenciais. (c) Regra: nunca usar long-lived access keys quando role pode ser usada. (d) Ver IAM User Guide — Roles for EC2."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["iam","ec2","instance-profile","credentials"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
