INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-006', 'aws-dva', 'Uma função Lambda precisa enviar mensagens para um tópico SNS de outra conta AWS. A execution role da Lambda concede sns:Publish no ARN do tópico. Mesmo assim, recebe AuthorizationError. O que falta?',
  '[{"id":"A","text":"Anexar policy adicional ao IAM user que criou a Lambda"},{"id":"B","text":"Adicionar uma resource-based policy no tópico SNS permitindo a role da conta origem"},{"id":"C","text":"Configurar VPC endpoint para SNS"},{"id":"D","text":"Habilitar criptografia KMS no tópico"}]'::jsonb, 'B',
  '"(a) Acesso cross-account exige permissão dos dois lados: identity-based (role da Lambda — já feito) E resource-based (topic policy do SNS permitindo a role da conta origem). (b) IAM user não está na cadeia — Lambda usa a role. VPC endpoint é para network privada, não autoriza. KMS habilita criptografia, não muda autorização de publish. (c) Regra: cross-account = dois lados. (d) Ver IAM User Guide — Cross-account."'::jsonb,
  'Security', 'Security', 'medium', 'troubleshoot', '["iam","sns","cross-account","resource-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
