INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-007', 'aws-dva', 'Um developer cria um IAM role com a managed policy AmazonS3FullAccess para uma Lambda que só precisa fazer GetObject em um bucket específico. O time de segurança rejeita por violação de least privilege. Qual ação corrige?',
  '[{"id":"A","text":"Manter S3FullAccess mas habilitar CloudTrail"},{"id":"B","text":"Adicionar S3ReadOnlyAccess e manter FullAccess"},{"id":"C","text":"Adicionar uma inline policy com s3:GetObject restrito ao ARN do bucket/objeto e remover a managed policy"},{"id":"D","text":"Usar a managed policy PowerUserAccess"}]'::jsonb, 'C',
  '"(a) Least privilege exige granularidade: ação específica (s3:GetObject) + resource específico (ARN do bucket/object), tipicamente via inline ou customer-managed policy. (b) CloudTrail audita, não restringe. Combinar policies amplas não reduz permissões — IAM aplica união. PowerUserAccess é ainda mais amplo. (c) Regra: least privilege = ação mínima + resource mínimo + condições. (d) Ver IAM User Guide — Least privilege."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["iam","least-privilege","policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
