INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-008', 'aws-dva', 'Uma função Lambda foi configurada com uma execution role recém-criada. No primeiro invoke, retorna InvalidClientTokenId. O developer suspeita de problema de permissão, mas o role foi anexado corretamente. Qual é a causa mais provável?',
  '[{"id":"A","text":"A função Lambda precisa ser recriada do zero"},{"id":"B","text":"A região está incorreta"},{"id":"C","text":"Falta MFA no IAM user que criou a role"},{"id":"D","text":"A role acabou de ser criada e ainda não propagou (eventual consistency do IAM)"}]'::jsonb, 'D',
  '"(a) IAM é eventually consistent — após criar/modificar role, pode haver atraso de segundos antes da propagação global. InvalidClientTokenId em primeiro invoke após criação é sintoma clássico. (b) Recriar a função não resolve eventual consistency. Região errada daria erro diferente (ResourceNotFound). MFA não se aplica a roles assumidas por serviços. (c) Regra: aguardar propagação (alguns segundos) ou implementar retry exponencial. (d) Ver IAM User Guide — Eventual consistency."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["iam","lambda","eventual-consistency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
