INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-009', 'aws-dva', 'Um developer precisa habilitar uma integração nativa entre Amazon RDS e Performance Insights. A AWS exige uma service-linked role específica. Como o developer deve proceder?',
  '[{"id":"A","text":"A service-linked role é criada automaticamente pela AWS na primeira ativação do recurso"},{"id":"B","text":"Criar manualmente a role e definir a trust policy de service"},{"id":"C","text":"Solicitar AWS Support para criar a role"},{"id":"D","text":"Service-linked roles foram descontinuadas"}]'::jsonb, 'A',
  '"(a) Service-linked roles são roles pré-definidas pela AWS, criadas automaticamente (ou via console do serviço) na primeira ativação, com permissions/trust gerenciadas pelo próprio serviço — o developer não cria nem edita manualmente. (b) Criar manualmente quebra o contrato; Support não é necessário; service-linked roles são vigentes e expandindo. (c) Regra: SLR = role gerenciada pelo serviço AWS; aparece com prefixo AWSServiceRoleFor*. (d) Ver IAM User Guide — Service-linked roles."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["iam","service-linked-role"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
