INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-010', 'aws-dva', 'Um time desenvolveu uma Lambda que escreve em DynamoDB. Em testes locais, o developer usa suas próprias access keys. No deploy para a conta AWS, a Lambda falha. O time decide padronizar. Qual é a melhor forma de garantir permissão em prod?',
  '[{"id":"A","text":"Hardcodar as keys do developer em variáveis de ambiente da Lambda"},{"id":"B","text":"Anexar uma execution role com dynamodb:PutItem no ARN da tabela"},{"id":"C","text":"Compartilhar as keys do dev via SSM Parameter Store SecureString"},{"id":"D","text":"Usar a role da AWS Console como execution role"}]'::jsonb, 'B',
  '"(a) Execution role com permission policy granular é o padrão para Lambda em prod — credenciais temporárias auto-rotacionadas. (b) Hardcode de keys pessoais quebra least privilege e vaza identidade do dev. Compartilhar via SSM ainda mantém keys de longa duração. Role da Console é a role do usuário humano, não pode ser assumida por serviço. (c) Regra: dev keys são para dev local; prod usa role. (d) Ver IAM User Guide — Roles for Lambda."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["iam","lambda","execution-role"]'::jsonb, 'ai-draft', 'active', now(), now()
)
