INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-011', 'aws-dva', 'Uma aplicação rodando em Amazon EKS precisa que cada Pod tenha sua própria identidade IAM granular (não compartilhar o nó). Qual recurso atende?',
  '[{"id":"A","text":"IAM instance profile do worker node EC2"},{"id":"B","text":"Hardcode de access keys no Pod spec"},{"id":"C","text":"IAM Roles for Service Accounts (IRSA) via OIDC provider"},{"id":"D","text":"Kubernetes ServiceAccount sem mapping IAM"}]'::jsonb, 'C',
  '"(a) IRSA associa um ServiceAccount Kubernetes a uma IAM role via OIDC provider do cluster EKS — cada Pod usando o SA assume a role correspondente, isolando permissões. (b) Instance profile do nó é compartilhado por todos os Pods (anti-padrão). Hardcode de keys é insegurança. SA sem IAM mapping não dá acesso AWS. (c) Regra: granularidade por Pod = IRSA. (d) Ver IAM User Guide — IRSA."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["iam","eks","irsa","oidc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
