INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-012', 'aws-dva', 'Um developer criou uma IAM role com permission policy `s3:*` mas a trust policy aceita Principal: ec2.amazonaws.com. Ao tentar usar a role em uma função Lambda, recebe erro de assumption. Por quê?',
  '[{"id":"A","text":"A permission policy precisa incluir lambda:*"},{"id":"B","text":"A role precisa de tags específicas"},{"id":"C","text":"Lambda só pode usar managed policies"},{"id":"D","text":"A trust policy não inclui lambda.amazonaws.com como Principal"}]'::jsonb, 'D',
  '"(a) Trust policy define quais principals podem assumir a role. Se só ec2.amazonaws.com está listado, Lambda não pode assumir. Adicionar lambda.amazonaws.com (ou usar lista) resolve. (b) Permission policy controla o que a role faz, não quem a assume. Tags são opcionais. Lambda usa qualquer tipo de policy. (c) Regra: trust policy = quem assume; permission policy = o que pode fazer. (d) Ver IAM User Guide — Trust policies."'::jsonb,
  'Security', 'Security', 'medium', 'troubleshoot', '["iam","trust-policy","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
