INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-013', 'aws-dva', 'Uma aplicação web usa AWS STS AssumeRole para acessar recursos em outra conta. Após login do usuário corporativo, o backend chama AssumeRole e usa as credenciais retornadas. Qual é a duração máxima padrão da sessão temporária?',
  '[{"id":"A","text":"1 hora (padrão), configurável até 12 horas via DurationSeconds"},{"id":"B","text":"15 minutos"},{"id":"C","text":"24 horas fixas"},{"id":"D","text":"30 dias"}]'::jsonb, 'A',
  '"(a) AssumeRole retorna credenciais com duração padrão de 3600s (1h), configurável entre 900s (15min) e 43200s (12h) via DurationSeconds — limitado também pelo MaxSessionDuration da role. (b) 15min é o mínimo, não o padrão. 24h e 30 dias estão fora do limite. (c) Regra: STS AssumeRole = 1h default, 12h máximo. AssumeRoleWithSAML/WebIdentity também 1h default. (d) Ver STS API Reference — AssumeRole."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["sts","assume-role","session-duration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
