INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-014', 'aws-dva', 'Uma aplicação mobile usa Cognito Identity Pool para federar usuários autenticados via Google. O fluxo retorna credenciais AWS temporárias diretamente para o app. Qual operação STS o Cognito chama internamente?',
  '[{"id":"A","text":"AssumeRole"},{"id":"B","text":"AssumeRoleWithWebIdentity"},{"id":"C","text":"AssumeRoleWithSAML"},{"id":"D","text":"GetSessionToken"}]'::jsonb, 'B',
  '"(a) AssumeRoleWithWebIdentity é a operação para federar identidades de provedores OIDC públicos (Google, Facebook, Cognito) — não requer credenciais AWS prévias. (b) AssumeRole exige credenciais AWS. AssumeRoleWithSAML é para SAML 2.0 enterprise (AD). GetSessionToken estende credenciais de IAM user (com MFA), não federa. (c) Regra: web identity (OIDC público) = AssumeRoleWithWebIdentity. (d) Ver STS API Reference."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["sts","cognito-identitypool","web-identity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
