INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-015', 'aws-dva', 'Uma empresa contratada precisa acessar recursos em uma conta da empresa cliente via AssumeRole. Para evitar confused deputy, o que deve ser configurado?',
  '[{"id":"A","text":"MFA obrigatório no IAM user da contratada"},{"id":"B","text":"Habilitar CloudTrail no Cliente"},{"id":"C","text":"ExternalId na trust policy da role e exigido na chamada AssumeRole"},{"id":"D","text":"Rotacionar a access key da role mensalmente"}]'::jsonb, 'C',
  '"(a) ExternalId é um secret compartilhado entre cliente (na trust policy via Condition sts:ExternalId) e contratada (na chamada AssumeRole), protegendo contra ataques de confused deputy onde outro cliente da contratada usaria o acesso indevidamente. (b) MFA protege usuário humano, não confused deputy entre serviços. CloudTrail audita, não previne. Roles não têm access keys rotacionáveis. (c) Regra: cross-account com terceiro (vendor) = sempre ExternalId. (d) Ver IAM User Guide — Confused deputy."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["sts","external-id","confused-deputy","cross-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
