INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-016', 'aws-dva', 'Um developer chama sts:AssumeRole com DurationSeconds=14400 (4 horas). A role tem MaxSessionDuration=3600. A chamada retorna ValidationError. Por quê?',
  '[{"id":"A","text":"DurationSeconds deve ser sempre 3600"},{"id":"B","text":"MFA é obrigatório para durações \u003e 1 hora"},{"id":"C","text":"STS não suporta durações fracionárias"},{"id":"D","text":"DurationSeconds solicitado excede MaxSessionDuration da role"}]'::jsonb, 'D',
  '"(a) MaxSessionDuration da role é o limite superior; DurationSeconds da chamada AssumeRole deve ser <= MaxSessionDuration. Para permitir 4h, role precisa MaxSessionDuration >= 14400. (b) DurationSeconds aceita valores entre 900 e 43200; MFA não é exigido para duração estendida. Frações não se aplicam (valor em segundos). (c) Regra: limite efetivo = min(DurationSeconds, MaxSessionDuration). (d) Ver STS API Reference — AssumeRole."'::jsonb,
  'Security', 'Security', 'medium', 'troubleshoot', '["sts","assume-role","session-duration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
