INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-017', 'aws-dva', 'Uma aplicação CLI exige MFA antes de chamar APIs sensíveis. O developer precisa obter credenciais temporárias após validar o token MFA do usuário IAM. Qual operação STS é apropriada?',
  '[{"id":"A","text":"GetSessionToken com parâmetros SerialNumber e TokenCode"},{"id":"B","text":"AssumeRole sem condições"},{"id":"C","text":"AssumeRoleWithWebIdentity"},{"id":"D","text":"GetCallerIdentity"}]'::jsonb, 'A',
  '"(a) GetSessionToken retorna credenciais temporárias para o próprio IAM user que chama, podendo incluir validação MFA via SerialNumber (ARN do device) + TokenCode (código de 6 dígitos). (b) AssumeRole troca para outra role, não estende user atual. AssumeRoleWithWebIdentity é para OIDC. GetCallerIdentity só retorna ARN/UserId (debug), não credenciais. (c) Regra: MFA + estender credenciais do próprio user = GetSessionToken. (d) Ver STS API Reference."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["sts","mfa","get-session-token"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
