INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-018', 'aws-dva', 'Após chamada AssumeRole bem-sucedida, o developer recebe três campos. Qual deve ser incluído no header `X-Amz-Security-Token` (ou config equivalente) das chamadas API?',
  '[{"id":"A","text":"AccessKeyId apenas"},{"id":"B","text":"SessionToken (junto com AccessKeyId + SecretAccessKey)"},{"id":"C","text":"Expiration timestamp"},{"id":"D","text":"AssumedRoleId"}]'::jsonb, 'B',
  '"(a) Credenciais temporárias STS sempre vêm em trio: AccessKeyId + SecretAccessKey + SessionToken. O SessionToken é obrigatório no header X-Amz-Security-Token; sem ele, a chamada falha como se fosse access key estática inválida. (b) AccessKeyId sozinho não autoriza temporária. Expiration é metadata. AssumedRoleId é identificador, não credencial. (c) Regra: credencial temporária = trio AKID/SAK/Token. (d) Ver STS API Reference — Credentials."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["sts","session-token","credentials"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
