INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-019', 'aws-dva', 'Um aplicativo de terceiros precisa acessar a conta AWS de um cliente. O cliente cria uma role e compartilha o ARN. O vendor chama AssumeRole, mas o cliente quer garantir que apenas usuários do vendor (não outros clientes do vendor) acessem. Qual mecanismo evita o ataque confused deputy?',
  '[{"id":"A","text":"Habilitar MFA no vendor"},{"id":"B","text":"Usar bucket policy com aws:SourceIp"},{"id":"C","text":"Configurar ExternalId único na trust policy, conhecido só entre vendor e este cliente"},{"id":"D","text":"Adicionar tags na role"}]'::jsonb, 'C',
  '"(a) ExternalId é segredo compartilhado entre vendor e cliente específico — sem ele na chamada AssumeRole, falha; mesmo se outro cliente conhecesse o ARN, sem o ExternalId não consegue assumir. (b) MFA não impede o vendor confundido. SourceIp é network-level, não autenticidade do cliente. Tags são metadados, não autenticam. (c) Regra: confused deputy entre contas via terceiro = ExternalId. (d) Ver IAM User Guide — Confused deputy."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["sts","external-id","confused-deputy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
