INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-020', 'aws-dva', 'Um developer precisa fazer role chaining: assumir RoleA e depois usar essa credencial para assumir RoleB. Qual é a limitação imposta pelo STS?',
  '[{"id":"A","text":"Role chaining não é suportado"},{"id":"B","text":"Cada chain duplica o limite de duração"},{"id":"C","text":"Role chaining exige MFA em cada step"},{"id":"D","text":"DurationSeconds máximo em role chaining é 1 hora (3600s), independente de MaxSessionDuration"}]'::jsonb, 'D',
  '"(a) Quando uma role assume outra (chaining), o STS limita a duração da sessão da segunda role a no máximo 1 hora, mesmo que MaxSessionDuration permita mais — para evitar amplificação de credenciais de longa duração. (b) Chaining é suportado e comum. Não duplica nada. MFA não é obrigatório em chains. (c) Regra: role chaining = teto fixo de 1h. (d) Ver STS API Reference — Role chaining."'::jsonb,
  'Security', 'Security', 'hard', 'recall', '["sts","role-chaining","session-duration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
