INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-021', 'aws-dva', 'Uma aplicação faz cache de credenciais STS após AssumeRole para reduzir chamadas. Como o app deve decidir quando renovar?',
  '[{"id":"A","text":"Usar o campo Expiration retornado e renovar pouco antes (ex: 5 min)"},{"id":"B","text":"Sempre chamar AssumeRole antes de cada request"},{"id":"C","text":"Renovar apenas após receber AccessDenied"},{"id":"D","text":"Credenciais STS não expiram"}]'::jsonb, 'A',
  '"(a) AssumeRole retorna Expiration (timestamp) — boa prática é renovar com margem (ex: 5 minutos antes) para evitar requests com token expirado. (b) Chamar AssumeRole por request anula o benefício do cache e gera throttling. Reagir só a AccessDenied causa falhas em janelas. Credenciais STS sempre expiram. (c) Regra: cache + refresh proativo baseado em Expiration. (d) Ver STS API Reference."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["sts","credentials","caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
