INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-022', 'aws-dva', 'Uma aplicação em conta A precisa publicar mensagens em uma fila SQS na conta B. Qual configuração mínima é necessária para autorizar?',
  '[{"id":"A","text":"Permissão sqs:SendMessage só na IAM policy da role em A"},{"id":"B","text":"Policy IAM em A (sqs:SendMessage no ARN da queue B) + queue policy em B autorizando o principal de A"},{"id":"C","text":"Habilitar SQS server-side encryption"},{"id":"D","text":"Criar um VPC peering entre A e B"}]'::jsonb, 'B',
  '"(a) Cross-account exige permissão dos dois lados: identity policy no chamador (role de A com sqs:SendMessage) + resource policy na queue (policy SQS de B permitindo principal de A). (b) Só IAM no lado de A não basta — queue rejeita por padrão chamadas externas. SSE é criptografia at-rest. VPC peering é rede, não autorização. (c) Regra: cross-account = dois lados. (d) Ver IAM User Guide — Cross-account."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["sqs","cross-account","resource-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
