INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-023', 'aws-dva', 'Um bucket S3 cross-account é acessado por uma role da conta vizinha. Os objetos são uploaded por uma terceira conta. Após acesso, a role recebe objetos mas com erro de KMS Decrypt. Qual permissão falta?',
  '[{"id":"A","text":"s3:GetObjectVersion na bucket policy"},{"id":"B","text":"Aumentar storage class do bucket"},{"id":"C","text":"kms:Decrypt no key policy do KMS CMK + IAM policy da role"},{"id":"D","text":"Desabilitar versionamento"}]'::jsonb, 'C',
  '"(a) Quando S3 SSE-KMS é usado, ler o objeto exige permissão kms:Decrypt na CMK (que pode ser de outra conta) — tanto na key policy quanto na IAM policy da role. Sem isso, S3 retorna erro de KMS independente de permissões S3. (b) GetObjectVersion é para versões antigas, não resolve KMS. Storage class não afeta acesso. Versionamento idem. (c) Regra: SSE-KMS = preciso GetObject (S3) + Decrypt (KMS). (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["s3","kms","cross-account","sse-kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
