INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-024', 'aws-dva', 'Uma SaaS (conta SaaS) precisa rodar Lambdas que escrevem em S3 do cliente final (conta Cliente). A SaaS quer evitar role manual per-cliente. Qual padrão é usado?',
  '[{"id":"A","text":"Compartilhar access keys da SaaS com o Cliente"},{"id":"B","text":"Replicar S3 da SaaS para o Cliente via DataSync"},{"id":"C","text":"Cliente compartilha sua root account com a SaaS"},{"id":"D","text":"Cliente cria uma IAM role que confia na conta SaaS (com ExternalId), e SaaS Lambda chama AssumeRole cross-account"}]'::jsonb, 'D',
  '"(a) Padrão SaaS cross-account: cliente cria role com trust policy permitindo conta SaaS + ExternalId; SaaS Lambda chama AssumeRole para obter credenciais e operar no S3 do cliente. (b) Compartilhar keys ou root é violação grave; DataSync é replicação, não autorização. (c) Regra: SaaS multi-tenant cross-account = AssumeRole + ExternalId por tenant. (d) Ver IAM User Guide."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["sts","cross-account","saas","external-id"]'::jsonb, 'ai-draft', 'active', now(), now()
)
