INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-025', 'aws-dva', 'Uma role na conta A está sendo usada para chamar KMS Decrypt em uma CMK da conta B. A IAM policy da role tem kms:Decrypt e a key policy permite a conta A. A chamada ainda falha. Qual configuração extra a key policy precisa para permitir?',
  '[{"id":"A","text":"Princípio AWS: ARN da role específica (ou root account) e kms:Decrypt como ação permitida"},{"id":"B","text":"Princípio Service: kms.amazonaws.com"},{"id":"C","text":"Adicionar a CMK em outra região"},{"id":"D","text":"Habilitar key rotation"}]'::jsonb, 'A',
  '"(a) Cross-account KMS exige que a key policy permita explicitamente o principal externo (role ARN ou root da conta A) com a ação (kms:Decrypt). IAM policy sozinha não basta — key policy é o gate primário. (b) Service principal é para serviços internos. Cross-region não autoriza. Rotation é gestão da chave. (c) Regra: KMS = key policy é mandatória, IAM é complementar. (d) Ver KMS Developer Guide — Key policies."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["kms","cross-account","key-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
