INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-026', 'aws-dva', 'Um time precisa que a função Lambda em uma conta consiga invocar outra Lambda em conta diferente. Como configurar?',
  '[{"id":"A","text":"Replicar a Lambda nas duas contas"},{"id":"B","text":"Resource-based policy na Lambda target permitindo principal da role chamadora + lambda:InvokeFunction na IAM policy da role"},{"id":"C","text":"Usar SNS como bridge sempre"},{"id":"D","text":"Habilitar Lambda layers cross-account"}]'::jsonb, 'B',
  '"(a) Lambda suporta resource-based policy (Lambda function policy) — adicionar permission para o principal externo invocar; combinar com IAM policy concedendo lambda:InvokeFunction no ARN da Lambda alvo. (b) Replicar Lambda quebra DRY. SNS é desnecessário para invocação direta. Layers cross-account é compartilhamento de código, não invocação. (c) Regra: cross-account Lambda invoke = ambos os lados. (d) Ver IAM User Guide."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["lambda","cross-account","resource-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
