INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-027', 'aws-dva', 'Uma role em conta A precisa assumir uma role em conta B, que por sua vez assume role em conta C (chain de 3 contas). O time observa que sessões duram só 1h, mesmo com MaxSessionDuration alto. Por quê?',
  '[{"id":"A","text":"Erro de configuração no MaxSessionDuration"},{"id":"B","text":"STS não suporta mais de 2 contas"},{"id":"C","text":"Role chaining limita sessão a no máximo 1 hora"},{"id":"D","text":"Falta MFA na cadeia"}]'::jsonb, 'C',
  '"(a) Por design, qualquer role chaining (role assume role) tem teto de 1h na sessão da role assumida em segundo lugar — independente de MaxSessionDuration. (b) Config correta; STS suporta N contas; MFA não é obrigatório. (c) Regra: chaining = 1h max sempre. Para sessões maiores, evitar chain (assumir direto do principal raiz). (d) Ver STS API Reference."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["sts","role-chaining","cross-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
