INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-028', 'aws-dva', 'Uma aplicação em conta A escreve objetos em bucket S3 da conta B. Após upload, objetos pertencem à conta A (uploader) e a conta B (bucket owner) não consegue lê-los. Como resolver?',
  '[{"id":"A","text":"Replicar o bucket"},{"id":"B","text":"Habilitar versionamento"},{"id":"C","text":"Trocar storage class para Glacier"},{"id":"D","text":"Configurar Object Ownership = Bucket owner enforced (ou usar ACL bucket-owner-full-control no PutObject)"}]'::jsonb, 'D',
  '"(a) S3 Object Ownership ''Bucket owner enforced'' (recomendado desde 2023) faz com que objetos uploaded sempre pertençam ao bucket owner, eliminando ACLs. Alternativa legada: uploader define ACL bucket-owner-full-control no PutObject. (b) Replicação não muda ownership. Versionamento mantém histórico. Glacier é storage class. (c) Regra: cross-account upload = Object Ownership BOE. (d) Ver Amazon S3 User Guide — Object Ownership."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["s3","cross-account","object-ownership"]'::jsonb, 'ai-draft', 'active', now(), now()
)
