INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-029', 'aws-dva', 'Uma aplicação SPA React quer permitir signup/login com email e senha sem rodar backend de auth. Qual serviço atende com fluxo padrão OAuth/OIDC?',
  '[{"id":"A","text":"Amazon Cognito User Pool com Hosted UI"},{"id":"B","text":"IAM users via API"},{"id":"C","text":"AWS Directory Service"},{"id":"D","text":"AWS Secrets Manager"}]'::jsonb, 'A',
  '"(a) Cognito User Pool é um IdP gerenciado com signup/login, MFA, recuperação de senha, Hosted UI customizável e fluxos OAuth/OIDC padrão — ideal para SPA sem backend de auth próprio. (b) IAM users são para acesso AWS, não usuários finais. Directory Service é Microsoft AD. Secrets Manager guarda segredos, não autentica usuários. (c) Regra: auth de usuários finais (B2C/B2B web/mobile) = Cognito User Pool. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'easy', 'scenario', '["cognito-userpool","auth","oidc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
