INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-030', 'aws-dva', 'Após autenticar no User Pool, o frontend recebe ID Token, Access Token e Refresh Token. Qual é a função correta de cada um?',
  '[{"id":"A","text":"Todos são intercambiáveis"},{"id":"B","text":"ID Token = identidade do usuário (OIDC); Access Token = autorização de API (scopes OAuth); Refresh Token = obter novos ID/Access"},{"id":"C","text":"ID Token autoriza API; Refresh autentica usuário"},{"id":"D","text":"Access Token expira em 30 dias"}]'::jsonb, 'B',
  '"(a) ID Token (OIDC) carrega claims sobre o usuário (sub, email, custom attrs) — usado no client app. Access Token (OAuth 2.0) carrega scopes — usado para autorizar chamadas a APIs (ex: API Gateway). Refresh Token tem vida longa (dias) e obtém novos ID/Access via /token endpoint. (b) Access Token padrão dura 1h. Refresh padrão dura 30 dias mas é configurável. (c) Regra: ID = identidade; Access = autorização API; Refresh = renovar. (d) Ver Cognito Developer Guide — Tokens."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["cognito-userpool","jwt","oauth2"]'::jsonb, 'ai-draft', 'active', now(), now()
)
