INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-031', 'aws-dva', 'Um developer precisa enviar email customizado de boas-vindas quando usuário confirma cadastro no Cognito User Pool. Qual recurso atende?',
  '[{"id":"A","text":"EventBridge rule no API Gateway"},{"id":"B","text":"Cognito Hosted UI custom HTML"},{"id":"C","text":"Lambda trigger Post Confirmation"},{"id":"D","text":"S3 event notification"}]'::jsonb, 'C',
  '"(a) Cognito User Pool expõe Lambda triggers em pontos do ciclo de vida: Pre Sign-up, Post Confirmation, Pre Auth, Post Auth, Pre Token Generation, Migrate User, Custom Message, etc. Post Confirmation é o gancho ideal para enviar email custom (via SES) após confirmação. (b) EventBridge no API Gateway é para outras finalidades. Hosted UI muda look-and-feel, não eventos. S3 events são para objetos. (c) Regra: hook em fluxo Cognito = Lambda trigger. (d) Ver Cognito Developer Guide — Lambda triggers."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito-userpool","lambda-trigger","post-confirmation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
