INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-032', 'aws-dva', 'Uma aplicação precisa adicionar campos customizados (ex: tenant_id, plan_tier) ao perfil dos usuários do User Pool. Como o developer deve fazer?',
  '[{"id":"A","text":"Salvar em DynamoDB separado"},{"id":"B","text":"Hardcode no Hosted UI"},{"id":"C","text":"Usar Cognito Identity Pool roles"},{"id":"D","text":"Definir custom attributes no User Pool e referenciar com prefixo custom:tenant_id"}]'::jsonb, 'D',
  '"(a) User Pool suporta até 50 custom attributes (string/number) — declarados no pool com prefixo ''custom:'' e expostos nos tokens JWT. (b) DynamoDB separado funciona mas não integra com tokens JWT. Hosted UI é UI, não data. Identity Pool é federação cross-AWS, não armazena perfil custom. (c) Regra: dados de perfil simples = custom attributes; dados complexos/transacionais = DynamoDB. (d) Ver Cognito Developer Guide — User attributes."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["cognito-userpool","custom-attributes"]'::jsonb, 'ai-draft', 'active', now(), now()
)
