INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-033', 'aws-dva', 'Uma empresa quer forçar MFA com TOTP (Google Authenticator) para todos os usuários do User Pool. Qual configuração aplica?',
  '[{"id":"A","text":"Configurar MFA como ''Required'' e habilitar Software Token MFA no User Pool"},{"id":"B","text":"Desabilitar Hosted UI"},{"id":"C","text":"Adicionar trigger Pre Auth com captcha"},{"id":"D","text":"Aumentar password policy length"}]'::jsonb, 'A',
  '"(a) User Pool suporta MFA: Off / Optional / Required. Para forçar todos, setar Required + habilitar Software Token MFA (TOTP) ou SMS. Usuários completam setup no primeiro login após enable. (b) Desabilitar Hosted UI não impõe MFA. Trigger Pre Auth com captcha mitiga bots, não MFA. Password length é outra dimensão. (c) Regra: MFA Required força segundo fator. (d) Ver Cognito Developer Guide — MFA."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito-userpool","mfa","totp"]'::jsonb, 'ai-draft', 'active', now(), now()
)
