INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-034', 'aws-dva', 'Um User Pool tem dois app clients: web (SPA) e mobile. O developer quer impedir que o app client web peça scope ''admin''. Onde configurar?',
  '[{"id":"A","text":"Na bucket policy do S3 do frontend"},{"id":"B","text":"Nos Allowed OAuth Scopes do app client web (excluindo admin)"},{"id":"C","text":"Não é configurável"},{"id":"D","text":"Apenas via Lambda trigger Pre Auth"}]'::jsonb, 'B',
  '"(a) Cada app client tem ''Allowed OAuth Scopes'' — só esses scopes podem aparecer no Access Token emitido. Restringir scopes por client isola permissões entre web e mobile. (b) Bucket policy não controla OAuth scope. É configurável diretamente. Lambda Pre Auth pode bloquear, mas a forma nativa é Allowed Scopes. (c) Regra: scopes por client = nativo do Cognito. (d) Ver Cognito Developer Guide — App clients."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["cognito-userpool","oauth-scopes","app-client"]'::jsonb, 'ai-draft', 'active', now(), now()
)
