INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-035', 'aws-dva', 'Um app client confidencial (backend server-side) precisa de Client ID e Client Secret para chamar /oauth2/token. Que precaução o developer deve tomar?',
  '[{"id":"A","text":"Embutir o Client Secret no SPA frontend"},{"id":"B","text":"Tornar o Client Secret público em GitHub"},{"id":"C","text":"Armazenar Client Secret somente no backend e usar Authorization: Basic base64(client_id:client_secret)"},{"id":"D","text":"Rotacionar manualmente a cada chamada"}]'::jsonb, 'C',
  '"(a) Client Secret é credencial confidencial — só usar em backend confiável; chamadas a /oauth2/token usam header Authorization Basic com client_id:client_secret base64. SPAs não devem ter secret (usar app client sem secret + PKCE). (b) Embutir em SPA expõe publicamente. GitHub público é vazamento. Rotação per-call inviável. (c) Regra: secret = só backend; SPA = app client público + PKCE. (d) Ver Cognito Developer Guide — App clients."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["cognito-userpool","client-secret","pkce"]'::jsonb, 'ai-draft', 'active', now(), now()
)
