INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-036', 'aws-dva', 'Um developer precisa migrar usuários de um sistema legado para Cognito User Pool sem forçar reset de senha. Qual mecanismo atende?',
  '[{"id":"A","text":"Importar via CSV com hashes"},{"id":"B","text":"Forçar reset de senha para todos"},{"id":"C","text":"Não é possível"},{"id":"D","text":"Lambda trigger Migrate User: valida credenciais no legacy na primeira tentativa de login e cria o usuário no pool transparentemente"}]'::jsonb, 'D',
  '"(a) Migrate User trigger é o padrão: quando usuário não existe no pool e tenta autenticar, Cognito chama a Lambda que valida no sistema legado e retorna o user; Cognito cria o user no pool com a senha fornecida — migração transparente. (b) CSV import não preserva senhas (hashes incompatíveis). Reset force afeta UX. É possível com Migrate User. (c) Regra: migração transparente = Lambda trigger Migrate User. (d) Ver Cognito Developer Guide — Lambda triggers."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito-userpool","migrate-user","lambda-trigger"]'::jsonb, 'ai-draft', 'active', now(), now()
)
