INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-037', 'aws-dva', 'Após autenticar no User Pool via Hosted UI, o usuário é redirecionado com um ''code'' na URL. Como o frontend obtém os tokens?',
  '[{"id":"A","text":"Frontend (ou backend) troca o code por tokens no endpoint /oauth2/token (Authorization Code grant)"},{"id":"B","text":"O code já é o token"},{"id":"C","text":"O Cognito envia tokens por email"},{"id":"D","text":"Tokens são automáticos no cookie httpOnly"}]'::jsonb, 'A',
  '"(a) Authorization Code grant: client recebe code, faz POST em /oauth2/token com grant_type=authorization_code + code + redirect_uri (+ client_secret se aplicável) e recebe ID/Access/Refresh tokens. (b) Code não é token; precisa ser trocado. Email não distribui token. Cookie httpOnly é opcional, não automático. (c) Regra: OAuth Authorization Code Flow = redirect com code, POST /token. (d) Ver Cognito Developer Guide — OAuth flows."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["cognito-userpool","oauth2","authorization-code"]'::jsonb, 'ai-draft', 'active', now(), now()
)
