INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-038', 'aws-dva', 'Um developer quer adicionar claim customizada (ex: tenant_id) ao ID Token para uso no client, baseado em lógica de runtime. Qual trigger atende?',
  '[{"id":"A","text":"Pre Sign-up"},{"id":"B","text":"Pre Token Generation"},{"id":"C","text":"Post Confirmation"},{"id":"D","text":"Pre Auth"}]'::jsonb, 'B',
  '"(a) Pre Token Generation é invocado antes da emissão do JWT — permite adicionar/modificar/suprimir claims no ID Token (e versão V2 também no Access Token). Ideal para injetar tenant_id, roles dinâmicas, feature flags. (b) Pre Sign-up valida cadastro; Post Confirmation roda após confirmação; Pre Auth bloqueia tentativa de login. (c) Regra: modificar claims do JWT = Pre Token Generation. (d) Ver Cognito Developer Guide — Lambda triggers."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito-userpool","pre-token-generation","claims"]'::jsonb, 'ai-draft', 'active', now(), now()
)
