INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-039', 'aws-dva', 'Uma aplicação mobile autentica usuários via Cognito User Pool, mas precisa que o app chame diretamente APIs AWS (S3, DynamoDB) com credenciais temporárias scoped por usuário. Qual serviço integra?',
  '[{"id":"A","text":"STS AssumeRole sem mais nada"},{"id":"B","text":"IAM users por usuário final"},{"id":"C","text":"Cognito Identity Pool, com o User Pool como auth provider"},{"id":"D","text":"Embed access keys da conta AWS"}]'::jsonb, 'C',
  '"(a) Identity Pool federa identidades de IdPs (User Pool, Google, Facebook, SAML) e troca por credenciais AWS temporárias via AssumeRoleWithWebIdentity — permite que o app mobile chame APIs AWS com identidade do usuário. (b) STS AssumeRole exige credenciais AWS prévias. IAM user per usuário é inviável (limite + admin overhead). Embed keys é violação grave. (c) Regra: User Pool autentica + Identity Pool autoriza AWS access. (d) Ver Cognito Developer Guide — Identity Pools."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito-userpool","cognito-identitypool","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
