INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-040', 'aws-dva', 'Uma aplicação móvel permite acesso a usuários anônimos (guest) e autenticados. Qual feature do Cognito Identity Pool habilita isso?',
  '[{"id":"A","text":"Pre Auth Lambda trigger"},{"id":"B","text":"API Keys do API Gateway"},{"id":"C","text":"Bucket policy public-read"},{"id":"D","text":"Habilitar ''Enable access to unauthenticated identities'' + configurar a unauthenticated role com permissões mínimas"}]'::jsonb, 'D',
  '"(a) Identity Pool tem duas roles: authenticated e unauthenticated. Habilitando ''unauthenticated identities'', usuários guest recebem credenciais AWS temporárias mapeadas para a role unauth (com permissões mínimas, ex: leitura de catálogo público). (b) Pre Auth é trigger de User Pool. API Keys não dão acesso AWS direto. Bucket policy public é alternativa, mas Identity Pool guest é mais flexível. (c) Regra: guest access AWS = Identity Pool unauthenticated. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito-identitypool","unauthenticated","guest"]'::jsonb, 'ai-draft', 'active', now(), now()
)
