INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-041', 'aws-dva', 'Um Identity Pool autentica usuários via User Pool e quer atribuir diferentes IAM roles baseado em group claim do usuário (ex: ''admins'' vs ''users''). Qual recurso suporta?',
  '[{"id":"A","text":"Role Mappings com regras baseadas em claim do token"},{"id":"B","text":"Múltiplos Identity Pools por grupo"},{"id":"C","text":"Reescrever no frontend"},{"id":"D","text":"Não suportado"}]'::jsonb, 'A',
  '"(a) Identity Pool suporta Role Mappings/Rules: avalia claims do token (ex: cognito:groups, custom:tier) e mapeia para role específica. Permite RBAC dinâmico sem fragmentar pools. (b) Múltiplos pools é overhead. Frontend não controla credenciais AWS. É suportado nativamente. (c) Regra: RBAC via Identity Pool = Role Mappings com claim rules. (d) Ver Cognito Developer Guide — Role mapping."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito-identitypool","role-mapping","rbac"]'::jsonb, 'ai-draft', 'active', now(), now()
)
