INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-042', 'aws-dva', 'Uma app integra Cognito Identity Pool com login do Facebook. Após login no Facebook, qual token o cliente envia para Identity Pool obter credenciais AWS?',
  '[{"id":"A","text":"Cognito ID Token"},{"id":"B","text":"Facebook access token (passado no GetCredentialsForIdentity via Logins map)"},{"id":"C","text":"Facebook app secret"},{"id":"D","text":"Google ID Token"}]'::jsonb, 'B',
  '"(a) Cliente passa o token do IdP (Facebook access token) no parâmetro Logins ({''graph.facebook.com'': ''<token>''}) ao chamar GetId/GetCredentialsForIdentity — Identity Pool valida com Facebook e emite credenciais AWS temporárias. (b) Cognito ID Token é caso User Pool. App secret é confidencial servidor. Google ID Token é outro provider. (c) Regra: federação social = passar token do IdP no Logins map. (d) Ver Cognito Developer Guide — External providers."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["cognito-identitypool","facebook","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
