INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-043', 'aws-dva', 'Um Identity Pool quer permitir que usuários autenticados só acessem objetos S3 prefixados com seu próprio identityId. Qual recurso usar na IAM policy da role?',
  '[{"id":"A","text":"Hardcode do user_id"},{"id":"B","text":"Lambda authorizer"},{"id":"C","text":"Variável de policy ${cognito-identity.amazonaws.com:sub} no Resource ARN"},{"id":"D","text":"Bucket por usuário"}]'::jsonb, 'C',
  '"(a) IAM policies suportam variáveis dinâmicas como ${cognito-identity.amazonaws.com:sub} (identityId do usuário) — usar no Resource ARN (ex: arn:aws:s3:::bucket/${cognito-identity.amazonaws.com:sub}/*) restringe acesso por usuário sem replicar policies. (b) Hardcode quebra com escala. Lambda authorizer é para API Gateway, não S3. Bucket por usuário é inviável (limite). (c) Regra: row-level no IAM = variáveis de policy. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["cognito-identitypool","iam-policy-variables","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
