INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-044', 'aws-dva', 'Após GetCredentialsForIdentity no Identity Pool, o SDK recebe credenciais STS. Quanto duram por padrão?',
  '[{"id":"A","text":"30 dias"},{"id":"B","text":"5 minutos"},{"id":"C","text":"Não expiram"},{"id":"D","text":"1 hora (padrão), até 12 horas configuráveis"}]'::jsonb, 'D',
  '"(a) Identity Pool emite credenciais via AssumeRoleWithWebIdentity — duração default 1h, configurável até 12h via API. SDK auto-renova ao se aproximar da expiração. (b) Refresh Token do User Pool tem vida longa, não credenciais STS. 5min é mínimo de STS. Sempre expiram. (c) Regra: credenciais Identity Pool = STS = 1h default. (d) Ver STS API Reference."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["cognito-identitypool","sts","credentials"]'::jsonb, 'ai-draft', 'active', now(), now()
)
