INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-045', 'aws-dva', 'Um time tem dois sistemas: app web com Cognito User Pool e mobile que precisa autorizar acesso AWS direto. Qual arquitetura é correta?',
  '[{"id":"A","text":"User Pool (auth) + Identity Pool com User Pool como provider (autorização AWS)"},{"id":"B","text":"Apenas User Pool"},{"id":"C","text":"Apenas Identity Pool"},{"id":"D","text":"IAM users em backend"}]'::jsonb, 'A',
  '"(a) Combinação canônica: User Pool autentica (signup/login/MFA) e emite JWT; Identity Pool aceita o JWT do User Pool e emite credenciais STS para chamar APIs AWS diretamente do cliente. (b) Só User Pool não dá AWS access direto; só Identity Pool não tem registro de usuários. IAM users por usuário é inviável. (c) Regra: User Pool = autenticação; Identity Pool = autorização AWS direta. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["cognito-userpool","cognito-identitypool","architecture"]'::jsonb, 'ai-draft', 'active', now(), now()
)
