INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-046', 'aws-dva', 'Uma empresa enterprise quer SSO via Active Directory (SAML 2.0) integrado ao Identity Pool. Qual configuração permite?',
  '[{"id":"A","text":"Migrar todos para Cognito User Pool primeiro"},{"id":"B","text":"Adicionar o IdP SAML como Authentication Provider no Identity Pool"},{"id":"C","text":"Identity Pool não suporta SAML"},{"id":"D","text":"Usar AWS IAM Identity Center exclusivamente"}]'::jsonb, 'B',
  '"(a) Identity Pool suporta SAML 2.0 como Authentication Provider — registrar metadado do IdP corporativo (AD FS, Okta, Azure AD); usuários autenticam no IdP e Identity Pool troca por credenciais AWS. (b) Migração não é necessária. Suporta SAML. IAM Identity Center é alternativa para acesso humano à console AWS, não para app federation. (c) Regra: enterprise SSO + AWS resources direto = Identity Pool com SAML. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito-identitypool","saml","sso"]'::jsonb, 'ai-draft', 'active', now(), now()
)
