INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-047', 'aws-dva', 'Um app mobile faz GetCredentialsForIdentity no Identity Pool sem token de provider. Recebe credenciais válidas. Qual configuração permitiu isso?',
  '[{"id":"A","text":"Bug do Cognito"},{"id":"B","text":"Credenciais root da conta"},{"id":"C","text":"Identity Pool tem unauthenticated access habilitado e o app usa a unauth role"},{"id":"D","text":"Impossível, deve haver erro de config"}]'::jsonb, 'C',
  '"(a) Com ''unauthenticated identities'' habilitado, qualquer chamada GetId sem Logins recebe credenciais mapeadas para a unauthenticated role — permitido por design para usuários guest. (b) Não é bug; root nunca emite via Identity Pool; config é válida. (c) Regra: Identity Pool emite credenciais para guests se habilitado; revisar permissions da unauth role para evitar exposição. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'medium', 'troubleshoot', '["cognito-identitypool","unauthenticated","guest"]'::jsonb, 'ai-draft', 'active', now(), now()
)
