INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-048', 'aws-dva', 'Um Identity Pool é configurado com OIDC provider (Auth0). Qual passo é necessário no IAM antes do Identity Pool aceitar tokens do Auth0?',
  '[{"id":"A","text":"Habilitar IAM Identity Center"},{"id":"B","text":"Nenhum, Identity Pool gerencia tudo"},{"id":"C","text":"Criar um IAM user no Auth0"},{"id":"D","text":"Criar um IAM OIDC Identity Provider apontando para Auth0 e seu thumbprint"}]'::jsonb, 'D',
  '"(a) Para OIDC custom (Auth0, Okta, etc.), criar um IAM OIDC Identity Provider com URL do issuer, audience e thumbprint do cert; depois referenciar no Identity Pool como Authentication Provider OIDC. (b) IAM Identity Center é outro produto. Identity Pool não cria o IdP. Não há IAM user no Auth0. (c) Regra: OIDC custom = IAM OIDC IdP + Identity Pool provider. (d) Ver IAM User Guide — OIDC providers."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito-identitypool","oidc","iam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
