INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-049', 'aws-dva', 'Uma aplicação Java usa AWS Encryption SDK e quer criptografar dados >4KB. KMS Encrypt direto falha por limite. Qual padrão aplicar?',
  '[{"id":"A","text":"Envelope encryption: GenerateDataKey gera data key (plaintext + ciphertext); criptografar dados local com data key plaintext; armazenar ciphertext blob junto"},{"id":"B","text":"Comprimir os dados até \u003c4KB"},{"id":"C","text":"Solicitar limite raise via Support"},{"id":"D","text":"Usar SSE-S3 sempre"}]'::jsonb, 'A',
  '"(a) KMS Encrypt aceita até 4KB de plaintext. Para volumes maiores, padrão é envelope encryption: GenerateDataKey retorna data key em plaintext + ciphertext blob; app criptografa o dado com data key plaintext (AES-GCM local), descarta plaintext, armazena ciphertext do dado + ciphertext blob da data key. Decrypt invoca KMS Decrypt no blob para recuperar a chave. (b) Compressão não escala. Support não muda 4KB. SSE-S3 ignora app-level. (c) Regra: dados >4KB = envelope encryption. (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["kms","envelope-encryption","generate-data-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
