INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-050', 'aws-dva', 'Um developer quer entender a diferença entre Customer-managed CMK e AWS-managed CMK. Qual afirmação é correta?',
  '[{"id":"A","text":"AWS-managed CMK permite custom key policy"},{"id":"B","text":"Customer-managed CMK permite key policy customizável, alias custom, rotation configurável; AWS-managed é por serviço (aws/s3, aws/lambda) e gerenciada pela AWS"},{"id":"C","text":"AWS-managed CMK tem cobrança extra"},{"id":"D","text":"Customer-managed CMK rotaciona obrigatoriamente a cada 90 dias"}]'::jsonb, 'B',
  '"(a) AWS-managed CMK (alias aws/<service>) é criada e gerenciada pela AWS para integração default do serviço — key policy não editável. Customer-managed permite controle total: policy, alias, grants, rotation opcional (annual). (b) AWS-managed não tem cobrança per-CMK (rotation incluída); customer-managed tem $1/mês por CMK. Rotation customer-managed é opt-in anual (não 90d). (c) Regra: customer-managed = controle total + custo; AWS-managed = simples + grátis mas limitada. (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["kms","cmk","key-management"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
