INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-051', 'aws-dva', 'Uma aplicação quer rotacionar automaticamente o material criptográfico de uma customer-managed CMK. Qual é o comportamento padrão da automatic key rotation?',
  '[{"id":"A","text":"Rotação a cada 30 dias e a CMK ID muda"},{"id":"B","text":"Manual sempre"},{"id":"C","text":"Rotação anual (365 dias); CMK ID/ARN/alias permanecem; AWS mantém versões antigas para descriptografar dados antigos"},{"id":"D","text":"Rotação invalida dados criptografados anteriormente"}]'::jsonb, 'C',
  '"(a) Automatic rotation em CMK customer-managed roda anualmente; KMS gera novo material e o associa à mesma CMK ID — aplicações continuam usando o mesmo ARN/alias sem mudança. Versões antigas permanecem internamente para descriptografar dados pré-rotation. (b) 30 dias não é o padrão. Rotação não invalida dados. ID/ARN permanecem. (c) Regra: rotation automática = anual + transparente. (d) Ver KMS Developer Guide — Rotating keys."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["kms","key-rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
