INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-052', 'aws-dva', 'Um developer cria uma CMK customer-managed mas esquece de adicionar a própria role na key policy. Tenta usar e recebe AccessDenied, mesmo sendo admin da conta. Por quê?',
  '[{"id":"A","text":"Bug do KMS"},{"id":"B","text":"Precisa habilitar MFA"},{"id":"C","text":"Region errada"},{"id":"D","text":"Key policy é o gate primário; sem o principal listado (mesmo admin), o acesso é negado. IAM admin acess não substitui key policy"}]'::jsonb, 'D',
  '"(a) KMS é único entre serviços AWS: key policy é OBRIGATÓRIA e gate primário. Mesmo um IAM admin com kms:* na IAM policy é negado se não estiver listado (ou pelo root) na key policy. Padrão da AWS adiciona root account principal para evitar lockout. (b) Não é bug; MFA não relacionado; region daria outro erro. (c) Regra: KMS = key policy é mandatória; IAM policy é aditiva, não substitutiva. (d) Ver KMS Developer Guide — Key policies."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["kms","key-policy","access-denied"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
