INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-053', 'aws-dva', 'Uma aplicação Lambda em conta A precisa criptografar/descriptografar dados com uma CMK em conta B usando GenerateDataKey. Que combinação de permissões é necessária?',
  '[{"id":"A","text":"kms:GenerateDataKey + kms:Decrypt na IAM policy da role A E key policy de B permitindo a role A nessas ações"},{"id":"B","text":"Só kms:GenerateDataKey na IAM policy da role A"},{"id":"C","text":"Só na key policy de B"},{"id":"D","text":"Compartilhar CMK via RAM"}]'::jsonb, 'A',
  '"(a) Cross-account KMS: IAM policy (lado A) deve conceder as ações; key policy (lado B) deve permitir explicitamente o principal externo nas mesmas ações. Para envelope encryption, normalmente preciso GenerateDataKey (encrypt) e Decrypt (decrypt). (b) Só um dos lados é insuficiente. RAM não compartilha CMK (usa key policy mesmo). (c) Regra: KMS cross-account = key policy + IAM policy dos dois lados. (d) Ver KMS Developer Guide — Cross-account."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","cross-account","generate-data-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
