INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-054', 'aws-dva', 'Um time precisa garantir que uma CMK só seja usada por uma role específica em uma janela temporária (8 horas) sem alterar key policy permanentemente. Qual recurso atende?',
  '[{"id":"A","text":"Tag temporária"},{"id":"B","text":"KMS Grant — concede uso programaticamente, scoped por operação/encryption context, com retire"},{"id":"C","text":"Alias temporário"},{"id":"D","text":"Bucket policy"}]'::jsonb, 'B',
  '"(a) KMS Grant é mecanismo programático para conceder permissões granulares (operações específicas, encryption context, constraints) a um grantee sem editar key policy — pode ser revogado (RetireGrant/RevokeGrant) e tem TTL implícito. Ideal para acesso temporário/programático. (b) Tags são metadata. Alias é nome. Bucket policy é de S3. (c) Regra: acesso programático temporário a CMK = Grant. (d) Ver KMS Developer Guide — Grants."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","grants"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
