INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-055', 'aws-dva', 'Um developer quer trocar uma CMK referenciada em código sem mudar o código. Qual recurso permite?',
  '[{"id":"A","text":"Tag da chave"},{"id":"B","text":"Grants"},{"id":"C","text":"Alias do KMS (alias/myapp-prod) referenciado em vez do KeyId/ARN"},{"id":"D","text":"Trocar a region"}]'::jsonb, 'C',
  '"(a) Alias é nome amigável (prefix alias/) referenciável no SDK em lugar do KeyId/ARN — apontá-lo para outra CMK (UpdateAlias) troca a chave usada sem recompilar/redeployar app. (b) Tag é metadata. Grant adiciona permissões, não troca chave. Region é outro recurso. (c) Regra: indireção de CMK = Alias. (d) Ver KMS Developer Guide — Aliases."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["kms","alias"]'::jsonb, 'ai-draft', 'active', now(), now()
)
