INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-056', 'aws-dva', 'Em uma chamada GenerateDataKey, o developer passa EncryptionContext={''tenantId'':''tenant-42''}. Qual é o efeito?',
  '[{"id":"A","text":"Criptografa dados maiores que 4KB"},{"id":"B","text":"Modifica a CMK"},{"id":"C","text":"Apenas logging"},{"id":"D","text":"Adiciona AAD (Additional Authenticated Data) ao ciphertext; Decrypt exige o mesmo EncryptionContext, garantindo binding ao tenant"}]'::jsonb, 'D',
  '"(a) EncryptionContext é pares chave-valor anexados como AAD na criptografia autenticada (AES-GCM) — preservados em CloudTrail logs para audit e exigidos exatamente iguais no Decrypt, oferecendo binding criptográfico (proteção contra confused deputy ao descriptografar dado de outro tenant). (b) Não muda tamanho, CMK, nem é só logging. (c) Regra: EncryptionContext = AAD + audit binding. (d) Ver KMS Developer Guide — Encryption context."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","encryption-context","aad"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
