INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-057', 'aws-dva', 'Um time deleta uma CMK por engano. Qual mecanismo evita perda total imediata de dados criptografados?',
  '[{"id":"A","text":"ScheduleKeyDeletion com pending window 7-30 dias (default 30) — durante esse período, key pode ser canceled"},{"id":"B","text":"KMS deleta imediatamente sem janela"},{"id":"C","text":"Backup automático em S3"},{"id":"D","text":"Replicação cross-region"}]'::jsonb, 'A',
  '"(a) KMS não deleta imediatamente: solicita-se ScheduleKeyDeletion com PendingWindowInDays entre 7 e 30 dias. Durante a janela a CMK fica em estado PendingDeletion (não usável); pode ser cancelada (CancelKeyDeletion). (b) Não há backup S3 nativo. Replicação multi-region é feature separada. (c) Regra: deletion = janela de espera obrigatória; sempre verificar uso antes. (d) Ver KMS Developer Guide — Deleting keys."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["kms","key-deletion"]'::jsonb, 'ai-draft', 'active', now(), now()
)
