INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-058', 'aws-dva', 'Um Lambda usa o AWS Encryption SDK para criptografar payloads. O SDK chama internamente KMS GenerateDataKey. Comparado a chamar Encrypt direto, qual vantagem?',
  '[{"id":"A","text":"Nenhuma"},{"id":"B","text":"Permite criptografar volumes arbitrários (envelope encryption); reduz chamadas KMS via data key caching"},{"id":"C","text":"Funciona offline sem KMS"},{"id":"D","text":"Elimina necessidade de IAM"}]'::jsonb, 'B',
  '"(a) Encryption SDK encapsula envelope encryption: gera data key via KMS, criptografa dados localmente (sem limite de 4KB), pode cachear data keys para reduzir custos/latência KMS, suporta multi-CMK e algoritmos modernos. (b) Não funciona sem KMS; IAM continua necessário para chamar KMS. (c) Regra: AWS Encryption SDK = envelope encryption + caching + multi-CMK. (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["kms","encryption-sdk","envelope-encryption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
