INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-059', 'aws-dva', 'Um cliente quer trazer seu próprio material criptográfico para CMK (BYOK) por exigência regulatória. Qual feature do KMS atende?',
  '[{"id":"A","text":"AWS-managed CMK com aliases"},{"id":"B","text":"Grants"},{"id":"C","text":"External Key Store (XKS) ou Import Key Material (BYOK) na CMK"},{"id":"D","text":"BYOK é incompatível com KMS"}]'::jsonb, 'C',
  '"(a) KMS suporta Import Key Material em CMK customer-managed: cliente importa material (256 bits, wrapped) e KMS o usa. Para chaves nunca expostas à AWS, usar External Key Store (XKS) com HSM externo. (b) AWS-managed não permite BYOK. Grants é permissão. É compatível. (c) Regra: BYOK = ImportKeyMaterial; sovereign = XKS. (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","byok","import-key-material"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
