INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-060', 'aws-dva', 'Uma chamada KMS Decrypt em uma Lambda falha com ''KMSAccessDeniedException''. A role tem kms:Decrypt na IAM policy e a key policy lista a role. Que outra causa pode ser?',
  '[{"id":"A","text":"Tabela DynamoDB"},{"id":"B","text":"Bucket S3"},{"id":"C","text":"Concurrency limit"},{"id":"D","text":"Falta KMS endpoint na VPC (Lambda em VPC privada sem internet) ou EncryptionContext divergente"}]'::jsonb, 'D',
  '"(a) Causas comuns além de IAM/key policy: (1) Lambda em subnet privada sem NAT/VPC endpoint para KMS — falha de network; (2) EncryptionContext usado em GenerateDataKey não passado igual no Decrypt — invalidade criptográfica reportada como AccessDenied. (b) DynamoDB/S3 não estão no caminho. Concurrency dá outra exception. (c) Regra: KMS Decrypt errors = checar network + EncryptionContext. (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["kms","decrypt","vpc-endpoint","encryption-context"]'::jsonb, 'ai-draft', 'active', now(), now()
)
