INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-061', 'aws-dva', 'Um team precisa armazenar a senha do banco RDS usada por uma Lambda. Quer rotação automática a cada 30 dias e integração nativa com RDS. Qual serviço atende?',
  '[{"id":"A","text":"AWS Secrets Manager"},{"id":"B","text":"SSM Parameter Store (Standard)"},{"id":"C","text":"S3 com SSE-KMS"},{"id":"D","text":"Variável de ambiente da Lambda"}]'::jsonb, 'A',
  '"(a) Secrets Manager tem rotação automática via Lambda template (integração nativa com RDS/Aurora/Redshift/DocumentDB), versionamento, replicação cross-region e criptografia KMS. (b) Parameter Store não tem rotação built-in (precisa custom Lambda + EventBridge); só Advanced Tier tem features avançadas (e custo). S3 não tem rotação. Env var não rotaciona. (c) Regra: rotação nativa de credenciais DB = Secrets Manager. (d) Ver Secrets Manager User Guide."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["secrets-manager","rotation","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
