INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-062', 'aws-dva', 'Um time tem 200 parâmetros de config (não-sensíveis) usados por microserviços. Quer custo zero. Qual serviço escolher?',
  '[{"id":"A","text":"Secrets Manager"},{"id":"B","text":"SSM Parameter Store Standard tier (free, até 10k params/account)"},{"id":"C","text":"DynamoDB encrypted table"},{"id":"D","text":"S3 com versionamento"}]'::jsonb, 'B',
  '"(a) Parameter Store Standard tier é gratuito até 10.000 parâmetros por conta/região, suporta String/StringList/SecureString — ideal para config não-sensível de microserviços. (b) Secrets Manager cobra $0.40/secret/mês — caro para 200 configs simples. DynamoDB exige modelagem. S3 é overkill. (c) Regra: config simples = Parameter Store; segredos rotacionados = Secrets Manager. (d) Ver SSM User Guide."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["parameter-store","ssm","config"]'::jsonb, 'ai-draft', 'active', now(), now()
)
