INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-063', 'aws-dva', 'Um SecureString no Parameter Store é criptografado com KMS. Para ler de Lambda, qual permissão é necessária além de ssm:GetParameter?',
  '[{"id":"A","text":"Nenhuma adicional"},{"id":"B","text":"ssm:DecryptParameter"},{"id":"C","text":"kms:Decrypt na CMK usada (default aws/ssm ou customer-managed)"},{"id":"D","text":"s3:GetObject"}]'::jsonb, 'C',
  '"(a) SecureString é criptografado por KMS; para ler decoded, Lambda precisa kms:Decrypt na CMK + WithDecryption=true na chamada GetParameter. Sem kms:Decrypt, retorna apenas ciphertext (ou erro). (b) Sempre adicional. ssm:DecryptParameter não existe. S3 fora do caminho. (c) Regra: SecureString = ssm + kms:Decrypt. (d) Ver SSM User Guide — Parameter Store."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["parameter-store","kms","secure-string"]'::jsonb, 'ai-draft', 'active', now(), now()
)
