INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-064', 'aws-dva', 'Um secret no Secrets Manager precisa rotacionar credenciais RDS sem downtime para a app. Como funciona a estratégia ''alternating users''?',
  '[{"id":"A","text":"App fica offline durante rotação"},{"id":"B","text":"Rotação manual"},{"id":"C","text":"Restart obrigatório"},{"id":"D","text":"Dois users no DB alternam; rotation Lambda cria novo password no user inativo, promove a current; app sempre lê secret atual sem invalidar conexões existentes"}]'::jsonb, 'D',
  '"(a) Rotation template ''alternate users'' mantém dois usuários no DB; o secret aponta para o ''current'' enquanto rotation prepara o ''previous''. Após teste, troca o current. Apps que recarregam secret periodicamente não percebem corte. (b) Não há offline; rotação automática; sem restart obrigatório. (c) Regra: zero-downtime credential rotation = alternating users. (d) Ver Secrets Manager User Guide — Rotation strategies."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["secrets-manager","rotation","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
