INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-065', 'aws-dva', 'Uma aplicação acessa parâmetros hierárquicos no Parameter Store: /app/prod/db-host, /app/prod/db-port. Qual recurso facilita o fetch em batch?',
  '[{"id":"A","text":"GetParametersByPath com Path=''/app/prod'' e Recursive=true"},{"id":"B","text":"GetParameter um por um sempre"},{"id":"C","text":"Scan S3"},{"id":"D","text":"Listar Secrets"}]'::jsonb, 'A',
  '"(a) Parameter Store suporta hierarquia por ''/''; GetParametersByPath retorna todos os parâmetros sob um path (com Recursive=true para descer subníveis), reduzindo chamadas e organizando por env/app. (b) Individual é ineficiente. S3 e Secrets não se aplicam. (c) Regra: organização hierárquica + batch fetch = Path + GetParametersByPath. (d) Ver SSM User Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["parameter-store","hierarchy","ssm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
