INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-066', 'aws-dva', 'Um secret é compartilhado entre contas via Secrets Manager. Qual mecanismo permite leitura cross-account?',
  '[{"id":"A","text":"Cópia manual periódica"},{"id":"B","text":"Resource-based policy no secret permitindo a conta/role externa + kms:Decrypt na CMK customer-managed"},{"id":"C","text":"Não é possível"},{"id":"D","text":"Apenas via export CSV"}]'::jsonb, 'B',
  '"(a) Secrets Manager suporta resource-based policy no secret — permitir principal externo a secretsmanager:GetSecretValue + permitir o mesmo principal a kms:Decrypt na customer-managed CMK que criptografa o secret (default aws/secretsmanager não permite cross-account, exige customer-managed). (b) Cópia manual deriva. É possível. CSV não. (c) Regra: cross-account secret = resource policy + customer-managed CMK. (d) Ver Secrets Manager User Guide."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["secrets-manager","cross-account","kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
