INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-067', 'aws-dva', 'Um time quer reduzir custo de chamadas a Secrets Manager em uma Lambda invocada milhares de vezes/dia. Qual abordagem ajuda?',
  '[{"id":"A","text":"Chamar GetSecretValue em todo invoke"},{"id":"B","text":"Migrar para hardcode"},{"id":"C","text":"Cachear o secret na memória do execution context (init phase), invalidar baseado em rotation interval"},{"id":"D","text":"Aumentar timeout da Lambda"}]'::jsonb, 'C',
  '"(a) Lambda reaproveita execution context (warm starts) — cachear o secret em variável global no init permite milhares de invokes reusarem sem nova chamada. Pode-se usar Lambda Extension ''AWS Parameters and Secrets'' que cacheia com TTL. (b) Por invoke é caro e adiciona latência. Hardcode é antipadrão. Timeout não resolve. (c) Regra: secret = cache no init com refresh consciente de rotation. (d) Ver Secrets Manager User Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["secrets-manager","lambda","caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
