INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-068', 'aws-dva', 'Um developer precisa entender quando preferir Parameter Store Advanced vs Secrets Manager. Qual diferença é decisiva?',
  '[{"id":"A","text":"Parameter Store Advanced tem rotation automática built-in para RDS"},{"id":"B","text":"Parameter Store criptografa com KMS, Secrets Manager não"},{"id":"C","text":"São idênticos"},{"id":"D","text":"Secrets Manager tem rotation automática nativa (com templates RDS/etc.) e replication cross-region; Parameter Store exige rotation custom e não tem replicação nativa"}]'::jsonb, 'D',
  '"(a) Diferenças-chave: Secrets Manager = rotation built-in com templates (RDS/Aurora/Redshift/DocumentDB) + multi-region replication + cobrança por secret. Parameter Store Advanced = parâmetros >4KB, parameter policies (expiração/notification), max 100k params + cobrança por requests; rotation precisa custom (EventBridge + Lambda). (b) Ambos criptografam SecureString/secret com KMS. (c) Regra: rotation nativa + multi-region = Secrets Manager; volume + custo baixo = Parameter Store. (d) Ver docs comparativos."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["secrets-manager","parameter-store","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
