INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-069', 'aws-dva', 'Uma API REST hospedada no API Gateway recebe tráfego de clientes web. O time exige HTTPS-only com TLS 1.2 mínimo. Como configurar?',
  '[{"id":"A","text":"Edge-optimized endpoint usa CloudFront com TLS gerenciado; para custom domain, configurar Security Policy TLS_1_2 e certificado ACM em us-east-1"},{"id":"B","text":"Configurar HTTPS no backend Lambda"},{"id":"C","text":"API Gateway só aceita HTTP"},{"id":"D","text":"Comprar certificado pago externamente"}]'::jsonb, 'A',
  '"(a) API Gateway endpoints (edge-optimized/regional) só aceitam HTTPS por design; para custom domain, configurar Security Policy (TLS_1_2 é o moderno) e usar certificado ACM público. Para edge-optimized, cert deve estar em us-east-1 (CloudFront). Para regional, na mesma região. (b) Backend interno é separado. Sempre HTTPS no GW. ACM é grátis. (c) Regra: API Gateway TLS = ACM cert + Security Policy. (d) Ver API Gateway Developer Guide + ACM."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["api-gateway","tls","acm","https"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
