INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-070', 'aws-dva', 'Uma distribuição CloudFront serve um site estático com HTTPS. O time quer usar um custom domain (www.exemplo.com.br). Onde o certificado ACM precisa estar?',
  '[{"id":"A","text":"Mesma região do bucket S3 origem"},{"id":"B","text":"us-east-1 (N. Virginia), pois CloudFront é serviço global atendido por essa região"},{"id":"C","text":"Qualquer região"},{"id":"D","text":"São Paulo (latência menor)"}]'::jsonb, 'B',
  '"(a) CloudFront só aceita certificados ACM em us-east-1, independentemente de onde estejam os origens. É exceção bem documentada. (b) Bucket pode estar em qualquer região. Não é qualquer; é us-east-1 fixo. SP não atende. (c) Regra: CloudFront cert = ACM em us-east-1 sempre. (d) Ver ACM User Guide + CloudFront Dev Guide."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["cloudfront","acm","tls","custom-domain"]'::jsonb, 'ai-draft', 'active', now(), now()
)
