INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-071', 'aws-dva', 'Uma API exige mTLS (mutual TLS) para autenticar clientes B2B com certificados. Qual recurso do API Gateway suporta?',
  '[{"id":"A","text":"API Gateway REST não suporta mTLS"},{"id":"B","text":"Lambda authorizer chamando OpenSSL"},{"id":"C","text":"Habilitar mTLS no custom domain do API Gateway com truststore (bundle de CAs) em S3"},{"id":"D","text":"API Key"}]'::jsonb, 'C',
  '"(a) API Gateway suporta mTLS em REST e HTTP APIs via custom domain — configurar truststore (PEM bundle das CAs aceitas) hosted em S3; clientes apresentam cert no handshake; API Gateway valida contra truststore. (b) Lambda authorizer roda depois do TLS; não atua na camada TLS. API Key é credencial separada. (c) Regra: mTLS = truststore no custom domain do API Gateway. (d) Ver API Gateway Developer Guide — mTLS."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["api-gateway","mtls","tls"]'::jsonb, 'ai-draft', 'active', now(), now()
)
