INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-072', 'aws-dva', 'Um ALB termina TLS para uma frota EC2 (HTTPS público → HTTP interno). Como fornecer o certificado?',
  '[{"id":"A","text":"Comprar cert externamente e fazer upload manual no IAM cert store"},{"id":"B","text":"Self-signed cert"},{"id":"C","text":"Não é possível terminar TLS no ALB"},{"id":"D","text":"Provisionar certificado público gratuito via ACM e associar ao listener HTTPS do ALB"}]'::jsonb, 'D',
  '"(a) ACM emite certificados públicos gratuitos validados por DNS/email, integrados nativamente a ALB/NLB/CloudFront/API Gateway. (b) IAM cert store é legado (usado quando ACM não atende, ex: cert externo). Self-signed quebra trust em browsers. ALB suporta nativamente termination. (c) Regra: cert público gratuito para AWS LB = ACM. (d) Ver ACM User Guide."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["alb","tls","acm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
