INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-073', 'aws-dva', 'Um time renovou manualmente um certificado ACM e quer entender o ciclo de renovação. Para um cert público com validação DNS, qual é o comportamento?',
  '[{"id":"A","text":"Renovação automática gerenciada pela ACM enquanto o registro DNS CNAME de validação permanece publicado"},{"id":"B","text":"Renovação manual obrigatória todo ano"},{"id":"C","text":"ACM não renova"},{"id":"D","text":"Renovação só por email"}]'::jsonb, 'A',
  '"(a) ACM renova automaticamente certificados públicos validados por DNS, desde que o CNAME de validação esteja publicado no DNS — sem ação manual. Email validation exige confirmação manual em cada renovação. (b) Não é manual obrigatória; ACM renova; não é só por email. (c) Regra: DNS validation = renovação automática perpétua. (d) Ver ACM User Guide — Renewal."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["acm","renewal","dns-validation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
