INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-074', 'aws-dva', 'Um developer expõe uma aplicação interna em VPC privada via API Gateway. Quer TLS end-to-end (cliente → API Gateway → backend) sem terminar TLS no LB. Qual configuração no API Gateway permite chamada HTTPS ao backend?',
  '[{"id":"A","text":"Backend integration HTTP forçado"},{"id":"B","text":"Backend integration HTTP_PROXY com URL https:// e cert válido no backend"},{"id":"C","text":"API Gateway aceita só HTTP no backend"},{"id":"D","text":"TLS é impossível em backend privado"}]'::jsonb, 'B',
  '"(a) Integration backend do API Gateway aceita URL https:// — basta o backend apresentar cert válido (público ou via VPC link com NLB). Configurar HTTPS no backend mantém TLS end-to-end. (b) HTTP no backend quebra E2E TLS. C/D estão errados — backend HTTPS é totalmente suportado. (c) Regra: TLS E2E = backend HTTPS na integration. (d) Ver API Gateway Developer Guide — Integrations."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["api-gateway","tls","backend-integration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
