INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-075', 'aws-dva', 'Um bucket S3 público foi descoberto vazando dados. O time quer garantir que nenhum bucket da conta possa ser tornado público. Qual configuração aplicar?',
  '[{"id":"A","text":"Habilitar versionamento"},{"id":"B","text":"Habilitar SSE-KMS"},{"id":"C","text":"Habilitar Block Public Access na conta inteira (account-level) — bloqueia ACLs públicas e bucket policies que dão acesso público"},{"id":"D","text":"Renomear buckets"}]'::jsonb, 'C',
  '"(a) S3 Block Public Access tem 4 settings (ACLs públicas, ACLs existentes, policies públicas, public/cross-account). Aplicado em account-level, sobrescreve qualquer bucket — nenhum bucket pode ser público. (b) Versionamento não controla exposição. SSE-KMS criptografa, mas bucket pode permanecer público. Renomear não muda permissão. (c) Regra: anti-leak = Block Public Access na conta. (d) Ver Amazon S3 User Guide — BPA."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["s3","block-public-access"]'::jsonb, 'ai-draft', 'active', now(), now()
)
