INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-076', 'aws-dva', 'Um developer precisa permitir GET temporário (1h) em um objeto S3 privado para um cliente externo, sem credenciais. Qual recurso atende?',
  '[{"id":"A","text":"Bucket policy public"},{"id":"B","text":"Habilitar BPA"},{"id":"C","text":"Trocar storage class"},{"id":"D","text":"Presigned URL para GetObject com expiração 3600s, assinada com credenciais do backend"}]'::jsonb, 'D',
  '"(a) Presigned URL embute credenciais temporárias assinadas (SigV4) na URL com expiração — cliente acessa sem AWS credenciais. Default expiração até 7 dias (com credenciais de IAM user) ou até a expiração da credencial temporária (STS). (b) Public expõe permanentemente. BPA bloqueia. Storage class é irrelevante. (c) Regra: acesso temporário a objeto privado = presigned URL. (d) Ver Amazon S3 User Guide — Presigned URLs."'::jsonb,
  'Security', 'Security', 'easy', 'scenario', '["s3","presigned-url"]'::jsonb, 'ai-draft', 'active', now(), now()
)
