INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-077', 'aws-dva', 'Um time precisa criptografar objetos S3 com chave gerenciada pelo cliente, sem que a AWS conheça a chave. Qual opção SSE atende?',
  '[{"id":"A","text":"SSE-C (Customer-Provided Keys) — cliente envia a chave em cada PUT/GET; AWS criptografa em memória e descarta a chave"},{"id":"B","text":"SSE-S3 (chaves AWS gerenciadas)"},{"id":"C","text":"SSE-KMS"},{"id":"D","text":"Nenhuma"}]'::jsonb, 'A',
  '"(a) SSE-C: cliente provê a chave AES-256 (x-amz-server-side-encryption-customer-key) em cada request; S3 usa para criptografar/decifrar e descarta — AWS nunca armazena. Cliente é responsável por reter a chave. (b) SSE-S3 e SSE-KMS = AWS gerencia (no caso de KMS, com auditoria via CloudTrail). (c) Regra: chave exclusivamente do cliente = SSE-C. (d) Ver Amazon S3 User Guide — Encryption."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["s3","sse-c","encryption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
