INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-078', 'aws-dva', 'Uma bucket policy permite GetObject para *. Block Public Access da conta está habilitado com ''IgnorePublicAcls=true'' apenas. O bucket ainda é público?',
  '[{"id":"A","text":"Não, BPA bloqueia tudo"},{"id":"B","text":"Sim, IgnorePublicAcls só afeta ACLs; para bloquear bucket policy public, precisa ''BlockPublicPolicy=true'' ou ''RestrictPublicBuckets=true''"},{"id":"C","text":"Depende do storage class"},{"id":"D","text":"Erro de configuração"}]'::jsonb, 'B',
  '"(a) BPA tem 4 toggles independentes: BlockPublicAcls (novas), IgnorePublicAcls (existentes), BlockPublicPolicy (novas), RestrictPublicBuckets (existentes). Para fechar bucket policy public, ativar BlockPublicPolicy ou RestrictPublicBuckets. (b) Não é tudo-ou-nada. Storage class irrelevante. Config válida mas insuficiente. (c) Regra: BPA = 4 controles distintos; ler cada um. (d) Ver Amazon S3 User Guide — BPA."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["s3","block-public-access","bucket-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
