INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-079', 'aws-dva', 'Uma presigned URL gerada por um IAM user com S3 access foi vazada. Como invalidar imediatamente?',
  '[{"id":"A","text":"Aguardar a expiração"},{"id":"B","text":"Habilitar BPA"},{"id":"C","text":"Rotacionar/revogar as credenciais do IAM user que assinou a URL (ou remover a permissão s3:GetObject)"},{"id":"D","text":"Trocar o nome do bucket"}]'::jsonb, 'C',
  '"(a) Presigned URL é assinada com credenciais; se as credenciais forem revogadas/rotacionadas (delete access key, remover permissão na policy), a assinatura para de ser válida imediatamente. Esperar expiração deixa janela aberta. (b) BPA bloqueia public mas presigned é autenticada — não bloqueia. Renomear bucket é destrutivo. (c) Regra: revogar presigned = revogar credencial signer. (d) Ver Amazon S3 User Guide."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["s3","presigned-url","credentials"]'::jsonb, 'ai-draft', 'active', now(), now()
)
