INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-080', 'aws-dva', 'Um SDK chama S3 PutObject com SigV4 mas falha em ClockSkew. Qual é a causa?',
  '[{"id":"A","text":"Falta MFA"},{"id":"B","text":"Bucket não existe"},{"id":"C","text":"Region errada"},{"id":"D","text":"Relógio da máquina cliente fora de sincronismo com o servidor (\u003e15min de drift quebra a assinatura SigV4)"}]'::jsonb, 'D',
  '"(a) SigV4 inclui timestamp na assinatura; AWS rejeita requests com clock drift >15 minutos para mitigar replay. Sincronizar via NTP resolve. (b) MFA não relacionado. Bucket missing daria NoSuchBucket. Region daria endpoint error. (c) Regra: SigV4 = clock skew sensitive; sempre rodar NTP. (d) Ver Amazon S3 User Guide — Signature."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["s3","sigv4","clock-skew"]'::jsonb, 'ai-draft', 'active', now(), now()
)
