INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-081', 'aws-dva', 'Um bucket criptografa objetos com SSE-KMS via CMK customer-managed. Para reduzir chamadas KMS (cobrança e throttling) em alto volume de PUT/GET, qual feature ativar?',
  '[{"id":"A","text":"S3 Bucket Keys — usa uma data key cacheada no bucket para criptografar múltiplos objetos, reduzindo chamadas KMS GenerateDataKey"},{"id":"B","text":"Versionamento"},{"id":"C","text":"Transfer Acceleration"},{"id":"D","text":"Cross-region replication"}]'::jsonb, 'A',
  '"(a) S3 Bucket Keys gera uma data key no bucket-level cacheada por período curto; objetos no bucket usam essa key derivada (em vez de chamar KMS GenerateDataKey por objeto), reduzindo até 99% custo KMS e mitigando throttling. (b) Versionamento, Transfer Acceleration, CRR são features ortogonais. (c) Regra: SSE-KMS volume alto = Bucket Keys. (d) Ver Amazon S3 User Guide — Bucket Keys."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["s3","sse-kms","bucket-keys"]'::jsonb, 'ai-draft', 'active', now(), now()
)
