INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-082', 'aws-dva', 'Um time precisa proteger uma API REST do API Gateway exigindo JWT do Cognito User Pool, sem rodar Lambda authorizer. Qual recurso atende?',
  '[{"id":"A","text":"API Keys"},{"id":"B","text":"Configurar Cognito User Pool Authorizer na rota; cliente envia JWT no header Authorization"},{"id":"C","text":"IAM_AUTH"},{"id":"D","text":"Resource policy IP-based"}]'::jsonb, 'B',
  '"(a) Cognito Authorizer nativo do API Gateway valida JWT contra o User Pool configurado, sem custo de Lambda. Configurar IdentitySource (default ''method.request.header.Authorization'') e os IDs do pool/client. (b) API Keys = identificação/usage plan, não autenticação. IAM_AUTH usa SigV4 (não JWT). Resource policy é network-level. (c) Regra: JWT Cognito + API Gateway = Cognito Authorizer. (d) Ver API Gateway Developer Guide."'::jsonb,
  'Security', 'Security', 'easy', 'scenario', '["api-gateway","cognito","authorizer"]'::jsonb, 'ai-draft', 'active', now(), now()
)
