INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-083', 'aws-dva', 'Uma API precisa autenticar via JWT custom (não Cognito) emitido por Auth0. Qual mecanismo do API Gateway é apropriado?',
  '[{"id":"A","text":"Cognito Authorizer"},{"id":"B","text":"API Keys"},{"id":"C","text":"Lambda Authorizer (tipo TOKEN) que valida o JWT Auth0 e retorna IAM policy; ou JWT Authorizer (HTTP API)"},{"id":"D","text":"Resource policy"}]'::jsonb, 'C',
  '"(a) Lambda Authorizer TOKEN recebe o token no header, valida (signature, exp, audience contra JWKS Auth0) e retorna policy IAM Allow/Deny + context. HTTP APIs (v2) têm JWT Authorizer nativo configurável com issuer/audience, sem Lambda. (b) Cognito Authorizer só aceita Cognito. API Keys não autentica. Resource policy é network. (c) Regra: JWT externo em REST API = Lambda Authorizer; em HTTP API = JWT Authorizer nativo. (d) Ver API Gateway Dev Guide."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["api-gateway","lambda-authorizer","jwt"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
