INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-084', 'aws-dva', 'Um Lambda authorizer tipo REQUEST recebe headers, query string e contexto da request. Qual vantagem sobre tipo TOKEN?',
  '[{"id":"A","text":"Apenas TOKEN suporta cache"},{"id":"B","text":"REQUEST sempre é mais rápido"},{"id":"C","text":"São idênticos"},{"id":"D","text":"REQUEST permite autorizar baseado em múltiplos parâmetros (IP, query, body indirect via context, multiple headers); TOKEN só lê um header"}]'::jsonb, 'D',
  '"(a) Lambda Authorizer REQUEST recebe identitySource configurável (headers, query params, stage vars, context) — útil para auth multi-fator (ex: API key + IP allowlist). TOKEN só lê um header (geralmente Authorization). Ambos suportam cache. (b) Cache existe em ambos. Performance similar. Não são idênticos. (c) Regra: TOKEN = simples header JWT; REQUEST = lógica composta. (d) Ver API Gateway Dev Guide."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["api-gateway","lambda-authorizer","request"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
