INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-085', 'aws-dva', 'Uma API interna deve ser chamada apenas por outras roles AWS da conta. Qual método de autorização do API Gateway é mais simples?',
  '[{"id":"A","text":"AWS_IAM authorization — cliente assina request com SigV4 usando role/credenciais AWS"},{"id":"B","text":"Lambda Authorizer custom"},{"id":"C","text":"API Keys"},{"id":"D","text":"JWT custom"}]'::jsonb, 'A',
  '"(a) AWS_IAM (METHOD authorization) exige que o caller assine a request com SigV4 — IAM policy do caller deve conceder execute-api:Invoke no ARN do método. Ideal para integrações service-to-service AWS sem dependência de JWT. (b) Lambda Authorizer adiciona código/latência. API Keys = identificação. JWT exige IdP. (c) Regra: service-to-service AWS = AWS_IAM (SigV4). (d) Ver API Gateway Dev Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["api-gateway","iam-auth","sigv4"]'::jsonb, 'ai-draft', 'active', now(), now()
)
