INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-086', 'aws-dva', 'Um time quer impor limite de 1000 requests/dia por cliente em uma API pública. Qual recurso atende?',
  '[{"id":"A","text":"Lambda Authorizer com contador em DynamoDB"},{"id":"B","text":"API Keys + Usage Plan com throttle e quota associado a cada chave"},{"id":"C","text":"Cognito Authorizer"},{"id":"D","text":"Resource policy"}]'::jsonb, 'B',
  '"(a) Usage Plans + API Keys: criar API Key por cliente, associar a Usage Plan com Quota (1000/day) e Throttle (rate/burst). API Gateway aplica nativamente — sem código. (b) Lambda custom é reinventar a roda. Cognito autentica, não rate-limita. Resource policy é network. (c) Regra: per-client quota/throttle = API Keys + Usage Plan. (d) Ver API Gateway Dev Guide — Usage plans."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["api-gateway","api-keys","usage-plan"]'::jsonb, 'ai-draft', 'active', now(), now()
)
