INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-087', 'aws-dva', 'Uma API REST deve só ser acessível de IPs corporativos. Qual recurso aplica?',
  '[{"id":"A","text":"Bucket policy"},{"id":"B","text":"Cognito group"},{"id":"C","text":"Resource policy do API Gateway com Condition aws:SourceIp"},{"id":"D","text":"Security group"}]'::jsonb, 'C',
  '"(a) Resource policy é anexada à API REST e avaliada na camada de network/policy do API Gateway — permite Allow/Deny baseado em aws:SourceIp, aws:SourceVpce, principais AWS. (b) Bucket policy é S3. Cognito group é autorização lógica, não IP. Security group não se aplica a API Gateway (managed service). (c) Regra: IP allowlist em API GW = Resource Policy. (d) Ver API Gateway Dev Guide."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["api-gateway","resource-policy","ip-allowlist"]'::jsonb, 'ai-draft', 'active', now(), now()
)
