INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-088', 'aws-dva', 'Uma Lambda authorizer está cacheada por 300s. Após mudar a policy no backend, clientes válidos ainda recebem Deny por 5 minutos. Qual ação resolve?',
  '[{"id":"A","text":"Reiniciar API Gateway"},{"id":"B","text":"Aumentar memory do Lambda"},{"id":"C","text":"Trocar de region"},{"id":"D","text":"Reduzir TTL do authorizer cache (ou desabilitar) e/ou variar o identitySource para invalidar"}]'::jsonb, 'D',
  '"(a) Authorizer Result Caching armazena a policy retornada por TTL (até 3600s) usando identitySource como chave. Para invalidar mais rápido, reduzir TTL ou trocar identitySource (forçar miss). Em produção, balancear performance vs latência de propagação. (b) Sem ''restart'' em managed service. Memory não relaciona. Region é destrutivo. (c) Regra: cache do authorizer = TTL configurável; tradeoff perf vs frescor. (d) Ver API Gateway Dev Guide."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["api-gateway","lambda-authorizer","caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
