INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-089', 'aws-dva', 'Uma cliente API envia Authorization: Bearer <JWT> mas o API Gateway com Cognito Authorizer rejeita com 401. CloudWatch mostra ''Unauthorized''. Quais checks?',
  '[{"id":"A","text":"Verificar: token expirado (exp); audience (aud) bate com client_id configurado; assinatura válida contra JWKS do pool; identitySource correto"},{"id":"B","text":"Mudar IAM role"},{"id":"C","text":"Reiniciar API Gateway"},{"id":"D","text":"Bucket policy"}]'::jsonb, 'A',
  '"(a) Erros 401 com Cognito Authorizer: (1) JWT expirado (Access Token 1h default), (2) audience/issuer mismatch (cliente errado ou pool errado), (3) header name diferente do identitySource, (4) signature inválida (token de outro pool). Logs do API Gateway/Cognito ajudam isolar. (b) IAM role não atua. Restart não existe. Bucket policy não. (c) Regra: 401 = sempre validar exp/aud/iss/signature/headerName. (d) Ver Cognito Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["api-gateway","cognito","jwt","401"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
