INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-090', 'aws-dva', 'Um site distribuído via CloudFront serve conteúdo premium que só pode ser visto por assinantes. Qual recurso restringe acesso a URLs assinadas?',
  '[{"id":"A","text":"Bucket policy public"},{"id":"B","text":"Trusted Key Groups + signed URLs (ou signed cookies) com private key armazenada no backend"},{"id":"C","text":"WAF rate limit"},{"id":"D","text":"Auto-scaling group"}]'::jsonb, 'B',
  '"(a) CloudFront restringe distribuição por behavior com Trusted Key Groups; backend gera signed URL ou signed cookie com private key (RSA) — cliente sem URL/cookie válido recebe 403. Signed URLs = um asset; signed cookies = sessão de múltiplos. (b) Bucket public abre acesso direto burlando CF. WAF é defesa de aplicação. ASG não controla acesso. (c) Regra: acesso pago a CF = Trusted Key Groups + signed URL/cookie. (d) Ver CloudFront Dev Guide."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cloudfront","signed-url","trusted-key-groups"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
