INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-091', 'aws-dva', 'Um time precisa restringir acesso ao bucket S3 origin do CloudFront para que ninguém acesse direto via URL S3 (somente via CF). Qual recurso recomendado em 2026?',
  '[{"id":"A","text":"Origin Access Identity (OAI) — legado"},{"id":"B","text":"Block Public Access apenas"},{"id":"C","text":"Origin Access Control (OAC) — recomendado, suporta SSE-KMS e SigV4"},{"id":"D","text":"Presigned URL"}]'::jsonb, 'C',
  '"(a) OAC é a evolução do OAI: suporta SigV4 (necessário para SSE-KMS), todas as regions e novos serviços. AWS recomenda migrar de OAI para OAC; OAI ainda funciona mas é legado. (b) BPA sozinho bloqueia tudo, inclusive CF. Presigned URL é outro mecanismo de acesso individual. (c) Regra: 2026 = OAC; legado = OAI. (d) Ver CloudFront Dev Guide — OAC."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["cloudfront","oac","oai","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
