INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-092', 'aws-dva', 'Quando preferir signed cookies em vez de signed URLs no CloudFront?',
  '[{"id":"A","text":"Para um único arquivo grande"},{"id":"B","text":"Apenas para imagens"},{"id":"C","text":"Sempre são intercambiáveis"},{"id":"D","text":"Quando precisa autorizar acesso a múltiplos arquivos/sessão de streaming sem reescrever cada URL no HTML"}]'::jsonb, 'D',
  '"(a) Signed cookies são ideais quando o cliente precisa acessar muitos assets (HLS playlist com centenas de segmentos, área logada com múltiplas imagens) — cookie é enviado automaticamente em todas as requests subsequentes. Signed URL é único arquivo. (b) Para um arquivo apenas, signed URL é mais simples. Não são intercambiáveis em UX. (c) Regra: 1 arquivo = URL; sessão multi-arquivos = cookies. (d) Ver CloudFront Dev Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["cloudfront","signed-cookies","signed-url"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
