INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-093', 'aws-dva', 'Em uma distribuição CloudFront com signed URLs usando Trusted Key Groups, como rotacionar a chave de assinatura sem downtime?',
  '[{"id":"A","text":"Adicionar nova public key à Key Group, distribuir backend gerando URLs assinadas com nova private key; após período de overlap, remover key antiga"},{"id":"B","text":"Forçar logoff de todos usuários"},{"id":"C","text":"Trocar a região"},{"id":"D","text":"Impossível sem downtime"}]'::jsonb, 'A',
  '"(a) Key Groups suportam múltiplas public keys simultaneamente — CloudFront aceita URLs assinadas com qualquer uma. Padrão: adicionar nova key, migrar geração de URLs no backend para nova private key, manter overlap durante a validade das URLs antigas, depois remover a key antiga. (b) Logoff é UX ruim. Region não relaciona. É possível sem downtime. (c) Regra: rotation = overlap nas Key Groups. (d) Ver CloudFront Dev Guide."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["cloudfront","trusted-key-groups","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
