INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-094', 'aws-dva', 'Um developer encontrou credenciais AWS hardcoded em um repo GitHub público. Quais ações imediatas tomar?',
  '[{"id":"A","text":"Deletar o commit e ignorar"},{"id":"B","text":"Revogar/rotacionar as keys imediatamente no IAM; auditar CloudTrail por uso indevido; usar git-filter-repo para purgar histórico; refazer commits sem credenciais"},{"id":"C","text":"Mudar de provider de DVCS"},{"id":"D","text":"Aguardar suporte AWS contatar"}]'::jsonb, 'B',
  '"(a) Mesmo deletando o commit, histórico Git mantém — bots de scrap pegam em minutos. Resposta: (1) DesactivateKey/DeleteAccessKey, (2) CloudTrail event lookup pela AKID por uso suspeito, (3) reescrever histórico, (4) revisar políticas para nunca usar long-lived keys, migrar para roles. (b) Trocar de DVCS não resolve histórico já scraping''ed. AWS Support pode notificar mas a primeira ação é do dono. (c) Regra: credencial vazada = revogar imediatamente + audit. (d) Ver IAM User Guide."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["iam","credentials","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()
)
