INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-095', 'aws-dva', 'Uma Lambda usa AWS SDK para escrever em DynamoDB. O time quer garantir que credenciais nunca apareçam em código, env vars ou logs. Qual padrão usar?',
  '[{"id":"A","text":"Hardcode em arquivo .env criptografado"},{"id":"B","text":"Env var AWS_ACCESS_KEY_ID na config da Lambda"},{"id":"C","text":"Confiar exclusivamente na execution role: SDK resolve automaticamente via container credentials provider; nenhuma env var de credencial é definida"},{"id":"D","text":"Logar AKID para debug"}]'::jsonb, 'C',
  '"(a) SDK AWS resolve credenciais via cadeia padrão: env vars → shared credentials → container credentials (ECS/Lambda) → instance profile. Lambda injeta vars temporárias via runtime; basta o SDK seguir o default. Não definir env var de credencial nem logar AKID. (b) .env criptografado ainda materializa a chave. AWS_ACCESS_KEY_ID custom quebra resolver. Logar AKID é vazamento. (c) Regra: aplicação AWS = role + SDK default resolver. (d) Ver IAM User Guide."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["iam","credentials","lambda","application-security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
