INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-096', 'aws-dva', 'Um service em EC2 precisa armazenar uma API key de terceiros (Stripe). Qual abordagem é mais segura?',
  '[{"id":"A","text":"Hardcode no código fonte"},{"id":"B","text":"Variável de ambiente shell exportada manualmente"},{"id":"C","text":"Arquivo .txt no /tmp"},{"id":"D","text":"Secrets Manager (com rotation se Stripe suportar) ou SSM Parameter Store SecureString, lido em runtime via SDK com permissão IAM na role da EC2"}]'::jsonb, 'D',
  '"(a) Secrets Manager (rotation, audit) ou Parameter Store SecureString (custo zero) — armazenam criptografados com KMS, accessíveis via IAM role da EC2; nada material em disco/código. (b) Hardcode é commit de credencial. Shell env perde no restart e é visível em ps. .txt em /tmp é exposição em disco. (c) Regra: API key de terceiro = Secrets Manager ou Parameter Store SecureString. (d) Ver Secrets Manager / SSM Guides."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["secrets-manager","parameter-store","api-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
