INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-097', 'aws-dva', 'Um developer recebe input do usuário e usa em uma query SQL contra RDS. Que prática previne SQL injection?',
  '[{"id":"A","text":"Usar prepared statements / parameterized queries no driver/ORM; validar input com whitelist quando possível"},{"id":"B","text":"Concatenar strings com escape manual"},{"id":"C","text":"Habilitar SSE-KMS no RDS"},{"id":"D","text":"Adicionar WAF rule no API Gateway apenas"}]'::jsonb, 'A',
  '"(a) Prepared statements separam código SQL de dados — driver envia query template + parâmetros independentemente; injeção não é parseada como código. Escape manual é frágil. (b) SSE-KMS criptografa at-rest, irrelevante para SQLi. WAF é defesa adicional, não substitui código seguro. (c) Regra: SQLi = prepared statements + input validation no app. (d) OWASP Top 10."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["application-security","sql-injection","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
