INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-098', 'aws-dva', 'Uma Lambda criptografa PII antes de gravar no DynamoDB usando KMS Encrypt. O dado é pequeno (~500 bytes). É correto chamar KMS Encrypt direto sem envelope encryption?',
  '[{"id":"A","text":"Não, sempre envelope encryption"},{"id":"B","text":"Sim, para dados \u003c4KB; envelope encryption é overhead desnecessário; usar Encrypt/Decrypt com EncryptionContext para audit binding"},{"id":"C","text":"Não, KMS não suporta dados pequenos"},{"id":"D","text":"Apenas com SSE-KMS no DynamoDB"}]'::jsonb, 'B',
  '"(a) KMS Encrypt aceita até 4KB plaintext — para campos pequenos (PII, tokens), chamada direta é simples e adequada; EncryptionContext oferece audit/binding ao registro. Envelope é necessário só para volumes maiores. (b) KMS suporta sim dados pequenos. SSE-KMS no DynamoDB criptografa toda tabela; ortogonal a criptografar campo específico. (c) Regra: <4KB = Encrypt direto OK; >4KB = envelope. (d) Ver KMS Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["kms","encrypt","pii","application-security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
