INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-099', 'aws-dva', 'Um time tem credenciais de OAuth client_secret expostas via variável de ambiente Lambda em texto plano (visíveis na console). Qual mitigação aplicar?',
  '[{"id":"A","text":"Ignorar; é interno"},{"id":"B","text":"Renomear a variável"},{"id":"C","text":"Habilitar Lambda environment variable encryption with KMS customer-managed key (helpers visualization disabled) ou ler de Secrets Manager no runtime"},{"id":"D","text":"Aumentar timeout"}]'::jsonb, 'C',
  '"(a) Lambda env vars são criptografadas at-rest com KMS (default aws/lambda); usar CMK customer-managed permite restringir Decrypt por IAM (ex: só execution role pode descriptografar, console operators não). Melhor ainda: armazenar em Secrets Manager e ler em runtime — segredo nunca aparece na config visível. (b) Ignorar viola compliance. Renomear não esconde. Timeout não relaciona. (c) Regra: secrets em Lambda env = CMK + IAM restrito, ou Secrets Manager runtime. (d) Ver Lambda + KMS guides."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["lambda","kms","secrets-manager","application-security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
