INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-100', 'aws-dva', 'Um developer monta um sistema onde uploads em S3 disparam Lambda que criptografa o conteúdo com CMK customer-managed e regrava em outro bucket. Qual conjunto mínimo de permissões a execution role precisa?',
  '[{"id":"A","text":"Apenas s3:*"},{"id":"B","text":"AdministratorAccess"},{"id":"C","text":"Apenas kms:*"},{"id":"D","text":"s3:GetObject (bucket origem), s3:PutObject (bucket destino), kms:GenerateDataKey + kms:Decrypt na CMK (com key policy permitindo a role), logs:* para CloudWatch"}]'::jsonb, 'D',
  '"(a) Least privilege: ações específicas no resource correto. Get no origem, Put no destino, GenerateDataKey (encrypt) + Decrypt (caso reencrypt) na CMK, CloudWatch Logs para observability. Não esquecer key policy autorizando a role. (b) s3:* e Administrator violam least privilege. kms:* sozinho não dá S3 access. (c) Regra: design = lista exata de actions × resources × condições; key policy KMS sempre necessária. (d) Ver IAM + KMS + S3 guides."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["iam","kms","s3","least-privilege"]'::jsonb, 'ai-draft', 'active', now(), now()
)
