INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-101', 'aws-dva', 'Uma SaaS multi-tenant permite que clientes (cada um numa conta AWS própria) acessem dados via cross-account role. Para mitigar o problema do confused deputy, o time pediu que cada cliente forneça um External ID único usado no AssumeRole. Onde esse External ID deve ser validado?',
  '[{"id":"A","text":"Como condição sts:ExternalId na trust policy da role do cliente"},{"id":"B","text":"Na permission policy da role do cliente"},{"id":"C","text":"Como header HTTP custom no SDK chamador"},{"id":"D","text":"Como tag de sessão no ABAC"}]'::jsonb, 'A',
  '"(a) External ID é uma condition key sts:ExternalId que vai na trust policy da role do cliente; só quem souber o valor combinado consegue assumir, evitando que um terceiro malicioso confunda o deputy (SaaS). (b) Permission policy define o que a role faz, não quem assume; header HTTP é client-side e não autoriza nada no IAM; tags de sessão servem para ABAC, propósito distinto. (c) Regra: confused deputy = External ID em Condition da trust policy. (d) Ver STS APIReference — AssumeRole ExternalId."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["sts","external-id","confused-deputy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
