INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-102', 'aws-dva', 'Um developer precisa que usuários só possam fazer AssumeRole para uma role administrativa se autenticarem com MFA presente na sessão atual. Como expressar isso na trust policy da role-alvo?',
  '[{"id":"A","text":"Habilitar MFA Delete no bucket S3 associado"},{"id":"B","text":"Adicionar Condition: { Bool: { aws:MultiFactorAuthPresent: \"true\" } } na trust policy"},{"id":"C","text":"Configurar sts:GetSessionToken com SerialNumber obrigatório"},{"id":"D","text":"Adicionar Action sts:AssumeRoleWithMFA na trust policy"},{"id":"E","text":"Não é possível impor MFA em AssumeRole"}]'::jsonb, 'B',
  '"(a) A condition key global aws:MultiFactorAuthPresent é avaliada quando o caller já autenticou com MFA (via console ou GetSessionToken com TOTP); colocá-la na trust policy bloqueia AssumeRole sem MFA na sessão. (b) MFA Delete é específico de versionamento S3; sts:AssumeRoleWithMFA não existe como Action; GetSessionToken obtém creds temporárias mas não impõe MFA em quem assume. (c) Regra: MFA enforcement = Condition global na policy de trust ou identity. (d) Ver IAM User Guide — Configuring MFA-protected API access."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["sts","mfa","trust-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
