INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-103', 'aws-dva', 'Um workflow chama AssumeRole e recebe credenciais válidas, mas a chamada subsequente s3:GetObject falha com AccessDenied — apesar da role-alvo ter S3FullAccess. O developer notou que passou um inline session policy no AssumeRole. Qual é a causa provável?',
  '[{"id":"A","text":"Session policy só pode expandir permissões da role"},{"id":"B","text":"Inline session policy é ignorada quando há managed policy anexada"},{"id":"C","text":"Session policy faz interseção com a permission policy da role e pode reduzir o acesso efetivo"},{"id":"D","text":"Session policies só funcionam para SAML federations"}]'::jsonb, 'C',
  '"(a) Session policies (parâmetro Policy/PolicyArns no AssumeRole) funcionam como filtro: o acesso efetivo é a interseção das permissions da role com a session policy. Se a session policy não inclui s3:GetObject, o acesso é negado mesmo com S3FullAccess na role. (b) Session policy nunca expande permissões; não é ignorada por managed policies; funciona para qualquer caller do AssumeRole. (c) Regra: session policy = filtro restritivo, nunca expansor — útil para delegação temporária de subset. (d) Ver STS APIReference — Session policies."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["sts","session-policy","assume-role"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
