INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-104', 'aws-dva', 'Uma empresa usa um IdP corporativo SAML 2.0. O developer quer mapear o atributo SAML ''Department'' para uma IAM role específica via AssumeRoleWithSAML. Qual atributo SAML a AWS espera receber para selecionar a role?',
  '[{"id":"A","text":"Um atributo customizado chamado ''aws:Role''"},{"id":"B","text":"Department como SAML NameID"},{"id":"C","text":"Um Bearer Token JWT no assertion"},{"id":"D","text":"https://aws.amazon.com/SAML/Attributes/Role com valor ''role_arn,provider_arn''"}]'::jsonb, 'D',
  '"(a) AWS exige um atributo SAML específico — https://aws.amazon.com/SAML/Attributes/Role — cujo valor é uma string CSV ''arn:aws:iam::ACCT:role/Name,arn:aws:iam::ACCT:saml-provider/Provider''. Pode haver múltiplas entradas, e o usuário escolhe qual assumir. (b) Não existe atributo ''aws:Role'' padrão; NameID identifica o usuário (mapeia para RoleSessionName via outro attribute); JWT é OIDC, não SAML. (c) Regra: AssumeRoleWithSAML usa attribute Role no formato ''roleARN,providerARN''. (d) Ver STS APIReference — AssumeRoleWithSAML + IAM SAML claim mapping."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["sts","saml","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
