INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-105', 'aws-dva', 'Uma role A assume a role B (cross-account). Em B, o código tenta novamente AssumeRole na role C — mas falha com ''cannot call AssumeRole from an assumed-role with role chaining if duration exceeds 1 hour''. Por quê?',
  '[{"id":"A","text":"Role chaining tem limite máximo de 1 hora de duração, independente do MaxSessionDuration da role"},{"id":"B","text":"AssumeRole não pode ser chamado por sessões assumidas"},{"id":"C","text":"Cross-account exige sempre MFA"},{"id":"D","text":"C precisa ter External ID configurado"}]'::jsonb, 'A',
  '"(a) Quando se faz role chaining (assumed-role chamando AssumeRole em outra role), o STS limita o DurationSeconds máximo a 3600s, mesmo se a role-alvo tem MaxSessionDuration maior. É uma proteção contra escalonamento prolongado. (b) AssumeRole pode ser chamado por sessões assumidas — o limite é só de duração; MFA não é exigido cross-account por default; External ID é específico de confused deputy. (c) Regra: chaining → DurationSeconds ≤ 3600. (d) Ver STS APIReference — Role chaining limits."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["sts","role-chaining","duration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
