INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-106', 'aws-dva', 'Um developer está debugando AssumeRole e quer saber qual identidade efetiva o caller tem após assumir a role — para auditoria. Qual API STS retorna a identidade da sessão atual (Arn da role assumida + RoleSessionName)?',
  '[{"id":"A","text":"sts:GetSessionToken"},{"id":"B","text":"sts:GetCallerIdentity"},{"id":"C","text":"iam:GetUser"},{"id":"D","text":"iam:GetRole"}]'::jsonb, 'B',
  '"(a) GetCallerIdentity é a forma canônica de obter a identidade efetiva do caller — retorna UserId, Account e Arn. Para uma assumed-role, Arn vem como ''arn:aws:sts::ACCT:assumed-role/RoleName/SessionName''. É também a forma mais confiável de provar identidade em scripts (sem permissão necessária). (b) GetSessionToken obtém creds temporárias com MFA, não retorna identidade; iam:GetUser falha se caller é assumed-role; iam:GetRole exige permissão. (c) Regra: ''quem sou eu agora?'' = sts:GetCallerIdentity. (d) Ver STS APIReference — GetCallerIdentity."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["sts","get-caller-identity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
