INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-107', 'aws-dva', 'Um Cognito User Pool autentica usuários via username/senha. O developer quer normalizar o email para lowercase antes de armazenar no pool e bloquear domínios @example.com. Qual Lambda trigger é o ponto correto para aplicar essa lógica?',
  '[{"id":"A","text":"Post Authentication trigger"},{"id":"B","text":"Custom Message trigger"},{"id":"C","text":"Pre Sign-up trigger"},{"id":"D","text":"User Migration trigger"}]'::jsonb, 'C',
  '"(a) Pre Sign-up roda antes do Cognito persistir o usuário — é onde se valida domínio (rejeitar via throw) e normaliza atributos (mutate event.request.userAttributes.email). Pode também auto-confirmar o usuário. (b) Post Auth roda após login bem-sucedido (tarde demais para bloquear sign-up); Custom Message customiza emails/SMS; User Migration importa usuários de IdP legado. (c) Regra: validação/normalização no momento do cadastro = Pre Sign-up. (d) Ver Cognito Developer Guide — User pool Lambda triggers."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito","cognito-trigger","pre-signup"]'::jsonb, 'ai-draft', 'active', now(), now()
)
