INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-108', 'aws-dva', 'Um app SaaS precisa que o ID token emitido pelo Cognito contenha claims customizadas — incluindo o tenant_id do usuário (lido de uma tabela DynamoDB). Qual Lambda trigger permite enriquecer o token antes da emissão?',
  '[{"id":"A","text":"Pre Authentication trigger"},{"id":"B","text":"Define Auth Challenge trigger"},{"id":"C","text":"Verify Auth Challenge Response trigger"},{"id":"D","text":"Pre Token Generation trigger"}]'::jsonb, 'D',
  '"(a) Pre Token Generation é executada após autenticação válida e antes da emissão do ID/Access token; o handler retorna claimsOverrideDetails permitindo adicionar/modificar/remover claims. Aqui se busca o tenant_id no DynamoDB e injeta como claim. (b) Pre Auth valida credenciais (cedo demais para claims); Define/Verify Challenge são do custom auth flow (challenge-response). (c) Regra: customizar conteúdo do token = Pre Token Generation. (d) Ver Cognito Developer Guide — Pre token generation Lambda trigger."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito","cognito-trigger","pre-token-generation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
