INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-109', 'aws-dva', 'Um sistema migra usuários de um banco legado para Cognito. O time não quer pedir reset de senha — quer migrar o usuário no primeiro login bem-sucedido contra o sistema antigo. Qual trigger orquestra esse fluxo?',
  '[{"id":"A","text":"User Migration trigger (Migrate User)"},{"id":"B","text":"Pre Sign-up trigger"},{"id":"C","text":"Custom Message trigger"},{"id":"D","text":"Post Confirmation trigger"}]'::jsonb, 'A',
  '"(a) User Migration trigger é chamado quando o user não existe no pool: Cognito repassa o login para a Lambda, que valida contra o sistema legado e retorna os atributos; o Cognito então cria o usuário transparentemente — sem reset de senha. Funciona com USER_PASSWORD_AUTH ou ADMIN_USER_PASSWORD_AUTH. (b) Pre Sign-up é para fluxo de cadastro novo; Custom Message customiza emails; Post Confirmation roda após confirmação de email/SMS. (c) Regra: migração transparente de senha = User Migration trigger. (d) Ver Cognito Developer Guide — Migrate user Lambda trigger."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito","cognito-trigger","user-migration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
