INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-110', 'aws-dva', 'Um developer implementa um custom auth flow (passwordless via OTP por email). Quais 3 Lambda triggers compõem o ciclo challenge-response do Cognito custom flow?',
  '[{"id":"A","text":"Pre Sign-up, Post Confirmation, Pre Auth"},{"id":"B","text":"Define Auth Challenge, Create Auth Challenge, Verify Auth Challenge Response"},{"id":"C","text":"Pre Token Generation, Post Auth, Custom Message"},{"id":"D","text":"User Migration, Pre Auth, Post Auth"}]'::jsonb, 'B',
  '"(a) O custom auth flow do Cognito orquestra 3 triggers: Define decide qual challenge enviar (ou aprovar/negar); Create gera o conteúdo do challenge (ex: OTP + envia via SES); Verify valida a resposta do usuário. Cognito itera Define→Create→Verify até issueTokens=true ou failAuthentication=true. (b) Pre Sign-up/Post Conf são do fluxo de cadastro; Pre Token Gen modifica tokens; User Migration é para import legado. (c) Regra: passwordless/MFA custom = trio Define/Create/Verify. (d) Ver Cognito Developer Guide — Custom authentication flow."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito","cognito-trigger","custom-auth"]'::jsonb, 'ai-draft', 'active', now(), now()
)
