INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-111', 'aws-dva', 'Em um Cognito Identity Pool com Google federation, um usuário autenticado recebe credenciais AWS para chamar S3. O developer quer que cada usuário só leia objetos no prefixo cognito/${cognito-identity.amazonaws.com:sub}/. Onde a substituição da variável acontece?',
  '[{"id":"A","text":"Na bucket policy do S3, hard-coded por usuário"},{"id":"B","text":"No SDK do cliente, montando o ARN dinamicamente"},{"id":"C","text":"Na IAM policy da role autenticada do Identity Pool, usando policy variables com sub do Cognito Identity"},{"id":"D","text":"Na trust policy da role"}]'::jsonb, 'C',
  '"(a) Policy variables — como ${cognito-identity.amazonaws.com:sub} — são substituídas em runtime pelo IAM durante a avaliação da policy da role autenticada. Permitem isolamento por usuário sem criar uma role por usuário. (b) Bucket policy hard-coded não escala; SDK montar ARN não impõe segurança (cliente pode forjar); trust policy define quem assume, não o que pode fazer. (c) Regra: isolamento per-user em Identity Pool = policy variables no Resource. (d) Ver Cognito Developer Guide — IAM roles and policy variables."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito","identity-pool","policy-variables"]'::jsonb, 'ai-draft', 'active', now(), now()
)
