INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-112', 'aws-dva', 'Um SPA usa Cognito Hosted UI com Authorization Code Grant + PKCE. Após receber o authorization code, qual endpoint o SPA chama para trocar pelo ID/Access/Refresh tokens?',
  '[{"id":"A","text":"/oauth2/authorize com response_type=code"},{"id":"B","text":"/oauth2/userInfo com Bearer token"},{"id":"C","text":"/oauth2/revoke"},{"id":"D","text":"/oauth2/token com grant_type=authorization_code e code_verifier"}]'::jsonb, 'D',
  '"(a) O endpoint /oauth2/token é onde se troca o code por tokens; com PKCE, o cliente envia code + code_verifier (o plain text do hash code_challenge enviado no /authorize). Cognito valida o hash bate. (b) /authorize inicia o flow (retorna o code); userInfo retorna claims do usuário dado um access_token; revoke invalida refresh token. (c) Regra: Authorization Code = /authorize → recebe code → POST /token → recebe tokens. PKCE = verifier no token exchange. (d) Ver Cognito Developer Guide — Token endpoint."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["cognito","oauth2","pkce"]'::jsonb, 'ai-draft', 'active', now(), now()
)
