INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-113', 'aws-dva', 'Um app mobile usa refresh tokens do Cognito (válidos por 30 dias) para evitar logins frequentes. O time de segurança exige rotação de refresh tokens — invalidar o anterior a cada uso. Como habilitar isso?',
  '[{"id":"A","text":"Ativar ''Refresh token rotation'' nas configurações do App Client do User Pool"},{"id":"B","text":"Reduzir o TTL do refresh token a 1 dia"},{"id":"C","text":"Usar GlobalSignOut a cada renovação"},{"id":"D","text":"Refresh token rotation não é suportado pelo Cognito"}]'::jsonb, 'A',
  '"(a) Cognito User Pools suporta refresh token rotation no App Client: ao usar um refresh token, o anterior é invalidado e um novo é emitido. Mitiga replay caso o token vaze. (b) Reduzir TTL ajuda mas não rotaciona; GlobalSignOut invalida todas as sessões do usuário (intrusivo); rotation é suportado nativamente. (c) Regra: detect-token-replay = rotation habilitado no App Client. (d) Ver Cognito Developer Guide — Token rotation."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["cognito","refresh-token","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
