INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-114', 'aws-dva', 'Um SPA verifica o ID token JWT emitido pelo Cognito no backend. O developer quer fazer a validação local (sem chamar Cognito a cada request). Onde estão as chaves públicas para verificar a assinatura RS256?',
  '[{"id":"A","text":"Em https://cognito-identity.amazonaws.com/.well-known/jwks.json"},{"id":"B","text":"Em https://cognito-idp.{region}.amazonaws.com/{userPoolId}/.well-known/jwks.json"},{"id":"C","text":"Em variável de ambiente injetada pelo Cognito"},{"id":"D","text":"É necessário chamar AdminInitiateAuth a cada validação"}]'::jsonb, 'B',
  '"(a) Cada User Pool expõe seu JWKS público em /{poolId}/.well-known/jwks.json — o backend cacheia esses JWKs e verifica a assinatura RS256 do token usando o kid do header. Validação local elimina round-trip a cada request. (b) cognito-identity é o Identity Pool (federation), não User Pool; não há env var automática; AdminInitiateAuth é para login, não verificação. (c) Regra: JWT cognito = baixar JWKS uma vez, cachear, verificar com kid. (d) Ver Cognito Developer Guide — Verifying a JSON Web Token."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["cognito","jwt","jwks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
