INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-115', 'aws-dva', 'Em um Cognito User Pool com app client configurado como ''confidential'' (com client secret), um SPA não consegue completar o flow Authorization Code porque o secret seria exposto no browser. Qual é a correção?',
  '[{"id":"A","text":"Embedar o client secret no JavaScript do SPA"},{"id":"B","text":"Usar Implicit Grant (response_type=token)"},{"id":"C","text":"Criar um app client público (sem secret) e usar PKCE para mitigar code interception"},{"id":"D","text":"Mover toda autenticação para o backend"}]'::jsonb, 'C',
  '"(a) SPAs e apps móveis nativos são clientes públicos — não podem proteger secret. A solução padrão OAuth 2.1 é app client sem secret + PKCE: o SPA gera code_verifier aleatório, envia hash code_challenge no /authorize e o verifier no /token. (b) Embedar secret no JS expõe credencial; Implicit Grant é deprecated e perigoso (tokens no fragment); mover tudo pro backend é over-engineering quando PKCE resolve. (c) Regra: SPA/mobile = public client + PKCE. (d) Ver Cognito Developer Guide — App client."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["cognito","oauth2","pkce","public-client"]'::jsonb, 'ai-draft', 'active', now(), now()
)
