INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-116', 'aws-dva', 'Um Cognito Identity Pool federa Google + Facebook + um SAML provider. O developer chama GetCredentialsForIdentity e quer logar o IdP origem em CloudWatch para auditoria. Qual claim do ID token retornado pelo Cognito contém esse contexto?',
  '[{"id":"A","text":"cognito:preferred_role"},{"id":"B","text":"iss (issuer)"},{"id":"C","text":"aud (audience)"},{"id":"D","text":"amr (Authentication Methods References) ou identities[].providerName"}]'::jsonb, 'D',
  '"(a) Em Identity Pools, a claim ''amr'' (no token Cognito Identity) e o array ''identities'' nos atributos do User Pool indicam o provider origem (Google, Facebook, SAML provider name). (b) preferred_role é uma claim opcional para role selection; iss identifica o pool emissor; aud é o app client. (c) Regra: auditar IdP de origem = inspecionar amr/identities, não iss. (d) Ver Cognito Developer Guide — Identity pool tokens."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito","identity-pool","federation","amr"]'::jsonb, 'ai-draft', 'active', now(), now()
)
