INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-117', 'aws-dva', 'Após adicionar um Pre Token Generation Lambda no Cognito, todos os logins começam a falhar com ''Unable to invoke Lambda function''. CloudTrail mostra que o Cognito tenta chamar a função. Qual é a causa típica?',
  '[{"id":"A","text":"Falta resource-based policy na Lambda permitindo cognito-idp.amazonaws.com invocar (lambda:InvokeFunction)"},{"id":"B","text":"A Lambda não tem permissão IAM para acessar o pool"},{"id":"C","text":"Cognito não suporta Pre Token Generation em pools regionais"},{"id":"D","text":"É necessário habilitar API Gateway na frente da Lambda"}]'::jsonb, 'A',
  '"(a) Triggers Cognito são invocações cross-service: o Cognito (service principal cognito-idp.amazonaws.com) precisa de permissão na resource-based policy da Lambda para chamar lambda:InvokeFunction com SourceArn = ARN do pool. Configurar via console adiciona automaticamente, mas via Terraform/CFN com import existente é fácil esquecer. (b) Lambda não ''acessa'' o pool — é invocada por ele; o trigger é suportado; API Gateway não é parte do fluxo. (c) Regra: serviço AWS invoca Lambda = policy de invoke no recurso da Lambda. (d) Ver Cognito Developer Guide — Lambda trigger permissions."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["cognito","cognito-trigger","lambda-permission"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
