INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-118', 'aws-dva', 'Um app federa Google → Cognito Identity Pool → IAM role. O developer quer escolher dinamicamente entre 2 roles (admin vs reader) baseado em claim ''admin=true'' do Google. Qual mecanismo do Identity Pool resolve isso?',
  '[{"id":"A","text":"Adicionar ambas as roles na trust policy"},{"id":"B","text":"Role-based access control via Rule-based mapping no Identity Pool"},{"id":"C","text":"Usar SwitchRole no console"},{"id":"D","text":"Não é possível — sempre é a role autenticada default"}]'::jsonb, 'B',
  '"(a) Cognito Identity Pools suportam role mapping: rules avaliam claims do IdP (ex: ''admin == true'') e mapeiam para roles diferentes. Também há token-based (cognito:roles claim) e default fallback. (b) Trust policy não decide qual role assumir; SwitchRole é console-only; é totalmente possível com role mapping. (c) Regra: choose role at federation = rule-based ou token-based mapping. (d) Ver Cognito Developer Guide — Role-based access control."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["cognito","identity-pool","role-mapping"]'::jsonb, 'ai-draft', 'active', now(), now()
)
