INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-119', 'aws-dva', 'Uma SaaS usa Cognito Hosted UI. O developer notou que após logout via /logout, o navegador ainda mantém sessão ativa quando o usuário volta — basta clicar ''login'' que entra sem credenciais. Qual configuração resolve?',
  '[{"id":"A","text":"Reduzir o TTL do refresh token"},{"id":"B","text":"Apagar cookies manualmente no browser"},{"id":"C","text":"Chamar GlobalSignOut para invalidar refresh tokens E redirecionar para /logout com logout_uri configurado para limpar cookie de sessão Hosted UI"},{"id":"D","text":"Recriar o App Client"}]'::jsonb, 'C',
  '"(a) O Hosted UI mantém um cookie de sessão próprio; mesmo após o app deletar tokens locais, esse cookie permite SSO no próximo /authorize. A solução completa é chamar /logout?client_id=...&logout_uri=... que limpa o cookie do Hosted UI, e adicionalmente GlobalSignOut para invalidar refresh tokens emitidos. (b) Reduzir TTL não resolve a sessão ativa; clear manual no browser é UX horrível; recriar app client é destrutivo. (c) Regra: logout completo = /logout endpoint + GlobalSignOut. (d) Ver Cognito Developer Guide — Logout endpoint."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["cognito","hosted-ui","logout"]'::jsonb, 'ai-draft', 'active', now(), now()
)
