INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-120', 'aws-dva', 'Para Pre Token Generation V2 trigger, o developer quer adicionar uma claim ''scope'' customizada ao access_token (não apenas ID token). Qual versão do event payload suporta modificar access token claims?',
  '[{"id":"A","text":"Pre Token Generation V1 já permite"},{"id":"B","text":"Custom Message trigger"},{"id":"C","text":"Apenas via DefineAuthChallenge"},{"id":"D","text":"Pre Token Generation V2 (trigger version 2) — suporta accessTokenGeneration além de idTokenGeneration"}]'::jsonb, 'D',
  '"(a) Pre Token Generation V1 só permite customizar claims do ID token. V2 expandiu para também permitir adicionar/remover claims e scopes do access token, via claimsAndScopeOverrideDetails.accessTokenGeneration. Útil para passar autorização granular para APIs downstream. (b) V1 é limitada a ID token; Custom Message é para emails; DefineAuthChallenge é do custom flow. (c) Regra: customizar access_token = Pre Token Gen V2. (d) Ver Cognito Developer Guide — Pre token generation V2."'::jsonb,
  'Security', 'Security', 'hard', 'recall', '["cognito","cognito-trigger","pre-token-generation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
