INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-121', 'aws-dva', 'Uma aplicação Node.js precisa criptografar arquivos de até 5 GB com KMS. O developer descobriu que KMS Encrypt tem limite de 4 KB. Qual é o padrão correto (envelope encryption) para criptografar arquivos grandes?',
  '[{"id":"A","text":"Chamar GenerateDataKey → criptografar arquivo localmente com a plaintext data key (AES-GCM) → armazenar o ciphertext blob da data key junto"},{"id":"B","text":"Chamar Encrypt repetidamente em chunks de 4 KB"},{"id":"C","text":"Habilitar S3 SSE-KMS e fazer upload"},{"id":"D","text":"Usar KMS ReEncrypt em loop"}]'::jsonb, 'A',
  '"(a) Envelope encryption é o padrão para >4KB: GenerateDataKey retorna PlaintextKey + CiphertextBlob; o app criptografa o arquivo com a Plaintext key (AES-GCM), descarta a Plaintext, e armazena o CiphertextBlob ao lado. Decrypt do blob recupera a key. (b) Chunks de 4KB explode latência e custo; SSE-KMS resolve só para S3; ReEncrypt é para rotação de CMK, não tamanho. (c) Regra: arquivos >4KB com KMS = envelope encryption client-side. (d) Ver KMS Developer Guide — Envelope encryption."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["kms","kms-envelope","generate-data-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
