INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-122', 'aws-dva', 'Um developer chama GenerateDataKeyWithoutPlaintext em vez de GenerateDataKey. Qual é o caso de uso típico dessa API?',
  '[{"id":"A","text":"Para criptografar payloads inline maiores que 4KB"},{"id":"B","text":"Quando não se quer criptografar nada agora — apenas armazenar a data key encrypted para uso futuro por outro processo"},{"id":"C","text":"Para reduzir custo de KMS pela metade"},{"id":"D","text":"Quando o cliente não tem permissão kms:Decrypt"}]'::jsonb, 'B',
  '"(a) GenerateDataKeyWithoutPlaintext retorna apenas o CiphertextBlob — sem a plaintext. Útil quando um processo administrativo pré-gera data keys que serão usadas depois por workers downstream (com kms:Decrypt) sem nunca expor plaintext ao processo gerador. (b) O limite de 4KB é da Encrypt direta, não muda; custo é o mesmo; precisa Decrypt para usar a key depois. (c) Regra: pre-emitir data keys para uso futuro = WithoutPlaintext. (d) Ver KMS Developer Guide — GenerateDataKeyWithoutPlaintext."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","kms-envelope","data-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
