INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-123', 'aws-dva', 'Um cluster de Lambdas precisa criptografar/descriptografar dados de uma KMS CMK na conta B sem que o time da conta B precise alterar a key policy a cada nova Lambda. Qual mecanismo do KMS permite delegar permissão granular temporariamente?',
  '[{"id":"A","text":"Key Policy statement com Principal: *"},{"id":"B","text":"Tags AWS na CMK"},{"id":"C","text":"Grants (CreateGrant) — concede operações específicas a um grantee principal, podem ser revogadas/expirar"},{"id":"D","text":"Alias secundário"}]'::jsonb, 'C',
  '"(a) Grants permitem delegação programática: especifica grantee + ops (Decrypt, Encrypt, GenerateDataKey) + constraints (encryption context). São efêmeras, podem ser revogadas (RetireGrant/RevokeGrant) e não exigem editar key policy. Padrão usado por serviços AWS (EBS, RDS) que criam grant na criação do recurso. (b) Principal:* é vazamento; tags não autorizam; alias é apenas nome amigável. (c) Regra: delegação granular/temporária = grant; permanente = key policy. (d) Ver KMS Developer Guide — Grants."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["kms","grants","delegation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
