INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-124', 'aws-dva', 'Um developer criptografou dados com encryption context = {''tenant'': ''acme''}. No Decrypt, esqueceu de passar o context. Qual o comportamento?',
  '[{"id":"A","text":"Decrypt funciona — encryption context é opcional na descriptografia"},{"id":"B","text":"Decrypt funciona mas retorna dados corrompidos"},{"id":"C","text":"KMS retorna warning e descriptografa"},{"id":"D","text":"Decrypt falha — encryption context é AAD (Additional Authenticated Data) e deve bater exatamente"}]'::jsonb, 'D',
  '"(a) Encryption context é AAD em AES-GCM: faz parte da autenticação do ciphertext. Se foi passado no Encrypt, DEVE ser passado idêntico (case-sensitive) no Decrypt, ou a operação falha com InvalidCiphertextException. Não está no ciphertext (mas é logado no CloudTrail). (b) Não é opcional quando usado; não retorna dados corrompidos (GCM detecta tampering); não há warning. (c) Regra: encryption context = AAD obrigatório no Decrypt + ferramenta de auditoria. (d) Ver KMS Developer Guide — Encryption context."'::jsonb,
  'Security', 'Security', 'medium', 'troubleshoot', '["kms","encryption-context","aad"]'::jsonb, 'ai-draft', 'active', now(), now()
)
