INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-125', 'aws-dva', 'Um app global precisa descriptografar dados em us-east-1 e eu-west-1 com baixa latência. Os dados foram criptografados em us-east-1. Qual é o recurso KMS apropriado?',
  '[{"id":"A","text":"Multi-Region keys — chave primária em us-east-1 replicada como replica key em eu-west-1; ambas compartilham o mesmo material e mesmo Key ID"},{"id":"B","text":"Criar CMK separada em cada região e re-criptografar tudo via ReEncrypt"},{"id":"C","text":"Cross-region grant"},{"id":"D","text":"S3 Cross-Region Replication transparente"}]'::jsonb, 'A',
  '"(a) Multi-Region Keys (introduzidas em 2021) permitem ciphertext criado em uma região ser descriptografado em outra sem ReEncrypt. Primária em us-east-1, replica em eu-west-1; Decrypt local na replica funciona com o mesmo ciphertext blob. (b) Re-criptografar tudo é custoso e disruptivo; grants não são cross-region; CRR replica objeto mas não resolve cripto-region. (c) Regra: cripto multi-região = MRK. (d) Ver KMS Developer Guide — Multi-Region keys."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["kms","multi-region-keys"]'::jsonb, 'ai-draft', 'active', now(), now()
)
