INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-126', 'aws-dva', 'Para compliance, a empresa exige que o material criptográfico das CMKs venha de um HSM on-premises — não gerado pela AWS. Qual mecanismo KMS atende?',
  '[{"id":"A","text":"AWS Managed Keys"},{"id":"B","text":"BYOK — Import key material para uma CMK com Origin=EXTERNAL"},{"id":"C","text":"CloudHSM federation"},{"id":"D","text":"Não é possível — KMS sempre gera o material internamente"}]'::jsonb, 'B',
  '"(a) BYOK: cria-se uma CMK com Origin=EXTERNAL; GetParametersForImport retorna um wrapping key público; o cliente wrapa o material no HSM on-prem com RSA-OAEP e chama ImportKeyMaterial. A CMK fica unusable se o material expirar (TTL opcional). (b) Managed Keys são geradas pela AWS; CloudHSM é serviço separado; importar é totalmente suportado. (c) Regra: trazer material próprio = Origin=EXTERNAL + ImportKeyMaterial. (d) Ver KMS Developer Guide — Importing key material."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","byok","import-key-material"]'::jsonb, 'ai-draft', 'active', now(), now()
)
