INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-127', 'aws-dva', 'Um developer cria uma KMS asymmetric key (RSA_2048) para assinar JWTs no backend. Que combinação de API + KeyUsage é necessária?',
  '[{"id":"A","text":"KeyUsage=ENCRYPT_DECRYPT, API: Encrypt/Decrypt"},{"id":"B","text":"KeyUsage=GENERATE_VERIFY_MAC, API: GenerateMac"},{"id":"C","text":"KeyUsage=SIGN_VERIFY, API: Sign/Verify; chave privada nunca sai do KMS"},{"id":"D","text":"KeyUsage=KEY_AGREEMENT, API: DeriveSharedSecret"}]'::jsonb, 'C',
  '"(a) Asymmetric keys em KMS são criadas com KeyUsage específico: SIGN_VERIFY para assinatura digital (RSA-PSS, RSA-PKCS1, ECDSA). API Sign retorna a signature; Verify valida. A chave privada permanece protegida pelo HSM do KMS. Pode-se exportar a chave pública via GetPublicKey para verificar offline. (b) ENCRYPT_DECRYPT é para wrap de keys; MAC é simétrico HMAC; KEY_AGREEMENT é ECDH. (c) Regra: assinar JWT com KMS = SIGN_VERIFY asymmetric. (d) Ver KMS Developer Guide — Asymmetric keys."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["kms","asymmetric","sign-verify"]'::jsonb, 'ai-draft', 'active', now(), now()
)
