INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-128', 'aws-dva', 'Um sistema tem milhões de Decrypt/segundo via uma CMK e está sendo throttled (ThrottlingException). A CMK não tem rotation, e a quota da conta já está no máximo. Qual estratégia client-side resolve sem aumentar custo KMS?',
  '[{"id":"A","text":"Mudar para Tokenization"},{"id":"B","text":"Trocar CMK por Customer Provided Key"},{"id":"C","text":"Habilitar Multi-Region Key"},{"id":"D","text":"Data key caching (AWS Encryption SDK) — reutiliza data key descriptografada por N usos ou T segundos, dentro do encryption context"}]'::jsonb, 'D',
  '"(a) Data key caching é feature do AWS Encryption SDK: ao invés de chamar Decrypt no KMS a cada operação, o SDK cacheia a plaintext data key em memória limitada por (max_age, max_messages_encrypted, max_bytes_encrypted, encryption context). Reduz drasticamente RPS contra KMS. Trade-off: chave plaintext em memória por mais tempo. (b) Tokenization é arquitetura diferente; CPK é S3-only; MRK não reduz RPS por região. (c) Regra: alto QPS em KMS = data key caching. (d) Ver Encryption SDK Developer Guide — Data key caching."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["kms","encryption-sdk","data-key-caching","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
