INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-129', 'aws-dva', 'Um developer deletou uma CMK acidentalmente via ScheduleKeyDeletion com PendingWindowInDays=7. Após 3 dias percebeu o erro. É possível recuperar?',
  '[{"id":"A","text":"Sim — durante o pending window (7-30 dias) chamar CancelKeyDeletion restaura a CMK"},{"id":"B","text":"Não, a key é destruída imediatamente"},{"id":"C","text":"Sim, mas só com AWS Support"},{"id":"D","text":"Apenas se houver backup CloudHSM"}]'::jsonb, 'A',
  '"(a) ScheduleKeyDeletion coloca a CMK em estado PendingDeletion por 7-30 dias (parâmetro PendingWindowInDays). Durante esse período, CancelKeyDeletion reverte para Disabled e depois Enable habilita novamente. Por isso AWS força o pending window mínimo — uma CMK deletada é irrecuperável após o prazo. (b) Não é imediato; Support não é necessário; sem CloudHSM. (c) Regra: chave KMS deletada com pendente = CancelKeyDeletion. (d) Ver KMS Developer Guide — Deleting keys."'::jsonb,
  'Security', 'Security', 'easy', 'troubleshoot', '["kms","key-deletion"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
