INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-130', 'aws-dva', 'Uma CMK gerenciada pelo customer tem rotation habilitada (annual). Após 1 ano, o developer testa Decrypt em um ciphertext antigo (de 18 meses atrás) — ainda funciona. Por quê?',
  '[{"id":"A","text":"Rotation não muda o material, só renova metadata"},{"id":"B","text":"Rotation gera novo backing key material; KMS retém versões antigas e seleciona automaticamente pelo KeyId no ciphertext metadata"},{"id":"C","text":"O ciphertext foi automaticamente re-criptografado"},{"id":"D","text":"Rotation está quebrada"}]'::jsonb, 'B',
  '"(a) Em automatic key rotation, KMS gera novo material criptográfico mas mantém todas as versões antigas indexadas. Cada ciphertext blob inclui o KeyId/version usado; no Decrypt, KMS seleciona a versão correta automaticamente. O Key ARN público não muda. (b) Material muda; ciphertext não é re-criptografado; rotation funciona como projetada. (c) Regra: rotation = nova versão + retenção das antigas + lookup automático. (d) Ver KMS Developer Guide — Rotating keys."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["kms","key-rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
