INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-131', 'aws-dva', 'Um developer escreve código Python (boto3) para envelope encryption manual. Após GenerateDataKey, qual cuidado de segurança é crítico para a Plaintext key?',
  '[{"id":"A","text":"Persistir em disco junto ao ciphertext para facilitar Decrypt"},{"id":"B","text":"Armazenar em variável global do processo"},{"id":"C","text":"Usar imediatamente para AES-GCM, zerar/descartar a referência da memória, manter apenas o CiphertextBlob persistido"},{"id":"D","text":"Enviar para outra CMK por segurança"}]'::jsonb, 'C',
  '"(a) A plaintext data key tem janela de vida mínima: usar AES-GCM imediatamente, descartar referência (em Python, deletar var; em Go, zerar slice). Só o CiphertextBlob deve ser persistido — Decrypt regenera a plaintext sob demanda. Persistir plaintext quebra o modelo de envelope encryption. (b) Persistir plaintext invalida tudo; var global expõe a memória mais tempo; enviar para outra CMK é nonsense. (c) Regra: plaintext data key = efêmera, ciphertext blob = persistente. (d) Ver KMS Developer Guide + Encryption SDK best practices."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["kms","kms-envelope","plaintext-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
