INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-132', 'aws-dva', 'Um developer quer auditar TODAS as operações cripto realizadas com uma CMK em produção (quem chamou Decrypt, quando, com qual encryption context). Onde estão esses logs?',
  '[{"id":"A","text":"VPC Flow Logs"},{"id":"B","text":"KMS não loga operações cripto por motivos de performance"},{"id":"C","text":"S3 server access logs do bucket de chaves"},{"id":"D","text":"CloudTrail Data events para KMS — cada Encrypt/Decrypt/GenerateDataKey aparece com requestParameters incluindo encryptionContext"}]'::jsonb, 'D',
  '"(a) CloudTrail loga management events do KMS por default e data events (Encrypt/Decrypt/GenerateDataKey/etc) quando habilitado no trail. O log inclui caller identity, timestamp, KeyId e encryptionContext — fornecendo auditoria completa de uso. (b) Flow logs são de rede; KMS sempre loga; S3 logs não cobrem KMS. (c) Regra: auditar KMS = CloudTrail data events. (d) Ver KMS Developer Guide — Logging API calls."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["kms","cloudtrail","audit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
