INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-133', 'aws-dva', 'Uma rotation Lambda do Secrets Manager para Aurora MySQL falha na etapa ''setSecret'' com ''AccessDenied''. A Lambda tem secretsmanager:* e rds:* no IAM. Qual permissão típica está faltando?',
  '[{"id":"A","text":"kms:Decrypt na CMK que criptografa o segredo (e kms:GenerateDataKey se o segredo usa CMK customer-managed)"},{"id":"B","text":"iam:PassRole para a role do RDS"},{"id":"C","text":"cloudwatch:PutMetricData"},{"id":"D","text":"ec2:DescribeInstances"}]'::jsonb, 'A',
  '"(a) Se o secret usa CMK customer-managed, a Lambda de rotation precisa de kms:Decrypt (para ler valor atual) e kms:GenerateDataKey (para escrever nova versão). Permissão secretsmanager:* não inclui implícito uso da CMK — esta é separada e exige policy KMS ou key policy. (b) PassRole é para criar serviços; CloudWatch é nice-to-have; EC2 describe não faz parte. (c) Regra: secret com customer CMK = lambda precisa kms:Decrypt + GenerateDataKey. (d) Ver Secrets Manager User Guide — Rotation troubleshooting."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["secrets-manager","rotation","kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
