INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-134', 'aws-dva', 'Uma rotation Lambda customizada do Secrets Manager implementa 4 steps. Em qual ordem o Secrets Manager os invoca?',
  '[{"id":"A","text":"finishSecret → createSecret → setSecret → testSecret"},{"id":"B","text":"createSecret → setSecret → testSecret → finishSecret"},{"id":"C","text":"setSecret → testSecret → createSecret → finishSecret"},{"id":"D","text":"testSecret → setSecret → createSecret → finishSecret"}]'::jsonb, 'B',
  '"(a) Os 4 steps padrão: createSecret (gera novo valor com AWSPENDING label); setSecret (aplica no serviço externo, ex: ALTER USER no MySQL); testSecret (valida que o novo segredo funciona conectando com AWSPENDING); finishSecret (move AWSCURRENT para a nova versão). Cada step é uma invocação separada da Lambda com ''Step'' no event. (b) Outras ordens não fazem sentido (não dá pra testar antes de criar). (c) Regra: create → set → test → finish. (d) Ver Secrets Manager User Guide — Lambda rotation function."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["secrets-manager","rotation","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
