INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-135', 'aws-dva', 'Uma equipe consome um Secret cross-account: conta A tem o segredo, conta B tem o consumidor. Mesmo após adicionar resource policy no segredo permitindo a role da conta B, falha no Decrypt. Qual outra permissão é necessária?',
  '[{"id":"A","text":"Nenhuma — a resource policy do Secrets Manager basta"},{"id":"B","text":"VPC peering entre as contas"},{"id":"C","text":"A CMK que criptografa o segredo deve ter key policy permitindo a role da conta B (não pode ser a aws/secretsmanager managed CMK)"},{"id":"D","text":"Habilitar STS regional endpoint na conta B"}]'::jsonb, 'C',
  '"(a) Cross-account com Secrets Manager exige: (1) resource policy no secret permitindo o principal da conta B; (2) CMK customer-managed (não a aws/secretsmanager AWS-managed, que NÃO pode ser usada cross-account); (3) key policy da CMK permitindo a role de B. As 3 condições combinadas são necessárias. (b) Não basta resource policy; VPC peering é de rede; STS regional não muda autorização. (c) Regra: cross-account Secret = resource policy + customer CMK + key policy. (d) Ver Secrets Manager User Guide — Cross-account access."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["secrets-manager","cross-account","kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
