INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-136', 'aws-dva', 'Um template CloudFormation precisa injetar uma senha do Secrets Manager numa propriedade DBPassword do RDS — sem expor o valor no template. Qual sintaxe usar?',
  '[{"id":"A","text":"Hard-coded no template"},{"id":"B","text":"Fn::ImportValue do segredo"},{"id":"C","text":"AWS::Secrets::Direct intrinsic function"},{"id":"D","text":"Dynamic reference: ''{{resolve:secretsmanager:MySecret:SecretString:password}}''"}]'::jsonb, 'D',
  '"(a) Dynamic references do CloudFormation resolvem em deploy-time sem expor o valor no template ou drift detection. Sintaxe: {{resolve:secretsmanager:secret-id:SecretString:json-key:version-stage:version-id}}. Também existe para SSM Parameter Store (secure-string ssm-secure). (b) Hard-code expõe; ImportValue é para outputs de stack, não secrets; AWS::Secrets::Direct não existe. (c) Regra: secret em CFN sem leak = dynamic reference resolve:secretsmanager. (d) Ver Secrets Manager + CFN dynamic references docs."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["secrets-manager","cloudformation","dynamic-reference"]'::jsonb, 'ai-draft', 'active', now(), now()
)
