INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-137', 'aws-dva', 'Um app organiza configs por ambiente em SSM Parameter Store: /app/prod/db/host, /app/prod/db/port, /app/staging/db/host, etc. O developer quer buscar TODOS os parametros sob /app/prod/db/ numa única chamada. Qual API usar?',
  '[{"id":"A","text":"GetParametersByPath com Path=''/app/prod/db/'' e Recursive=true"},{"id":"B","text":"GetParameter chamado várias vezes"},{"id":"C","text":"DescribeParameters com filter"},{"id":"D","text":"ListSecrets"}]'::jsonb, 'A',
  '"(a) GetParametersByPath foi feita para isso: aceita Path hierárquico, Recursive=true para descer subtrees, paginação via NextToken. Decrypt automático para SecureString se WithDecryption=true. Reduz N+1 chamadas. (b) GetParameter individual é wasteful; DescribeParameters lista metadata mas não valores; ListSecrets é Secrets Manager. (c) Regra: PS organizado em hierarquia + leitura batch = GetParametersByPath. (d) Ver Systems Manager User Guide — Parameter Store API."'::jsonb,
  'Security', 'Security', 'easy', 'scenario', '["parameter-store","ssm","hierarchical"]'::jsonb, 'ai-draft', 'active', now(), now()
)
