INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-138', 'aws-dva', 'Um developer comparou Secrets Manager vs Parameter Store SecureString. Para uma senha de RDS que precisa rotation automática a cada 30 dias, qual é a escolha apropriada e por quê?',
  '[{"id":"A","text":"Parameter Store — é gratuito"},{"id":"B","text":"Secrets Manager — suporta rotation nativa via Lambda templates e integração com RDS/Redshift/DocumentDB"},{"id":"C","text":"Parameter Store Advanced — suporta rotation"},{"id":"D","text":"Indiferente"}]'::jsonb, 'B',
  '"(a) Secrets Manager é o serviço apropriado para credenciais com rotation: oferece rotation managed via Lambda templates oficiais para RDS, Redshift, DocumentDB; controle de versões (AWSCURRENT/AWSPENDING/AWSPREVIOUS); resource policy nativa. Custo: ~$0.40/secret/month + API calls. (b) PS é grátis para Standard, mas NÃO tem rotation nativa (precisa orquestrar com EventBridge + Lambda custom); PS Advanced expande size e adiciona policies/expiry mas continua sem rotation managed. (c) Regra: rotation manageda + custo aceitável = Secrets Manager. (d) Ver Secrets Manager vs Parameter Store comparison."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["secrets-manager","parameter-store","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
