INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-139', 'aws-dva', 'Uma API privada interna usa mTLS — cliente e servidor se autenticam com certificados X.509. Quem emite e gerencia o ciclo de vida dos certs do cliente quando a empresa quer evitar CAs públicas?',
  '[{"id":"A","text":"ACM público (Amazon issued certificates)"},{"id":"B","text":"IAM Server Certificates"},{"id":"C","text":"AWS Certificate Manager Private CA (ACM PCA) — emite certs privados com hierarquia controlada pela empresa"},{"id":"D","text":"Let''s Encrypt"}]'::jsonb, 'C',
  '"(a) ACM Private CA permite criar uma hierarquia PKI privada (root CA + subordinate CAs) e emitir certificados de servidor/cliente assinados por ela. Cobra por CA ativa + por cert emitido. Ideal para mTLS interno, IoT, microsserviços. (b) ACM público só emite certs para domínios DNS controlados publicamente; IAM Server Certs é legado (CloudFront/ELB); Let''s Encrypt é público. (c) Regra: PKI interna = ACM PCA. (d) Ver ACM Private CA User Guide."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["acm-pca","mtls","private-ca"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
