INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-140', 'aws-dva', 'Um cert público ACM emitido para api.example.com está integrado num ALB. Quem renova o cert e o que o developer precisa fazer manualmente perto da expiração?',
  '[{"id":"A","text":"Renovação manual via re-import a cada ano"},{"id":"B","text":"AWS Support precisa aprovar a renovação"},{"id":"C","text":"Re-validar por email a cada 90 dias"},{"id":"D","text":"Renovação automática (managed renewal) para certs validados via DNS — desde que o CNAME de validação permaneça publicado; nada a fazer"}]'::jsonb, 'D',
  '"(a) ACM faz managed renewal automaticamente 60 dias antes da expiração para certs públicos: se a validação foi DNS e o CNAME continua publicado, renova transparente. Para email validation, AWS envia link de re-validação. Certs em uso por serviços integrados (ALB, CloudFront, API GW) recebem o novo automaticamente. (b) Re-import é só para certs importados, não emitidos pelo ACM; Support não é envolvido; 90 dias é Let''s Encrypt. (c) Regra: ACM público + DNS validation = renovação zero-touch. (d) Ver ACM User Guide — Managed renewal."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["acm","renewal","tls"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
