INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-141', 'aws-dva', 'Um API Gateway REST API exige mTLS — clientes apresentam cert X.509 e o server valida contra um truststore. Como o developer configura o truststore?',
  '[{"id":"A","text":"Upload de um arquivo PEM com as CAs confiáveis para um bucket S3 e configurar TruststoreUri no custom domain do API GW"},{"id":"B","text":"Adicionar CAs no IAM"},{"id":"C","text":"ACM faz isso automaticamente"},{"id":"D","text":"VPC PrivateLink habilita mTLS"}]'::jsonb, 'A',
  '"(a) mTLS no API Gateway exige um custom domain name + um truststore (arquivo PEM com a cadeia de CAs aceitas) hospedado em S3 — TruststoreUri aponta para s3://bucket/file.pem com versionId opcional. API GW valida o cert client contra essas CAs durante o TLS handshake. (b) IAM não armazena truststore; ACM gerencia certs do server, não truststore; PrivateLink é rede, não autenticação. (c) Regra: mTLS API GW = custom domain + truststore PEM no S3. (d) Ver API Gateway Developer Guide — mTLS."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["api-gateway","mtls","truststore"]'::jsonb, 'ai-draft', 'active', now(), now()
)
