INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-142', 'aws-dva', 'Um developer chama uma API AWS via curl sem SDK — precisa assinar a request manualmente com SigV4. Quais 4 componentes compõem a signature?',
  '[{"id":"A","text":"Apenas access_key_id e secret"},{"id":"B","text":"Canonical Request, String to Sign, Signing Key derivada (date+region+service+aws4_request), Signature HMAC-SHA256"},{"id":"C","text":"JWT + nonce"},{"id":"D","text":"OAuth Bearer token"}]'::jsonb, 'B',
  '"(a) SigV4 é o protocolo padrão de assinatura AWS: (1) Canonical Request hash de método+URI+headers+payload; (2) String to Sign incluindo algoritmo, timestamp, credential scope (date/region/service/aws4_request) e hash da canonical; (3) Signing Key derivada por HMAC encadeado de secret→date→region→service→aws4_request; (4) Signature = HMAC-SHA256(signingKey, stringToSign). Enviada no header Authorization. (b) Keys sozinhas não autenticam request; JWT/OAuth são outros protocolos. (c) Regra: SigV4 = canonical + sts + key derivada + HMAC. (d) Ver IAM/STS Reference — Signature Version 4."'::jsonb,
  'Security', 'Security', 'hard', 'recall', '["sigv4","signing","authentication"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
