INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-143', 'aws-dva', 'Um developer assinou uma request SigV4 e a AWS retornou ''RequestTimeTooSkewed''. Qual é o motivo e como corrigir?',
  '[{"id":"A","text":"Access key expirada"},{"id":"B","text":"Região inválida"},{"id":"C","text":"O timestamp X-Amz-Date difere mais de 5 minutos do server clock da AWS; sincronizar o relógio do cliente (NTP)"},{"id":"D","text":"Payload muito grande"}]'::jsonb, 'C',
  '"(a) SigV4 inclui timestamp na string to sign; AWS rejeita requests com skew >5 minutos contra o tempo do server, prevenindo replay. RequestTimeTooSkewed = relógio do cliente fora. Correção: sincronizar via NTP (no Linux: chronyd/systemd-timesyncd). (b) Key expirada daria InvalidClientTokenId; região errada daria EndpointResolution erro; payload grande daria EntityTooLarge. (c) Regra: timestamp ≤5min de skew obrigatório. (d) Ver SigV4 reference — Request signing."'::jsonb,
  'Security', 'Security', 'medium', 'troubleshoot', '["sigv4","clock-skew"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
