INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-144', 'aws-dva', 'Um cert ACM emitido para *.api.example.com cobre quais subdomínios?',
  '[{"id":"A","text":"Apenas api.example.com"},{"id":"B","text":"Todos os subdomínios em qualquer profundidade"},{"id":"C","text":"Nenhum, wildcards não são suportados em ACM"},{"id":"D","text":"Um nível de subdomínio: foo.api.example.com SIM; foo.bar.api.example.com NÃO"}]'::jsonb, 'D',
  '"(a) Wildcard cert *.api.example.com cobre exatamente um nível de subdomínio sob api.example.com: foo.api.example.com é válido, mas foo.bar.api.example.com não — precisaria de *.bar.api.example.com adicional como SAN. Também não cobre api.example.com em si (apex sob o wildcard) — precisa adicionar como SAN separado no request. (b) Apenas um nível, não qualquer profundidade nem ''apenas o exato''; wildcards são suportados pelo ACM. (c) Regra: *.foo.bar = 1 nível de subdomínio + SAN para o apex se preciso. (d) Ver ACM User Guide — Certificate request."'::jsonb,
  'Security', 'Security', 'easy', 'recall', '["acm","wildcard","tls"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
