INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-145', 'aws-dva', 'Um bucket S3 armazena documentos legais que precisam permanecer imutáveis por 7 anos (compliance regulatório). O administrador da conta NÃO deve conseguir deletar antes do prazo — nem com root. Qual modo do S3 Object Lock atende?',
  '[{"id":"A","text":"Compliance mode — nenhum usuário (nem root) pode deletar ou alterar o retention period até expirar"},{"id":"B","text":"Governance mode — admins com s3:BypassGovernanceRetention podem remover"},{"id":"C","text":"Legal Hold sem retention period"},{"id":"D","text":"Versioning sozinho"}]'::jsonb, 'A',
  '"(a) Object Lock Compliance mode é imutável: ninguém — nem root account — pode deletar o objeto, encurtar a retention nem desabilitar versioning até a data expirar. WORM real. Necessário para regulamentações como SEC 17a-4. (b) Governance permite bypass com permissão específica (útil para retenção menos rigorosa); Legal Hold é flag indeterminada sem prazo; versioning só impede sobrescrita acidental. (c) Regra: WORM regulatório = Compliance mode. (d) Ver S3 User Guide — Object Lock."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["s3","object-lock","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
