INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-146', 'aws-dva', 'Uma empresa tem 200 aplicações compartilhando 1 bucket S3 — cada app precisa de policies distintas. Manter 200 statements numa única bucket policy ficou ingerenciável. Qual feature do S3 resolve?',
  '[{"id":"A","text":"Criar 200 buckets"},{"id":"B","text":"S3 Access Points — endpoints com hostname próprio e policy isolada por consumidor"},{"id":"C","text":"Usar IAM tags exclusivamente"},{"id":"D","text":"Mover para FSx"}]'::jsonb, 'B',
  '"(a) S3 Access Points permitem múltiplos endpoints nomeados (ap-name-acctid.s3-accesspoint.region.amazonaws.com) sobre o mesmo bucket; cada AP tem sua própria policy e configuração de bloqueio público. Simplifica gestão de muitos consumidores. Multi-Region Access Points adicionam roteamento global. (b) 200 buckets explodiriam quota; tags ajudam mas não isolam endpoints; FSx é outro serviço. (c) Regra: muitos consumidores em 1 bucket = Access Points. (d) Ver S3 User Guide — Access Points."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["s3","access-points","multi-tenant"]'::jsonb, 'ai-draft', 'active', now(), now()
)
