INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-147', 'aws-dva', 'Em uma bucket policy, o developer quer permitir s3:PutObject apenas se o caller estiver enviando com SSE-KMS habilitado usando uma CMK específica. Qual condition key impõe isso?',
  '[{"id":"A","text":"aws:SecureTransport: true"},{"id":"B","text":"s3:VersionId"},{"id":"C","text":"s3:x-amz-server-side-encryption-aws-kms-key-id deve igualar o ARN da CMK"},{"id":"D","text":"s3:prefix"}]'::jsonb, 'C',
  '"(a) s3:x-amz-server-side-encryption-aws-kms-key-id é a condition key que captura o header X-Amz-Server-Side-Encryption-Aws-Kms-Key-Id enviado pelo cliente; combinada com s3:x-amz-server-side-encryption=''aws:kms'' garante que apenas uploads SSE-KMS com a CMK exata sejam aceitos. (b) SecureTransport força HTTPS, não SSE; VersionId é versioning; prefix limita key. (c) Regra: forçar SSE-KMS com CMK específica = duas condition keys combinadas. (d) Ver S3 User Guide — Bucket policy condition keys for SSE."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["s3","bucket-policy","sse-kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
