INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-148', 'aws-dva', 'Um bucket recebe uploads de mobile via presigned PUT URL. O developer quer garantir que o cliente seja obrigado a fornecer Content-Type específico e tag ''origin=mobile'' no upload. Como impor?',
  '[{"id":"A","text":"Confiar que o cliente envia corretamente"},{"id":"B","text":"Validar via Lambda trigger após upload"},{"id":"C","text":"Forçar via bucket policy com s3:RequestObjectTag prefix"},{"id":"D","text":"Usar S3 POST policy (Browser-Based Upload) com conditions ou incluir headers/tags assinados na presigned URL como parte da signature"}]'::jsonb, 'D',
  '"(a) Presigned URLs assinam o request inteiro: qualquer header não incluído na signature pode ser alterado pelo cliente; para forçar Content-Type/tags, incluí-los no SignedHeaders + valor esperado. POST policy (browser upload) usa conditions explícitas no policy document (eq, starts-with). (b) Cliente sem validação = inseguro; Lambda post-event é tardio (objeto já lá); bucket policy s3:RequestObjectTagKeys pode validar tags mas o developer precisa incluir x-amz-tagging assinado na URL. (c) Regra: forçar metadata em upload = incluir nos signed headers ou usar POST policy. (d) Ver S3 User Guide — Presigned URLs + POST policy."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["s3","presigned-url","post-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
