INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-149', 'aws-dva', 'Para impor SSL/TLS em todo acesso a um bucket S3 (rejeitar HTTP), qual statement da bucket policy é canônico?',
  '[{"id":"A","text":"Effect: Deny, Action: s3:*, Principal: *, Condition: { Bool: { aws:SecureTransport: false } }"},{"id":"B","text":"Effect: Allow, Action: s3:*, Condition: { StringEquals: { aws:RequestedRegion: us-east-1 } }"},{"id":"C","text":"Habilitar S3 Block Public Access"},{"id":"D","text":"Configurar CloudFront na frente"}]'::jsonb, 'A',
  '"(a) O snippet canônico é um Deny com SecureTransport=false: nega tudo via HTTP, permitindo só HTTPS. Boa prática pré-built em AWS Config rule e Security Hub. (b) RequestedRegion limita geografia, não TLS; Block Public Access é outro controle (público vs privado); CloudFront ajuda mas o bucket continua acessível direto. (c) Regra: forçar TLS no S3 = Deny aws:SecureTransport=false. (d) Ver S3 User Guide — Policy examples."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["s3","bucket-policy","tls"]'::jsonb, 'ai-draft', 'active', now(), now()
)
