INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-150', 'aws-dva', 'Um aplicativo serverless tem múltiplos consumidores: webapp interno (Cognito JWT), parceiros B2B (API key), e admin tools (IAM SigV4). API Gateway REST. Como configurar autorização por método para suportar os três?',
  '[{"id":"A","text":"Forçar todos a usar API key"},{"id":"B","text":"Configurar Cognito User Pool authorizer no method de webapp, API Key + Usage Plan nos métodos B2B, e AWS_IAM authorization nos métodos admin"},{"id":"C","text":"Lambda authorizer para tudo"},{"id":"D","text":"Não é possível combinar mecanismos"}]'::jsonb, 'B',
  '"(a) API Gateway permite autorização per-method: Cognito User Pool authorizer valida ID token JWT; API Key + Usage Plan controla quota/throttle por parceiro (não é autenticação forte sozinho — combine com policy); AWS_IAM permite chamadas SigV4 com IAM permissions de execute-api. Os três coexistem no mesmo API. (b) Forçar API key perde benefícios; Lambda authorizer único é over-engineering; combinação é totalmente suportada. (c) Regra: API GW = autorização por method, escolha o mecanismo correto por consumidor. (d) Ver API Gateway Developer Guide — Authorizers comparison."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["api-gateway","cognito-authorizer","iam-auth","api-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
