INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-151', 'aws-dva', 'Um Lambda authorizer (REQUEST type) está sendo invocado a cada request mesmo quando o header Authorization se repete. O developer quer cache para reduzir invocações. Como funciona o cache do API GW authorizer?',
  '[{"id":"A","text":"Cache não existe em REQUEST authorizer"},{"id":"B","text":"Cache acontece automaticamente sem configuração"},{"id":"C","text":"Configurar Authorizer Result TTL (até 3600s) e Identity Sources — o API GW cacheia o policy result por combinação única de identity sources"},{"id":"D","text":"Usar CloudFront edge cache"}]'::jsonb, 'C',
  '"(a) API Gateway suporta cache de authorizer (TOKEN e REQUEST): TTL configurável (default 300s, max 3600s) + Identity Sources (headers, query params, stage vars) compõem a chave de cache. Resultados idênticos para os mesmos identity sources retornam do cache. Para REQUEST type, identity sources deve ser configurado explicitamente (multi-key permitido). (b) Cache existe em ambos; não é automático sem configurar TTL; CloudFront é antes do API GW. (c) Regra: reduzir invocações = TTL + identity sources corretos. (d) Ver API Gateway Developer Guide — Lambda authorizer caching."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["api-gateway","lambda-authorizer","caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
