INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-152', 'aws-dva', 'Diferença prática entre Lambda authorizer TOKEN vs REQUEST type?',
  '[{"id":"A","text":"TOKEN é mais lento"},{"id":"B","text":"REQUEST só funciona em HTTP API"},{"id":"C","text":"São idênticos"},{"id":"D","text":"TOKEN recebe somente o valor de UM header (typically Authorization); REQUEST recebe headers, query string, path, stage variables, context — útil para autorização baseada em múltiplos sinais"}]'::jsonb, 'D',
  '"(a) TOKEN type recebe payload mínimo (apenas o valor do identity source único, tipicamente o JWT do Authorization header) — adequado para validar tokens simples. REQUEST type recebe o request inteiro (multiValueHeaders, queryStringParameters, pathParameters, stageVariables, requestContext) — necessário quando autorização depende de múltiplos campos (ex: API key + IP de origem + path). (b) Performance similar; ambos funcionam em REST API; não são idênticos. (c) Regra: token JWT simples = TOKEN; lógica complexa multi-input = REQUEST. (d) Ver API Gateway Developer Guide — Authorizer types."'::jsonb,
  'Security', 'Security', 'medium', 'recall', '["api-gateway","lambda-authorizer","token-vs-request"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
