INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-153', 'aws-dva', 'Um Lambda authorizer retorna o IAM policy document; o developer percebeu que mudou o effect de Allow para Deny no policy retornado, mas alguns clientes ainda conseguem chamar a API. Qual a causa provável?',
  '[{"id":"A","text":"O Authorizer Result Cache ainda tem entries Allow válidas — invalidar reduzindo TTL ou trocando identity source rompe o cache"},{"id":"B","text":"API Gateway ignora effect Deny"},{"id":"C","text":"Falta CloudWatch Logs"},{"id":"D","text":"Necessário recriar o stage"}]'::jsonb, 'A',
  '"(a) Quando authorizer cache está ativo, resultados (incluindo Allow) são reutilizados até o TTL expirar para a mesma combinação de identity sources. Mudar a lógica do authorizer não invalida cache existente. Soluções: aguardar TTL, reduzir TTL temporariamente para 0, ou alterar identity sources. (b) Deny é respeitado quando avaliado; logs ajudam debug mas não causam isso; recriar stage é overkill. (c) Regra: mudanças em authorizer só refletem após cache TTL expirar. (d) Ver API Gateway Developer Guide — Authorizer caching gotchas."'::jsonb,
  'Security', 'Security', 'hard', 'troubleshoot', '["api-gateway","lambda-authorizer","caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
