INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-154', 'aws-dva', 'Para API Gateway HTTP API (não REST), qual é o tipo de autorizer JWT nativo que valida tokens Cognito/Auth0 sem Lambda intermediária?',
  '[{"id":"A","text":"Lambda Authorizer obrigatório"},{"id":"B","text":"JWT Authorizer — configura issuer e audience; API GW valida assinatura via JWKS e claims automaticamente"},{"id":"C","text":"API Key only"},{"id":"D","text":"Cognito Authorizer (mesmo que REST API)"}]'::jsonb, 'B',
  '"(a) HTTP API tem JWT Authorizer nativo: configura-se IssuerURL (ex: cognito-idp.region.amazonaws.com/poolId) e Audiences (client IDs); API GW baixa JWKS, valida assinatura RS256, exp, iss, aud sem código custom. Suporta qualquer IdP OIDC-compatible (Cognito, Auth0, Okta). REST API não tem isso — usa Cognito authorizer ou Lambda. (b) Lambda não é obrigatória; API Key não autentica usuário; Cognito Authorizer é REST-only. (c) Regra: HTTP API + JWT = autorizer nativo, zero Lambda. (d) Ver API Gateway Developer Guide — JWT authorizers (HTTP APIs)."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["api-gateway","http-api","jwt-authorizer"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
