INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-155', 'aws-dva', 'Em API Key + Usage Plan, qual é o propósito real da API Key — e o que ela NÃO faz?',
  '[{"id":"A","text":"Substitui autenticação completamente"},{"id":"B","text":"Criptografa o payload"},{"id":"C","text":"Identifica/contabiliza o cliente para throttling e quota — NÃO é mecanismo de autenticação forte (chaves podem vazar; combine com IAM/Cognito/Lambda authorizer)"},{"id":"D","text":"Garante TLS"}]'::jsonb, 'C',
  '"(a) API Key serve para identificar o cliente em uma Usage Plan (rate limit, burst, quota mensal); é enviada no header x-api-key. Não é autenticação forte — pode vazar e não há rotação automática. Em produção, combine com authorizer real (IAM/Cognito/Lambda) que valide a identidade, deixando a API Key apenas para metering. (b) Substituir auth é antipadrão; chave em plain text não criptografa nada; TLS vem do endpoint. (c) Regra: API Key = metering, não auth; sempre combinar com autenticação real. (d) Ver API Gateway Developer Guide — Usage Plans + API Keys."'::jsonb,
  'Security', 'Security', 'easy', 'best-practice', '["api-gateway","api-key","usage-plan"]'::jsonb, 'ai-draft', 'active', now(), now()
)
