INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-156', 'aws-dva', 'O developer prefere AWS Encryption SDK em vez de chamar KMS diretamente. Qual benefício o SDK fornece sobre Encrypt/Decrypt manual?',
  '[{"id":"A","text":"Não usa KMS"},{"id":"B","text":"É só uma alias para KMS"},{"id":"C","text":"Substitui IAM"},{"id":"D","text":"Formato de mensagem padronizado (headers + encrypted data keys + ciphertext + auth tag), data key caching, suporte a multi-CMK (multiple master keys) e algorithm suite selection — abstrai envelope encryption corretamente"}]'::jsonb, 'D',
  '"(a) AWS Encryption SDK encapsula envelope encryption end-to-end: gera data key (via KMS), criptografa payload com AES-GCM, escreve um message format binário que carrega encrypted data keys + IV + tag, suporta múltiplos CMKs (HA cross-region), algorithm suites configuráveis, data key caching. Sem o SDK, o developer reimplementa tudo (e erra). (b) Usa KMS por baixo; não é só alias; IAM continua. (c) Regra: cripto client-side em produção = Encryption SDK, não Encrypt direto. (d) Ver AWS Encryption SDK Developer Guide — Concepts."'::jsonb,
  'Security', 'Security', 'medium', 'best-practice', '["encryption-sdk","envelope"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
