INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-157', 'aws-dva', 'Um app DynamoDB armazena PII (CPF, salário). O developer quer client-side encryption — dados criptografados antes de chegar ao DynamoDB. Qual biblioteca AWS faz isso de forma per-attribute?',
  '[{"id":"A","text":"AWS Database Encryption SDK for DynamoDB (anteriormente DynamoDB Encryption Client) — define quais atributos são ENCRYPT_AND_SIGN, SIGN_ONLY ou DO_NOTHING"},{"id":"B","text":"DynamoDB server-side encryption resolve"},{"id":"C","text":"Não há solução managed"},{"id":"D","text":"Criptografar a tabela inteira como single blob"}]'::jsonb, 'A',
  '"(a) Database Encryption SDK for DynamoDB permite per-attribute action: ENCRYPT_AND_SIGN para PII (criptografa + autentica), SIGN_ONLY para attributes que precisam ser legíveis mas íntegros (como partition key), DO_NOTHING para atributos não sensíveis. Usa KMS data keys com caching. Permite queries em chaves SIGN_ONLY sem decrypt. (b) SSE-KMS do DynamoDB protege at-rest no disco mas dados são plaintext na API; blob único quebra queries. (c) Regra: PII em DynamoDB com queries = Database Encryption SDK per-attribute. (d) Ver AWS Database Encryption SDK Developer Guide."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["encryption-sdk","dynamodb","client-side-encryption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
