INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-158', 'aws-dva', 'O developer quer fazer queries por email criptografado em DynamoDB — ex: ''WHERE email = encrypted(value)''. Criptografia padrão (probabilistic AES-GCM) gera ciphertext diferente a cada chamada, quebrando equality. Qual técnica resolve?',
  '[{"id":"A","text":"Reduzir o tamanho da key"},{"id":"B","text":"Searchable / deterministic encryption — usa um IV derivado deterministicamente para que o mesmo plaintext gere o mesmo ciphertext (com trade-off: vaza igualdade de valores)"},{"id":"C","text":"Usar AES-ECB"},{"id":"D","text":"Impossível em DynamoDB"}]'::jsonb, 'B',
  '"(a) Deterministic encryption (AES-SIV ou AES-CBC com IV determinístico baseado em HMAC do plaintext) gera ciphertext reproducível, permitindo equality queries. Trade-off de segurança: revela quando dois valores são iguais (frequência atacável). AWS Database Encryption SDK suporta isso via ''SIGN_AND_INCLUDE_IN_ENCRYPTION_CONTEXT'' / beacon attributes para search. (b) Reduzir key compromete tudo; AES-ECB é quebrado/banido; é possível com cuidado. (c) Regra: search em campo criptografado = deterministic encryption + ciência do trade-off. (d) Ver Database Encryption SDK — Searchable encryption / beacons."'::jsonb,
  'Security', 'Security', 'hard', 'scenario', '["encryption-sdk","deterministic-encryption","dynamodb"]'::jsonb, 'ai-draft', 'active', now(), now()
)
