INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-159', 'aws-dva', 'O developer usa AWS Encryption SDK com data key caching configurado com max_age=600s e max_messages_encrypted=100. Para o mesmo encryption context, o SDK quando vai consultar o KMS para nova data key?',
  '[{"id":"A","text":"A cada criptografia (cache desativado nesse cenário)"},{"id":"B","text":"Apenas no boot"},{"id":"C","text":"Quando o primeiro dos limites é atingido: 600 segundos OU 100 mensagens (o que vier primeiro); ou se encryption context diferir"},{"id":"D","text":"Quando o KMS forçar via push"}]'::jsonb, 'C',
  '"(a) Data key cache invalida quando o primeiro limite é atingido: max_age (tempo de vida da data key plaintext em memória), max_messages_encrypted (operações criptografadas com a key), max_bytes_encrypted (volume de dados). Encryption context diferente também força nova data key — keys são cacheadas por hash do context. (b) Não é cache desativado nem só no boot; KMS não faz push. (c) Regra: cache invalidation = OR entre age/messages/bytes + context-keyed. (d) Ver AWS Encryption SDK — Data key caching parameters."'::jsonb,
  'Security', 'Security', 'medium', 'scenario', '["encryption-sdk","data-key-caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
