INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-sec-160', 'aws-dva', 'Após criptografar dados com o AWS Encryption SDK em region us-east-1 (CMK_A) e querer ler em eu-west-1 sem MRK, qual padrão arquitetural permite Decrypt sem dependência de us-east-1?',
  '[{"id":"A","text":"Impossível sem MRK"},{"id":"B","text":"Reduzir o tamanho da CMK"},{"id":"C","text":"Usar IAM cross-account"},{"id":"D","text":"Configurar múltiplas master keys (multi-CMK) no encrypt: cada CMK (uma por região) recebe sua própria copy da encrypted data key na mensagem; decrypt usa qualquer uma das CMKs disponíveis"}]'::jsonb, 'D',
  '"(a) AWS Encryption SDK permite envolver a data key com MÚLTIPLOS CMKs no Encrypt — cada CMK recebe seu próprio encrypted data key, todas anexadas à mensagem. No Decrypt, qualquer das CMKs (a primeira disponível) funciona. Padrão usado para failover de região antes de MRK existir. Trade-off: mensagem maior (uma entry por CMK). MRK é a evolução simplificada para o mesmo problema. (b) MRK é uma das soluções, não a única; tamanho da CMK não muda; IAM cross-account não resolve cripto-region. (c) Regra: HA cross-region cripto pré-MRK = multi-CMK no Encryption SDK. (d) Ver AWS Encryption SDK — Multiple master keys."'::jsonb,
  'Security', 'Security', 'hard', 'best-practice', '["encryption-sdk","multi-cmk","cross-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
