INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-001', 'aws-dva', 'Uma função Lambda em Node.js 20 está em produção há 3 dias. Os logs no CloudWatch mostram que 8% das invocações têm duração > 6s, enquanto 92% terminam em < 200ms. A métrica InitDuration aparece apenas nas invocações lentas. Qual a causa raiz e qual mitigação reduz a cauda longa sem reescrever o código?',
  '[{"id":"A","text":"Habilitar Provisioned Concurrency para manter execution environments quentes"},{"id":"B","text":"Aumentar o timeout da função para 30s"},{"id":"C","text":"Reduzir o memory size para 128MB"},{"id":"D","text":"Mover a função para outra região"}]'::jsonb, 'A',
  '"(a) InitDuration só aparece em cold starts — invocação que precisa baixar código, inicializar runtime e rodar handler init. 8% de cold starts é o padrão de tráfego com vales. (b) Aumentar timeout não acelera cold start, só permite mais tempo de execução; reduzir memória aumenta init duration (CPU é proporcional à memória); região não afeta cold start. (c) Provisioned Concurrency pré-inicializa N execution environments — invocações dentro do quota não pagam InitDuration. (d) Ver Lambda Developer Guide — Provisioned Concurrency."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","cold-start","provisioned-concurrency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
