INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-002', 'aws-dva', 'Uma API REST em API Gateway integrada com Lambda começa a retornar ''Access-Control-Allow-Origin header missing'' no console do browser quando o frontend (app.example.com) chama POST /orders. O GET /orders funciona. O developer já habilitou CORS na console do API Gateway. O que provavelmente ainda falta?',
  '[{"id":"A","text":"Habilitar HTTPS no CloudFront"},{"id":"B","text":"A Lambda precisa retornar o header Access-Control-Allow-Origin na resposta de integração proxy"},{"id":"C","text":"Adicionar permissão s3:GetObject à role"},{"id":"D","text":"Aumentar o timeout do API Gateway para 30s"}]'::jsonb, 'B',
  '"(a) Habilitar CORS na console cria o método OPTIONS (preflight) mas, em Lambda Proxy Integration, a resposta real (POST) é construída pela própria Lambda — ela precisa devolver os headers CORS no objeto de retorno. (b) HTTPS não tem relação; permissão S3 não causa erro CORS; timeout daria 504. (c) Regra: com proxy integration, CORS no console só cobre OPTIONS; methods reais dependem do código da Lambda. (d) Ver API Gateway Developer Guide — Enable CORS."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["api-gateway","cors","lambda-proxy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
