INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-003', 'aws-dva', 'Uma tabela DynamoDB com partition key ''tenantId'' tem 200 tenants. Logs mostram ProvisionedThroughputExceededException intermitente, mas o CloudWatch mostra que ConsumedWriteCapacityUnits da tabela está em 60% do provisionado. O que está acontecendo?',
  '[{"id":"A","text":"A região da tabela está incorreta"},{"id":"B","text":"Falta habilitar criptografia at-rest"},{"id":"C","text":"Hot partition — um tenantId concentra a maior parte do tráfego e excede a capacidade por partição"},{"id":"D","text":"O SDK está usando versão desatualizada"}]'::jsonb, 'C',
  '"(a) DynamoDB distribui capacidade por partição: cada partição tem ~1000 WCU/3000 RCU. Se um tenant grande recebe mais writes do que sua partição suporta, o cliente vê throttle mesmo com a tabela ''no geral'' subutilizada. (b) Região errada daria endpoint inválido, não throttle parcial; criptografia/SDK não causam ProvisionedThroughputExceeded. (c) Fix: redesign da partition key (composta com sufixo aleatório), write sharding ou migrar para on-demand. (d) Ver DynamoDB Developer Guide — Designing partition keys."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["dynamodb","hot-partition","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
