INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-004', 'aws-dva', 'Um developer precisa investigar latência ponta-a-ponta em uma cadeia: API Gateway → Lambda → DynamoDB → SNS. Os logs do CloudWatch mostram só a duração da Lambda. Qual abordagem permite ver onde o tempo é gasto em cada serviço da cadeia, com mapa visual?',
  '[{"id":"A","text":"Aumentar verbosity dos logs para DEBUG em todas as funções"},{"id":"B","text":"Criar um dashboard CloudWatch com a métrica Duration"},{"id":"C","text":"Usar VPC Flow Logs"},{"id":"D","text":"Habilitar X-Ray tracing no API Gateway e na Lambda; instrumentar o SDK AWS com X-Ray"}]'::jsonb, 'D',
  '"(a) X-Ray captura segments por serviço e mostra Service Map visual com latência por nó. Habilitar no API GW + active tracing na Lambda + AWSXRayCore SDK auto-instrumenta calls AWS (DynamoDB, SNS). (b) Logs DEBUG não correlacionam entre serviços sem trace-id; dashboard com Duration mostra só Lambda; VPC Flow Logs é tráfego de rede, não tracing de aplicação. (c) Regra: latência distribuída → X-Ray; logs locais → CloudWatch Logs. (d) Ver X-Ray Developer Guide — Service map."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'best-practice', '["x-ray","service-map","distributed-tracing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
