INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-005', 'aws-dva', 'Uma Lambda configurada com 512MB de memória e timeout 10s está com média de duração de 8.5s e ocasionalmente é encerrada por ''Task timed out after 10.00 seconds''. O CloudWatch Lambda Insights mostra CPU utilization a 99% durante toda a invocação. Qual ajuste reduz a duração?',
  '[{"id":"A","text":"Aumentar a memória alocada (Lambda escala CPU proporcionalmente à memória)"},{"id":"B","text":"Aumentar o timeout para 30s"},{"id":"C","text":"Mudar o runtime para Python"},{"id":"D","text":"Habilitar SnapStart"}]'::jsonb, 'A',
  '"(a) Em Lambda, CPU/network/IO escalam proporcionalmente à memória configurada. CPU 99% indica CPU-bound: mais memória = mais vCPU = execução mais rápida. (b) Aumentar timeout só permite mais tempo de execução, não acelera; trocar runtime não resolve CPU bound; SnapStart é para cold start (Java/.NET). (c) Regra: CPU-bound em Lambda → tune memory up; usar AWS Lambda Power Tuning para achar o ponto custo/perf ótimo. (d) Ver Lambda Developer Guide — Memory configuration."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'troubleshoot', '["lambda","memory-tuning","cpu-bound"]'::jsonb, 'ai-draft', 'active', now(), now()
)
