INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-006', 'aws-dva', 'Uma fila SQS recebe mensagens de uma API. Um worker Lambda processa as mensagens, mas 0.5% delas falham consistentemente (mensagem malformada). Após muitas tentativas, essas mensagens bloqueiam reprocessamento e o backlog cresce. Qual configuração resolve sem perder as mensagens com defeito?',
  '[{"id":"A","text":"Aumentar o visibility timeout da fila"},{"id":"B","text":"Configurar uma Dead Letter Queue com maxReceiveCount e redirecionar falhas após N tentativas"},{"id":"C","text":"Reduzir o batch size para 1"},{"id":"D","text":"Habilitar long polling"}]'::jsonb, 'B',
  '"(a) DLQ recebe automaticamente mensagens que excederam maxReceiveCount, liberando a main queue. Permite análise posterior dos poison messages sem perdê-los. (b) Visibility timeout só esconde a mensagem por mais tempo; batch=1 não evita o loop; long polling reduz API calls, não trata falhas. (c) Padrão: SQS main → maxReceiveCount=5 → DLQ; configurar alarm em ApproximateNumberOfMessagesVisible da DLQ. (d) Ver Lambda Developer Guide — Dead-letter queues."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'best-practice', '["sqs","dlq","poison-message"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
