INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-007', 'aws-dva', 'Uma aplicação web faz 50k GETs/segundo a uma tabela DynamoDB com chave única ProductId. Os custos de RCU estão altíssimos e a maioria das requisições é leitura repetida de poucos produtos populares. Qual solução reduz custo e latência sem mudar o código de leitura significativamente?',
  '[{"id":"A","text":"Migrar para Aurora MySQL"},{"id":"B","text":"Habilitar Streams e replicar para outra região"},{"id":"C","text":"Colocar DAX (DynamoDB Accelerator) na frente da tabela — cache write-through em memória"},{"id":"D","text":"Aumentar provisioned RCU"}]'::jsonb, 'C',
  '"(a) DAX é cache write-through nativo para DynamoDB; o SDK DAX é drop-in para o SDK DynamoDB. Reduz RCU consumption drasticamente em workloads read-heavy com hot keys. (b) Aurora é mudança de arquitetura grande; Streams é CDC, não cache; aumentar RCU resolve mas custa mais. (c) Regra: read-heavy + repetitivo → DAX (sub-ms) ou ElastiCache (se quiser controle fino); write-heavy → DAX ainda ajuda, mas menos. (d) Ver DynamoDB Developer Guide — DAX."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'scenario', '["dynamodb","dax","caching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
