INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-008', 'aws-dva', 'O developer publicou v2 do site estático via CloudFront + S3. Após o upload, usuários ainda veem a versão antiga do index.html, mesmo após hard refresh. O TTL do behavior é 86400s. Qual a forma correta de forçar atualização imediata?',
  '[{"id":"A","text":"Aguardar 24h pelo TTL expirar"},{"id":"B","text":"Deletar e recriar a distribution"},{"id":"C","text":"Mudar o protocolo para HTTPS"},{"id":"D","text":"Criar uma invalidation no CloudFront para ''/index.html'' (ou ''/*'')"}]'::jsonb, 'D',
  '"(a) CloudFront invalidation marca paths como inválidos no cache de edge; próxima requisição força fetch da origin. Para SPA, normalmente invalidar /index.html basta; assets versionados por hash não precisam. (b) Esperar 24h não é opção em produção; recriar distribution causa downtime e novo domain; HTTPS não tem relação. (c) Boa prática: versionar assets (app.[hash].js) — só invalidar HTML; primeiras 1000 paths/mês são free. (d) Ver CloudWatch monitoring + CloudFront docs (consulte API GW dev guide referência geral)."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'troubleshoot', '["cloudfront","cache-invalidation","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
