INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-009', 'aws-dva', 'Uma Lambda em VPC privada precisa chamar DynamoDB. Após mover a função para a VPC (para acessar RDS), DynamoDB começa a retornar timeout de conexão. NAT Gateway existe mas custa caro com o volume. Qual solução elimina o problema e reduz custo?',
  '[{"id":"A","text":"Criar um VPC Gateway Endpoint para DynamoDB (zero custo de NAT, tráfego permanece privado)"},{"id":"B","text":"Remover a Lambda da VPC"},{"id":"C","text":"Aumentar o tamanho do NAT Gateway"},{"id":"D","text":"Habilitar IPv6 na subnet"}]'::jsonb, 'A',
  '"(a) Gateway Endpoints (S3 e DynamoDB) são gratuitos, adicionam rota na route table da subnet e mantêm tráfego dentro da AWS sem precisar de NAT. (b) Remover da VPC quebra acesso a RDS; NAT não tem ''tamanho'' configurável (scales auto, mas paga por GB processado); IPv6 não é a raiz do problema. (c) Regra: Lambda em VPC + service AWS público → preferir VPC Endpoint (Gateway pra S3/DDB, Interface pra outros). (d) Ver Lambda Developer Guide — Configuring VPC."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","vpc","vpc-endpoint","nat-gateway"]'::jsonb, 'ai-draft', 'active', now(), now()
)
