INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-010', 'aws-dva', 'Um developer quer alertar quando a taxa de erros 5xx da Lambda ''CheckoutFn'' exceder 1% das invocações em janela de 5 minutos, mas só durante horário comercial. Qual configuração no CloudWatch faz isso?',
  '[{"id":"A","text":"Criar alarm na métrica Errors \u003e 1 absoluto"},{"id":"B","text":"Criar metric math expression Errors/Invocations e alarm com threshold 0.01 e evaluation period em horário comercial"},{"id":"C","text":"Habilitar Lambda Insights e nada mais"},{"id":"D","text":"Criar um log group e usar Logs Insights manualmente todo dia"}]'::jsonb, 'B',
  '"(a) Metric math (m1/m2 com IDs Errors/Invocations) computa a taxa em tempo de avaliação do alarm. Combinado com EventBridge schedule de habilitar/desabilitar alarm, cobre janela horário. (b) Alarm em Errors absolutos não escala — 10 erros em 100 invocações é diferente de 10 em 100k; Insights é diagnóstico, não alerting; Logs Insights manual não é alarm. (c) Padrão SRE: alarms em error rate (%), não em error count. (d) Ver CloudWatch User Guide — Metric math."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["cloudwatch","alarm","metric-math","error-rate"]'::jsonb, 'ai-draft', 'active', now(), now()
)
