INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-011', 'aws-dva', 'Um quiz aleatório de 1000 traces do X-Ray para a API de checkout mostra que 75% dos traces vêm do health check /health. O developer quer reduzir custo de tracing sem perder visibilidade dos endpoints críticos. Qual ação tomar?',
  '[{"id":"A","text":"Desabilitar X-Ray completamente"},{"id":"B","text":"Aumentar o número de daemons X-Ray"},{"id":"C","text":"Criar uma sampling rule customizada que reduza fixed_rate de /health e aumente o sampling de /checkout"},{"id":"D","text":"Migrar todos os traces para CloudWatch Logs"}]'::jsonb, 'C',
  '"(a) X-Ray Sampling Rules permitem regras por host/method/url com fixed_rate (% sample) e reservoir (mínimo/s). Reduzir fixed_rate de /health para 0.01 e setar /checkout para 1.0 mantém visibilidade onde importa. (b) Desabilitar perde toda visibilidade; daemons não controlam volume; logs não substituem traces correlacionados. (c) Regra: sampling rules são ordenadas por prioridade — específicas (URL exata) antes da default. (d) Ver X-Ray Developer Guide — Sampling rules."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["x-ray","sampling","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
