INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-012', 'aws-dva', 'Em uma aplicação de e-commerce com X-Ray, o developer quer filtrar traces por customerId para investigar reclamações de um cliente específico. Atualmente os segments têm só o request HTTP raw. O que ele deve adicionar ao código?',
  '[{"id":"A","text":"Metadata com customerId (indexada e filtrável)"},{"id":"B","text":"Tag no recurso AWS"},{"id":"C","text":"Comentário no código"},{"id":"D","text":"Annotation com customerId (indexada e filtrável via console)"}]'::jsonb, 'D',
  '"(a) X-Ray Annotations são pares key-value indexados (até 50 por segment) — aparecem em filter expressions tipo `annotation.customerId = \"123\"`. (b) Metadata também armazena dados arbitrários, mas NÃO é indexada (não filtrável); tags AWS são para billing/IAM; comentário no código não vai pro trace. (c) Regra: Annotation = busca/filtro; Metadata = contexto adicional não-indexável (payloads grandes). (d) Ver X-Ray Developer Guide — Annotations and metadata."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'recall', '["x-ray","annotations","metadata"]'::jsonb, 'ai-draft', 'active', now(), now()
)
