INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-013', 'aws-dva', 'Uma Lambda escreve logs estruturados em JSON. O developer quer extrair P95 de latência por endpoint para um dashboard, mas sem custo de métrica custom emitida via PutMetricData. Qual abordagem é mais eficiente?',
  '[{"id":"A","text":"Embedded Metric Format (EMF) — logar JSON com schema _aws.CloudWatchMetrics e CloudWatch extrai métricas dos logs automaticamente"},{"id":"B","text":"PutMetricData em cada invocação"},{"id":"C","text":"Salvar em S3 e analisar com Athena diariamente"},{"id":"D","text":"Usar tags no log group"}]'::jsonb, 'A',
  '"(a) EMF permite emitir métricas e logs estruturados na mesma chamada de log (stdout). CloudWatch extrai métricas a partir do JSON sem cost adicional de PutMetricData API. (b) PutMetricData custa ~$0.30/milhão e adiciona latência de chamada; Athena tem latência alta; tag em log group é organização, não métrica. (c) Regra: alta cardinalidade + log já existente → EMF; baixa freq + crítico → PutMetricData. (d) Ver CloudWatch Logs User Guide — Embedded Metric Format."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["cloudwatch","emf","custom-metrics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
