INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-014', 'aws-dva', 'Após um incidente, o time precisa saber quantas requisições /api/orders tiveram status 500 no log da última hora. Os logs estão em CloudWatch Logs em formato JSON. Qual ferramenta executa essa consulta ad-hoc com aggregations?',
  '[{"id":"A","text":"Baixar todos os logs e usar grep"},{"id":"B","text":"CloudWatch Logs Insights com query: filter status=500 and url=''/api/orders'' | stats count()"},{"id":"C","text":"Criar uma métrica e esperar 1h"},{"id":"D","text":"Abrir cada log stream manualmente"}]'::jsonb, 'B',
  '"(a) Logs Insights tem linguagem própria com filter, stats, parse, sort. Suporta JSON nativo (campos viram referenciáveis) e roda em segundos sobre TBs de log. (b) grep não escala e perde estrutura JSON; criar métrica não cobre passado retrocedidamente; revisar stream manual é inviável. (c) Pattern útil: filter @message like /ERROR/ | stats count() by bin(5m). (d) Ver CloudWatch Logs User Guide — Logs Insights."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'best-practice', '["cloudwatch","logs-insights","query"]'::jsonb, 'ai-draft', 'active', now(), now()
)
