INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-015', 'aws-dva', 'Uma API Gateway REST integra com Lambda e retorna 502 ''Bad Gateway'' aleatoriamente. Os logs da Lambda mostram a função executando com sucesso e retornando o objeto esperado. O developer suspeita do formato da resposta. Qual a causa mais provável em Lambda Proxy Integration?',
  '[{"id":"A","text":"A Lambda tem permissão insuficiente em IAM"},{"id":"B","text":"O CORS está desabilitado"},{"id":"C","text":"A resposta da Lambda não está no formato esperado pelo proxy integration ({ statusCode, body, headers })"},{"id":"D","text":"A região do API Gateway é diferente da Lambda"}]'::jsonb, 'C',
  '"(a) Em proxy integration, API GW espera JSON com keys statusCode (int), body (string), headers (object), isBase64Encoded (bool). Retornar objeto solto causa 502. (b) IAM faltando daria 403, CORS daria erro de browser, region diferente daria erro de invocação no setup. (c) Fix comum: garantir body sempre como JSON.stringify do payload, statusCode sempre int. (d) Ver API Gateway Developer Guide — Lambda proxy integration."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["api-gateway","lambda-proxy","502"]'::jsonb, 'ai-draft', 'active', now(), now()
)
