INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-016', 'aws-dva', 'Uma aplicação Node.js consulta DynamoDB via GSI ''orders-by-status-index''. Após adicionar novos campos à projection, queries começam a retornar ''ValidationException: One or more parameter values were invalid: Query condition missed key schema element''. O que o developer está fazendo de errado?',
  '[{"id":"A","text":"Está usando GetItem em vez de Query"},{"id":"B","text":"Não pagou pela capacidade do GSI"},{"id":"C","text":"Precisa habilitar streams"},{"id":"D","text":"Está faltando o campo PartitionKey do GSI na expressão Query"}]'::jsonb, 'D',
  '"(a) Query no GSI exige KeyConditionExpression com a partition key do índice (e opcionalmente sort key). Sem ela, DynamoDB rejeita pois Query é point-or-range em uma partition. (b) GetItem é point em PK da tabela base; capacity do GSI causa ThrottlingException, não ValidationException; streams não tem relação. (c) Fix: KeyConditionExpression: ''status = :s'' + ExpressionAttributeValues. Sem PK do GSI, usa Scan (caro). (d) Ver DynamoDB Developer Guide — Querying secondary indexes."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["dynamodb","gsi","query"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
