INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-017', 'aws-dva', 'Uma Lambda Java demora 4-6s no primeiro request após deploy (cold start) por inicialização do Spring. O time aceita pagar por Provisioned Concurrency, mas quer alternativa mais barata para o mesmo runtime Java. Qual recurso AWS Lambda atende?',
  '[{"id":"A","text":"SnapStart — restaura snapshot do runtime inicializado, reduzindo cold start em até 90%"},{"id":"B","text":"Aumentar memória para 10GB"},{"id":"C","text":"Trocar para zip layer"},{"id":"D","text":"Usar container image"}]'::jsonb, 'A',
  '"(a) SnapStart (Java 11+, Python 3.12+, .NET 8+) tira snapshot do execution environment após init e restaura em invocações futuras — cold start cai drasticamente sem custo de Provisioned. (b) Aumentar memory ajuda mas não na ordem de magnitude do SnapStart; layer/container não reduzem init time intrinsecamente. (c) Cuidado: SnapStart requer cuidado com state que muda (UUID, conexões) — hooks beforeCheckpoint/afterRestore. (d) Ver Lambda Developer Guide — SnapStart."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'scenario', '["lambda","snapstart","java","cold-start"]'::jsonb, 'ai-draft', 'active', now(), now()
)
