INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-018', 'aws-dva', 'Em uma aplicação stateful, sessões de usuário são armazenadas em Redis (ElastiCache). Após scale-out do cluster, alguns usuários reportam logout aleatório. O developer não usa cluster mode. Qual padrão de cache provavelmente está sendo violado?',
  '[{"id":"A","text":"Lazy loading sem TTL"},{"id":"B","text":"Falta de consistent hashing — adicionar/remover nó move keys e quebra session affinity"},{"id":"C","text":"ElastiCache não suporta sessões"},{"id":"D","text":"Falta criptografia at-rest"}]'::jsonb, 'B',
  '"(a) Em Redis cluster mode disabled com replicas, scale-out replica reads. Mas se o app usa multiple primary nodes via client-side hashing simples (sem consistent hashing), reshard re-mapeia keys. Em cluster mode enabled, o slot mapping cuida disso. (b) TTL/encryption não causam logout; ElastiCache absolutamente suporta sessões (use case canonico). (c) Fix: habilitar cluster mode + Redis cluster client; ou usar single primary + replicas para HA. (d) Ver ElastiCache User Guide — Cluster mode."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["elasticache","redis","consistent-hashing","sessions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
