INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-019', 'aws-dva', 'Uma Lambda assíncrona invocada via SNS falha em ~2% dos events com erro de DynamoDB temporário. As mensagens são perdidas. O developer quer reter e reprocessar essas falhas automaticamente. Qual a configuração correta no Lambda?',
  '[{"id":"A","text":"Configurar uma DLQ no SNS Topic apenas"},{"id":"B","text":"Aumentar a memória da Lambda"},{"id":"C","text":"Configurar uma Dead Letter Queue (SQS) na própria Lambda + ajustar Maximum Retry Attempts"},{"id":"D","text":"Mudar a invocação para sync"}]'::jsonb, 'C',
  '"(a) Lambda async (event source SNS, S3, etc.) tem 2 retries internos por default; após falhar, envia para a DLQ configurada na função (SQS ou SNS) ou On-failure destination. (b) DLQ no SNS só pega falhas de delivery do SNS, não de execução do consumer; mais memória não trata erros; sync muda o modelo todo. (c) Padrão moderno: usar Lambda Destinations (onSuccess/onFailure) em vez de DLQ — mais expressivo, evento com payload completo. (d) Ver Lambda Developer Guide — Async invocation + DLQs."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","async","dlq","destinations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
