INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-020', 'aws-dva', 'O CloudWatch mostra que API Gateway está retornando 429 Too Many Requests para alguns clientes. O developer não configurou rate limits no método. Qual limite default da AWS está sendo atingido?',
  '[{"id":"A","text":"Limite por método (não existe default)"},{"id":"B","text":"Limite de timeout do Lambda"},{"id":"C","text":"Limite de IPs por VPC"},{"id":"D","text":"Account-level throttle: 10.000 req/s, 5.000 burst (default por região)"}]'::jsonb, 'D',
  '"(a) Por default, API Gateway tem soft limit account-wide de 10k req/s sustained e 5k burst por região. Excedendo, API retorna 429 e a métrica 4XXError sobe. (b) Limites por método existem mas são opcionais; Lambda timeout dá 504; IPs por VPC não causam 429 no APIGW. (c) Fix: configurar usage plans com API keys para isolar tenants, ou pedir aumento de quota; monitorar ThrottlingException no CloudWatch. (d) Ver API Gateway Developer Guide — Throttling."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["api-gateway","throttling","429"]'::jsonb, 'ai-draft', 'active', now(), now()
)
