INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-021', 'aws-dva', 'Uma aplicação grava em DynamoDB e em Redis ElastiCache (cache-aside pattern). Após updates no DB, leituras retornam valor antigo por minutos. O TTL no cache é 1h. Qual ajuste mantém cache rápido e dados consistentes?',
  '[{"id":"A","text":"Implementar write-through: ao escrever no DB, invalidar/atualizar a key no cache imediatamente"},{"id":"B","text":"Aumentar o TTL para 24h"},{"id":"C","text":"Trocar Redis por Memcached"},{"id":"D","text":"Habilitar replicas read-only"}]'::jsonb, 'A',
  '"(a) Cache-aside puro só atualiza cache no read miss. Pra evitar staleness, no write: DEL key (ou SET com novo valor). Pattern write-through escreve sincrono em ambos. (b) TTL maior piora stale; Memcached não resolve consistency; replicas leem o mesmo dado stale. (c) Padrão híbrido: write-through + TTL curto (segundos) como safety net. Avaliar trade-offs: write-through aumenta latência de write. (d) Ver ElastiCache for Redis User Guide — Caching strategies."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["elasticache","cache-aside","consistency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
