INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-022', 'aws-dva', 'O developer precisa visualizar de onde vem cada milissegundo da request /checkout no X-Ray. Atualmente os segments mostram só os calls AWS (DynamoDB, S3) capturados pelo SDK. Como adicionar visibilidade aos blocos do código interno (ex: ''validate_cart'', ''compute_tax'')?',
  '[{"id":"A","text":"Aumentar a sampling rate"},{"id":"B","text":"Criar subsegments customizados via SDK X-Ray dentro do código"},{"id":"C","text":"Habilitar mais logs no CloudWatch"},{"id":"D","text":"Ativar Lambda Insights"}]'::jsonb, 'B',
  '"(a) AWSXRay.captureAsyncFunc(''validate_cart'', segment => {...}) ou begin_subsegment/end_subsegment cria nodos extras no waterfall, mostrando duração de cada bloco. (b) Sampling rate muda quantidade de traces, não granularidade; logs e Insights são complementares mas não mostram waterfall. (c) Boa prática: subsegments para operações > 50ms ou críticas; metadata em cada para contexto. (d) Ver X-Ray Developer Guide — Subsegments."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["x-ray","subsegments","instrumentation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
