INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-023', 'aws-dva', 'Uma Lambda em VPC privada sobe 200 invocações/seg em pico. Logs começam a mostrar ''EC2ThrottledException'' e ''Hyperplane ENI not available''. O que está acontecendo?',
  '[{"id":"A","text":"A região da Lambda está cheia"},{"id":"B","text":"A Lambda precisa de mais memória"},{"id":"C","text":"Falta de ENIs/IPs disponíveis na subnet — esgotou o pool"},{"id":"D","text":"Falta habilitar X-Ray"}]'::jsonb, 'C',
  '"(a) Lambda em VPC usa Hyperplane ENIs compartilhadas por concurrency. Se a subnet tem IP CIDR pequeno, esgota IPs disponíveis e Lambda não escala. (b) Região cheia daria outro erro; memória é unrelated; X-Ray não impacta network setup. (c) Fix: usar subnets com /22 ou maior em múltiplas AZs; monitorar AvailableIPCount; em alguns casos remover Lambda da VPC e usar VPC endpoints. (d) Ver Lambda Developer Guide — VPC networking."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["lambda","vpc","eni","scaling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
