INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-024', 'aws-dva', 'Uma tabela DynamoDB on-demand está com latência P99 de 300ms para Query, esperado < 20ms. O CloudWatch mostra que SuccessfulRequestLatency aumenta proporcional ao item size. Os items têm em média 200KB. Qual otimização ajuda?',
  '[{"id":"A","text":"Aumentar provisioned capacity"},{"id":"B","text":"Habilitar PITR"},{"id":"C","text":"Mudar a região para us-east-1"},{"id":"D","text":"Mover blobs grandes para S3 e armazenar apenas pointer (URL/key) no DynamoDB"}]'::jsonb, 'D',
  '"(a) Items grandes (> 4KB) consomem mais RCU/WCU e aumentam latência. Pattern recomendado: armazenar metadata no DDB + blob no S3 (referenciado por key). DynamoDB items têm limite hard de 400KB. (b) On-demand não tem provisioning; PITR é backup; região não muda perfil. (c) Outra opção: comprimir o payload antes de gravar (gzip → menor item) se ainda for textual. (d) Ver DynamoDB Developer Guide — Best practices for storing large attribute values."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["dynamodb","item-size","s3-offload"]'::jsonb, 'ai-draft', 'active', now(), now()
)
