INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-025', 'aws-dva', 'A métrica IteratorAge da event source mapping Lambda ↔ Kinesis cresce continuamente. Os logs mostram a Lambda processando OK e sem erros. O que essa métrica indica e como resolver?',
  '[{"id":"A","text":"Lambda está atrasada lendo do stream; aumentar ParallelizationFactor ou shard count"},{"id":"B","text":"Lambda está fast enough — nada a fazer"},{"id":"C","text":"Stream está corrompido"},{"id":"D","text":"Falta habilitar encryption"}]'::jsonb, 'A',
  '"(a) IteratorAge = idade em ms do registro mais antigo ainda não processado. Crescente = backlog acumulando. (b) Solução: aumentar ParallelizationFactor (até 10 concurrent Lambdas por shard) ou adicionar shards (Kinesis); otimizar batch processing na Lambda. Corrupção daria erro de read; encryption não afeta lag. (c) Pattern: alarm em IteratorAge > 60000ms (1min) ou crescente por 5 min. (d) Ver Lambda Developer Guide — Kinesis event source."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","kinesis","iterator-age"]'::jsonb, 'ai-draft', 'active', now(), now()
)
