INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-026', 'aws-dva', 'Após habilitar X-Ray active tracing no API Gateway e Lambda, o developer ainda não vê os calls a um RDS PostgreSQL nos traces. O SDK X-Ray está importado. O que está faltando?',
  '[{"id":"A","text":"Configurar a region"},{"id":"B","text":"Patchear o driver SQL (pg/psycopg2) via aws-xray-sdk para capturar SQL queries como subsegments"},{"id":"C","text":"Reiniciar a função"},{"id":"D","text":"Habilitar Enhanced Monitoring no RDS"}]'::jsonb, 'B',
  '"(a) X-Ray SDK tem patcher para libs comuns: aws-xray-sdk-core patch() para psycopg2/pg/requests/http. Sem patch, calls saem do trace. (b) Region é autodescoberta; reiniciar não corrige falta de instrumentação; Enhanced Monitoring é OS metrics no RDS, não tracing. (c) Em Node.js: AWSXRay.captureMySQL(require(''mysql'')); em Python: patch_all() ou patch([''psycopg2'']). (d) Ver X-Ray Developer Guide — Tracing SQL queries."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["x-ray","sdk","sql-tracing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
