INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-027', 'aws-dva', 'Uma Lambda usando Secrets Manager para buscar credencial RDS no handler tem cold start de 1.5s extra. O developer não quer expor a senha como env var em plaintext. Qual otimização preserva segurança e reduz latência?',
  '[{"id":"A","text":"Colocar a senha em env var"},{"id":"B","text":"Aumentar memory para 10GB"},{"id":"C","text":"Mover GetSecretValue para fora do handler (init phase), cacheando o secret na global scope"},{"id":"D","text":"Buscar a senha do S3"}]'::jsonb, 'C',
  '"(a) Código fora do handler roda só uma vez no init de cada execution environment; cached em variável global é reutilizado nas invocações subsequentes. Combinado com AWS Parameters and Secrets Lambda Extension (cache layer), reduz ainda mais. (b) Env var plaintext é antipadrão; mais memory não muda I/O network; S3 não tem o mesmo modelo de rotação/auditoria. (c) Adicionalmente: implementar rotation handler para invalidar cache global após X minutos. (d) Ver Lambda Developer Guide — Best practices."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["lambda","secrets-manager","init-phase"]'::jsonb, 'ai-draft', 'active', now(), now()
)
