INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-028', 'aws-dva', 'O developer cria um CloudWatch alarm para Lambda Errors > 0 mas ele dispara constantemente em horário noturno quando há 0 invocações. O comportamento esperado seria ''INSUFFICIENT_DATA → OK''. Qual configuração corrige?',
  '[{"id":"A","text":"Aumentar evaluation period"},{"id":"B","text":"Mudar para AlarmAction=SNS"},{"id":"C","text":"Remover o alarm"},{"id":"D","text":"TreatMissingData = notBreaching (trata datapoints faltantes como OK)"}]'::jsonb, 'D',
  '"(a) TreatMissingData tem 4 opções: missing (default), notBreaching, breaching, ignore. Errors sem invocações = sem datapoint, default vai pra INSUFFICIENT_DATA, mas se default for missing pode falsamente alertar. notBreaching trata explicitamente como OK. (b) Evaluation period não muda comportamento de dados ausentes; ações são para notificação; remover perde monitoring. (c) Pattern: para métricas count-based com lulls, sempre notBreaching. (d) Ver CloudWatch User Guide — Configuring how alarms treat missing data."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["cloudwatch","alarm","treat-missing-data"]'::jsonb, 'ai-draft', 'active', now(), now()
)
