INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-029', 'aws-dva', 'Uma fila SQS Standard recebe 5k mensagens/seg. A Lambda consumer processa em ~200ms cada e tem reserved concurrency = 10. O backlog cresce mas a Lambda nunca passa de 10 invocações simultâneas. Por quê?',
  '[{"id":"A","text":"Reserved concurrency = 10 é o hard cap; Lambda nunca passará disso"},{"id":"B","text":"SQS está com defeito"},{"id":"C","text":"Visibility timeout está baixo"},{"id":"D","text":"Falta permissão IAM"}]'::jsonb, 'A',
  '"(a) Reserved concurrency reserva e LIMITA simultaneamente. Com 10, no máximo 10 execution environments paralelos; com 200ms cada, throughput máximo = 50 msg/s. 5k msg/s → backlog cresce. (b) SQS funciona normalmente; visibility timeout afeta retry; sem permissão daria erro nos logs. (c) Fix: aumentar reserved concurrency (ou remover limit) e considerar batch size + maxBatchingWindow. (d) Ver Lambda Developer Guide — Reserved concurrency."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","sqs","reserved-concurrency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
