INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-030', 'aws-dva', 'Após mudança de código, uma Lambda começou a vazar memória — duração estável, mas Max Memory Used cresce a cada invocação até atingir o limit e a função falhar. O que está acontecendo no modelo de execução do Lambda?',
  '[{"id":"A","text":"Cada invocação é uma VM nova — vazamento não persiste"},{"id":"B","text":"Execution environment é reutilizado; variáveis globais e listeners não-removidos acumulam state entre invocações"},{"id":"C","text":"AWS rotaciona o environment a cada minuto"},{"id":"D","text":"Falta de IAM permission"}]'::jsonb, 'B',
  '"(a) Lambda reusa execution environments por minutos/horas se houver tráfego. Globals (caches, arrays append-only, event emitters) acumulam entre invocações. (b) Não é VM nova por call; rotação não é a cada minuto; IAM não causa memory leak. (c) Fix: limpar/limitar caches no início do handler, remover listeners, evitar push em arrays globais. Monitorar via Max Memory Used em logs e Lambda Insights. (d) Ver Lambda Developer Guide — Execution environment."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["lambda","memory-leak","execution-environment"]'::jsonb, 'ai-draft', 'active', now(), now()
)
