INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-031', 'aws-dva', 'Em uma busca DynamoDB, queries com FilterExpression retornam poucos items mas consomem RCU equivalente a milhares. Por quê?',
  '[{"id":"A","text":"DynamoDB tem bug de cobrança"},{"id":"B","text":"Filter usa criptografia extra"},{"id":"C","text":"FilterExpression é aplicado APÓS o Query/Scan ler os items — RCU é cobrado por items lidos, não retornados"},{"id":"D","text":"Indexes não funcionam com Filter"}]'::jsonb, 'C',
  '"(a) Query/Scan lê items conforme KeyCondition; FilterExpression descarta no servidor antes de devolver — mas RCU já foi consumido. (b) Sem bug; sem cripto especial; indexes funcionam com Filter mas ainda lê o conjunto pré-filter. (c) Fix: redesign tabela com GSI cuja PK = critério de filtragem, ou usar KeyConditionExpression em vez de Filter. Última opção: Scan + Filter só quando inevitável. (d) Ver DynamoDB Developer Guide — Filter expressions."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["dynamodb","filter-expression","rcu"]'::jsonb, 'ai-draft', 'active', now(), now()
)
