INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-032', 'aws-dva', 'Logs Insights mostra que a média de duration da Lambda saltou de 200ms para 1200ms após 14h ontem. Não houve deploy. Qual feature de CloudWatch permite identificar visualmente qual dimensão (versão, region, runtime) divergiu?',
  '[{"id":"A","text":"CloudWatch Anomaly Detection com banda de confiança"},{"id":"B","text":"Athena query"},{"id":"C","text":"Renomear o log group"},{"id":"D","text":"CloudWatch ServiceLens / Contributor Insights por dimensão"}]'::jsonb, 'D',
  '"(a) Contributor Insights analisa logs e identifica top contributors (IPs, error codes, paths) que dominam a métrica. Em conjunto com ServiceLens (X-Ray + CloudWatch), correlaciona dimensões. Anomaly Detection só sinaliza desvio na série única. (b) Athena é offline, lento; renomear log group não diagnostica. (c) Use case: detectar ''qual rota está lenta hoje'' ou ''qual customerId está consumindo mais quota''. (d) Ver CloudWatch User Guide — Contributor Insights."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'scenario', '["cloudwatch","contributor-insights","anomaly"]'::jsonb, 'ai-draft', 'active', now(), now()
)
