INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-033', 'aws-dva', 'Uma Lambda recebe payload de 8MB via API Gateway REST e retorna 413 ''Request Entity Too Large''. O que isso indica?',
  '[{"id":"A","text":"API Gateway REST tem limite de payload de 10MB e Lambda de 6MB sync — payload excedeu"},{"id":"B","text":"A Lambda está com timeout"},{"id":"C","text":"Falta permissão IAM"},{"id":"D","text":"API Gateway está desligado"}]'::jsonb, 'A',
  '"(a) Limites hard: API Gateway REST max payload = 10MB; Lambda sync invocation = 6MB request / 6MB response. Sobre 6MB → 413 da própria Lambda; sobre 10MB → 413 do API GW. (b) Timeout daria 504; IAM daria 403; desligado daria 5xx. (c) Fix: para uploads grandes, usar pre-signed URL S3 → cliente faz upload direto → Lambda processa após. Para responses, retornar pre-signed URL de download. (d) Ver Lambda Developer Guide — Quotas."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["api-gateway","lambda","payload-limit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
