INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-034', 'aws-dva', 'Uma Lambda em Python 3.12 chama uma API externa via boto3. Em horários de pico, ConnectionError aparece. O developer suspeita de connection pool. Que padrão evita reabrir conexões TLS a cada invocação?',
  '[{"id":"A","text":"Instanciar dentro do handler para garantir isolamento"},{"id":"B","text":"Instanciar o client boto3 (e sessions HTTPS) FORA do handler para reutilizar entre invocações"},{"id":"C","text":"Aumentar memory"},{"id":"D","text":"Habilitar X-Ray"}]'::jsonb, 'B',
  '"(a) Clients criados em init phase persistem em execution environment reusado — TCP/TLS handshake só na primeira invocação. boto3 client tem connection pool urllib3. (b) Dentro do handler reabre conexão em toda invocação (custo de ~100ms TLS); memory não corrige; X-Ray observa, não corrige. (c) Padrão: configurar boto3 client com retry config (adaptive) + timeout explícito; usar AWS_LAMBDA_RUNTIME_API keep-alive env var (HTTP keep-alive global). (d) Ver Lambda Developer Guide — Best practices."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["lambda","connection-pool","boto3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
