INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-035', 'aws-dva', 'Um stream Kinesis tem 4 shards. Lambda consumer tem batch size 100 e processa em 500ms. ApproximateNumberOfMessagesVisible não existe (não é SQS), mas IteratorAge sobe. Sabendo que batch size é 100 e cada shard suporta 1000 records/sec, qual ajuste mais provável aumenta throughput sem aumentar shards?',
  '[{"id":"A","text":"Mudar para SQS"},{"id":"B","text":"Habilitar encryption"},{"id":"C","text":"Aumentar ParallelizationFactor para 10 (Lambda processa até 10 batches simultaneous por shard, mantendo ordem por partition key)"},{"id":"D","text":"Reduzir batch size para 10"}]'::jsonb, 'C',
  '"(a) ParallelizationFactor (1-10) é específico de event source mapping Kinesis/DynamoDB Streams: permite múltiplos invocations simultâneos por shard, ordenados por partition key (FIFO mantém-se por key). (b) SQS muda semântica; encryption não muda throughput; reduzir batch size aumenta overhead. (c) Caveat: se ordering global é requirement, ParallelizationFactor=1; se ordering por key basta, aumenta. (d) Ver Lambda Developer Guide — Kinesis ParallelizationFactor."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["lambda","kinesis","parallelization-factor"]'::jsonb, 'ai-draft', 'active', now(), now()
)
