INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-036', 'aws-dva', 'Após habilitar lambda destinations (onFailure → SQS), mensagens com erro reaparecem na SQS mesmo após retry esgotado. O developer quer entender qual destination é usado para async invocations falhas e parado.',
  '[{"id":"A","text":"DLQ e Destinations não funcionam juntos"},{"id":"B","text":"Destinations só recebem sucesso"},{"id":"C","text":"Sempre retorna ao API caller"},{"id":"D","text":"OnFailure destination é entregue após esgotar Maximum Retry Attempts (default 2)"}]'::jsonb, 'D',
  '"(a) Lambda async: 1) tenta executar; 2) on error retry até MaximumRetryAttempts; 3) se ainda falhar, manda ao OnFailure destination (SQS/SNS/EventBridge/Lambda) OU DLQ legacy. Destinations payload inclui requestContext + erro. (b) Destinations substituem DLQ; usar um ou outro; ambos é redundante; sucesso vai pra OnSuccess. (c) Pattern: OnFailure → SQS pra DLT humano-readable; OnSuccess → EventBridge pra workflow continuation. (d) Ver Lambda Developer Guide — Destinations."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'recall', '["lambda","destinations","async"]'::jsonb, 'ai-draft', 'active', now(), now()
)
