INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-037', 'aws-dva', 'Uma aplicação tem CloudFront na frente de S3 (origin) servindo imagens. Um asset ''logo.png'' foi atualizado mas algumas regiões geográficas ainda servem versão antiga 12h depois, mesmo após invalidation ''/logo.png''. Qual o motivo mais provável?',
  '[{"id":"A","text":"Cliente está com cache local; CloudFront já serviu versão nova"},{"id":"B","text":"S3 está em outra região"},{"id":"C","text":"Invalidação não funcionou"},{"id":"D","text":"Falta de criptografia"}]'::jsonb, 'A',
  '"(a) CloudFront invalidation propaga em ~5-15min em todos POPs. Após 12h, edge caches estão limpos. O ainda-velho vem do browser cache (Cache-Control headers), service worker, ou CDN intermediário do ISP. (b) S3 em outra região só adiciona latência, não causa stale; invalidação após 12h funcionou; criptografia não tem relação. (c) Fix: usar fingerprint nas URLs (logo.abc123.png) ou headers Cache-Control max-age curto + ETag para browsers. (d) Ver CloudWatch User Guide / CloudFront Developer Guide."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["cloudfront","cache","browser-cache"]'::jsonb, 'ai-draft', 'active', now(), now()
)
