INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-038', 'aws-dva', 'Uma API Gateway REST com Lambda Authorizer está retornando 401 Unauthorized mesmo com token válido em 5% dos requests. O developer suspeita que o cache do authorizer está retornando policy stale após troca de role. Qual ajuste resolve sem desabilitar cache?',
  '[{"id":"A","text":"Desativar HTTPS"},{"id":"B","text":"Reduzir o TTL do authorizer cache para um valor compatível com a frequência de mudança de policy"},{"id":"C","text":"Aumentar o timeout"},{"id":"D","text":"Remover o authorizer"}]'::jsonb, 'B',
  '"(a) Authorizer cache (até 1h, default 5min) armazena policy IAM por token. Após troca de permissões, cache fica stale até TTL expirar. Reduzir TTL (ex: 30s) trade-off: mais invocações ao authorizer. (b) HTTPS unrelated; timeout não afeta auth; remover authorizer perde segurança. (c) Alternativa: invalidar cache via API admin (recreate authorizer) em deploys de policy. (d) Ver API Gateway Developer Guide — Lambda Authorizer."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["api-gateway","authorizer","cache-ttl"]'::jsonb, 'ai-draft', 'active', now(), now()
)
