INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-039', 'aws-dva', 'Uma DynamoDB query usa ConsistentRead=true (strongly consistent). O developer nota que custos de RCU dobraram. Por quê e quando vale a pena?',
  '[{"id":"A","text":"Strongly consistent custa metade"},{"id":"B","text":"Não há diferença de custo"},{"id":"C","text":"Strongly consistent read custa 2x mais RCU; só usar quando read-after-write é obrigatório (ex: contador, idempotency check)"},{"id":"D","text":"Só funciona em GSI"}]'::jsonb, 'C',
  '"(a) DynamoDB cobra 1 RCU = 1 strongly consistent read até 4KB OU 2 eventually consistent reads (default). 1 transactional read = 2 strongly. (b) Custos invertidos não fazem sentido; diferença existe; GSI só suporta eventually consistent (regra). (c) Pattern: usar eventually consistent (default) na maioria dos paths de leitura; strongly só onde lógica crítica depende. (d) Ver DynamoDB Developer Guide — Read consistency."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'recall', '["dynamodb","read-consistency","rcu"]'::jsonb, 'ai-draft', 'active', now(), now()
)
