INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-040', 'aws-dva', 'Em um data pipeline com SNS → SQS → Lambda, mensagens duplicadas aparecem ocasionalmente na Lambda mesmo com SNS Standard. Qual padrão garantiria entrega exactly-once neste fluxo?',
  '[{"id":"A","text":"SNS Standard garante exactly-once nativamente"},{"id":"B","text":"Aumentar visibility timeout"},{"id":"C","text":"Trocar Lambda por EC2"},{"id":"D","text":"Implementar idempotência na Lambda usando idempotency key e cache (DynamoDB com TTL) — SNS Standard é at-least-once"}]'::jsonb, 'D',
  '"(a) SNS Standard e SQS Standard são at-least-once por design; duplicatas são inerentes. Idempotency pattern: hash da mensagem (ou messageId) → check DynamoDB → se existe, skip; senão grava com TTL e processa. AWS Powertools Idempotency utility implementa isso. (b) Standard não é exactly-once; FIFO é, mas com throughput limitado; (c) visibility timeout afeta retries; EC2 não muda semântica. (d) Pattern alt: usar SNS FIFO + SQS FIFO + messageDeduplicationId para exactly-once de fato. (d) Ver Lambda Developer Guide."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'best-practice', '["lambda","idempotency","sns-sqs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
