INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-041', 'aws-dva', 'Em uma Lambda, a métrica Throttles aparece > 0 em CloudWatch enquanto outras Lambdas da mesma conta processam normalmente. A Reserved concurrency dessa função é 0. Qual o efeito de Reserved Concurrency = 0?',
  '[{"id":"A","text":"Reserved Concurrency = 0 desabilita a função completamente — todas invocações são throttled"},{"id":"B","text":"Concurrency ilimitada"},{"id":"C","text":"Default de 1000"},{"id":"D","text":"Habilita auto-scaling"}]'::jsonb, 'A',
  '"(a) Reserved Concurrency = 0 é o ''kill switch'' do Lambda — pausa invocações sem deletar a função, útil em incident response (ex: stop poison source). Throttles métricos sobem. (b) Sem reserved = usa unreserved pool (default 1000 por conta); 0 explícito desabilita. (c) Use case: durante incident, set 0 para parar processamento sem destruir resource; depois restaurar. (d) Ver Lambda Developer Guide — Reserved concurrency."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'recall', '["lambda","reserved-concurrency","throttle"]'::jsonb, 'ai-draft', 'active', now(), now()
)
