INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-042', 'aws-dva', 'Para uma feature de leaderboard global em tempo real (10k incrementos/sec, leitura top-100), DynamoDB tem throttle por hot partition na key ''global''. ElastiCache Redis suporta nativamente esse caso. Qual estrutura Redis usar?',
  '[{"id":"A","text":"String (SET/GET)"},{"id":"B","text":"Sorted Set (ZADD/ZREVRANGE) — ordenação por score em O(log N)"},{"id":"C","text":"List (LPUSH/LRANGE)"},{"id":"D","text":"Pub/Sub"}]'::jsonb, 'B',
  '"(a) Sorted Sets armazenam member+score com ZADD; ZREVRANGE retorna top-N em O(log N + M). Caso clássico de leaderboard. (b) String não tem semântica de ordenação; List é FIFO sem ranking; Pub/Sub é fan-out, não storage. (c) Pattern: ZADD leaderboard 9500 user:42 + ZREVRANGE leaderboard 0 99 WITHSCORES. Persistência: AOF + replication para HA. (d) Ver ElastiCache for Redis User Guide — Use cases."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'scenario', '["elasticache","redis","sorted-set","leaderboard"]'::jsonb, 'ai-draft', 'active', now(), now()
)
