INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-043', 'aws-dva', 'Uma Lambda em Go ECR container image tem cold start de 8s em algumas invocações. O image tem 4GB. Que otimizações específicas de container Lambda reduzem cold start?',
  '[{"id":"A","text":"Aumentar timeout"},{"id":"B","text":"Mudar de Go para Java"},{"id":"C","text":"Otimizar layers da imagem (multi-stage build), usar AWS-provided base image, fazer slim image; considerar zip se \u003c 250MB"},{"id":"D","text":"Remover IAM role"}]'::jsonb, 'C',
  '"(a) Cold start de container Lambda inclui pull do registry, descompactação e carregamento. Mitigations: imagens base AWS (cached at edge), multi-stage para reduzir tamanho, ordenar layers do menos-modificável para mais, evitar binários gigantes. (b) Timeout não afeta cold start; trocar runtime pode aumentar; sem role não roda. (c) Provisioned Concurrency também funciona em container Lambda. (d) Ver Lambda Developer Guide — Container images."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'best-practice', '["lambda","container","cold-start","image-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
