INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-044', 'aws-dva', 'O developer quer alarme proativo quando a tabela DynamoDB chegar a 80% da capacity provisionada para escalar antes do throttle. Qual métrica é a base correta?',
  '[{"id":"A","text":"SuccessfulRequestLatency"},{"id":"B","text":"ThrottledRequests (já tarde demais)"},{"id":"C","text":"ReturnedItemCount"},{"id":"D","text":"ConsumedWriteCapacityUnits / ProvisionedWriteCapacityUnits via metric math, threshold 0.8"}]'::jsonb, 'D',
  '"(a) Metric math: (m1/m2) compara consumo vs provisionado; alarm > 0.8 dá margem. ConsumedRCU/ProvisionedRCU também. (b) Latency mede performance, não capacity; ThrottledRequests é reativo (já passou); ReturnedItemCount é volume. (c) Pattern produtivo: combinar com Application Auto Scaling para tabela escalar automaticamente (target 70%, scale-out faster que scale-in). (d) Ver CloudWatch User Guide e DynamoDB Developer Guide."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["dynamodb","cloudwatch","capacity-alarm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
