INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-045', 'aws-dva', 'Após reset de senha de banco em Secrets Manager, alguns containers ECS continuam usando a senha antiga e falham auth. O Secrets é injetado como env var via task definition. O developer precisa que rotação tome efeito sem rolling restart manual. O que é VERDADE sobre injeção de secrets como env var?',
  '[{"id":"A","text":"Env vars são lidas só no startup do container — após rotação, é preciso novo deploy/restart ou usar API para refetch em runtime"},{"id":"B","text":"ECS atualiza env vars automaticamente em runtime"},{"id":"C","text":"Secrets Manager push para containers"},{"id":"D","text":"Não é possível injetar secrets"}]'::jsonb, 'A',
  '"(a) Em ECS, valueFrom em containerDefinition injeta secret no boot do container. Rotação no Secrets Manager NÃO propaga para containers já rodando. (b) ECS não tem mecanismo de live-update; Secrets não ''push'' a clientes; injetar é o padrão. (c) Fix: app chama GetSecretValue em runtime com cache + refresh; ou usa rolling deployment a cada rotação; AWSCURRENT vs AWSPREVIOUS para zero-downtime rotation. (d) Ver Secrets Manager docs / Lambda Developer Guide."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["ecs","secrets-manager","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
