INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-046', 'aws-dva', 'Um endpoint /api/upload com Lambda + API Gateway tem latência alta para uploads de 5MB de imagens. Os uploads contam contra os 29s do API GW timeout e os 6MB sync da Lambda. Qual arquitetura otimiza este fluxo?',
  '[{"id":"A","text":"Aumentar timeout do API Gateway para 60s"},{"id":"B","text":"API GW retorna pre-signed URL S3; cliente faz PUT direto no S3; S3 trigger dispara Lambda para processamento async"},{"id":"C","text":"Usar API Gateway WebSocket"},{"id":"D","text":"Stream o upload pela Lambda"}]'::jsonb, 'B',
  '"(a) Pre-signed URL desacopla upload do compute Lambda: cliente envia bytes direto pro S3 (escala infinita, sem timeout API GW), depois Lambda processa via event-driven. (b) API GW hard cap 29s para integration; WebSocket é para messaging bidirecional; stream via Lambda ainda passa pelo limit. (c) Pattern: POST /upload → Lambda gera pre-signed URL → cliente PUT no S3 → S3 ObjectCreated event → Lambda processa. (d) Ver Lambda + API Gateway Developer Guides."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'scenario', '["lambda","s3","pre-signed-url","upload"]'::jsonb, 'ai-draft', 'active', now(), now()
)
