INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-047', 'aws-dva', 'Uma Lambda Java cria conexão JDBC ao RDS no handler. Sob carga, vê ''connection refused'' do RDS. O developer aprendeu sobre RDS Proxy. Que problema o RDS Proxy resolve neste contexto?',
  '[{"id":"A","text":"Aumenta a CPU do RDS"},{"id":"B","text":"Faz backup"},{"id":"C","text":"Multiplexa conexões — milhares de Lambdas compartilham um pool de conexões DB, evitando exaustão"},{"id":"D","text":"Habilita encryption at-rest"}]'::jsonb, 'C',
  '"(a) Lambda escalando para 1000 concurrent invocations = 1000 conexões diretas ao RDS, mas RDS tem limite de conexões (configurado em parameter group). RDS Proxy faz connection pooling — Lambda fala com proxy, proxy gerencia pool ao DB. Reduz failover time também. (b) CPU/backup/encryption são features unrelated. (c) Caveat: Proxy adiciona latência ~ms; em workloads transacionais simples vale; long transactions ficam pinned. (d) Ver Lambda Developer Guide — Working with RDS."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'scenario', '["lambda","rds-proxy","connection-pool"]'::jsonb, 'ai-draft', 'active', now(), now()
)
