INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-048', 'aws-dva', 'Após atualizar Lambda runtime, deploys via console começam a falhar com ''function code combined with layers exceeds the maximum allowed size of 250MB unzipped''. O developer já minimizou node_modules. Que alternativa permite código maior?',
  '[{"id":"A","text":"Aumentar timeout"},{"id":"B","text":"Splittar em 2 Lambdas pequenas"},{"id":"C","text":"Mudar de região"},{"id":"D","text":"Empacotar como container image (até 10GB)"}]'::jsonb, 'D',
  '"(a) Lambda container images suportam até 10GB (vs 250MB unzipped do zip). Útil para libs pesadas (Pandas + ML model + Python runtime). (b) Timeout não muda code size; splittar funciona às vezes mas adiciona complexidade; região tem mesmo limit. (c) Trade-off: container tem cold start tipicamente maior (especialmente primeira invocação após deploy) mas Provisioned Concurrency cobre. (d) Ver Lambda Developer Guide — Container images."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'recall', '["lambda","container","deployment-size"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
