INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-049', 'aws-dva', 'Em DynamoDB, BatchWriteItem retorna UnprocessedItems no response com 5 dos 25 items submetidos. O code só loga e continua. O que isso significa e qual a ação correta?',
  '[{"id":"A","text":"5 items não foram processados (throttle/erro temporário); o cliente deve fazer retry com exponential backoff somente dos UnprocessedItems"},{"id":"B","text":"Falha total — refazer tudo"},{"id":"C","text":"DynamoDB descartou os items permanentemente"},{"id":"D","text":"Erro do SDK"}]'::jsonb, 'A',
  '"(a) BatchWriteItem é parcialmente bem-sucedido por design. Items não processados (geralmente por throttle) retornam em UnprocessedItems; cliente DEVE reenviar (com backoff) ou perde dados. AWS SDK v3 não faz retry automático de batch parcial em todos casos. (b) Refazer tudo causa duplicatas; não foram descartados, foram pulados; não é bug do SDK. (c) Pattern: loop while(UnprocessedItems) com jitter + max attempts. (d) Ver DynamoDB Developer Guide — BatchWriteItem."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["dynamodb","batch-write","unprocessed-items"]'::jsonb, 'ai-draft', 'active', now(), now()
)
