INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-050', 'aws-dva', 'O custo CloudWatch Logs subiu 5x após habilitar verbose logging em produção. O developer quer reduzir custo sem perder visibilidade em erros. Qual estratégia combinada faz sentido?',
  '[{"id":"A","text":"Desabilitar logs"},{"id":"B","text":"Ajustar retention do log group; usar log level WARN+ em prod; exportar a S3 + Lifecycle para logs antigos; usar Logs Insights pontual"},{"id":"C","text":"Aumentar batch size"},{"id":"D","text":"Comprimir manualmente"}]'::jsonb, 'B',
  '"(a) CloudWatch Logs custa ingestion ($0.50/GB) + storage ($0.03/GB-month) + Insights ($0.005/GB scanned). Reduzir log level baixa ingestion drasticamente; retention curta + export S3 + Glacier baixa storage; Logs Insights só quando precisa. (b) Desabilitar perde tudo; batch size é detail; comprimir não é opção (CW comprime automaticamente). (c) Pattern: prod=WARN, staging=INFO, dev=DEBUG; retention 7-14d em prod, ARQ no S3 para compliance. (d) Ver CloudWatch Logs User Guide."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'best-practice', '["cloudwatch","logs","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
