INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-051', 'aws-dva', 'Em uma Lambda VPC-bound, calls externas (api.stripe.com) fazem timeout enquanto calls a serviços AWS funcionam. A subnet onde a Lambda corre é privada com route table apontando para Internet Gateway diretamente. Qual o problema?',
  '[{"id":"A","text":"Lambda não suporta calls externas"},{"id":"B","text":"Stripe está down"},{"id":"C","text":"Subnet privada não pode usar IGW diretamente — precisa de NAT Gateway em subnet pública para acessar internet"},{"id":"D","text":"Falta criptografia"}]'::jsonb, 'C',
  '"(a) Subnet privada = sem rota direta ao IGW. Para internet outbound, precisa NAT Gateway em subnet pública + rota 0.0.0.0/0 → nat-gw na route table privada. IGW direto em subnet privada não funciona (não tem IP público). (b) Lambda fala internet normalmente fora de VPC; em VPC precisa de NAT/VPC endpoint. (c) Stripe up; criptografia unrelated. (d) Ver Lambda Developer Guide — VPC networking."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'troubleshoot', '["lambda","vpc","nat-gateway","internet"]'::jsonb, 'ai-draft', 'active', now(), now()
)
