INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-052', 'aws-dva', 'API Gateway HTTP API (v2) vs REST API (v1): em qual cenário o HTTP API é a escolha errada?',
  '[{"id":"A","text":"Quer menor latência e custo"},{"id":"B","text":"Lambda integration simples"},{"id":"C","text":"JWT authorizer com Cognito"},{"id":"D","text":"Precisa de request/response transformations, AWS WAF nativo, ou API keys com usage plans"}]'::jsonb, 'D',
  '"(a) HTTP API é 70% mais barato e mais rápido, mas não suporta: mapping templates, WAF (Q1 2024 limited), request validation rica, API keys/usage plans, X-Ray segments de integration. (b) Latência e custo são vantagens do HTTP; Lambda proxy é o caso ideal; JWT authorizer é nativo no HTTP. (c) Decision tree: precisa WAF/API keys/mapping → REST; senão HTTP. (d) Ver API Gateway Developer Guide — REST vs HTTP."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'medium', 'recall', '["api-gateway","http-api","rest-api"]'::jsonb, 'ai-draft', 'active', now(), now()
)
