INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-053', 'aws-dva', 'Em uma aplicação fan-out (1 event → N consumers diferentes), o developer usou SNS com 4 subscribers Lambda. Um dos subscribers começou a falhar e seu DLQ enche. Os outros 3 ficam OK. Como isolar falha do subscriber problemático?',
  '[{"id":"A","text":"Cada subscriber tem sua própria DLQ — falhas em um Lambda não afetam outros (SNS já isola entrega)"},{"id":"B","text":"Falha de um subscriber pausa todo SNS topic"},{"id":"C","text":"Recriar o SNS topic"},{"id":"D","text":"Aumentar memória do SNS"}]'::jsonb, 'A',
  '"(a) SNS entrega para cada subscriber independentemente, com retry policy e DLQ por subscription. Falha em Lambda A não bloqueia Lambdas B/C/D. (b) Tópico continua entregando para outros; recriar é destrutivo; SNS não tem ''memória'' configurável. (c) Diagnostic: NumberOfNotificationsFailed por subscription identifica qual está em erro; verificar DLQ específica. (d) Ver Lambda Developer Guide — SNS integration."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'recall', '["sns","fan-out","dlq"]'::jsonb, 'ai-draft', 'active', now(), now()
)
