INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-054', 'aws-dva', 'Uma tabela DynamoDB usa Global Secondary Index ''email-index''. PutItems na tabela base começam a falhar com ThrottlingException, mesmo com WCU base abundante. Logs mencionam ''index''. Qual a causa específica?',
  '[{"id":"A","text":"GSI sempre herda capacity da tabela base"},{"id":"B","text":"GSI tem capacity independente; está sub-provisionado e bloqueia writes na tabela base"},{"id":"C","text":"Tabela está corrompida"},{"id":"D","text":"Falta IAM dynamodb:Query"}]'::jsonb, 'B',
  '"(a) GSI tem RCU/WCU provisionados separados. Writes na tabela base que projetam para GSI consomem WCU do GSI. Se GSI fica throttled, a write inteira falha. (b) GSI não herda; provisionamento separado por design; tabela não corrompe sozinha; Query é permissão de leitura. (c) Fix: monitorar WriteThrottleEvents por GSI; on-demand mode evita; ou auto-scaling per-index. (d) Ver DynamoDB Developer Guide — GSI provisioned throughput."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["dynamodb","gsi","throttling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
