INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-055', 'aws-dva', 'O developer quer agregar logs de 12 Lambdas em um único dashboard. Os log groups têm naming convention /aws/lambda/svc-*. Qual feature do CloudWatch Logs facilita queries unificadas?',
  '[{"id":"A","text":"Criar 12 dashboards separados"},{"id":"B","text":"Fazer scan no S3"},{"id":"C","text":"Logs Insights suporta query em múltiplos log groups via prefix selection (até 50)"},{"id":"D","text":"Não é possível"}]'::jsonb, 'C',
  '"(a) Logs Insights query builder permite selecionar múltiplos log groups (até 50) e roda query unificada. Útil para agregação cross-service. (b) Dashboards separados perdem unificação; scan S3 sai do CW; é totalmente possível. (c) Alternativas: subscription filter para enviar a Kinesis Firehose → OpenSearch para análise mais avançada. (d) Ver CloudWatch Logs User Guide — Cross-account/cross-log-group queries."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'recall', '["cloudwatch","logs-insights","multi-log-group"]'::jsonb, 'ai-draft', 'active', now(), now()
)
