INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-056', 'aws-dva', 'Em uma migration legacy, o developer precisa de visibilidade detalhada por usuário em produção sem inundar X-Ray. Quer que apenas 1% dos usuários (selecionados aleatoriamente) tenham todos os requests traced. Qual abordagem implementa isso?',
  '[{"id":"A","text":"Habilitar traces em 100% e filtrar depois"},{"id":"B","text":"Pagar mais X-Ray"},{"id":"C","text":"Não é possível controlar por usuário"},{"id":"D","text":"No código, decidir por usuário (% sampling) e setar trace header Sampled=1 ou usar X-Ray SDK setSamplingRule programaticamente"}]'::jsonb, 'D',
  '"(a) X-Ray usa header X-Amzn-Trace-Id com flag Sampled=0/1. Forçar Sampled=1 no início do request (após decisão de % por user) garante o trace inteiro percorrer; downstream services preservam o trace. (b) 100% inunda e custa; é possível controlar fine-grained via header; pagar não é solução. (c) Pattern útil: random.random() < 0.01 || isVip(user) → force sample. (d) Ver X-Ray Developer Guide — Sampling and the X-Amzn-Trace-Id header."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'scenario', '["x-ray","sampling","trace-header"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
