INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-057', 'aws-dva', 'Uma Lambda async é chamada por S3 PutObject. Em testes de carga, 100 uploads simultâneos resultam em 78 invocações. O developer não vê nenhum erro. Para onde foram as outras 22?',
  '[{"id":"A","text":"S3 event notifications são at-least-once mas raramente at-most-once em bursts; verificar S3 → Lambda direct integration tem batching/eventual; alternativa: usar S3 → EventBridge para garantir entrega"},{"id":"B","text":"Lambda perdeu as invocações"},{"id":"C","text":"S3 nunca dispara eventos"},{"id":"D","text":"AWS quota global"}]'::jsonb, 'A',
  '"(a) S3 event notifications direct (Lambda destination) entregam at-least-once mas, em casos raros de carga ou problemas internos, podem suprimir. AWS doc menciona possibilidade rara de eventos perdidos. EventBridge oferece SLA mais forte e DLQ nativo. (b) Lambda não ''perde'' silenciosamente — métricas mostrariam; S3 dispara eventos sim; quota global não causa drop sem alarm. (c) Best practice: para event-driven crítico, S3 → EventBridge → Lambda (com DLQ) ou S3 → SQS → Lambda. (d) Ver Lambda Developer Guide."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["lambda","s3","event-notifications","eventbridge"]'::jsonb, 'ai-draft', 'active', now(), now()
)
