INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-058', 'aws-dva', 'Logs Insights query: ''stats avg(duration) as avg_dur by bin(5m)'' em uma Lambda mostra picos repetitivos a cada hora cheia. Não há cron interno. Qual a fonte mais provável dos picos?',
  '[{"id":"A","text":"Lambda tem comportamento sazonal"},{"id":"B","text":"EventBridge scheduled rule (cron) disparando job pesado de hora em hora; correlacionar com CloudWatch Events/EventBridge metrics"},{"id":"C","text":"AWS bug"},{"id":"D","text":"Falta encryption"}]'::jsonb, 'B',
  '"(a) Pico horário regular = scheduler. EventBridge schedule expressions (rate/cron) são a fonte mais comum. Verificar Rules dashboard e correlacionar TriggeredRules. (b) Não há sazonalidade inerente; AWS bug é improvável; encryption não causa picos. (c) Diagnostic: usar X-Ray annotation ''triggered_by=eventbridge'' ou logar o source no event. (d) Ver CloudWatch Logs User Guide / EventBridge."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'troubleshoot', '["cloudwatch","logs-insights","eventbridge"]'::jsonb, 'ai-draft', 'active', now(), now()
)
