INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-059', 'aws-dva', 'Após habilitar Lambda Function URL para teste rápido, o developer nota que requests vindos do browser falham com CORS mesmo com AuthType=NONE. O que precisa configurar?',
  '[{"id":"A","text":"Mudar runtime"},{"id":"B","text":"Habilitar VPC"},{"id":"C","text":"Function URL CORS config (allowOrigins, allowMethods, allowHeaders) — separado do CORS da Lambda"},{"id":"D","text":"Aumentar memória"}]'::jsonb, 'C',
  '"(a) Function URL tem seu próprio CORS configurável na resource Lambda (cors: { allowOrigins, allowMethods, ... }). Sem isso, browser bloqueia. (b) Runtime não afeta CORS; VPC não muda CORS; memória unrelated. (c) Diferenças vs API Gateway: Function URL é mais simples, sem custos extras, mas sem features ricas (authorizers customizados, transformations). (d) Ver Lambda Developer Guide — Function URLs."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'easy', 'troubleshoot', '["lambda","function-url","cors"]'::jsonb, 'ai-draft', 'active', now(), now()
)
