INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'dva-c02-troub-060', 'aws-dva', 'Um time roda chaos engineering: durante o test, EFS mount da Lambda falha por 2 minutos. Lambdas com EFS mount começam a retornar ''EFSMountFailure'' e morrem em ~30s. Qual configuração da Lambda determina como ela trata falhas de inicialização do mount?',
  '[{"id":"A","text":"Lambda monta EFS in-memory"},{"id":"B","text":"Auto-fallback para S3"},{"id":"C","text":"Não existe integração Lambda-EFS"},{"id":"D","text":"Init timeout (~10s) — se EFS mount falha no init, a Lambda falha invocação; sem retry automático para mount issues, precisa monitorar EFSIsAlive e ter fallback no código"}]'::jsonb, 'D',
  '"(a) Lambda monta EFS access point durante init phase. Mount failure = init failure = invocação falha com erro. Lambda não faz fallback automático; precisa retry da invocação (assíncrono via DLQ/destinations) ou código defensivo. (b) Não monta in-memory — é network attach; sem fallback nativo para S3; integração Lambda-EFS existe (file storage 10GB+). (c) Best practice: EFS é para shared state mutável; para read-only podes preferir layers ou S3 download em init. (d) Ver Lambda Developer Guide — Configuring file system access."'::jsonb,
  'Troubleshooting & Optimization', 'Troubleshooting & Optimization', 'hard', 'troubleshoot', '["lambda","efs","mount-failure"]'::jsonb, 'ai-draft', 'active', now(), now()
)
